Route::post('/pos/kalem-sil', function (Request $r) {
    if ($g = _posKapi()) return $g;
    $k = DB::table('adisyon_kalemleri')->find($r->kalem_id);
    if (!$k) return ['ok' => 0];
    // KACAK KORUMASI: mutfaga GITMIS urun IZSIZ silinemez -> 'iptal' (soft) + LOG (kayip radarinda gorunur, garson cebe atamaz).
    // Henuz gonderilmemis ('yeni') urun normal duzenleme sayilir, fiziksel cikar.
    if (in_array($k->durum, ['gonderildi', 'hazir', 'servis'], true)) {
        DB::table('adisyon_kalemleri')->where('id', $k->id)->update(['durum' => 'iptal', 'updated_at' => now()]);
        $subeId = DB::table('adisyonlar')->where('id', $k->adisyon_id)->value('sube_id');
        if (Schema::hasTable('iptal_indirim_loglari')) {
            DB::table('iptal_indirim_loglari')->insert(['sube_id' => $subeId, 'adisyon_id' => $k->adisyon_id, 'adisyon_kalem_id' => $k->id,
                'tip' => 'void', 'tutar' => (float) $k->tutar, 'sebep' => $r->sebep ?: 'POS ürün silme', 'personel_id' => $r->personel_id ?: null, 'created_at' => now()]);
        }
    } else {
        DB::table('adisyon_kalemleri')->where('id', $k->id)->delete();
    }
    return _adisyonToplamGuncelle($k->adisyon_id);
});

Route::post('/pos/gonder', function (Request $r) {
    if ($g = _posKapi()) return $g;
    DB::table('adisyon_kalemleri')->where('adisyon_id', $r->adisyon_id)->where('durum', 'yeni')
        ->update(['durum' => 'gonderildi', 'gonderim_zamani' => now()]);
    return ['ok' => 1];
});

Route::post('/pos/ode', function (Request $r) {
    if ($g = _posKapi()) return $g;
    $a = DB::table('adisyonlar')->find($r->adisyon_id);
    if (!$a) return ['ok' => 0, 'hata' => 'Adisyon bulunamadı'];
    $odemeTip = $r->tip ?? 'nakit';
    DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => $odemeTip, 'tutar' => $a->toplam, 'bahsis' => 0, 'personel_id' => $a->acan_personel_id, 'created_at' => now()]);
    if ($odemeTip === 'nakit' && function_exists('_kasaYaz')) _kasaYaz($a->sube_id, 'satis', 'giris', $a->toplam, 'Nakit satış · adisyon #' . $a->id, 'adisyon', $a->id, $a->acan_personel_id);
    DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'odendi', 'kapanis' => now()]);
    if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
    // SADAKAT: adisyona musteri bagliysa puan + harcama isle (her 10 TL = 1 puan)
    if (!empty($a->musteri_id)) {
        DB::table('musteriler')->where('id', $a->musteri_id)->update([
            'siparis_sayisi' => DB::raw('siparis_sayisi + 1'),
            'toplam_harcama' => DB::raw('toplam_harcama + ' . (float) $a->toplam),
            'puan' => DB::raw('puan + ' . (int) floor($a->toplam / 10)),
            'updated_at' => now(),
        ]);
    }
    // NORMAL FIS: fis moduna gore otomatik belge (adisyona daha once fatura kesilmediyse)
    $ayar = DB::table('edonusum_ayarlari')->where('sube_id', $a->sube_id)->first();
    $zatenBelge = DB::table('e_faturalar')->where('adisyon_id', $a->id)->exists();
    if (!$zatenBelge) {
        $sube = DB::table('subeler')->find($a->sube_id);
        if ($ayar && ($ayar->fis_modu ?? 'earsiv') === 'okc') {
            _okcFisBas($sube, $a);          // Yazarkasa mali fisi
        } else {
            _eFaturaKes($sube, $a, []);     // e-Arsiv fisi (Son Tuketici)
        }
    }
    return ['ok' => 1];
});

// Adisyon kapaninca (odendi) ORTAK isler: SADAKAT (musteri puan/harcama) + NORMAL MALI FIS (e-Arsiv/OKC).
// adisyon-islem'deki 3 kapanis noktasi (kapat / kalem-bol / parcali) bunu cagirir -> CRM istatistik + mali belge
// artik GERCEK odeme yolunda da uretilir. Idempotent: mali belge zatenBelge ile tek sefer; kapanis zaten tek kez olur.
if (!function_exists('_adisyonKapanisIsle')) {
    function _adisyonKapanisIsle($adisyonId)
    {
        $a = DB::table('adisyonlar')->find($adisyonId);
        if (!$a) return;
        if (!empty($a->musteri_id)) {
            try {
                DB::table('musteriler')->where('id', $a->musteri_id)->update([
                    'siparis_sayisi' => DB::raw('siparis_sayisi + 1'),
                    'toplam_harcama' => DB::raw('toplam_harcama + ' . (float) $a->toplam),
                    'puan' => DB::raw('puan + ' . (int) floor(((float) $a->toplam) / 10)),
                    'updated_at' => now(),
                ]);
            } catch (\Throwable $e) {
            }
        }
        try {
            $zatenBelge = Schema::hasTable('e_faturalar') && DB::table('e_faturalar')->where('adisyon_id', $a->id)->exists();
            if (!$zatenBelge && function_exists('_eFaturaKes')) {
                $ayar = Schema::hasTable('edonusum_ayarlari') ? DB::table('edonusum_ayarlari')->where('sube_id', $a->sube_id)->first() : null;
                $sube = DB::table('subeler')->find($a->sube_id);
                if ($ayar && ($ayar->fis_modu ?? 'earsiv') === 'okc' && function_exists('_okcFisBas')) {
                    _okcFisBas($sube, $a);
                } else {
                    _eFaturaKes($sube, $a, []);
                }
            }
        } catch (\Throwable $e) {
        }
        // Memnuniyet anketi (müşteri + telefon varsa WA'dan token'lı link) — guard'lı, akışı bozmaz
        try { if (function_exists('_waAnketGonder')) _waAnketGonder($a->id); } catch (\Throwable $e) {}
    }
}

// ============ PAKET TESLİMAT + TAHSİLAT (İKİ AŞAMALI) ============
// Kurye TESLİM eder (teslimat_durumu), KASA TAHSİL eder (para kasaya girer).
// tahsilat_durumu: bekliyor -> kuryede (teslim edildi, para kuryede) -> kasada (kasa tahsil etti) ; iade (teslim edilemedi)
if (!function_exists('_paketTahsilatEnsure')) {
    function _paketTahsilatEnsure()
    {
        try {
            if (!Schema::hasColumn('adisyonlar', 'tahsilat_durumu')) {
                Schema::table('adisyonlar', fn ($t) => $t->string('tahsilat_durumu', 16)->nullable()->after('teslimat_durumu'));
            }
            if (!Schema::hasColumn('adisyonlar', 'teslim_notu')) {
                Schema::table('adisyonlar', fn ($t) => $t->string('teslim_notu', 255)->nullable());
            }
        } catch (\Throwable $e) {}
    }
}
if (!function_exists('_paketSettle')) {
    // KASA TAHSİLATI: parayı kasaya işle + ödeme kaydı + adisyonu kapat + mali fiş/CRM. tahsilat_durumu='kasada'.
    // Akşam sayımı için ödeme TİPİ doğru yazılır (nakit->nakit, kapıda kart->kredi/fiş, online->online).
    function _paketSettle($a, $personelId = null)
    {
        if (!$a) return false;
        if (($a->durum ?? '') === 'odendi') return true; // zaten kapalı/tahsil edilmiş
        _paketTahsilatEnsure();
        $tip = ['nakit' => 'nakit', 'kart_kapida' => 'kredi', 'online' => 'online'][$a->odeme_yontemi ?? 'nakit'] ?? 'nakit';
        $tutar = (float) $a->toplam;
        try {
            DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => $tip, 'tutar' => $tutar,
                'bahsis' => 0, 'personel_id' => $personelId ?: ($a->acan_personel_id ?? null), 'created_at' => now()]);
        } catch (\Throwable $e) {}
        // Nakit tahsilat kasaya giriş olarak işlensin (kart/online kasada nakit yaratmaz)
        if ($tip === 'nakit' && function_exists('_kasaYaz')) {
            try { _kasaYaz($a->sube_id, 'satis', 'giris', $tutar, 'Paket tahsilat · #' . $a->id, 'adisyon', $a->id, $personelId); } catch (\Throwable $e) {}
        }
        DB::table('adisyonlar')->where('id', $a->id)->update([
            'durum' => 'odendi', 'kapanis' => now(), 'tahsilat_durumu' => 'kasada', 'updated_at' => now(),
        ]);
        try { _adisyonKapanisIsle($a->id); } catch (\Throwable $e) {}
        return true;
    }
}

