    if ($stored === 'ozel' && !empty($s->tema_renk)) $tema = resto_tema_uret($s->tema_renk, $s->tema_renk2 ?? null);
    elseif ($stored && isset($temalar[$stored])) $tema = $temalar[$stored];
    else $tema = $temalar['altin'] ?? reset($temalar);
