Route::get('/api/m/profil', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    return ['ok' => 1, 'musteri' => _musteriKart2($m)];
});
Route::post('/api/m/profil-guncelle', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    $upd = ['updated_at' => now()];
    foreach (['ad', 'soyad', 'email', 'cinsiyet', 'adres'] as $f) if ($r->filled($f)) $upd[$f] = trim((string) $r->input($f));
    if ($r->filled('dogum_tarihi')) $upd['dogum_tarihi'] = $r->input('dogum_tarihi');
    if ($r->filled('damak')) $upd['damak'] = (string) $r->input('damak');
    DB::table('musteriler')->where('id', $m->id)->update($upd);
    return ['ok' => 1, 'musteri' => _musteriKart2(DB::table('musteriler')->find($m->id)), 'mesaj' => 'Profil güncellendi'];
});

// Hesabımı sil (KVKK): token geçersiz kılınır + kişisel veriler anonimleştirilir
Route::post('/api/m/hesap-sil', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    try { if (!Schema::hasColumn('musteriler', 'silindi_at')) Schema::table('musteriler', fn ($t) => $t->timestamp('silindi_at')->nullable()); } catch (\Throwable $e) {}
    $upd = ['api_token' => null, 'updated_at' => now()];
    foreach (['ad' => 'Silinmiş Hesap', 'soyad' => null, 'email' => null, 'adres' => null, 'dogum_tarihi' => null, 'cinsiyet' => null, 'silindi_at' => now()] as $k => $v) {
        try { if (Schema::hasColumn('musteriler', $k)) $upd[$k] = $v; } catch (\Throwable $e) {}
    }
    DB::table('musteriler')->where('id', $m->id)->update($upd);
    return ['ok' => 1, 'mesaj' => 'Hesabın silindi. Bizi tercih ettiğin için teşekkürler.'];
});
// Sadakat özeti (puan + kademe + ödül merdiveni)
// Ödül tipleri (bedava ürün / %indirim / ₺indirim) için kolon garantisi
if (!function_exists('_odulKolonEnsure')) {
    function _odulKolonEnsure()
    {
        if (cache()->get('odul_kolon_ensure_ok2')) return;
        if (Schema::hasTable('puan_odulleri')) {
            foreach (['tip' => 'str', 'deger' => 'dec', 'urun_id' => 'int'] as $k => $t) {
                if (!Schema::hasColumn('puan_odulleri', $k)) {
                    try { Schema::table('puan_odulleri', function ($tb) use ($k, $t) {
                        if ($t === 'str') $tb->string($k, 16)->nullable();
                        elseif ($t === 'dec') $tb->decimal($k, 10, 2)->default(0);
                        else $tb->unsignedBigInteger($k)->nullable();
                    }); } catch (\Throwable $e) {}
                }
            }
        }
        cache()->put('odul_kolon_ensure_ok2', 1, now()->addHours(12));
    }
}
// Ödülün hesaba nasıl yansıdığını metinle anlat
if (!function_exists('_odulAciklama')) {
    function _odulAciklama($o)
    {
        $tip = $o->tip ?? 'urun';
        if ($tip === 'yuzde') return '%' . rtrim(rtrim(number_format((float) ($o->deger ?? 0), 2, '.', ''), '0'), '.') . ' indirim';
        if ($tip === 'tutar') return number_format((float) ($o->deger ?? 0), 0, ',', '.') . '₺ indirim';
        return 'Bedava ürün';
    }
}
Route::get('/api/m/sadakat', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    _odulKolonEnsure();
    $oduller = [];
    if (Schema::hasTable('puan_odulleri')) {
        try {
            $oduller = DB::table('puan_odulleri')->where('sube_id', $m->sube_id)->where('aktif', 1)->orderBy('puan')
                ->get()->map(fn ($o) => ['id' => (int) $o->id, 'ad' => $o->ad, 'puan' => (int) $o->puan,
                    'tip' => $o->tip ?? 'urun', 'deger' => (float) ($o->deger ?? 0), 'aciklama' => _odulAciklama($o),
                    'alinabilir' => (int) ($m->puan ?? 0) >= (int) $o->puan])->values();
        } catch (\Throwable $e) {}
    }
    return ['ok' => 1, 'puan' => (int) ($m->puan ?? 0), 'kademe' => _musteriKademe((float) ($m->toplam_harcama ?? 0)),
        'siparis_sayisi' => (int) ($m->siparis_sayisi ?? 0), 'toplam_harcama' => (float) ($m->toplam_harcama ?? 0), 'oduller' => $oduller];
});
// Geçmiş siparişler (tekrar sipariş için)
Route::get('/api/m/siparislerim', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    $list = DB::table('adisyonlar')->where('musteri_id', $m->id)->orderByDesc('id')->limit(30)
        ->get(['id', 'toplam', 'durum', 'teslimat_durumu', 'kanal', 'platform', 'takip_token', 'created_at'])
        ->map(function ($a) {
            $kalemler = DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')
                ->get(['urun_id', 'urun_adi', 'adet', 'tutar'])->map(fn ($k) => ['urun_id' => (int) $k->urun_id, 'ad' => $k->urun_adi, 'adet' => (float) $k->adet, 'tutar' => (float) $k->tutar]);
            return ['id' => (int) $a->id, 'toplam' => (float) $a->toplam, 'durum' => $a->durum, 'teslimat_durumu' => $a->teslimat_durumu,
                'takip_token' => $a->takip_token, 'tarih' => $a->created_at ? \Carbon\Carbon::parse($a->created_at)->format('d.m.Y H:i') : '', 'kalemler' => $kalemler];
        });
    return ['ok' => 1, 'siparisler' => $list];
});
// DEMO: giriş yapmış müşteriye fake veri doldur (ödül merdiveni + puan + cüzdan hareketi + geçmiş sipariş). Tekrar çağrı katlamaz.
Route::post('/api/m/demo-doldur', function (Request $r) {
