        foreach ($gruplar as $gi => $g) {
            $sec = array_slice($havuz, $gi % max(1, count($havuz)), 2); if (!$sec) $sec = array_slice($havuz, 0, 2);
            $top = 0; foreach ($sec as $s) $top += $s['fiyat'];
