    foreach ($kartlar as $k) { try { DB::table('app_banner')->insert(array_merge(['sube_id' => $sid, 'aktif' => 1, 'created_at' => now(), 'updated_at' => now()], $k)); } catch (\Throwable $e) {} }
    return ['ok' => 1, 'mesaj' => 'Demo veriler + 5 resimli kart yüklendi', 'puan' => 65];
