// AI asistan (müşteri bağlamıyla: geçmiş ürünler + damak -> kişiselleştirilmiş)
// AI asistan — QR menü MusteriAsistan'ı ile BİREBİR (tam eğitim seti + sipariş akışı).
// baglam = son konuşulan ürün adı (STRING), yanıtta urun_baglam döner; istemci saklar (QR akışı aynen).
Route::post('/api/m/ai', function (Request $r) {
    $m = _musteriAuth($r);
    $subeId = $m ? $m->sube_id : _musteriSube($r);
    $soru = (string) $r->input('mesaj');
    if (trim($soru) === '') return ['ok' => 0, 'hata' => 'Mesaj boş'];
    try {
        $a = new \App\Services\MusteriAsistan($subeId);
        $res = $a->cevapla($soru, (string) $r->input('baglam', ''));
        if (is_array($res)) { $res['ok'] = 1; return $res; }
        return ['ok' => 1, 'cevap' => (string) $res];
    } catch (\Throwable $e) {
        return ['ok' => 0, 'hata' => 'AI şu an yanıt veremedi'];
    }
});
// Kart/kampanya KULLAN — detay sayfasındaki "Kullan" butonu (tek seferlik: ödül puanı ekle + kupon döndür)
Route::post('/api/m/kart-kullan', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    _appEnsure2();
    $id = (int) $r->input('id');
    $b = DB::table('app_banner')->where('id', $id)->where('sube_id', $m->sube_id)->first();
    if (!$b) return ['ok' => 0, 'hata' => 'Kampanya bulunamadı'];
    if (!Schema::hasTable('musteri_kart_kullanim')) {
        try { Schema::create('musteri_kart_kullanim', function ($t) {
            $t->id(); $t->unsignedBigInteger('musteri_id')->index(); $t->unsignedBigInteger('banner_id')->index(); $t->timestamps();
        }); } catch (\Throwable $e) {}
    }
    $odul = (int) ($b->odul_puan ?? 0);
    $kupon = $b->kupon_kodu ?? null;
    $kullanildi = DB::table('musteri_kart_kullanim')->where('musteri_id', $m->id)->where('banner_id', $id)->exists();
    if ($kullanildi) {
        return ['ok' => 1, 'tekrar' => 1, 'kupon_kodu' => $kupon,
            'mesaj' => $kupon ? "Bu kampanyayı zaten aldın.\nKupon kodun: $kupon" : 'Bu kampanyayı zaten kullandın.'];
    }
    DB::table('musteri_kart_kullanim')->insert(['musteri_id' => $m->id, 'banner_id' => $id, 'created_at' => now(), 'updated_at' => now()]);
    $puanYeni = (int) ($m->puan ?? 0);
    if ($odul > 0) { try { DB::table('musteriler')->where('id', $m->id)->update(['puan' => DB::raw('puan + ' . $odul), 'updated_at' => now()]); $puanYeni += $odul; } catch (\Throwable $e) {} }
    $parca = [];
    if ($odul > 0) $parca[] = "+$odul puan hesabına eklendi 🎉";
    if ($kupon) $parca[] = "Kupon kodun: $kupon";
    if (!$parca) $parca[] = 'Kampanya hesabına tanımlandı ✓';
    return ['ok' => 1, 'mesaj' => implode("\n", $parca), 'kupon_kodu' => $kupon, 'odul_puan' => $odul, 'puan' => $puanYeni];
});

// KUPONLARIM: müşterinin aldığı tüm kampanyalar (geçmiş dahil) + kupon kodları
Route::get('/api/m/kuponlarim', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    $list = collect();
    if (Schema::hasTable('musteri_kart_kullanim')) {
        $list = DB::table('musteri_kart_kullanim as k')
            ->join('app_banner as b', 'k.banner_id', '=', 'b.id')
            ->where('k.musteri_id', $m->id)
            ->orderByDesc('k.id')
            ->get(['b.baslik', 'b.metin', 'b.gorsel', 'b.kupon_kodu', 'b.odul_puan', 'k.created_at'])
            ->map(fn ($x) => [
                'baslik' => $x->baslik ?: 'Kampanya',
                'metin' => $x->metin ?: '',
                'gorsel' => $x->gorsel,
                'kupon_kodu' => $x->kupon_kodu,
                'odul_puan' => (int) ($x->odul_puan ?? 0),
                'tur' => 'kampanya',
                'tarih' => $x->created_at ? \Carbon\Carbon::parse($x->created_at)->format('d.m.Y') : '',
            ]);
    }
    // Çarktan kazanılan indirim kuponları (bekleyen + süresi geçmemiş)
    $cark = collect();
    try {
        _carkKur();
        $cark = DB::table('odul_kullanimlari')->where('musteri_id', $m->id)->where('kaynak', 'cark')
            ->where('durum', 'bekliyor')->where('bitis', '>', now())->orderByDesc('id')
            ->get(['baslik', 'kod', 'bitis', 'created_at'])
            ->map(fn ($x) => [
                'baslik' => $x->baslik ?: 'Çark Ödülü',
                'metin' => 'Kasada bu kodu göster — anında indirim',
                'gorsel' => null,
                'kupon_kodu' => $x->kod,
                'odul_puan' => 0,
                'tur' => 'cark',
                'bitis' => $x->bitis ? \Carbon\Carbon::parse($x->bitis)->format('d.m.Y') : null,
                'tarih' => $x->created_at ? \Carbon\Carbon::parse($x->created_at)->format('d.m.Y') : '',
            ]);
    } catch (\Throwable $e) {}
    return ['ok' => 1, 'kuponlar' => $cark->concat($list)->values()];
});

// ===== PUAN ÖDÜLÜ KULLANIMI (müşteri Kullan -> QR/kod -> kasa doğrula -> puan düş) =====
if (!function_exists('_odulKullanimEnsure')) {
    function _odulKullanimEnsure()
    {
        if (cache()->get('odul_kullanim_ensure_ok')) return;
        if (!Schema::hasTable('odul_kullanimlari')) {
            try { Schema::create('odul_kullanimlari', function ($t) {
                $t->id(); $t->unsignedBigInteger('musteri_id')->index(); $t->unsignedBigInteger('sube_id')->index();
                $t->unsignedBigInteger('odul_id')->nullable(); $t->string('odul_ad', 120); $t->integer('puan')->default(0);
                $t->string('kod', 20)->unique(); $t->string('durum', 12)->default('bekliyor');
                $t->timestamp('bitis')->nullable(); $t->unsignedBigInteger('kasiyer_id')->nullable(); $t->timestamp('kullanildi_at')->nullable();
                $t->timestamps();
            }); } catch (\Throwable $e) {}
        }
        cache()->put('odul_kullanim_ensure_ok', 1, now()->addHours(12));
    }
}
// Müşteri: ödülü kullan -> tek seferlik kod (puan HENÜZ düşmez; kasada onayınca düşer)
Route::post('/api/m/odul-kullan', function (Request $r) {
    $m = _musteriAuth($r); if (!$m) return response()->json(['ok' => 0], 401);
    _odulKullanimEnsure();
    $o = DB::table('puan_odulleri')->where('id', (int) $r->input('odul_id'))->where('sube_id', $m->sube_id)->where('aktif', 1)->first();
    if (!$o) return ['ok' => 0, 'hata' => 'Ödül bulunamadı'];
    if ((int) ($m->puan ?? 0) < (int) $o->puan) return ['ok' => 0, 'hata' => "Yeterli puanın yok ({$o->puan} puan gerekli)"];
    $mevcut = DB::table('odul_kullanimlari')->where('musteri_id', $m->id)->where('odul_id', $o->id)
        ->where('durum', 'bekliyor')->where('bitis', '>', now())->orderByDesc('id')->first();
    if ($mevcut) return ['ok' => 1, 'kod' => $mevcut->kod, 'odul_ad' => $mevcut->odul_ad, 'puan' => (int) $mevcut->puan, 'bitis' => \Carbon\Carbon::parse($mevcut->bitis)->timestamp];
    do { $kod = strtoupper(\Illuminate\Support\Str::random(6)); } while (DB::table('odul_kullanimlari')->where('kod', $kod)->exists());
    $bitis = now()->addMinutes(10);
    DB::table('odul_kullanimlari')->insert(['musteri_id' => $m->id, 'sube_id' => $m->sube_id, 'odul_id' => $o->id,
        'odul_ad' => $o->ad, 'puan' => (int) $o->puan, 'kod' => $kod, 'durum' => 'bekliyor', 'bitis' => $bitis, 'created_at' => now(), 'updated_at' => now()]);
    return ['ok' => 1, 'kod' => $kod, 'odul_ad' => $o->ad, 'puan' => (int) $o->puan, 'bitis' => $bitis->timestamp];
});
