        'detay' => $b->detay ?? null, 'buton' => $b->buton ?? null, 'kupon_kodu' => $b->kupon_kodu ?? null, 'odul_puan' => (int) ($b->odul_puan ?? 0)];
    return ['ok' => 1,
        'hero' => $all->where('tip', 'hero')->map($map)->values(),
        'kampanyalar' => $all->where('tip', 'kampanya')->map($map)->values(),
