});

// ===== APP YÖNETİM: dashboard kartlarını (hero + kampanya) tasarla (sahip/müdür, POS PIN oturumu) =====
if (!function_exists('_appYonetimKapi')) {
    function _appYonetimKapi()
    {
        if (function_exists('_posKapi')) { $g = _posKapi(); if ($g) return [$g, null]; }
        $p = function_exists('_posPersonel') ? _posPersonel() : null;
        if (!$p) return [redirect('/pos-giris'), null];
        if (!in_array($p->rol, ['sahip', 'mudur'])) return [response('Bu alana sadece işletme sahibi / müdür erişebilir.', 403), null];
        return [null, $p];
    }
}
Route::get('/app-yonetim', function () {
    [$g, $p] = _appYonetimKapi(); if ($g) return $g;
    $sid = $p->sube_id;
    _appBannerEnsure($sid);
    $kartlar = DB::table('app_banner')->where('sube_id', $sid)->orderBy('tip')->orderBy('sira')->orderBy('id')->get();
    $duz = request('duzenle') ? DB::table('app_banner')->where('id', (int) request('duzenle'))->where('sube_id', $sid)->first() : null;
    return view('app_yonetim', compact('kartlar', 'duz'));
});
Route::post('/app-yonetim/kaydet', function (Request $r) {
    [$g, $p] = _appYonetimKapi(); if ($g) return $g;
    $sid = $p->sube_id;
    $gorsel = trim((string) $r->input('gorsel'));
    if ($r->hasFile('gorsel_dosya')) {
        try {
            $f = $r->file('gorsel_dosya');
            $dir = public_path('uploads/app-banner/' . $sid);
            if (!is_dir($dir)) @mkdir($dir, 0775, true);
            $ext = $f->getClientOriginalExtension() ?: 'jpg';
            $name = time() . '_' . \Illuminate\Support\Str::random(6) . '.' . $ext;
            $f->move($dir, $name);
            $gorsel = url('uploads/app-banner/' . $sid . '/' . $name);
        } catch (\Throwable $e) {}
    }
    $data = [
        'sube_id' => $sid,
        'tip' => $r->input('tip') === 'kampanya' ? 'kampanya' : 'hero',
        'baslik' => trim((string) $r->input('baslik')),
        'metin' => trim((string) $r->input('metin')),
        'gorsel' => $gorsel ?: null,
        'detay' => trim((string) $r->input('detay')) ?: null,
        'buton' => trim((string) $r->input('buton')) ?: null,
        'link' => trim((string) $r->input('link')) ?: null,
        'kupon_kodu' => trim((string) $r->input('kupon_kodu')) ?: null,
        'odul_puan' => (int) $r->input('odul_puan', 0),
        'renk' => trim((string) $r->input('renk')) ?: '#14342B',
        'renk2' => trim((string) $r->input('renk2')) ?: null,
        'sira' => (int) $r->input('sira', 1),
        'aktif' => $r->input('aktif') ? 1 : 0,
        'updated_at' => now(),
    ];
    $id = (int) $r->input('id');
    if ($id) DB::table('app_banner')->where('id', $id)->where('sube_id', $sid)->update($data);
    else { $data['created_at'] = now(); DB::table('app_banner')->insert($data); }
    return redirect('/app-yonetim')->with('ay_ok', 'Kart kaydedildi');
});
Route::post('/app-yonetim/sil', function (Request $r) {
    [$g, $p] = _appYonetimKapi(); if ($g) return $g;
    DB::table('app_banner')->where('id', (int) $r->input('id'))->where('sube_id', $p->sube_id)->delete();
