// ==================== ONLINE ODEME (pluggable: Iyzico/PayTR; simulasyon -> anahtar gelince canli) ====================
if (!function_exists('_odemeEnsure')) {
    function _odemeEnsure()
    {
        if (!Schema::hasTable('odeme_islemleri')) {
            Schema::create('odeme_islemleri', function ($t) {
                $t->id(); $t->unsignedBigInteger('sube_id'); $t->unsignedBigInteger('adisyon_id');
                $t->string('token', 40)->index(); $t->decimal('tutar', 12, 2);
                $t->string('saglayici', 20)->default('simulasyon'); $t->string('durum', 15)->default('bekliyor');
                $t->timestamp('created_at')->useCurrent();
            });
        }
        if (!Schema::hasTable('odeme_ayarlari')) {
            Schema::create('odeme_ayarlari', function ($t) {
                $t->id(); $t->unsignedBigInteger('sube_id')->unique();
                $t->string('saglayici', 20)->default('kapali'); $t->boolean('aktif')->default(0);
                $t->string('api_key')->nullable(); $t->string('secret')->nullable(); $t->string('magaza_id')->nullable();
                $t->timestamps();
            });
        }
    }
}
if (!function_exists('_odemeSaglayici')) {
    function _odemeSaglayici($subeId)
    {
        _odemeEnsure();
        $a = DB::table('odeme_ayarlari')->where('sube_id', $subeId)->first();
        if ($a && $a->aktif && $a->saglayici !== 'kapali' && $a->api_key) return $a->saglayici;
        return 'simulasyon';
    }
}
if (!function_exists('_odemeSplitEnsure')) {
    // Kalem-bazli / parcali odeme icin ek kolonlar (idempotent) — masada herkes kendi payini odeyebilsin
    function _odemeSplitEnsure()
    {
        _odemeEnsure();
        if (!Schema::hasColumn('adisyon_kalemleri', 'odeme_durum')) {
            Schema::table('adisyon_kalemleri', function ($t) { $t->string('odeme_durum', 10)->default('acik')->index(); }); // acik | beklemede | odendi
        }
        if (!Schema::hasColumn('adisyon_kalemleri', 'odeme_token')) {
            Schema::table('adisyon_kalemleri', function ($t) { $t->string('odeme_token', 40)->nullable(); });
        }
        if (!Schema::hasColumn('odeme_islemleri', 'kalem_ids')) {
            Schema::table('odeme_islemleri', function ($t) { $t->text('kalem_ids')->nullable(); }); // bu odemenin kapsadigi kalem id'leri (JSON); null = tum hesap
        }
        if (!Schema::hasColumn('odeme_islemleri', 'indirim')) {
            Schema::table('odeme_islemleri', function ($t) { $t->decimal('indirim', 12, 2)->default(0); $t->integer('indirim_kural_id')->nullable(); });
        }
        if (!Schema::hasColumn('odemeler', 'indirim')) {
            Schema::table('odemeler', function ($t) { $t->decimal('indirim', 12, 2)->default(0); });
        }
    }
}
if (!function_exists('_odemeStaleRelease')) {
    // Yarim kalan odemelerin rezerve ettigi kalemleri geri ac. Online (kart) 5 dk; kasa/garson bekleyen 45 dk (garson gelene kadar surebilir).
    function _odemeStaleRelease($adisyonId)
    {
        $eski = DB::table('odeme_islemleri')->where('adisyon_id', $adisyonId)->where('durum', 'bekliyor')
            ->where(function ($w) {
                $w->where(function ($x) { $x->where('saglayici', '!=', 'kasa')->where('created_at', '<', now()->subMinutes(5)); })
                  ->orWhere(function ($x) { $x->where('saglayici', 'kasa')->where('created_at', '<', now()->subMinutes(45)); });
            })->pluck('token')->all();
        if (!$eski) return;
        DB::table('odeme_islemleri')->whereIn('token', $eski)->update(['durum' => 'iptal']);
        DB::table('adisyon_kalemleri')->whereIn('odeme_token', $eski)->where('odeme_durum', 'beklemede')
            ->update(['odeme_durum' => 'acik', 'odeme_token' => null]);
    }
}
if (!function_exists('_masaCagriEnsure')) {
    // masa_cagrilari tablosu + odeme cagrisi icin tutar/token kolonlari (idempotent)
    function _masaCagriEnsure()
    {
        if (!Schema::hasTable('masa_cagrilari')) {
            Schema::create('masa_cagrilari', function ($t) {
                $t->increments('id'); $t->unsignedBigInteger('sube_id'); $t->unsignedBigInteger('masa_id');
                $t->string('tip', 20)->default('garson'); $t->string('durum', 20)->default('bekliyor');
                $t->timestamp('created_at')->useCurrent();
            });
        }
        if (!Schema::hasColumn('masa_cagrilari', 'tutar')) Schema::table('masa_cagrilari', function ($t) { $t->decimal('tutar', 12, 2)->nullable(); });
        if (!Schema::hasColumn('masa_cagrilari', 'odeme_token')) Schema::table('masa_cagrilari', function ($t) { $t->string('odeme_token', 40)->nullable(); });
        if (!Schema::hasColumn('masa_cagrilari', 'hedef_masa_id')) Schema::table('masa_cagrilari', function ($t) { $t->unsignedBigInteger('hedef_masa_id')->nullable(); }); // tasima talebi: gidilecek masa
    }
}
if (!function_exists('_indirimEnsure')) {
    // Yonetilebilir indirim kurallari (her tur icin ayri kayit + aktif/pasif). Idempotent + ilk kurulusta ornek kurallar (hepsi PASIF).
    function _indirimEnsure($subeId = null)
    {
        if (!Schema::hasTable('indirimler')) {
            Schema::create('indirimler', function ($t) {
                $t->increments('id');
                $t->unsignedBigInteger('sube_id')->index();
                $t->string('tip', 24);              // online_odeme|uygulama|kupon|ilk_siparis|tutar_ustu|happy_hour|gun|dogum_gunu
                $t->string('ad', 120);
                $t->string('deger_tipi', 8)->default('yuzde'); // yuzde | tutar
                $t->decimal('deger', 12, 2)->default(0);
                $t->decimal('min_tutar', 12, 2)->nullable();
                $t->decimal('max_indirim', 12, 2)->nullable(); // yuzde indiriminde tavan
                $t->string('kupon_kodu', 40)->nullable();
                $t->string('saat_bas', 5)->nullable();
                $t->string('saat_bit', 5)->nullable();
                $t->string('gun_maskesi', 20)->nullable();     // "1,2,3" (1=pzt ... 7=paz)
                $t->date('baslangic')->nullable();
                $t->date('bitis')->nullable();
                $t->integer('kullanim_limiti')->nullable();
                $t->integer('kullanim_sayisi')->default(0);
                $t->boolean('aktif')->default(0);
                $t->timestamp('created_at')->useCurrent();
            });
        }
        if (Schema::hasTable('indirimler') && !Schema::hasColumn('indirimler', 'urun_ids')) {
            Schema::table('indirimler', function ($t) { $t->text('urun_ids')->nullable(); }); // tip=urun icin secili urun id'leri (JSON)
        }
        if ($subeId && Schema::hasTable('indirimler') && DB::table('indirimler')->where('sube_id', $subeId)->count() === 0) {
            $ornek = [
                ['tip' => 'online_odeme', 'ad' => 'Online Ödeme İndirimi', 'deger_tipi' => 'yuzde', 'deger' => 10],
                ['tip' => 'kupon', 'ad' => 'Hoş Geldin Kuponu', 'deger_tipi' => 'yuzde', 'deger' => 15, 'kupon_kodu' => 'HOSGELDIN'],
                ['tip' => 'uygulama', 'ad' => 'Uygulamadan Sipariş İndirimi', 'deger_tipi' => 'yuzde', 'deger' => 5],
                ['tip' => 'ilk_siparis', 'ad' => 'İlk Sipariş İndirimi', 'deger_tipi' => 'yuzde', 'deger' => 10],
                ['tip' => 'tutar_ustu', 'ad' => '500 TL Üstü İndirim', 'deger_tipi' => 'tutar', 'deger' => 50, 'min_tutar' => 500],
                ['tip' => 'happy_hour', 'ad' => 'Happy Hour (14:00-17:00)', 'deger_tipi' => 'yuzde', 'deger' => 15, 'saat_bas' => '14:00', 'saat_bit' => '17:00'],
                ['tip' => 'gun', 'ad' => 'Salı Günü İndirimi', 'deger_tipi' => 'yuzde', 'deger' => 10, 'gun_maskesi' => '2'],
                ['tip' => 'dogum_gunu', 'ad' => 'Doğum Günü İndirimi', 'deger_tipi' => 'yuzde', 'deger' => 20],
            ];
            foreach ($ornek as $o) {
                DB::table('indirimler')->insert(array_merge(['sube_id' => $subeId, 'aktif' => 0, 'kullanim_sayisi' => 0, 'created_at' => now()], $o));
            }
        }
    }
}
if (!function_exists('_indirimUygula')) {
    // Verilen tutara uygulanabilecek AKTIF kurallardan EN YUKSEK indirimi dondurur.
    // $baglam: yontem, kanal, kupon, ilk_siparis, dogum_gunu, kalemler=[['urun_id','tutar'],...] (tip=urun icin sart)
    // Doner: null | ['indirim'=>x, 'kural_id'=>, 'ad'=>, 'tip'=>]
    function _indirimUygula($subeId, $tutar, $baglam = [])
    {
        _indirimEnsure();
        if ($tutar <= 0) return null;
        $now = now();
        $gun = ($now->dayOfWeekIso); // 1=pzt ... 7=paz
        $saat = $now->format('H:i');
        $kalemler = (isset($baglam['kalemler']) && is_array($baglam['kalemler'])) ? $baglam['kalemler'] : null;
        $enIyi = null;
        foreach (DB::table('indirimler')->where('sube_id', $subeId)->where('aktif', 1)->get() as $k) {
            if ($k->baslangic && $now->lt(\Carbon\Carbon::parse($k->baslangic)->startOfDay())) continue;
            if ($k->bitis && $now->gt(\Carbon\Carbon::parse($k->bitis)->endOfDay())) continue;
            if ($k->kullanim_limiti && $k->kullanim_sayisi >= $k->kullanim_limiti) continue;
            if ($k->min_tutar && $tutar < (float) $k->min_tutar) continue;
            $uygun = false;
            $taban = $tutar; // indirimin uygulanacagi taban (urun bazlida sadece o urunlerin tutari)
            switch ($k->tip) {
                case 'online_odeme': $uygun = (($baglam['yontem'] ?? '') === 'online'); break;
                case 'uygulama':     $uygun = (($baglam['kanal'] ?? '') === 'app'); break;
                case 'kupon':        $uygun = (!empty($baglam['kupon']) && strcasecmp(trim((string) $baglam['kupon']), (string) $k->kupon_kodu) === 0); break;
                case 'ilk_siparis':  $uygun = !empty($baglam['ilk_siparis']); break;
                case 'dogum_gunu':   $uygun = !empty($baglam['dogum_gunu']); break;
                case 'tutar_ustu':   $uygun = true; break; // min_tutar yukarida kontrol edildi
                case 'happy_hour':   $uygun = ($k->saat_bas && $k->saat_bit && $saat >= $k->saat_bas && $saat <= $k->saat_bit); break;
                case 'gun':          $uygun = ($k->gun_maskesi && in_array((string) $gun, array_map('trim', explode(',', (string) $k->gun_maskesi)), true)); break;
                case 'urun':
                    // Indirim SADECE secili urunlerin odenmekte olan tutarina uygulanir
                    $ids = (isset($k->urun_ids) && $k->urun_ids) ? array_map('intval', (array) json_decode($k->urun_ids, true)) : [];
                    if ($ids && is_array($kalemler)) {
                        $taban = 0;
                        foreach ($kalemler as $kl) { if (in_array((int) ($kl['urun_id'] ?? 0), $ids, true)) $taban += (float) ($kl['tutar'] ?? 0); }
                        $uygun = $taban > 0;
                    }
                    break;
            }
            if (!$uygun || $taban <= 0) continue;
            $ind = $k->deger_tipi === 'yuzde' ? round($taban * (float) $k->deger / 100, 2) : min((float) $k->deger, $taban);
            if ($k->max_indirim && $ind > (float) $k->max_indirim) $ind = (float) $k->max_indirim;
            if ($ind > $tutar) $ind = $tutar;
            if ($ind <= 0) continue;
            if (!$enIyi || $ind > $enIyi['indirim']) $enIyi = ['indirim' => $ind, 'kural_id' => (int) $k->id, 'ad' => $k->ad, 'tip' => $k->tip];
        }
        return $enIyi;
    }
}
// Odeme baslat: takip_token VEYA adisyon_id
Route::post('/api/odeme/baslat', function (Request $r) {
    _odemeEnsure();
    $a = null;
    if ($r->filled('takip_token')) $a = DB::table('adisyonlar')->where('takip_token', $r->takip_token)->first();
    elseif ($r->filled('adisyon_id')) $a = DB::table('adisyonlar')->find((int) $r->adisyon_id);
