    $tutar = (float) $a->toplam;
    if ($tutar <= 0) return ['ok' => 0, 'hata' => 'Ödenecek tutar yok'];
    $saglayici = _odemeSaglayici($a->sube_id);
    $token = \Illuminate\Support\Str::random(30);
    DB::table('odeme_islemleri')->insert(['sube_id' => $a->sube_id, 'adisyon_id' => $a->id, 'token' => $token,
        'tutar' => $tutar, 'saglayici' => $saglayici, 'durum' => 'bekliyor', 'created_at' => now()]);
    return ['ok' => 1, 'ode_url' => url('/ode/' . $token), 'saglayici' => $saglayici, 'tutar' => $tutar];
});
// Odeme sayfasi
Route::get('/ode/{token}', function ($token) {
    _odemeEnsure();
    $i = DB::table('odeme_islemleri')->where('token', $token)->first();
    if (!$i) abort(404);
    // Alt menu "Menuye Don" icin masa id
    $masaId = 0;
    if (!empty($i->adisyon_id)) {
        $ad = DB::table('adisyonlar')->find($i->adisyon_id);
        $masaId = ($ad && !empty($ad->masa_id)) ? (int) $ad->masa_id : 0;
    }
    // Alt menudeki asistan butonu MENUYLE AYNI renk olsun (isletme aksani, or. kirmizi)
    $sube = DB::table('subeler')->find($i->sube_id);
    $temalar = resto_temalar();
    $stored = ($sube && isset($sube->tema)) ? $sube->tema : null;
    if ($stored === 'ozel' && !empty($sube->tema_renk)) { $tema = resto_tema_uret($sube->tema_renk, $sube->tema_renk2 ?? null); }
    elseif ($stored && isset($temalar[$stored])) { $tema = $temalar[$stored]; }
    else { $tema = $temalar['altin'] ?? reset($temalar); }
    $aksan = $tema['ana'] ?? '#C41E3A';
    $aksan3 = $tema['ana3'] ?? ($tema['ana2'] ?? $aksan);   // menudeki .qi gradient = ana -> ana3
    return view('odeme', ['islem' => $i, 'sube' => $sube, 'masaId' => $masaId, 'aksan' => $aksan, 'aksan3' => $aksan3]);
});
// Odeme tamamla (CSRF muaf: ode/*) — simulasyon basarili; gercek saglayici callback'i buraya baglanir
Route::post('/ode/{token}/tamamla', function (Request $r, $token) {
    _odemeEnsure();
    _odemeSplitEnsure();
    $i = DB::table('odeme_islemleri')->where('token', $token)->first();
    if (!$i) return response()->json(['ok' => 0], 404);
    if ($i->durum === 'odendi') return ['ok' => 1, 'mesaj' => 'Zaten ödendi'];
    // CÜZDAN YÜKLEME ödemesi -> bakiyeye yükle (adisyon değil). Gerçek sağlayıcıda imzalı callback şart.
    if (($i->tur ?? 'adisyon') === 'cuzdan' && !empty($i->musteri_id)) {
        if (_odemeSaglayici($i->sube_id) !== 'simulasyon') {
            $imzaGecerli = false; // TODO: PayTR/iyzico callback imza/hash doğrulaması
            if (!$imzaGecerli) return response()->json(['ok' => 0, 'hata' => 'Ödeme sağlayıcı doğrulaması bekleniyor.'], 402);
        }
        $tutar = (float) $i->tutar;
        $bonus = _cuzdanBonus($i->sube_id, $tutar);
        $yeni = round((float) (DB::table('musteriler')->where('id', $i->musteri_id)->value('cuzdan_bakiye') ?? 0) + $tutar + $bonus, 2);
        DB::table('musteriler')->where('id', $i->musteri_id)->update(['cuzdan_bakiye' => $yeni]);
        if (Schema::hasTable('cuzdan_hareketleri')) {
            DB::table('cuzdan_hareketleri')->insert(['musteri_id' => $i->musteri_id, 'tip' => 'yukleme', 'tutar' => $tutar + $bonus, 'bakiye_sonra' => $yeni,
                'aciklama' => $bonus > 0 ? "Yükleme {$tutar}₺ (+{$bonus}₺ bonus)" : "Yükleme {$tutar}₺", 'created_at' => now(), 'updated_at' => now()]);
        }
        DB::table('odeme_islemleri')->where('id', $i->id)->update(['durum' => 'odendi']);
        return ['ok' => 1, 'mesaj' => 'Cüzdan yüklendi 🎉', 'bakiye' => $yeni];
    }
    $a = DB::table('adisyonlar')->find($i->adisyon_id);
    if ($a) {
        // GÜVENLİK: gerçek sağlayıcı (Iyzico/PayTR) yapılandırılmışsa ödeme ancak sağlayıcı İMZALI callback ile kapanır.
        // Simülasyon modu = demo (gerçek para kasadan authed tahsil edilir). İmza doğrulaması entegrasyonda doldurulur.
        if (_odemeSaglayici($a->sube_id) !== 'simulasyon') {
            $imzaGecerli = false; // TODO: Iyzico/PayTR 3D callback imza/hash doğrulaması
            if (!$imzaGecerli) return response()->json(['ok' => 0, 'hata' => 'Ödeme sağlayıcı doğrulaması bekleniyor. (Doğrulanmamış tahsilat kabul edilmez.)'], 402);
        }
        $indirim = isset($i->indirim) ? (float) $i->indirim : 0;
        DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => 'online', 'tutar' => $i->tutar, 'indirim' => $indirim, 'created_at' => now()]);
        // Verilen indirim adisyonun indirimine eklenir + toplam yeniden hesaplanir (tahsilat acigi gorunmesin) + kupon kullanimi sayilir
        if ($indirim > 0) {
            DB::table('adisyonlar')->where('id', $a->id)->increment('indirim', $indirim);
            $a = DB::table('adisyonlar')->find($a->id);
            $yeniToplam = max(0, (float) $a->ara_toplam - (float) $a->indirim - (float) $a->ikram);
            DB::table('adisyonlar')->where('id', $a->id)->update(['toplam' => $yeniToplam]);
            if (!empty($i->indirim_kural_id)) DB::table('indirimler')->where('id', $i->indirim_kural_id)->increment('kullanim_sayisi');
        }
        // Bu odemenin kapsadigi kalemleri 'odendi' yap (parcali odeme). kalem_ids yoksa (mobil/eski akis) tum adisyon.
        $kids = (isset($i->kalem_ids) && $i->kalem_ids) ? json_decode($i->kalem_ids, true) : null;
        if (is_array($kids) && $kids) {
            DB::table('adisyon_kalemleri')->whereIn('id', $kids)->update(['odeme_durum' => 'odendi', 'odeme_token' => null, 'updated_at' => now()]);
        } else {
            DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->update(['odeme_durum' => 'odendi', 'updated_at' => now()]);
        }
        _onOdemePromote($a, $kids); // ON ODEME: odenen 'odeme_bekliyor' kalemler simdi mutfaga dussun
        // Odenmemis kalem kaldi mi? Kalmadiysa adisyonu kapat + masayi bosalt (yoksa acik kalir, digerleri oder)
        $acikKalan = DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->where('odeme_durum', '!=', 'odendi')->count();
        if ($acikKalan === 0 && $a->durum !== 'odendi') {
            DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'odendi', 'kapanis' => now(), 'updated_at' => now()]);
            if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
        }
    }
    DB::table('odeme_islemleri')->where('id', $i->id)->update(['durum' => 'odendi']);
    return ['ok' => 1, 'mesaj' => 'Ödeme başarılı'];
});
