// Musteri sorusu -> MusteriAsistan (menu/oneri/kalip/garson)
Route::post('/api/qr/asistan', function (Request $r) {
    $masa = DB::table('masalar')->find((int) $r->masa);
    $subeId = $masa ? $masa->sube_id : DB::table('subeler')->value('id');
    $dil = preg_replace('/[^a-z]/', '', strtolower((string) $r->input('dil', 'tr')));
    $kodlar = _qrDilKodlari();
    if (!isset($kodlar[$dil])) $dil = 'tr';
    $a = new \App\Services\MusteriAsistan($subeId);
    $soru = (string) $r->soru;
    // COK DILLI: yabanci soru -> Turkce (motor Turkce calisir); cevap -> tekrar o dile.
    if ($dil !== 'tr' && $soru !== '') $soru = _qrCevir($soru, 'tr', $dil);
    $res = $a->cevapla($soru, (string) $r->input('baglam', ''));
    if ($dil !== 'tr' && is_array($res)) {
        $parts = [(string) ($res['cevap'] ?? '')];
        $idx = [];
        if (!empty($res['kartlar']) && is_array($res['kartlar'])) {
            foreach ($res['kartlar'] as $i => $k) {
                if (!empty($k['aciklama'])) { $idx[] = $i; $parts[] = (string) $k['aciklama']; }
            }
        }
        $cev = _qrCevirCoklu($parts, $dil, 'tr');
        if (is_array($cev) && count($cev) === count($parts)) {
            $res['cevap'] = $cev[0];
            foreach ($idx as $n => $ki) $res['kartlar'][$ki]['aciklama'] = $cev[$n + 1];
        }
        $res['dil'] = $dil;
    }
    return $res;
});

// Istemci metinlerini (karsilama/sistem/arayuz) hedef dile cevir; tekil (metin) veya toplu (metinler=JSON dizi)
Route::post('/api/qr/cevir', function (Request $r) {
    $hedef = preg_replace('/[^a-z]/', '', strtolower((string) $r->input('hedef', 'tr')));
    if ($r->filled('metinler')) {
        $arr = json_decode((string) $r->input('metinler'), true);
        if (!is_array($arr)) $arr = [];
        if ($hedef === 'tr' || $hedef === '' || empty($arr)) return response()->json(['metinler' => $arr]);
        $out = [];
        foreach (array_chunk($arr, 100) as $c) $out = array_merge($out, _qrCevirCoklu($c, $hedef, 'tr'));
        return response()->json(['metinler' => (count($out) === count($arr)) ? $out : $arr]);
    }
    $metin = trim((string) $r->input('metin', ''));
    if ($metin === '' || $hedef === 'tr' || $hedef === '') return response()->json(['metin' => $metin]);
    return response()->json(['metin' => _qrCevir($metin, $hedef, 'tr')]);
});

