// ---- COK DILLI destek: dil -> STT/TTS kodlari + Google Translate cevirmen ----
if (!function_exists('_qrDilKodlari')) {
    function _qrDilKodlari()
    {
        return [
            'tr' => ['stt' => 'tr-TR', 'tts' => 'tr-TR-Wavenet-D'],
            'en' => ['stt' => 'en-US', 'tts' => 'en-US-Wavenet-D'],
            'ar' => ['stt' => 'ar-SA', 'tts' => 'ar-XA-Wavenet-B'],
            'de' => ['stt' => 'de-DE', 'tts' => 'de-DE-Wavenet-B'],
            'ru' => ['stt' => 'ru-RU', 'tts' => 'ru-RU-Wavenet-D'],
            'es' => ['stt' => 'es-ES', 'tts' => 'es-ES-Wavenet-B'],
            'fr' => ['stt' => 'fr-FR', 'tts' => 'fr-FR-Wavenet-D'],
            'nl' => ['stt' => 'nl-NL', 'tts' => 'nl-NL-Wavenet-B'],
            'it' => ['stt' => 'it-IT', 'tts' => 'it-IT-Wavenet-C'],
            'uk' => ['stt' => 'uk-UA', 'tts' => 'uk-UA-Wavenet-A'],
        ];
    }
}
if (!function_exists('_qrCevirCoklu')) {
    function _qrCevirCoklu(array $metinler, $hedef, $kaynak = '')
    {
        $key = (string) config('services.google_tts.key', '');
        if ($key === '' || $hedef === $kaynak || empty($metinler)) return $metinler;
        $payload = ['q' => array_values($metinler), 'target' => $hedef, 'format' => 'text'];
        if ($kaynak) $payload['source'] = $kaynak;
        try {
            $ch = curl_init('https://translation.googleapis.com/language/translate/v2?key=' . $key);
            curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload), CURLOPT_TIMEOUT => 10]);
            $resp = curl_exec($ch);
            curl_close($ch);
            $j = json_decode($resp, true);
            $tr = $j['data']['translations'] ?? null;
            if (!is_array($tr) || count($tr) !== count($metinler)) return $metinler;
            $out = [];
            foreach ($tr as $t) $out[] = (string) ($t['translatedText'] ?? '');
            return $out;
        } catch (\Throwable $e) {
            return $metinler;
        }
    }
}
if (!function_exists('_qrCevir')) {
    function _qrCevir($metin, $hedef, $kaynak = '')
    {
        $r = _qrCevirCoklu([(string) $metin], $hedef, $kaynak);
        return $r[0] ?? (string) $metin;
    }
}
// Tum menuyu (kategori + urun ad/aciklama) hedef dile cevir — ONBELLEKLI (bir kez cevir, tekrar kullan).
if (!function_exists('_qrMenuCevir')) {
    function _qrMenuCevir($kategoriler, $subeId, $dil)
    {
        if ($dil === 'tr' || !is_array($kategoriler) || empty($kategoriler)) return $kategoriler;
        $metinler = [];
        $harita = [];
        foreach ($kategoriler as $ki => $k) {
            if (!empty($k['ad'])) { $harita[] = ['k', $ki, 'ad']; $metinler[] = (string) $k['ad']; }
            foreach (($k['kartlar'] ?? []) as $ci => $c) {
                if (!empty($c['ad'])) { $harita[] = ['c', $ki, $ci, 'ad']; $metinler[] = (string) $c['ad']; }
                if (!empty($c['aciklama'])) { $harita[] = ['c', $ki, $ci, 'aciklama']; $metinler[] = (string) $c['aciklama']; }
            }
        }
        if (empty($metinler)) return $kategoriler;
        $hash = md5($dil . '|' . implode('~', $metinler));
        try {
            if (!Schema::hasTable('qr_menu_ceviri')) {
                Schema::create('qr_menu_ceviri', function ($t) {
                    $t->bigIncrements('id');
                    $t->unsignedBigInteger('sube_id')->nullable();
                    $t->string('dil', 5);
                    $t->string('hash', 32);
                    $t->longText('icerik');
                    $t->index(['sube_id', 'dil']);
                });
            }
            $c = DB::table('qr_menu_ceviri')->where('sube_id', $subeId)->where('dil', $dil)->where('hash', $hash)->value('icerik');
            if ($c) { $d = json_decode($c, true); if (is_array($d)) return $d; }
        } catch (\Throwable $e) {
        }
        $cevrilen = [];
        foreach (array_chunk($metinler, 100) as $chunk) {
            $cevrilen = array_merge($cevrilen, _qrCevirCoklu($chunk, $dil, 'tr'));
        }
        if (count($cevrilen) !== count($metinler)) return $kategoriler; // ceviri basarisiz -> orijinal
        foreach ($harita as $i => $h) {
            if ($h[0] === 'k') $kategoriler[$h[1]][$h[2]] = $cevrilen[$i];
            else $kategoriler[$h[1]]['kartlar'][$h[2]][$h[3]] = $cevrilen[$i];
        }
        try {
            DB::table('qr_menu_ceviri')->where('sube_id', $subeId)->where('dil', $dil)->delete();
            DB::table('qr_menu_ceviri')->insert(['sube_id' => $subeId, 'dil' => $dil, 'hash' => $hash, 'icerik' => json_encode($kategoriler)]);
        } catch (\Throwable $e) {
        }
        return $kategoriler;
    }
}

// Gunluk STT kullanim sayaci (MALIYET TAVANI icin)
if (!function_exists('_sttTabloEnsure')) {
    function _sttTabloEnsure()
    {
        if (!Schema::hasTable('stt_kullanim')) {
            Schema::create('stt_kullanim', function ($t) {
                $t->bigIncrements('id');
                $t->unsignedBigInteger('sube_id')->nullable();
                $t->unsignedBigInteger('masa_id')->nullable();
                $t->string('gun', 10);
                $t->integer('adet')->default(0);
                $t->index(['sube_id', 'gun']);
                $t->index(['sube_id', 'masa_id', 'gun']);
            });
        }
    }
}

// Sesli tanima (STT): tarayici WAV kaydini Google Speech-to-Text'e gonderir -> metin.
// Her cihazda (iPhone dahil) deterministik calisir; tarayici Web Speech API kirilganligi biter.
// MALIYET TAVANI: gunluk sube + masa limiti; asilinca Google'a HIC gitmez (ucret YOK), sesli->yaziya duser.
Route::post('/api/qr/stt', function (Request $r) {
    $key = (string) config('services.google_tts.key', '');
    if ($key === '') return response()->json(['metin' => '', 'hata' => 'stt_anahtar_yok'], 200);
    if (!$r->hasFile('ses')) return response()->json(['metin' => '', 'hata' => 'ses_yok'], 200);
    $bytes = @file_get_contents($r->file('ses')->getRealPath());
    if ($bytes === false || strlen($bytes) < 800) return response()->json(['metin' => ''], 200); // cok kisa/bos
    // ---- MALIYET TAVANI: gunluk sube + masa limiti (asilinca Google cagrilmaz -> ucret yok) ----
    $masa = $r->filled('masa') ? DB::table('masalar')->find((int) $r->input('masa')) : null;
    $subeId = $masa ? (int) $masa->sube_id : (int) DB::table('subeler')->value('id');
    $masaId = $masa ? (int) $masa->id : 0;
    _sttTabloEnsure();
    $bugun = now()->toDateString();
    $subeLimit = (int) resto_ayar_al('stt_gunluk_sube_limit', 1500);
    $masaLimit = (int) resto_ayar_al('stt_gunluk_masa_limit', 150);
    if ($subeLimit > 0) {
        $subeToplam = (int) DB::table('stt_kullanim')->where('sube_id', $subeId)->where('gun', $bugun)->sum('adet');
        if ($subeToplam >= $subeLimit) return response()->json(['metin' => '', 'limit' => true], 200);
    }
    $mrow = DB::table('stt_kullanim')->where('sube_id', $subeId)->where('masa_id', $masaId)->where('gun', $bugun)->first();
    if ($masaLimit > 0 && $mrow && (int) $mrow->adet >= $masaLimit) return response()->json(['metin' => '', 'limit' => true], 200);
    if ($mrow) DB::table('stt_kullanim')->where('id', $mrow->id)->update(['adet' => (int) $mrow->adet + 1]);
    else DB::table('stt_kullanim')->insert(['sube_id' => $subeId, 'masa_id' => $masaId, 'gun' => $bugun, 'adet' => 1]);
    // Dil: istemcinin aktif dili birincil; otomatik algilama icin birkac alternatif (Google en fazla 3 alternatif).
    $dil = preg_replace('/[^a-z]/', '', strtolower((string) $r->input('dil', 'tr')));
    $kodlar = _qrDilKodlari();
    if (!isset($kodlar[$dil])) $dil = 'tr';
    $cfg = [
        'encoding' => 'LINEAR16',
        'sampleRateHertz' => 16000,
        'languageCode' => $kodlar[$dil]['stt'],
        'model' => 'latest_short',
        'enableAutomaticPunctuation' => true,
        'maxAlternatives' => 1,
    ];
    // Otomatik dil KARISTIRMA yok (yanlis dil algilamayi + dogruluk kaybini onler): tek dil = secili dil.
    // NOT: Menu adlarini "speechContexts + boost 16" ile ipucu vermek HER konusmayi urun adina zorluyordu
    // ("hesap alabilir miyim" -> rastgele urun) = kullanici "kafasina gore konusuyor" sikayeti.
    // Cozum: cok daha HAFIF boost (2) ve sadece birkac genel komut ipucu. Uzun urun listesi HIC verilmiyor.
    $cfg['speechContexts'] = [['phrases' => ['garson', 'hesap', 'menü', 'öneri', 'evet', 'hayır', 'teşekkürler'], 'boost' => 2]];
    $payload = ['config' => $cfg, 'audio' => ['content' => base64_encode($bytes)]];
    try {
        $ch = curl_init('https://speech.googleapis.com/v1/speech:recognize?key=' . $key);
        curl_setopt_array($ch, [
            CURLOPT_POST => true,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER => ['Content-Type: application/json'],
            CURLOPT_POSTFIELDS => json_encode($payload),
            CURLOPT_TIMEOUT => 15,
        ]);
        $resp = curl_exec($ch);
        $kod = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        $j = json_decode($resp, true);
        $metin = $j['results'][0]['alternatives'][0]['transcript'] ?? '';
        $algDil = strtolower(substr((string) ($j['results'][0]['languageCode'] ?? $kodlar[$dil]['stt']), 0, 2));
        if (!isset($kodlar[$algDil])) $algDil = $dil;
        return response()->json(['metin' => trim((string) $metin), 'dil' => $algDil, 'kod' => $kod]);
    } catch (\Throwable $e) {
        return response()->json(['metin' => '', 'hata' => 'stt_hata'], 200);
    }
});

// ============ ONE CIKAN URUN / GUNUN ONERISI YONETIMI (isletme onceden girer, asistan okur) ============
