// GARSON EKRANI: kasada/garsonda odemeyi SEÇİLEN YÖNTEMLE tahsil et (nakit -> kasaya yazilir). Kalemleri odendi yapar, hepsi bitince masa kapanir.
Route::post('/api/qr/kasa-tahsil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _odemeSplitEnsure();
    $tip = in_array($r->odeme_tip, ['nakit', 'kredi', 'yemek_karti'], true) ? $r->odeme_tip : 'nakit';
    $token = (string) $r->odeme_token;
    if ($token === '' && $r->filled('cagri_id')) $token = (string) DB::table('masa_cagrilari')->where('id', (int) $r->cagri_id)->value('odeme_token');
    if ($token === '') return ['ok' => 0, 'hata' => 'Ödeme bulunamadı'];
    $i = DB::table('odeme_islemleri')->where('token', $token)->first();
    if (!$i) return ['ok' => 0, 'hata' => 'Ödeme bulunamadı'];
    if ($i->durum === 'odendi') { DB::table('masa_cagrilari')->where('odeme_token', $token)->update(['durum' => 'karsilandi']); return ['ok' => 1, 'mesaj' => 'Zaten tahsil edilmiş']; }
    if ($i->durum !== 'bekliyor') return ['ok' => 0, 'hata' => 'Bu ödeme talebi zaman aşımına uğramış; müşteri tekrar başlatmalı.'];

    $a = DB::table('adisyonlar')->find($i->adisyon_id);
    if ($a) {
        DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => $tip, 'tutar' => $i->tutar, 'created_at' => now()]);
        if ($tip === 'nakit' && function_exists('_kasaYaz')) _kasaYaz($a->sube_id, 'satis', 'giris', $i->tutar, 'QR masa nakit tahsilat · adisyon #' . $a->id, 'adisyon', $a->id, $p->id);
        $kids = (isset($i->kalem_ids) && $i->kalem_ids) ? json_decode($i->kalem_ids, true) : null;
        if (is_array($kids) && $kids) {
            DB::table('adisyon_kalemleri')->whereIn('id', $kids)->where('odeme_token', $token)->update(['odeme_durum' => 'odendi', 'odeme_token' => null, 'updated_at' => now()]);
        } else {
            DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->update(['odeme_durum' => 'odendi', 'updated_at' => now()]);
        }
        _onOdemePromote($a, $kids); // ON ODEME: garson tahsil edince de kalemler mutfaga dussun
        $acikKalan = DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->where('odeme_durum', '!=', 'odendi')->count();
        if ($acikKalan === 0 && $a->durum !== 'odendi') {
            DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'odendi', 'kapanis' => now(), 'updated_at' => now()]);
            if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
        }
    }
    DB::table('odeme_islemleri')->where('id', $i->id)->update(['durum' => 'odendi']);
    DB::table('masa_cagrilari')->where('odeme_token', $token)->update(['durum' => 'karsilandi']);
    $etiket = ['nakit' => 'Nakit', 'kredi' => 'Kredi Kartı', 'yemek_karti' => 'Yemek Kartı'][$tip];
    return ['ok' => 1, 'mesaj' => number_format((float) $i->tutar, 0, ',', '.') . ' TL ' . $etiket . ' ile tahsil edildi.'];
});

// Sunucu TTS (Google Cloud, kaliteli ERKEK ses) -> MP3 URL (onbellekli). Anahtar yoksa basarili=false.
Route::match(['get', 'post'], '/api/tts', function (Request $r) {
    $metin = trim((string) $r->input('metin', ''));
    if ($metin === '') return response()->json(['basarili' => false], 422);
    if (mb_strlen($metin) > 2000) $metin = mb_substr($metin, 0, 2000);
    // Hangi restoran/sube? -> her sube kendi aylik limitine sayilir (multi-tenant)
    $subeId = null;
    if ($r->filled('masa')) { $m = DB::table('masalar')->find((int) $r->input('masa')); $subeId = $m ? $m->sube_id : null; }
    elseif ($r->filled('sube')) { $subeId = (int) $r->input('sube'); }
    $servis = new \App\Services\SeslendirmeServisi($subeId);
    $ses = $r->input('ses');
    // COK DILLI: dil verildiyse o dilin sesini sec (tr'de patronun sectigi kalici ses).
    $dil = preg_replace('/[^a-z]/', '', strtolower((string) $r->input('dil', 'tr')));
    if (!$ses && $dil && $dil !== 'tr') { $kd = _qrDilKodlari(); if (isset($kd[$dil])) $ses = $kd[$dil]['tts']; }
    if (!$ses) $ses = resto_ayar_al('tts_ses', null); // patronun sectigi kalici ses (yoksa config varsayilani)
    $ad = $servis->uret($metin, $ses);
    if (!$ad) return response()->json(['basarili' => false, 'anahtar_var' => (string) config('services.google_tts.key', '') !== ''], 200);
    return response()->json(['basarili' => true, 'url' => url('/api/ses/' . $ad)]);
});
Route::get('/api/ses/{ad}', function ($ad) {
    $servis = new \App\Services\SeslendirmeServisi();
    $yol = $servis->dosyaYolu($ad);
    if (!$yol) abort(404);
    return response()->file($yol, ['Content-Type' => 'audio/mpeg', 'Cache-Control' => 'public, max-age=31536000']);
})->where('ad', '[a-f0-9]{32}\.mp3');

// ---- Ayarlar (anahtar-deger) yardimcilari: secilen TTS sesi burada saklanir ----
if (!function_exists('resto_ayar_al')) {
    function resto_ayar_tablo()
    {
        if (!Schema::hasTable('ayarlar')) {
            Schema::create('ayarlar', function ($t) {
                $t->string('anahtar', 60)->primary();
                $t->text('deger')->nullable();
            });
        }
    }
    function resto_ayar_al($anahtar, $vars = null)
    {
        resto_ayar_tablo();
        $v = DB::table('ayarlar')->where('anahtar', $anahtar)->value('deger');
        return ($v === null || $v === '') ? $vars : $v;
    }
    function resto_ayar_yaz($anahtar, $deger)
    {
        resto_ayar_tablo();
        DB::table('ayarlar')->updateOrInsert(['anahtar' => $anahtar], ['deger' => $deger]);
    }
}

// ==================== WHATSAPP SİPARİŞ (whatsmeow sidecar · HİBRİT) ====================
// Mevcut paket + app_siparis + MusteriAsistan beynini WhatsApp kanalina baglar.
// Hibrit: selam/anahtar -> siparis linki (app_siparis); serbest metin -> MusteriAsistan (kural motoru bedava, Haiku kaçakta).
// Siparis olusunca onay + durum degisince canli takip bildirimi musteriye WA'dan gider.
// GUARD: sidecar/ayar yoksa _restoWaGonder sessizce false doner; tum cagirici noktalar try/catch -> mevcut akis ASLA kirilmaz.
if (!function_exists('_waTelNorm')) {
    // Telefon -> 905xxxxxxxxx (bridge formati). Gecersizse ''.
    function _waTelNorm($tel)
    {
        $d = preg_replace('/\D+/', '', (string) $tel);
        if ($d === '') return '';
        if (strlen($d) === 10 && $d[0] === '5') $d = '90' . $d;              // 5xxxxxxxxx
        elseif (strlen($d) === 11 && $d[0] === '0') $d = '90' . substr($d, 1); // 05xxxxxxxxx
        return $d;
    }
}
if (!function_exists('_restoWaGonder')) {
    // Outbound: musteriye WA mesaji (whatsmeow bridge). Konfig yoksa / hata -> false (sessiz).
    function _restoWaGonder($subeId, $tel, $mesaj)
    {
        // KONTÖR: kontörlü dönemde bakiye yoksa gönderme (ücretsiz/deneme döneminde her zaman geçer).
        if (!\App\Services\KontorServisi::yeterliMi($subeId)) return false;
        $base = rtrim((string) resto_ayar_al('wa_sidecar_url', ''), '/');
        $token = (string) resto_ayar_al('wa_servis_token', '');
        // Tam JID geldiyse (or. LID "<lid>@lid") dokunma; degilse numarayi normalize et
        $jid = (strpos((string) $tel, '@') !== false) ? (string) $tel : _waTelNorm($tel);
        if ($base === '' || $jid === '' || trim((string) $mesaj) === '') return false;
        try {
            $ch = curl_init($base . '/session/' . (int) $subeId . '/send');
            curl_setopt_array($ch, [
                CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 8, CURLOPT_POST => true,
                CURLOPT_HTTPHEADER => ['Content-Type: application/json', 'Accept: application/json', 'X-Service-Token: ' . $token],
                // whatsmeow bridge send sozlesmesi: {to, message, logId, urgent}
                // urgent=true -> bridge'in 12-30sn anti-burst beklemesini ATLAR (interaktif cevap, aninda gider)
                CURLOPT_POSTFIELDS => json_encode(['to' => $jid, 'message' => (string) $mesaj, 'logId' => 0, 'urgent' => true], JSON_UNESCAPED_UNICODE),
            ]);
            curl_exec($ch);
            $kod = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            $ok = $kod >= 200 && $kod < 300;
            if ($ok) { try { \App\Services\KontorServisi::dus($subeId, 1, 'whatsapp-mesaj'); } catch (\Throwable $e) {} } // 1 mesaj = 1 kontör
            try { _waLog($subeId, $jid, (string) $mesaj, $ok ? 1 : 2, $ok ? null : ('http ' . $kod)); } catch (\Throwable $e) {} // istatistik logu
            return $ok;
        } catch (\Throwable $e) { return false; }
    }
}
// WhatsApp mesaj logu (istatistik: başarılı/başarısız + günlük hacim grafiği)
if (!function_exists('_waLogEnsure')) {
    function _waLogEnsure()
    {
        if (!Schema::hasTable('wa_mesaj_loglari')) {
            try {
                Schema::create('wa_mesaj_loglari', function ($t) {
                    $t->increments('id');
                    $t->unsignedBigInteger('sube_id')->index();
                    $t->string('telefon', 40)->nullable()->index();
                    $t->string('yon', 8)->default('giden'); // giden|gelen
                    $t->tinyInteger('durum')->default(1);    // 1 gönderildi · 2 başarısız · 3 SMS'e düştü · 0 kuyrukta
                    $t->text('mesaj')->nullable();
                    $t->string('hata', 160)->nullable();
                    $t->timestamp('created_at')->nullable()->index();
                });
            } catch (\Throwable $e) {
            }
        }
    }
}
if (!function_exists('_waLog')) {
    function _waLog($subeId, $tel, $mesaj, $durum = 1, $hata = null, $yon = 'giden')
    {
        // HIZ: her mesajda hasTable (information_schema) sorgusu YAPMA; direkt insert dene,
        // sadece tablo yoksa (ilk sefer) oluştur + tekrar dene.
        $row = [
            'sube_id' => (int) $subeId, 'telefon' => mb_substr((string) $tel, 0, 40), 'yon' => $yon,
