        ];
        try {
            DB::table('wa_mesaj_loglari')->insert($row);
        } catch (\Throwable $e) {
            _waLogEnsure();
            try { DB::table('wa_mesaj_loglari')->insert($row); } catch (\Throwable $e2) {}
        }
    }
}
