// İNSAN DEVRALMA: eski kurulumlarda wa_oturumlari'nda kolon olmayabilir; ilk yazimda bir kez ekle (self-healing).
if (!function_exists('_waDevralmaYaz')) {
    function _waDevralmaKolonEkle()
    {
        try {
