}
if (!function_exists('_waUrunBul')) {
    // Metin parcasini sube urunlerinden en spesifik (en uzun ad) eslesme ile bul.
    function _waUrunBul($subeId, $parca)
    {
        $p = _waNorm($parca);
        if ($p === '' || mb_strlen($p) < 2) return null;
        $urunler = DB::table('urunler')->where('sube_id', $subeId)->where('aktif', 1)->get(['id', 'ad', 'fiyat', 'tukendi']);
        $best = null; $bestLen = 0;
        foreach ($urunler as $u) {
            $n = _waNorm($u->ad);
            if ($n === '') continue;
            // KELİME SINIRLI eşleşme — "su" artık "yapıyorSUnuz" içinde eşleşmez
            $eslesti = false;
            if ($p === $n) $eslesti = true;                                                              // birebir
            elseif (mb_strlen($n) >= 3 && preg_match('/\b' . preg_quote($n, '/') . '\b/u', $p)) $eslesti = true; // ürün adı metinde TAM kelime
            elseif (mb_strlen($p) >= 4 && preg_match('/\b' . preg_quote($p, '/') . '/u', $n)) $eslesti = true;   // kullanıcı kısa yazdı, ürün adının kelime başı
            if ($eslesti && mb_strlen($n) > $bestLen) { $best = $u; $bestLen = mb_strlen($n); }
        }
        return $best;
    }
}
if (!function_exists('_waSepetParse')) {
    // "2 adana, 1 ayran" / "köfte x2" -> [items[], bulunamayan[]]
    function _waSepetParse($subeId, $text)
    {
        $parts = preg_split('/[\n,;]+|\bve\b|\+/u', (string) $text);
        $items = []; $bulunamayan = [];
        foreach ((array) $parts as $frag) {
            $frag = trim((string) $frag);
            if ($frag === '') continue;
            $adet = 1;
            if (preg_match('/^\s*(\d{1,2})\s*(?:adet|tane|x|\*|porsiyon)?\s+(.+)$/iu', $frag, $m)) { $adet = max(1, min(50, (int) $m[1])); $frag = $m[2]; }
            elseif (preg_match('/^(.+?)\s*[x\*]\s*(\d{1,2})$/iu', $frag, $m)) { $frag = $m[1]; $adet = max(1, min(50, (int) $m[2])); }
            $u = _waUrunBul($subeId, $frag);
            if ($u) {
                if ($u->tukendi) { $bulunamayan[] = $u->ad . ' (tükendi)'; continue; }
                $items[] = ['urun_id' => (int) $u->id, 'ad' => $u->ad, 'fiyat' => (float) $u->fiyat, 'adet' => $adet];
            } elseif (mb_strlen(_waNorm($frag)) >= 3) {
                $bulunamayan[] = $frag;
            }
        }
        return ['items' => $items, 'bulunamayan' => $bulunamayan];
    }
}
if (!function_exists('_waSepetMetni')) {
    // Modern/temiz sepet karti (WhatsApp *kalin* + hizalı)
    function _waSepetMetni($sepet)
    {
        if (empty($sepet)) return "🛒 Sepetiniz henüz boş.";
        $l = "🧾 *SİPARİŞİNİZ*\n"; $top = 0;
        foreach ($sepet as $it) {
            $tut = (float) $it['fiyat'] * (int) $it['adet']; $top += $tut;
            $l .= "\n*" . $it['adet'] . '×* ' . $it['ad'] . "\n" . '       ' . number_format($tut, 0, ',', '.') . " ₺\n";
        }
        $l .= "\n━━━━━━━━━━━━━\n*Toplam:  " . number_format($top, 0, ',', '.') . " ₺*";
        return $l;
    }
    // Onay oncesi tam ozet
    function _waOzetMetni($sepet, $adres, $odeme)
    {
        return _waSepetMetni($sepet)
            . "\n\n📍 *Adres:*  " . $adres
            . "\n💳 *Ödeme:*  " . ($odeme === 'nakit' ? 'Kapıda nakit' : 'Kapıda kart');
    }
    function _waSepetBirlestir($sepet, $yeni)
    {
        $map = [];
        foreach ((array) $sepet as $it) { $map[$it['urun_id']] = $it; }
        foreach ($yeni as $it) { if (isset($map[$it['urun_id']])) { $map[$it['urun_id']]['adet'] += $it['adet']; } else { $map[$it['urun_id']] = $it; } }
        return array_values($map);
    }
    // ---- Dogal dil niyet tespiti (yanlis/degisik yazilsa da anla; "soyle yazin" demeyiz) ----
    function _waIcerirMi($tl, array $anahtarlar)
    {
        foreach ($anahtarlar as $k) { if ($tl === $k || mb_strpos($tl, $k) !== false) return true; }
        return false;
    }
    function _waIptalMi($tl) { return _waIcerirMi($tl, ['iptal', 'vazgec', 'vazgectim', 'siparisi iptal', 'iptal et']); }
    function _waOnayMi($tl)  { return _waIcerirMi($tl, ['onayla', 'onayliyorum', 'onaylyorum', 'onaylarim', 'onaydir', 'evet', 'evt', 'olur', 'oldu', 'tamam', 'tamamdir', 'ok', 'okey', 'okay', 'tabi', 'tabii', 'kesinlikle', 'elbette', 'uygun', 'gonder', 'ver', 'gecelim', 'devam', 'onaylyoruz', 'onaylyoz', 'hadi', 'bastan al']); }
    function _waOlumsuzMu($tl) { return _waIcerirMi($tl, ['hayir', 'yok', 'istemiyorum', 'olmaz', 'vazgectim', 'gerek yok', 'bosver', 'yanlis']); }
    function _waBittiMi($tl) { return _waIcerirMi($tl, ['tamam', 'bu kadar', 'bukadar', 'yeter', 'yeterli', 'bitti', 'bitir', 'devam', 'tamamla', 'hepsi bu', 'baska yok', 'yok baska', 'siparisi tamamla', 'gecelim', 'hazir', 'hazirim', 'odeme', 'adres']); }
    function _waOdemeTipi($tl)
    {
        if (_waIcerirMi($tl, ['nakit', 'cash', 'pesin'])) return 'nakit';
        if (_waIcerirMi($tl, ['kart', 'kredi', 'pos', 'banka'])) return 'kart_kapida';
        return null;
    }
}
if (!function_exists('_waSiparisOlustur')) {
    // WhatsApp sepetinden paket adisyonu olustur (app_siparis ile ayni semayi kullanir, platform=whatsapp).
    function _waSiparisOlustur($s, $ad, $tel, $adres, $sepet, $odeme)
    {
        if (empty($sepet)) return null;
        _appEnsure(); _calleridEnsure();
        $norm = _telNorm($tel);
        $m = $norm ? DB::table('musteriler')->where('sube_id', $s->id)->where('telefon_norm', $norm)->first() : null;
        if ($m) { DB::table('musteriler')->where('id', $m->id)->update(['ad' => $ad ?: $m->ad, 'adres' => $adres ?: $m->adres, 'updated_at' => now()]); $mid = $m->id; }
        else { $mid = DB::table('musteriler')->insertGetId(['sube_id' => $s->id, 'ad' => $ad, 'telefon' => $tel, 'telefon_norm' => $norm, 'adres' => $adres ?: null, 'created_at' => now(), 'updated_at' => now()]); }
        $token = \Illuminate\Support\Str::random(28);
        $adId = DB::table('adisyonlar')->insertGetId([
            'sube_id' => $s->id, 'masa_id' => null, 'musteri_id' => $mid, 'kanal' => 'paket', 'platform' => 'whatsapp',
            'teslimat_adres' => $adres ?: 'WhatsApp', 'teslimat_durumu' => 'hazirlaniyor', 'takip_token' => $token,
            'odeme_yontemi' => ($odeme === 'nakit' ? 'nakit' : 'kart_kapida'), 'misafir_sayisi' => 1, 'durum' => 'acik',
            'ara_toplam' => 0, 'indirim' => 0, 'ikram' => 0, 'toplam' => 0, 'acilis' => now(), 'created_at' => now(), 'updated_at' => now(),
        ]);
        $top = 0;
        foreach ($sepet as $it) {
            $u = DB::table('urunler')->where('id', $it['urun_id'])->where('sube_id', $s->id)->first();
            if (!$u || $u->tukendi) continue;
            $adet = max(1, min(50, (int) $it['adet'])); $tut = (float) $u->fiyat * $adet;
            DB::table('adisyon_kalemleri')->insert(['adisyon_id' => $adId, 'urun_id' => $u->id, 'urun_adi' => $u->ad, 'adet' => $adet,
                'birim_fiyat' => (float) $u->fiyat, 'tutar' => $tut, 'durum' => 'gonderildi', 'not' => 'WhatsApp', 'gonderim_zamani' => now(), 'created_at' => now(), 'updated_at' => now()]);
            $top += $tut;
        }
        if ($top <= 0) { DB::table('adisyonlar')->where('id', $adId)->delete(); return null; }
        DB::table('adisyonlar')->where('id', $adId)->update(['ara_toplam' => $top, 'toplam' => $top, 'updated_at' => now()]);
        return ['id' => $adId, 'token' => $token, 'toplam' => $top];
    }
}
if (!function_exists('_waSohbetIsle')) {
    // Durum makinesi. Siparis akisiyla ilgiliyse cevap metni doner; degilse null (cagiran AI/karsilamaya birakir).
    function _waSohbetIsle($s, $tel, $text, $konum = null)
    {
        $sube = (int) $s->id;
        $tl = _waNorm($text);
        $o = _waOturumAl($sube, $tel);
        $durum = $o->durum ?? 'idle';
        $sepet = ($o && $o->sepet) ? (json_decode($o->sepet, true) ?: []) : [];
        $konumAdres = ($konum && !empty($konum['lat']))
            ? ('https://maps.google.com/?q=' . $konum['lat'] . ',' . $konum['lng'])
            : null;

        // Net iptal — her asamada
        if (_waIptalMi($tl)) {
            if (!empty($sepet) || $durum !== 'idle') { _waOturumSil($sube, $tel); return "Siparişinizi iptal ettim. 🙂 Dilediğiniz an yeniden başlayabilirsiniz."; }
            return null;
        }

        // ADRES asamasi
        if ($durum === 'adres') {
            $adres = $konumAdres ?: (mb_strlen(trim((string) $text)) >= 6 ? trim((string) $text) : null);
            if (!$adres) return "Siparişi nereye getirelim? 🛵\nAçık adresinizi yazabilir ya da 📍 *konumunuzu* paylaşabilirsiniz.";
            _waOturumYaz($sube, $tel, ['durum' => 'odeme', 'adres' => $adres, 'sepet' => json_encode($sepet)]);
            return "Harika, aldım. 🙏\nSon olarak ödemeyi nasıl yapmak istersiniz?\n\n💵  Nakit\n💳  Kart (kapıda)";
        }

        // ODEME asamasi
        if ($durum === 'odeme') {
            $odeme = _waOdemeTipi($tl);
            if (!$odeme) return "Ödemeyi nakit mi yoksa kartla mı yapmak istersiniz? 🙂";
            _waOturumYaz($sube, $tel, ['durum' => 'onay', 'odeme' => $odeme]);
            return _waOzetMetni($sepet, $o->adres, $odeme) . "\n\nSiparişinizi onaylıyor musunuz? 😊";
        }

        // ONAY asamasi
        if ($durum === 'onay') {
            if (_waOnayMi($tl) || mb_strpos((string) $text, '👍') !== false || mb_strpos((string) $text, '✅') !== false || mb_strpos((string) $text, '👌') !== false) {
                $ad = $o->ad ?: 'WhatsApp Müşteri';
                $res = _waSiparisOlustur($s, $ad, $tel, $o->adres, $sepet, $o->odeme);
                _waOturumSil($sube, $tel);
                if (!$res) return "Bir aksilik oldu, siparişi oluşturamadım. 🙏 Birazdan tekrar dener misiniz?";
                return "🎉 *Siparişiniz alındı!*\n\nSipariş No:  *#" . $res['id'] . "*\nToplam:  *" . number_format($res['toplam'], 0, ',', '.') . " ₺*\n\n👨‍🍳 Hemen hazırlamaya başlıyoruz.\n📍 Canlı takip:\n" . url('/siparisim/' . $res['token']) . "\n\nAfiyet olsun! 😊";
            }
            if (_waOlumsuzMu($tl)) { _waOturumSil($sube, $tel); return "Tamamdır, siparişi iptal ettim. 🙂 İsterseniz baştan oluşturabiliriz."; }
            return _waOzetMetni($sepet, $o->adres, $o->odeme) . "\n\nOnaylıyor musunuz? 😊";
        }

        // Soru/bilgi amaçlı mesaj (sipariş DEĞİL) -> AI/karşılama yanıtlasın (ör. "adana nasıl yapıyorsunuz")
        if (_waIcerirMi($tl, ['nasil', 'ne kadar', 'kacta', 'kac para', 'kac tl', 'var mi', 'nerede', 'nerde', 'acik mi', 'kapali mi', 'neler', 'hangi', 'onerir', 'tavsiye', 'yapiyor', 'yapiliyor', 'musunuz', 'misiniz', 'nedir', 'ne zaman', 'kac saat', 'calisiyor']) || mb_strpos((string) $text, '?') !== false) {
            return null;
        }

        // Urun ekleme (idle / sepet dolu)
        $parse = _waSepetParse($sube, $text);
        if (!empty($parse['items'])) {
            $sepet = _waSepetBirlestir($sepet, $parse['items']);
            _waOturumYaz($sube, $tel, ['durum' => 'idle', 'sepet' => json_encode($sepet)]);
            $msg = _waSepetMetni($sepet);
            if (!empty($parse['bulunamayan'])) $msg .= "\n\n_Menüde bulamadığım: " . implode(', ', $parse['bulunamayan']) . "_";
            return $msg . "\n\nBaşka eklemek istediğiniz var mı? 😊";
        }

        // Sepet dolu + "bitti/yeter/yok" -> adrese gec
        if (!empty($sepet) && _waBittiMi($tl)) {
            _waOturumYaz($sube, $tel, ['durum' => 'adres', 'sepet' => json_encode($sepet)]);
            return _waSepetMetni($sepet) . "\n\nSiparişi nereye getirelim? 🛵\nAdresinizi yazın ya da 📍 konumunuzu paylaşın.";
        }

        // Sadece konum geldi + sepet dolu -> adresi al, odemeye gec
        if ($konumAdres && !empty($sepet)) {
            _waOturumYaz($sube, $tel, ['durum' => 'odeme', 'adres' => $konumAdres, 'sepet' => json_encode($sepet)]);
            return "Konumunuzu aldım 📍\nÖdemeyi nakit mi, kartla mı yapalım? 🙂";
        }

        return null; // siparisle ilgili degil -> AI/karsilama
    }
}

// INBOUND: bridge gelen WA mesajini buraya POST eder (sube_id, from, text). Hibrit yonlendirme.
Route::post('/api/wa/gelen', function (Request $r) {
    // Dogrulama: bridge 'X-Webhook-Secret' yollar. wa_webhook_secret ayarliysa onu, yoksa wa_servis_token'i bekle.
    $whSec = (string) resto_ayar_al('wa_webhook_secret', '');
    $svcTok = (string) resto_ayar_al('wa_servis_token', '');
    $beklenen = $whSec !== '' ? $whSec : $svcTok;
    $gelenSec = (string) ($r->header('X-Webhook-Secret') ?: $r->header('X-Service-Token') ?: $r->input('token'));
    if ($beklenen !== '' && $gelenSec !== $beklenen) {
        return response()->json(['ok' => 0, 'hata' => 'yetkisiz'], 403);
    }
    // Bridge TUM event'leri ayni URL'e POST eder (connected/qr.ready/message.sent/delivered/read...).
    // Sadece GELEN mesaji isle; digerlerini sessizce yoksay.
    $event = (string) $r->input('event', '');
    // İNSAN DEVRALMA: personel KENDI telefonundan musteriye elle yazdi (bridge 'message.manual' yollar).
    // O sohbette AI'yi duraklat. (Echo ayikligi bridge'de messageId ile yapiliyor; buraya yalniz gercek insan gelir.)
    if ($event === 'message.manual') {
        $subeIdM = (int) ($r->input('salonId') ?: $r->input('sube_id') ?: 0);
        $toM = (string) ($r->input('to') ?: $r->input('tel'));
        if ($subeIdM > 0 && trim($toM) !== '') {
            try { _waDevralmaYaz($subeIdM, $toM, ['insan_devraldi' => 1, 'son_insan_mesaj_at' => now()]); } catch (\Throwable $e) {}
            try { _waLog($subeIdM, $toM, (string) $r->input('text'), 1, 'personel-elle', 'giden'); } catch (\Throwable $e) {}
        }
        return response()->json(['ok' => 1, 'tip' => 'insan_devraldi']);
    }
    if ($event !== '' && $event !== 'message.received') {
        return response()->json(['ok' => 1, 'tip' => 'ignored', 'event' => $event]);
    }
    // Oturum id = salonId (bridge alan adi) = bizim sube_id
    $subeId = (int) ($r->input('salonId') ?: $r->input('sube_id') ?: $r->input('session') ?: DB::table('subeler')->min('id'));
    $from = (string) ($r->input('from') ?: $r->input('tel') ?: $r->input('gonderen'));
    $fromJid = (string) $r->input('fromJid');           // cevap hedefi (LID ise "<lid>@lid")
    $yanitHedef = $fromJid !== '' ? $fromJid : $from;   // _restoWaGonder tam JID'i oldugu gibi yollar
    $text = trim((string) ($r->input('text') ?: $r->input('mesaj') ?: $r->input('body')));
    $s = DB::table('subeler')->find($subeId);
    if (!$s || $from === '') return response()->json(['ok' => 0], 200);
    // İNSAN DEVRALMA GUARD: personel bu sohbeti elle devraldiysa AI sus.
    // Akilli geri-alma: personel 'wa_ai_sessizlik_esik_dk' dk (vars. 3) boyunca sessizse ve
    // musteri tekrar yaziyorsa AI otomatik devralir (personel 'AI'a geri ver' demeyi unutsa bile).
    try {
        $od = _waOturumAl($subeId, $from);
        if ($od && !empty($od->insan_devraldi)) {
            $esikDk = (int) resto_ayar_al('wa_ai_sessizlik_esik_dk', 3);
            if ($esikDk < 1) $esikDk = 3;
            $sonInsan = isset($od->son_insan_mesaj_at) ? $od->son_insan_mesaj_at : null;
            // Ayni saat-dilimi referansi (now ile yazildi, now ile karsilastir -> tz kaymasi yok)
            $bosGecti = $sonInsan ? \Carbon\Carbon::parse($sonInsan)->lte(now()->subMinutes($esikDk)) : true;
            if (!$bosGecti) {
                // Personel hala aktif -> AI cevap VERMEZ; musteri mesajini panel icin logla.
                try { _waLog($subeId, $from, $text, 1, 'insan-devralmada', 'gelen'); } catch (\Throwable $e) {}
                return response()->json(['ok' => 1, 'tip' => 'insan_devralmada']);
            }
            // Esik gecti -> AI geri devralir, normal akisa devam.
            try { _waDevralmaYaz($subeId, $from, ['insan_devraldi' => 0]); } catch (\Throwable $e) {}
        }
    } catch (\Throwable $e) { /* devralma kontrolu basarisiz -> normal akisa devam */ }
    $siparisLink = url('/app/' . $subeId . '?wa=' . _waTelNorm($from));
    // Konum mesaji?
    $konum = null;
    $tip = _waNorm((string) ($r->input('type') ?: $r->input('tip')));
    $lat = $r->input('lat') ?: $r->input('latitude');
    $lng = $r->input('lng') ?: $r->input('longitude');
    if ($lat && $lng && ($tip === 'location' || $tip === 'konum' || $tip === '')) $konum = ['lat' => (float) $lat, 'lng' => (float) $lng];
    // FAZ 2: once sohbet-siparis durum makinesi (ilgiliyse buradan doner)
    try {
        $cevap = _waSohbetIsle($s, $from, $text, $konum);
        if ($cevap !== null) { _restoWaGonder($subeId, $yanitHedef,$cevap); return response()->json(['ok' => 1, 'tip' => 'sohbet']); }
    } catch (\Throwable $e) { /* duser -> AI/karsilama */ }
    $t = mb_strtolower($text, 'UTF-8');
    $anahtarlar = ['merhaba', 'selam', 'mrb', 'slm', 'iyi gun', 'iyi aksam', 'gunayd', 'hello', 'hi', 'menu', 'menü', 'siparis', 'sipariş', 'yemek', 'baslat', 'başlat'];
    $karsilama = $text === '';
    foreach ($anahtarlar as $k) { if (mb_strpos($t, $k) !== false) { $karsilama = true; break; } }
    if ($karsilama) {
        $ozel = trim((string) resto_ayar_al('wa_karsilama', ''));
        $msg = $ozel !== ''
            ? $ozel . "\n\n📋 Menü ve sipariş: " . $siparisLink
            : "Merhaba! 👋 " . $s->ad . " sipariş hattına hoş geldiniz.\n\n"
                . "📋 Menüyü görmek ve sipariş vermek için:\n" . $siparisLink . "\n\n"
                . "Dilerseniz doğrudan buraya da yazabilirsiniz — örn. \"1 Adana Kebap, 1 Ayran\" ya da \"ne önerirsin?\".";
        _restoWaGonder($subeId, $yanitHedef,$msg);
        return response()->json(['ok' => 1, 'tip' => 'karsilama']);
    }
    // AI yarisi (hibrit): MusteriAsistan (kural motoru bedava -> Haiku sadece kaçakta)
    try {
        $asistan = new \App\Services\MusteriAsistan($subeId);
        $cevap = $asistan->cevapla($text, null);
        $metin = is_array($cevap) ? (string) ($cevap['metin'] ?? $cevap['cevap'] ?? $cevap['mesaj'] ?? '') : (string) $cevap;
        $metin = _waCevapTemizle(trim($metin));
        if ($metin === '') $metin = "📋 Menüyü görüp sipariş vermek için:\n" . $siparisLink;
        else $metin .= "\n\n📋 Sipariş vermek için: " . $siparisLink;
        _restoWaGonder($subeId, $yanitHedef,$metin);
    } catch (\Throwable $e) {
        _restoWaGonder($subeId, $yanitHedef,"📋 Menüyü görüp sipariş vermek için:\n" . $siparisLink);
    }
    return response()->json(['ok' => 1, 'tip' => 'ai']);
});

// ============================================================================
//  WHATSAPP BİLDİRİM MOTORU — sipariş dışı tüm restoran mesajları
//  (rezervasyon onay/hatırlatma · doğum günü · memnuniyet anketi · kayıp müşteri · toplu duyuru)
//  TÜM gönderim _restoWaGonder üzerinden (kontör guard + log dahil). Hepsi additive + try/catch.
// ============================================================================

// Müşteri doğum tarihi kolonu (doğum günü mesajı için veri)
if (!function_exists('_waMusteriDogumEnsure')) {
    function _waMusteriDogumEnsure()
    {
        try {
            if (Schema::hasTable('musteriler') && !Schema::hasColumn('musteriler', 'dogum_tarihi')) {
                Schema::table('musteriler', fn ($t) => $t->date('dogum_tarihi')->nullable()->after('telefon'));
            }
        } catch (\Throwable $e) {}
    }
}
// Müşteri doğum tarihini güvenle kaydet (çeşitli formatları normalize eder)
if (!function_exists('_waDogumKaydet')) {
    function _waDogumKaydet($musteriId, $ham)
    {
        if (!$musteriId) return;
        $ham = trim((string) $ham);
        if ($ham === '') return;
        _waMusteriDogumEnsure();
        $d = null;
        // Kabul: YYYY-MM-DD, DD.MM.YYYY, DD/MM, DD.MM
        if (preg_match('/^(\d{4})-(\d{2})-(\d{2})$/', $ham, $m)) $d = "{$m[1]}-{$m[2]}-{$m[3]}";
        elseif (preg_match('#^(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?$#', $ham, $m)) {
            $g = str_pad($m[1], 2, '0', STR_PAD_LEFT); $ay = str_pad($m[2], 2, '0', STR_PAD_LEFT);
            $yil = isset($m[3]) && $m[3] !== '' ? (strlen($m[3]) === 2 ? '19' . $m[3] : $m[3]) : '1990';
            if ((int) $ay >= 1 && (int) $ay <= 12 && (int) $g >= 1 && (int) $g <= 31) $d = "$yil-$ay-$g";
        }
        if ($d) { try { DB::table('musteriler')->where('id', $musteriId)->update(['dogum_tarihi' => $d, 'updated_at' => now()]); } catch (\Throwable $e) {} }
    }
}

// Mükerrer-gönderim koruması (cron idempotent olsun): aynı tür+anahtar bir kez
if (!function_exists('_waBildirimGecmisiEnsure')) {
    function _waBildirimGecmisiEnsure()
    {
        if (!Schema::hasTable('wa_bildirim_gecmisi')) {
            try {
                Schema::create('wa_bildirim_gecmisi', function ($t) {
                    $t->increments('id');
                    $t->integer('sube_id')->index();
                    $t->string('tur', 30)->index();        // rez_hatirlat|dogum|anket|winback|duyuru
                    $t->string('anahtar', 120)->index();   // benzersiz iş anahtarı (ör. rez-123-2026-10-06)
                    $t->timestamp('created_at')->nullable();
                });
            } catch (\Throwable $e) {}
        }
    }
    // true dönerse: daha önce gönderildi (atla). false: yeni (işaretlenir).
    function _waDahaOnce($subeId, $tur, $anahtar)
    {
        _waBildirimGecmisiEnsure();
        try {
            if (DB::table('wa_bildirim_gecmisi')->where('tur', $tur)->where('anahtar', $anahtar)->exists()) return true;
            DB::table('wa_bildirim_gecmisi')->insert(['sube_id' => (int) $subeId, 'tur' => $tur, 'anahtar' => mb_substr((string) $anahtar, 0, 120), 'created_at' => now()]);
            return false;
        } catch (\Throwable $e) { return false; }
    }
}

// Aktif indirim kuponunu metne çevir (doğum günü / hoş geldin mesajında kullanılır)
if (!function_exists('_waKuponMetni')) {
    function _waKuponMetni($subeId, $tip)
    {
        try {
            if (!Schema::hasTable('indirimler')) return '';
            $k = DB::table('indirimler')->where('sube_id', $subeId)->where('tip', $tip)->orderByDesc('aktif')->first();
            if (!$k) $k = DB::table('indirimler')->where('tip', $tip)->orderByDesc('aktif')->first();
            if (!$k) return '';
            $deger = (($k->deger_tipi ?? 'yuzde') === 'yuzde')
                ? ('%' . (int) $k->deger)
                : (number_format((float) $k->deger, 0, ',', '.') . '₺');
            $kod = (!empty($k->kupon_kodu)) ? ("\n🎟️ Kod: *" . $k->kupon_kodu . "*") : '';
            return $deger . $kod;
        } catch (\Throwable $e) { return ''; }
    }
}

// --- 1) REZERVASYON ONAYI (rezervasyon oluşunca anında) ---
if (!function_exists('_waRezervasyonOnay')) {
    function _waRezervasyonOnay($rezId)
    {
        try {
            $rez = DB::table('rezervasyonlar')->find($rezId);
            if (!$rez || empty($rez->telefon)) return;
            $sube = DB::table('subeler')->find($rez->sube_id);
            $ad = $sube->ad ?? 'Restoran';
            $tarih = \Carbon\Carbon::parse($rez->tarih)->format('d.m.Y');
            $msg = "✅ *Rezervasyonunuz alındı!*\n\n"
                . "🏠 " . $ad . "\n"
                . "📅 " . $tarih . " · 🕐 " . substr((string) $rez->saat, 0, 5) . "\n"
                . "👥 " . (int) $rez->kisi . " kişi\n\n"
                . "Değişiklik için bu numaradan bize yazabilirsiniz. Sizi ağırlamak için sabırsızlanıyoruz! 🙏";
            _restoWaGonder($rez->sube_id, $rez->telefon, $msg);
        } catch (\Throwable $e) {}
    }
}

// --- 2) MEMNUNİYET ANKETİ (hesap kapanınca token'lı link) ---
if (!function_exists('_waAnketTokenEnsure')) {
    function _waAnketTokenEnsure()
    {
        try {
            if (Schema::hasTable('degerlendirmeler') && !Schema::hasColumn('degerlendirmeler', 'token')) {
                Schema::table('degerlendirmeler', fn ($t) => $t->string('token', 40)->nullable()->index());
            }
            if (Schema::hasTable('degerlendirmeler') && !Schema::hasColumn('degerlendirmeler', 'durum')) {
                Schema::table('degerlendirmeler', fn ($t) => $t->string('durum', 16)->default('dolduruldu'));
            }
        } catch (\Throwable $e) {}
    }
}
if (!function_exists('_waAnketGonder')) {
    function _waAnketGonder($adisyonId)
    {
        try {
            if (!Schema::hasTable('degerlendirmeler')) return;
            _waAnketTokenEnsure();
            $a = DB::table('adisyonlar')->find($adisyonId);
            if (!$a || empty($a->musteri_id) || (float) $a->toplam <= 0) return;
            // Bu adisyon için zaten anket oluşturulmuşsa tekrar gönderme
            if (DB::table('degerlendirmeler')->where('adisyon_id', $a->id)->whereNotNull('token')->exists()) return;
            $tel = DB::table('musteriler')->where('id', $a->musteri_id)->value('telefon');
            if (!$tel) return;
            $token = \Illuminate\Support\Str::random(28);
            DB::table('degerlendirmeler')->insert([
                'sube_id' => $a->sube_id, 'adisyon_id' => $a->id, 'masa_id' => $a->masa_id ?? null,
                'musteri_id' => $a->musteri_id, 'puan' => 0, 'lezzet' => 0, 'servis' => 0, 'hiz' => 0,
                'token' => $token, 'durum' => 'bekliyor', 'created_at' => now(),
            ]);
            $sube = DB::table('subeler')->find($a->sube_id);
            $msg = "🙏 Bizi tercih ettiğiniz için teşekkürler!\n\n"
                . "Deneyiminiz nasıldı? 30 saniyenizi ayırıp değerlendirir misiniz?\n"
                . "👉 " . url('/anket/' . $token) . "\n\n"
                . "Görüşleriniz bizim için çok değerli. ❤️";
            _restoWaGonder($a->sube_id, $tel, $msg);
        } catch (\Throwable $e) {}
    }
}

// Anket sayfası (müşteri) — token'lı, giriş gerektirmez
Route::get('/anket/{token}', function ($token) {
    if (function_exists('_waAnketTokenEnsure')) _waAnketTokenEnsure();
    $d = (Schema::hasTable('degerlendirmeler') && Schema::hasColumn('degerlendirmeler', 'token')) ? DB::table('degerlendirmeler')->where('token', $token)->first() : null;
    if (!$d) abort(404);
    $sube = DB::table('subeler')->find($d->sube_id);
    $googleUrl = (string) resto_ayar_al('google_yorum_url', '');
    return view('anket', ['d' => $d, 'sube' => $sube, 'token' => $token, 'dolduruldu' => (($d->durum ?? '') === 'dolduruldu' || (int) $d->puan > 0), 'googleUrl' => $googleUrl]);
});
Route::post('/anket/{token}', function (Request $r, $token) {
    if (function_exists('_waAnketTokenEnsure')) _waAnketTokenEnsure();
    $d = (Schema::hasTable('degerlendirmeler') && Schema::hasColumn('degerlendirmeler', 'token')) ? DB::table('degerlendirmeler')->where('token', $token)->first() : null;
    if (!$d) return response()->json(['ok' => 0], 404);
    $puan = max(1, min(5, (int) $r->input('puan', 5)));
    DB::table('degerlendirmeler')->where('id', $d->id)->update([
        'puan' => $puan,
        'lezzet' => max(0, min(5, (int) $r->input('lezzet', $puan))),
        'servis' => max(0, min(5, (int) $r->input('servis', $puan))),
        'hiz' => max(0, min(5, (int) $r->input('hiz', $puan))),
        'yorum' => mb_substr(trim((string) $r->input('yorum')), 0, 500) ?: null,
        'durum' => 'dolduruldu',
    ]);
    // Yüksek puan -> Google yorumuna yönlendir (ayarlıysa)
    $googleUrl = (string) resto_ayar_al('google_yorum_url', '');
    return ['ok' => 1, 'google' => ($puan >= 4 && $googleUrl !== '') ? $googleUrl : null];
});

// --- 3) GÜNLÜK CRON: rezervasyon hatırlatma + doğum günü + kayıp müşteri ---
//  Dakikalık git-pull cron'una ek: günde 1 kez  curl "<site>/api/wa/gunluk-gorevler?key=SANTRAL_SECRET"
//  İdempotent: gün içinde kaç kez çağrılırsa çağrılsın aynı kişiye 1 kez gider.
Route::get('/api/wa/gunluk-gorevler', function (Request $r) {
    $beklenen = (string) env('SANTRAL_SECRET', '');
    $key = (string) $r->query('key');
    $ok = ($beklenen !== '' && hash_equals($beklenen, $key)) || _adminKeyGecerli($key);
    if (!$ok) return response()->json(['ok' => 0, 'hata' => 'yetkisiz'], 403);
    _waMusteriDogumEnsure();
    $rapor = ['rez_hatirlat' => 0, 'dogum' => 0, 'winback' => 0];
    $bugun = now()->format('Y-m-d');
    $md = now()->format('m-d');

    // (a) Bugünkü rezervasyonlara sabah hatırlatma
    try {
        if (Schema::hasTable('rezervasyonlar')) {
            $rezler = DB::table('rezervasyonlar')->where('tarih', $bugun)
                ->whereIn('durum', ['bekliyor', 'onaylandi'])->whereNotNull('telefon')->get();
            foreach ($rezler as $rez) {
                if (empty($rez->telefon)) continue;
                if (_waDahaOnce($rez->sube_id, 'rez_hatirlat', 'rez-' . $rez->id . '-' . $bugun)) continue;
                $sube = DB::table('subeler')->find($rez->sube_id);
                $msg = "⏰ *Rezervasyon hatırlatması*\n\n"
                    . "Bugün saat " . substr((string) $rez->saat, 0, 5) . "'te " . ($sube->ad ?? 'restoranımızda')
                    . " " . (int) $rez->kisi . " kişilik masanız hazır olacak. 🍽️\n\n"
                    . "Gelemeyecekseniz lütfen bu numaradan haber verin. Görüşmek üzere! 🙏";
                if (_restoWaGonder($rez->sube_id, $rez->telefon, $msg)) $rapor['rez_hatirlat']++;
            }
        }
    } catch (\Throwable $e) {}

    // (b) Bugün doğum günü olan müşterilere kutlama + indirim
    try {
        if (Schema::hasColumn('musteriler', 'dogum_tarihi')) {
            $kisiler = DB::table('musteriler')->whereNotNull('dogum_tarihi')->whereNotNull('telefon')
                ->whereRaw("DATE_FORMAT(dogum_tarihi,'%m-%d') = ?", [$md])->get();
            foreach ($kisiler as $m) {
                if (empty($m->telefon)) continue;
                if (_waDahaOnce($m->sube_id, 'dogum', 'dogum-' . $m->id . '-' . now()->format('Y'))) continue;
                $sube = DB::table('subeler')->find($m->sube_id);
                $kupon = _waKuponMetni($m->sube_id, 'dogum_gunu');
                $msg = "🎉🎂 *İyi ki doğdunuz " . ($m->ad ?: '') . "!*\n\n"
                    . ($sube->ad ?? 'Biz') . " olarak doğum gününüzü kutlarız. 🥳\n"
                    . ($kupon !== '' ? ("\n🎁 Size özel doğum günü hediyesi: *" . $kupon . "*\nBu ay içinde ziyaretinizde geçerli.") : "")
                    . "\n\nNice mutlu senelere! ❤️";
                if (_restoWaGonder($m->sube_id, $m->telefon, $msg)) $rapor['dogum']++;
            }
        }
    } catch (\Throwable $e) {}

    // (c) Kayıp müşteri geri kazanım (son ziyaret 30-120 gün önce, ayda en fazla 1)
    try {
        $sinirBas = now()->subDays(120)->format('Y-m-d H:i:s');
        $sinirSon = now()->subDays(30)->format('Y-m-d H:i:s');
        $adaylar = DB::table('musteriler as m')->whereNotNull('m.telefon')
            ->select('m.id', 'm.ad', 'm.sube_id', 'm.telefon', DB::raw('(SELECT MAX(kapanis) FROM adisyonlar WHERE adisyonlar.musteri_id=m.id AND adisyonlar.durum=\'odendi\') as son'))
            ->havingRaw('son BETWEEN ? AND ?', [$sinirBas, $sinirSon])->limit(200)->get();
        foreach ($adaylar as $m) {
            if (empty($m->telefon)) continue;
            if (_waDahaOnce($m->sube_id, 'winback', 'winback-' . $m->id . '-' . now()->format('Y-m'))) continue;
            $sube = DB::table('subeler')->find($m->sube_id);
            $kupon = _waKuponMetni($m->sube_id, 'kupon');
            $msg = "👋 Merhaba " . ($m->ad ?: '') . ", sizi özledik!\n\n"
                . ($sube->ad ?? 'Restoranımız') . " olarak bir süredir görüşemedik. 🥺"
                . ($kupon !== '' ? ("\n\n🎁 Dönüşünüze özel: *" . $kupon . "*") : "")
                . "\n\nSizi tekrar ağırlamaktan mutluluk duyarız! 🍽️";
            if (_restoWaGonder($m->sube_id, $m->telefon, $msg)) $rapor['winback']++;
        }
    } catch (\Throwable $e) {}

    return response()->json(['ok' => 1, 'tarih' => $bugun, 'rapor' => $rapor], 200, [], JSON_UNESCAPED_UNICODE);
});

// --- 4) TOPLU DUYURU / KAMPANYA (patron panelinden) ---
//  Hedef: hepsi | son30 (son 30 gün gelen) | sadik (>=3 sipariş). Kontör guard her gönderimde.
Route::post('/api/wa/duyuru-gonder', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz — sadece sahip/müdür toplu duyuru gönderebilir.'], 401);
    $subeId = (int) $p->sube_id; // kendi şubesi (çapraz-şube spam engeli)
    $mesaj = trim((string) $r->input('mesaj'));
    if ($mesaj === '') return ['ok' => 0, 'hata' => 'Mesaj boş.'];
    $hedef = in_array($r->input('hedef'), ['son30', 'sadik', 'hepsi']) ? $r->input('hedef') : 'hepsi';
    $q = DB::table('musteriler')->where('sube_id', $subeId)->whereNotNull('telefon')->where('telefon', '!=', '');
    if ($hedef === 'sadik') $q->where('siparis_sayisi', '>=', 3);
    if ($hedef === 'son30') {
        $aktifIds = DB::table('adisyonlar')->where('sube_id', $subeId)->where('durum', 'odendi')
            ->where('kapanis', '>=', now()->subDays(30))->whereNotNull('musteri_id')->distinct()->pluck('musteri_id')->all();
        $q->whereIn('id', $aktifIds ?: [0]);
    }
    $kisiler = $q->limit(500)->get(['id', 'telefon']);
    $gonderilen = 0; $atlanan = 0;
    foreach ($kisiler as $m) {
        if (!\App\Services\KontorServisi::yeterliMi($subeId)) { $atlanan++; continue; } // kontör bitti -> dur
        if (_restoWaGonder($subeId, $m->telefon, $mesaj)) $gonderilen++; else $atlanan++;
    }
    return ['ok' => 1, 'hedef' => $hedef, 'aday' => $kisiler->count(), 'gonderilen' => $gonderilen, 'atlanan' => $atlanan];
});

