Route::post('/bildirim-ayar-kaydet', function (Request $r) {
    $bp = null;
    try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp) return redirect('/bildirim-ayar')->with('hata', 'Oturum bulunamadı.');
