if (!function_exists('_patronAiBriefDemo')) {
    function _patronAiBriefDemo($sid, $ad = null)
    {
        $veri = _patronAiDemoVeri();
        $kural = _patronAiKurallar($veri, 'sabah', $ad);
        $az = _patronAiAnalizZengin($sid, $veri, 'sabah', $ad, true, true);
        return ['ok' => 1, 'demo' => true, 'ad' => $ad, 'tarih' => $veri['tarih'], 'tip' => 'sabah',
            'veri' => $veri, 'oncelikler' => $kural['oncelikler'], 'metin' => $kural['metin'],
            'analiz' => $az['bloklar'], 'ai_ozet' => $az['ozet'], 'ai_var' => ($az['kaynak'] === 'ai'), 'kaynak' => $az['kaynak'],
            'tuketim' => _aiKrediDurum($sid), 'sureklilik' => ['acik' => [], 'kapanan' => []], 'whatsapp' => ['giden' => 0, 'gelen' => []]];
    }
}
// API: sabah brifingi (sahip/müdür). ?force=1 yeniden üretir. ?demo=1 sahte veriyle önizleme.
Route::get('/api/patron-ai/brief', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if (!in_array(($p->rol ?? ''), ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Bu ekrana yetkiniz yok'], 403);
    if ($r->boolean('demo')) return array_merge(_patronAiBriefDemo($p->sube_id, $p->ad ?? null), ['ai_erisim' => _aiErisim($p)]);
    $tip = $r->input('tip') === 'aksam' ? 'aksam' : 'sabah';
    $b = _patronAiBriefUret($p->sube_id, $tip, $r->boolean('force'), $p->ad ?? null);
    $az = _patronAiAnalizZengin($p->sube_id, $b['veri'] ?? [], $tip, $p->ad ?? null, $r->boolean('force'));
    return array_merge($b, ['ok' => 1, 'ad' => $p->ad ?? null, 'ai_erisim' => _aiErisim($p),
        'analiz' => $az['bloklar'], 'ai_ozet' => $az['ozet'], 'ai_var' => ($az['kaynak'] === 'ai'), 'kaynak' => $az['kaynak'],
        'tuketim' => _aiKrediDurum($p->sube_id), 'sureklilik' => _patronAiSureklilik($p->sube_id),
        'whatsapp' => _patronAiWhatsapp($p->sube_id)]);
});
// API: AI tüketim durumu (abonelik-gömülü aylık hak + kullanım) — sahip/müdür.
Route::get('/api/patron-ai/tuketim', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array(($p->rol ?? ''), ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $durum = _aiKrediDurum($p->sube_id);
    // Bu ay en çok tüketen personeller (şeffaflık)
    $ay = now()->format('Y-m'); $top = [];
    try {
        $rows = DB::table('patron_ai_tuketim')->where('sube_id', $p->sube_id)->where('yil_ay', $ay)->where('personel_id', '>', 0)
            ->orderByDesc('kullanim')->limit(5)->get();
        $adlar = DB::table('personeller')->whereIn('id', $rows->pluck('personel_id')->all())->pluck('ad', 'id');
        foreach ($rows as $x) $top[] = ['ad' => $adlar[$x->personel_id] ?? ('#' . $x->personel_id), 'kullanim' => (int) $x->kullanim];
    } catch (\Throwable $e) {}
    return array_merge(['ok' => 1, 'ai_erisim' => _aiErisim($p), 'top' => $top], $durum);
});
// API: çok şubeli zincir özeti (aynı markanın/app_bundle şubeleri — tenant güvenli).
Route::get('/api/patron-ai/zincir-ozet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || ($p->rol ?? '') !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $subem = DB::table('subeler')->where('id', $p->sube_id)->first();
    $q = DB::table('subeler');
    $bundle = (Schema::hasColumn('subeler', 'app_bundle') && !empty($subem->app_bundle)) ? $subem->app_bundle : null;
    if ($bundle) $q->where('app_bundle', $bundle); else $q->where('id', $p->sube_id);
    $liste = [];
    foreach ($q->orderBy('id')->get(['id', 'ad']) as $s) {
        $v = _patronAiBriefVeri($s->id);
        $durum = ($v['kritik_sayi'] > 0 || $v['ciro_yuzde'] <= -10) ? 'uyari' : (($v['food_cost_yuzde'] >= 35) ? 'dikkat' : 'iyi');
        $liste[] = ['id' => (int) $s->id, 'ad' => $s->ad, 'dun_ciro' => $v['dun_ciro'], 'ciro_yuzde' => $v['ciro_yuzde'],
            'food_cost' => $v['food_cost_yuzde'], 'kritik' => $v['kritik_sayi'], 'durum' => $durum];
    }
    return ['ok' => 1, 'subeler' => $liste, 'cok_sube' => count($liste) > 1];
});
// CRON: sabah brifingi üret + sahip/müdüre FCM. OS cron: curl "/api/patron-ai/sabah?key=SANTRAL_SECRET[&sube=ID]"
Route::get('/api/patron-ai/sabah', function (Request $r) {
    $g = function_exists('_santralAuthGuard') ? _santralAuthGuard($r) : null; if ($g) return $g;
    $sid = (int) $r->input('sube', 0);
    $hedef = $sid > 0 ? [$sid] : DB::table('subeler')->pluck('id')->all();
    $n = 0;
    foreach ($hedef as $s) {
        try {
            $b = _patronAiBriefUret($s, 'sabah', true);
            $ozet = mb_substr(trim(preg_replace('/\s+/', ' ', (string) $b['metin'])), 0, 180);
            if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($s, '☀️ Sabah Brifingi', $ozet, ['tur' => 'patron_ai_brief'], ['sahip', 'mudur'], 'sabah_brief');
            $n++;
        } catch (\Throwable $e) {}
    }
    return ['ok' => 1, 'uretildi' => $n];
});
// ============================ PATRON AI — DEPARTMAN DENETİMİ (her departmanı tek tek incele + AI yorum) ============================
if (!function_exists('_departmanRaporVeri')) {
    // Bir departmanın GÜNLÜK verisi (kod'a göre ilgili alandan). durum/ozet/kpi/uyari/veri_yok döner.
    function _departmanRaporVeri($sid, $kod, $gun, $simdiSaat = null, $depId = 0)
    {
        $sid = (int) $sid; $ds = $gun->toDateString();
        $tl = fn ($n) => number_format((float) ($n ?? 0), 0, ',', '.') . '₺';
        $kpi = []; $uyari = []; $durum = 'notr'; $ozet = ''; $veriYok = false; $isAkisi = null; $kritikListe = []; $aksiyonlar = [];
        $ciroGun = function () use ($sid, $ds, $simdiSaat) {
            try { $q = DB::table('odemeler')->join('adisyonlar', 'adisyonlar.id', '=', 'odemeler.adisyon_id')
                ->where('adisyonlar.sube_id', $sid)->whereDate('odemeler.created_at', $ds);
                if ($simdiSaat) $q->whereTime('odemeler.created_at', '<=', $simdiSaat);
                return (float) $q->sum('odemeler.tutar'); } catch (\Throwable $e) { return 0.0; }
        };
        $kritikSay = function () use ($sid) { try { if (function_exists('_restoUretimRiski')) return count((_restoUretimRiski($sid, 3))['kritik'] ?? []); } catch (\Throwable $e) {} return 0; };
        $fireGun = function () use ($sid, $ds) { try { return (float) DB::table('stok_hareketleri')->where('sube_id', $sid)->where('tip', 'fire')->whereDate('created_at', $ds)->selectRaw('SUM(ABS(miktar)*COALESCE(birim_maliyet,0)) t')->value('t'); } catch (\Throwable $e) { return 0.0; } };
        try {
            switch ($kod) {
                case 'servis': case 'bar': case 'karsilama':
                    $ad = (int) DB::table('adisyonlar')->where('sube_id', $sid)->whereDate('created_at', $ds)->count();
                    $ciro = $ciroGun(); $acik = (int) DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'acik')->count();
                    $iptal = 0;
                    try { $iptal = (int) DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyonlar.id', '=', 'adisyon_kalemleri.adisyon_id')->where('adisyonlar.sube_id', $sid)->whereDate('adisyonlar.created_at', $ds)->where('adisyon_kalemleri.durum', 'iptal')->count(); } catch (\Throwable $e) {}
                    $kpi = [['Adisyon', $ad], ['Ciro', $tl($ciro)], ['Açık masa', $acik], ['İptal kalem', $iptal]];
                    if ($iptal >= 8) { $durum = 'dikkat'; $uyari[] = "İptal edilen ürün sayısı yüksek ($iptal) — servis/mutfak hatası olabilir."; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'İptalleri İncele', 'url' => '/hareketler', 'ikon' => 'search', 'renk' => 'amber']; }
                    if ($acik > 0) $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Açık Masaları Gör', 'url' => '/pos', 'ikon' => 'table_restaurant', 'renk' => 'mavi'];
                    $ozet = "$ad adisyon, " . $tl($ciro) . " ciro" . ($iptal ? ", $iptal iptal kalem" : "") . ".";
                    break;
                case 'mutfak': case 'soguk_mutfak': case 'pastane': case 'kasap':
                    // İSTASYON AYRIMI: bu departmana bağlı menü kategorilerinin ürünleri. Yoksa: 'mutfak'=tüm mutfak, diğerleri=veri yok.
                    $katIds = [];
                    try { if ($depId && Schema::hasColumn('menu_kategorileri', 'departman_id')) $katIds = DB::table('menu_kategorileri')->where('departman_id', (int) $depId)->pluck('id')->all(); } catch (\Throwable $e) {}
                    $urunFiltre = null; // null = filtre yok (tüm mutfak)
                    if ($katIds) { try { $urunFiltre = DB::table('urunler')->whereIn('kategori_id', $katIds)->pluck('id')->all(); } catch (\Throwable $e) { $urunFiltre = []; } }
                    if (!$katIds && $kod !== 'mutfak') {
                        $veriYok = true; $durum = 'notr';
                        $ozet = 'Bu istasyona menü kategorisi bağlanmamış — Departman Yönetimi\'nden bu departmanı düzenleyip ilgili kategorileri seç.';
                        break;
                    }
                    $bq = DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyonlar.id', '=', 'adisyon_kalemleri.adisyon_id')->where('adisyonlar.sube_id', $sid)->where('adisyonlar.durum', 'acik')->whereIn('adisyon_kalemleri.durum', ['bekliyor', 'hazirlaniyor']);
                    if ($urunFiltre !== null) $bq->whereIn('adisyon_kalemleri.urun_id', $urunFiltre);
                    $bekleyen = 0; try { $bekleyen = (int) $bq->count(); } catch (\Throwable $e) {}
                    $gq = DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyonlar.id', '=', 'adisyon_kalemleri.adisyon_id')->where('adisyonlar.sube_id', $sid)->whereDate('adisyonlar.created_at', $ds);
                    if ($urunFiltre !== null) $gq->whereIn('adisyon_kalemleri.urun_id', $urunFiltre);
                    $gonderilen = 0; try { $gonderilen = (int) $gq->sum('adisyon_kalemleri.adet'); } catch (\Throwable $e) {}
                    $kpi = [['Hazırlanacak', $bekleyen], ['Bugün gönderilen', $gonderilen . ' adet']];
                    if ($urunFiltre === null) { $fire = $fireGun(); $kpi[] = ['Fire (mutfak geneli)', $tl($fire)]; if ($fire > 0) { $uyari[] = $tl($fire) . " fire/zayiat var — israf kontrolü gerek."; $durum = 'dikkat'; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Fire/Zayiatı İncele', 'url' => '/sayim', 'ikon' => 'search', 'renk' => 'amber']; } }
                    $isAkisi = $bekleyen >= 15 ? 'yavaş' : 'normal';
                    if ($bekleyen >= 15) { $durum = 'dikkat'; $uyari[] = "Kuyruk yoğun ($bekleyen bekleyen ürün) — servis yavaşlıyor olabilir."; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Mutfak Ekranını Aç', 'url' => '/mutfak', 'ikon' => 'soup_kitchen', 'renk' => 'amber']; }
                    $ozet = "$gonderilen ürün hazırlandı, $bekleyen bekliyor" . ($urunFiltre === null ? " (mutfak geneli)" : "") . ".";
                    break;
                case 'kasa':
                    $ciro = $ciroGun();
                    $nakit = 0; $kart = 0;
                    try { $nakit = (float) DB::table('odemeler')->join('adisyonlar', 'adisyonlar.id', '=', 'odemeler.adisyon_id')->where('adisyonlar.sube_id', $sid)->whereDate('odemeler.created_at', $ds)->where('odemeler.tip', 'nakit')->sum('odemeler.tutar'); } catch (\Throwable $e) {}
                    try { $kart = (float) DB::table('odemeler')->join('adisyonlar', 'adisyonlar.id', '=', 'odemeler.adisyon_id')->where('adisyonlar.sube_id', $sid)->whereDate('odemeler.created_at', $ds)->whereIn('odemeler.tip', ['kredi', 'kart', 'yemek_karti'])->sum('odemeler.tutar'); } catch (\Throwable $e) {}
                    $acik = (int) DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'acik')->count();
                    $kpi = [['Tahsilat', $tl($ciro)], ['Nakit', $tl($nakit)], ['Kart', $tl($kart)], ['Açık adisyon', $acik]];
                    if ($acik > 0) $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Açık Adisyonlar', 'url' => '/pos', 'ikon' => 'receipt_long', 'renk' => 'mavi'];
                    $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Z Raporu', 'url' => '/z-raporu', 'ikon' => 'summarize', 'renk' => 'mavi'];
                    $ozet = $tl($ciro) . " tahsilat (nakit " . $tl($nakit) . " / kart " . $tl($kart) . ").";
                    break;
                case 'satinalma':
                    $kritikListe = function_exists('_kritikStokListesi') ? _kritikStokListesi($sid) : [];
                    $kritik = count($kritikListe);
                    $acikPO = 0; $talep = 0;
                    try { if (Schema::hasTable('satinalma_siparisleri')) $acikPO = (int) DB::table('satinalma_siparisleri')->where('sube_id', $sid)->whereNotIn('durum', ['teslim', 'tamamlandi', 'iptal'])->count(); } catch (\Throwable $e) {}
                    try { if (Schema::hasTable('satinalma_talepleri')) $talep = (int) DB::table('satinalma_talepleri')->where('sube_id', $sid)->whereIn('durum', ['yeni', 'teklif', 'onayda'])->count(); } catch (\Throwable $e) {}
                    $kpi = [['Kritik stok', $kritik . ' kalem'], ['Açık sipariş', $acikPO], ['Bekleyen talep', $talep]];
                    if ($kritik > 0) { $durum = 'risk'; $uyari[] = "$kritik malzeme kritik seviyede — acil sipariş gerekiyor."; $aksiyonlar[] = ['tip' => 'acil_siparis', 'lbl' => 'Acil Sipariş Oluştur', 'ikon' => 'shopping_cart_checkout', 'renk' => 'kirmizi']; }
                    $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Sipariş Önerisi', 'url' => '/siparis-onerisi', 'ikon' => 'auto_awesome', 'renk' => 'mavi'];
                    $ozet = "$kritik kritik malzeme, $acikPO açık sipariş, $talep bekleyen talep.";
                    break;
                case 'depo': case 'mal_kabul':
                    $kritikListe = function_exists('_kritikStokListesi') ? _kritikStokListesi($sid) : [];
                    $kritik = count($kritikListe);
                    $hareket = 0;
                    try { $hareket = (int) DB::table('stok_hareketleri')->where('sube_id', $sid)->whereDate('created_at', $ds)->count(); } catch (\Throwable $e) {}
                    $fire = $fireGun();
                    $kpi = [['Kritik stok', $kritik . ' kalem'], ['Bugün stok hareketi', $hareket], ['Fire', $tl($fire)]];
                    if ($kritik > 0) { $durum = 'dikkat'; $uyari[] = "$kritik malzeme kritik — tedarik planla."; $aksiyonlar[] = ['tip' => 'acil_siparis', 'lbl' => 'Acil Sipariş Oluştur', 'ikon' => 'shopping_cart_checkout', 'renk' => 'kirmizi']; }
                    if ($fire > 0) { $uyari[] = $tl($fire) . " fire kaydı."; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Fire/Sayım', 'url' => '/sayim', 'ikon' => 'search', 'renk' => 'amber']; }
                    $ozet = "$kritik kritik, $hareket stok hareketi" . ($fire > 0 ? ", " . $tl($fire) . " fire" : "") . ".";
                    break;
                case 'ik':
                    $toplam = (int) DB::table('personeller')->where('sube_id', $sid)->where('aktif', 1)->count();
                    $mesaide = null;
                    try { if (Schema::hasTable('personel_mesai')) $mesaide = (int) DB::table('personel_mesai')->where('sube_id', $sid)->whereNull('cikis_at')->count(); } catch (\Throwable $e) {}
                    $kpi = [['Aktif personel', $toplam], ['Şu an mesaide', $mesaide === null ? '—' : $mesaide]];
                    $ozet = "$toplam aktif personel" . ($mesaide !== null ? ", $mesaide şu an mesaide" : "") . ".";
                    if ($mesaide === null) { $uyari[] = "Puantaj/mesai verisi yok — devam-devamsızlık takip edilemiyor."; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Puantajı Aç', 'url' => '/puantaj', 'ikon' => 'schedule', 'renk' => 'mavi']; }
                    $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Personel & Maaş', 'url' => '/personel', 'ikon' => 'badge', 'renk' => 'mavi'];
                    break;
                case 'finans':
                    $gelir = $ciroGun();
                    $gider = 0;
                    try { if (Schema::hasTable('giderler')) $gider = (float) DB::table('giderler')->where('sube_id', $sid)->whereDate('tarih', $ds)->sum('tutar'); } catch (\Throwable $e) {}
                    $net = $gelir - $gider;
                    $kpi = [['Gelir', $tl($gelir)], ['Gider', $tl($gider)], ['Net', $tl($net)]];
                    if ($net < 0) { $durum = 'dikkat'; $uyari[] = "Günlük net negatif (" . $tl($net) . ") — gider kontrolü."; }
                    if ($gider <= 0 && $gelir > 0) { if ($durum === 'notr') $durum = 'dikkat'; $uyari[] = "Bugün hiç gider kaydı yok — eksik veri girişi olabilir."; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Gider Ekle', 'url' => '/gider', 'ikon' => 'add', 'renk' => 'amber']; }
                    $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'Finans / Kâr-Zarar', 'url' => '/finans', 'ikon' => 'analytics', 'renk' => 'mavi'];
                    $ozet = "Gelir " . $tl($gelir) . ", gider " . $tl($gider) . ", net " . $tl($net) . ".";
                    break;
                case 'pazarlama': case 'crm':
                    $isk = 0;
                    try { $isk = (float) DB::table('iptal_indirim_loglari')->where('sube_id', $sid)->whereIn('tip', ['indirim', 'ikram'])->whereDate('created_at', $ds)->sum('tutar'); } catch (\Throwable $e) {}
                    $odul = 0;
                    try { if (Schema::hasTable('odul_kullanimlari')) $odul = (int) DB::table('odul_kullanimlari')->where('sube_id', $sid)->where('durum', 'kullanildi')->whereDate('updated_at', $ds)->count(); } catch (\Throwable $e) {}
                    $kpi = [['İskonto + İkram', $tl($isk)], ['Kullanılan ödül', $odul]];
                    if ($isk >= 500) { $durum = 'dikkat'; $uyari[] = "Yüksek iskonto/ikram (" . $tl($isk) . ") — sebep ve yetki kontrolü."; $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'İskonto/İkramları İncele', 'url' => '/hareketler', 'ikon' => 'search', 'renk' => 'amber']; }
                    $aksiyonlar[] = ['tip' => 'link', 'lbl' => 'İndirimler', 'url' => '/indirimler', 'ikon' => 'local_offer', 'renk' => 'mavi'];
                    $ozet = $tl($isk) . " iskonto/ikram, $odul ödül kullanıldı.";
                    break;
                default:
                    $veriYok = true;
                    $ozet = "Bu departman için sistemde takip edilen operasyonel veri henüz yok.";
            }
        } catch (\Throwable $e) { $veriYok = true; $ozet = 'Veri alınamadı.'; }
        return ['durum' => $durum, 'ozet' => $ozet, 'kpi' => $kpi, 'uyari' => $uyari, 'veri_yok' => $veriYok, 'is_akisi' => $isAkisi,
            'kritik_liste' => $kritikListe, 'aksiyonlar' => $aksiyonlar];
    }
}
if (!function_exists('_departmanHaftalik')) {
    // Son 7 günün birincil göstergesi (ciro tabanlı genel aktivite) — grafik için.
    function _departmanHaftalik($sid, $kod, $depId = 0)
    {
        // Mutfak istasyonu ise bağlı kategorilerin ürünleri (yoksa tüm mutfak)
        $urunFiltre = null;
        if (in_array($kod, ['mutfak', 'soguk_mutfak', 'pastane', 'kasap'])) {
            try { if ($depId && Schema::hasColumn('menu_kategorileri', 'departman_id')) {
                $katIds = DB::table('menu_kategorileri')->where('departman_id', (int) $depId)->pluck('id')->all();
                if ($katIds) $urunFiltre = DB::table('urunler')->whereIn('kategori_id', $katIds)->pluck('id')->all();
            } } catch (\Throwable $e) {}
        }
        $out = [];
        for ($i = 6; $i >= 0; $i--) {
            $g = \Carbon\Carbon::today()->subDays($i); $ds = $g->toDateString(); $v = 0;
            try {
                if (in_array($kod, ['mutfak', 'soguk_mutfak', 'pastane', 'kasap'])) {
                    $q = DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyonlar.id', '=', 'adisyon_kalemleri.adisyon_id')->where('adisyonlar.sube_id', $sid)->whereDate('adisyonlar.created_at', $ds);
                    if ($urunFiltre !== null) $q->whereIn('adisyon_kalemleri.urun_id', $urunFiltre);
                    $v = (int) $q->sum('adisyon_kalemleri.adet');
                } elseif (in_array($kod, ['depo', 'mal_kabul'])) {
                    $v = (int) DB::table('stok_hareketleri')->where('sube_id', (int) $sid)->whereDate('created_at', $ds)->count();
                } else {
                    $v = (int) round((float) DB::table('odemeler')->join('adisyonlar', 'adisyonlar.id', '=', 'odemeler.adisyon_id')->where('adisyonlar.sube_id', $sid)->whereDate('odemeler.created_at', $ds)->sum('odemeler.tutar'));
                }
            } catch (\Throwable $e) {}
            $out[] = ['gun' => $g->format('d.m'), 'deger' => $v];
        }
        return $out;
    }
}
if (!function_exists('_departmanDenetim')) {
    // Patron AI sayfasındaki "Departman Denetimi" listesi: her aktif departman için durum + özet + id.
    function _departmanDenetim($sid, $gun)
    {
        _departmanEnsure();
        $list = [];
        try {
            $deps = DB::table('departmanlar')->where('sube_id', (int) $sid)->where('aktif', 1)->orderBy('grup')->orderBy('ad')->get(['id', 'ad', 'kod', 'grup', 'renk', 'ikon']);
            $simdi = $gun->isToday() ? now()->format('H:i:s') : null;
            foreach ($deps as $d) {
                $r = _departmanRaporVeri($sid, $d->kod ?? '', $gun, $simdi, (int) $d->id);
                $list[] = ['id' => (int) $d->id, 'ad' => $d->ad, 'grup' => $d->grup, 'renk' => $d->renk, 'ikon' => $d->ikon,
                    'durum' => $r['durum'], 'ozet' => $r['ozet'], 'uyari_say' => count($r['uyari']), 'veri_yok' => $r['veri_yok']];
            }
        } catch (\Throwable $e) {}
        return $list;
    }
}
if (!function_exists('_departmanAiYorum')) {
    // Bir departmanın GÜNLÜK verisine AI (Haiku) yorumu: durum + yorum + sorunlar + öneriler + iş akışı. Kapalıysa kural.
    function _departmanAiYorum($sid, $dad, $kod, $veri, $personeller, $force = false)
    {
        $sonuc = ['kaynak' => 'kural', 'yorum' => null];
        if (!config('services.resteos.patron_ai_v2', false)) return $sonuc;
        $ck = 'patron_ai_dep:' . (int) $sid . ':' . $kod . ':' . now()->toDateString();
        if ($force) \Illuminate\Support\Facades\Cache::forget($ck);
        return \Illuminate\Support\Facades\Cache::remember($ck, now()->addHours(3), function () use ($sid, $dad, $kod, $veri, $personeller, $sonuc) {
            $kritikAd = array_map(fn ($x) => ($x['ad'] ?? '') . ' (' . ($x['mevcut'] ?? 0) . '/' . ($x['kritik'] ?? 0) . ' ' . ($x['birim'] ?? '') . ')', array_slice($veri['kritik_liste'] ?? [], 0, 12));
            $paket = ['departman' => $dad, 'kpi' => $veri['kpi'], 'uyarilar' => $veri['uyari'], 'is_akisi' => $veri['is_akisi'], 'personel' => $personeller, 'kritik_malzemeler' => $kritikAd];
            $sys = 'Sen bir restoranın kıdemli operasyon müdürüsün. "' . $dad . '" departmanının bugünkü durumunu bir patrona DEĞERLENDİR. '
                . 'SADECE doğal, akıcı, profesyonel TÜRKÇE yaz; yabancı kelime kullanma. Sadece verilen veriyi kullan, UYDURMA. '
                . 'Şunları yap: işler yolunda mı söyle; aksayan/geciken/hatalı bir şey varsa yakala ve açıkla; iş akışı normal mi yavaş mı değerlendir; personel performansına kısaca değin; sonunda ÇÖZÜM ODAKLI net öneri ver. '
                . 'kritik_malzemeler listesi doluysa bu malzemeleri İSİMLERİYLE say ve "acil sipariş verilmeli" de. '
                . 'ÇIKTIYI YALNIZCA şu JSON ile ver (başka metin yok): {"yorum":"3-5 cümle değerlendirme","sorunlar":["varsa kısa madde"],"oneriler":["1-2 somut öneri"]}'
                . "\n--- VERİ ---\n" . json_encode($paket, JSON_UNESCAPED_UNICODE);
            $ai = _patronAiCagir($sys, 'Bu departmanı değerlendir, sadece JSON döndür.', 900, null, $sid);
            if (!$ai) return $sonuc;
            $s = strpos($ai, '{'); $e = strrpos($ai, '}');
            if ($s !== false && $e !== false && $e > $s) $ai = substr($ai, $s, $e - $s + 1);
            $j = json_decode($ai, true);
            if (!is_array($j) || empty($j['yorum'])) return $sonuc;
            return ['kaynak' => 'ai', 'yorum' => (string) $j['yorum'], 'sorunlar' => (array) ($j['sorunlar'] ?? []), 'oneriler' => (array) ($j['oneriler'] ?? [])];
        });
    }
}

// WEB: Departman Rapor sayfası (günlük + haftalık + personel + AI analizi)
Route::get('/departman-rapor', function () {
    $bp = null;
    try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur'])) return redirect('/pos-giris');
    _departmanEnsure();
    $sid = _webSubeId();
    $id = (int) request('id');
    $dep = DB::table('departmanlar')->where('id', $id)->where('sube_id', $sid)->first();
    if (!$dep) return redirect('/patron-ai');
    $gun = \Carbon\Carbon::yesterday(); // dünkü rapor
    $simdi = null;
    $veri = _departmanRaporVeri($sid, $dep->kod ?? '', $gun, $simdi, (int) $dep->id);
    $haftalik = _departmanHaftalik($sid, $dep->kod ?? '', (int) $dep->id);
    // Bu departmana bağlı personel + bugünkü aktivitesi
    $personeller = [];
    try {
        foreach (DB::table('personeller')->where('sube_id', $sid)->where('departman_id', $id)->where('aktif', 1)->get(['id', 'ad', 'rol', 'departman_unvan']) as $pp) {
            $ad = (int) DB::table('adisyonlar')->where('sube_id', $sid)->where('acan_personel_id', $pp->id)->whereDate('created_at', $gun->toDateString())->count();
            $personeller[] = ['ad' => $pp->ad, 'rol' => $pp->rol, 'unvan' => $pp->departman_unvan, 'adisyon' => $ad];
        }
    } catch (\Throwable $e) {}
    $aiPers = array_map(fn ($x) => ['ad' => $x['ad'], 'unvan' => $x['unvan'] ?: $x['rol'], 'adisyon' => $x['adisyon']], $personeller);
    $ai = _departmanAiYorum($sid, $dep->ad, $dep->kod ?? '', $veri, $aiPers, request()->boolean('force'));
    return view('departman_rapor', ['dep' => $dep, 'veri' => $veri, 'haftalik' => $haftalik, 'personeller' => $personeller, 'ai' => $ai, 'tarih' => $gun->toDateString()]);
});

// AKSİYON: AI'nın yakaladığı kritik stoğu TEK TIKLA acil satın alma talebine çevir (çözüm odaklı).
Route::post('/patron-ai/acil-siparis', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur'])) return redirect('/patron-ai')->with('hata', 'Yetkisiz.');
    $sid = _webSubeId();
    $geri = request('geri', '/patron-ai');
    if (function_exists('_satinalmaTalepEnsure')) _satinalmaTalepEnsure();
    $kritik = function_exists('_kritikStokListesi') ? _kritikStokListesi($sid) : [];
    if (!$kritik) return redirect($geri)->with('ok', 'Şu an kritik stok yok, sipariş gerekmiyor.');
    try {
        $talepId = DB::table('satinalma_talepleri')->insertGetId([
            'sube_id' => $sid, 'departman' => 'Patron AI (acil)', 'isteyen_id' => $bp->id, 'isteyen_ad' => $bp->ad ?? 'Patron AI',
            'aciliyet' => 'acil', 'durum' => 'yeni', 'not' => 'Patron AI tarafından kritik stoktan otomatik oluşturuldu.',
            'created_at' => now(), 'updated_at' => now(),
        ]);
        foreach ($kritik as $k) {
            DB::table('talep_kalemleri')->insert([
                'talep_id' => $talepId, 'malzeme_id' => $k['id'], 'ad' => $k['ad'],
