Route::post('/fiyat-arastir-sec', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur', 'satinalmaci'])) return redirect('/patron-ai')->with('hata', 'Yetkisiz.');
    _rfqEnsure(); $sid = _webSubeId();
    $sec = (array) $r->input('sec', []);
    if (!$sec) return redirect('/fiyat-arastir-sec')->with('hata', 'En az bir tedarikçi işaretle.');
    $matMap = [];
    foreach ((function_exists('_kritikStokListesi') ? _kritikStokListesi($sid) : []) as $k) $matMap[(int) $k['id']] = ['malzeme_id' => (int) $k['id'], 'ad' => $k['ad'], 'miktar' => $k['oneri'], 'birim' => $k['birim']];
    $supMap = [];
    foreach ($sec as $pair) {
        $p = explode(':', (string) $pair); $mid = (int) ($p[0] ?? 0); $tid = (int) ($p[1] ?? 0);
        if ($mid && $tid && isset($matMap[$mid])) $supMap[$tid][] = $matMap[$mid];
    }
    if (!$supMap) return redirect('/fiyat-arastir-sec')->with('hata', 'Seçim çözümlenemedi.');
    $res = _rfqSupMapGonder($sid, $supMap, 0, 0);
    return redirect('/gelen-teklifler')->with('ok', $res['gonderilen'] . ' tedarikçiye fiyat isteği gönderildi (e-posta: ' . $res['mail'] . ', WhatsApp: ' . $res['wa'] . '). Yanıt gelince "Şimdi Teklifleri Oku" ile çek.');
});

// ============================ P3 — GELEN TEKLİFLERİ AI OKU (WhatsApp + Gmail) ============================
if (!function_exists('_rfqTeklifEnsure')) {
    function _rfqTeklifEnsure()
    {
        if (cache()->get('rfq_teklif_ensure_ok')) return;
        if (!Schema::hasTable('rfq_teklif')) {
            try { Schema::create('rfq_teklif', function ($t) {
                $t->id(); $t->unsignedBigInteger('sube_id')->index();
                $t->unsignedBigInteger('rfq_id')->nullable()->index(); $t->unsignedBigInteger('tedarikci_id')->nullable();
                $t->unsignedBigInteger('malzeme_id')->nullable(); $t->string('urun_ad', 160)->nullable();
                $t->decimal('fiyat', 14, 2)->default(0); $t->text('ham_metin')->nullable();
                $t->string('kaynak', 10)->nullable(); $t->string('kaynak_ref', 120)->nullable();
                $t->timestamps();
                $t->index(['rfq_id', 'kaynak_ref']);
            }); } catch (\Throwable $e) {}
        }
        cache()->put('rfq_teklif_ensure_ok', 1, now()->addHours(12));
    }
}
if (!function_exists('_rfqTeklifIsle')) {
    // Bir mesaj metninden RFQ kodu bul, fiyatları AI ile çıkar, kaydet, satınalmacıya bildir. Zaten işlendiyse atla.
    function _rfqTeklifIsle($sid, $metin, $kaynak, $ref, $tedId = null)
    {
        $metin = (string) $metin; if ($metin === '') return 0;
        if (!preg_match('/RFQ-(\d+)/i', $metin, $mm)) return 0;
        $rfqId = (int) $mm[1];
        _rfqEnsure(); _rfqTeklifEnsure();
        $rfq = DB::table('rfq_gonderim')->where('id', $rfqId)->where('sube_id', (int) $sid)->first();
        if (!$rfq) return 0;
        if (DB::table('rfq_teklif')->where('rfq_id', $rfqId)->where('kaynak_ref', $ref)->exists()) return 0; // dedup
        $ai = _patronAiCagir(
            'Bir tedarikçiden gelen fiyat teklifi mesajından ürün adı ve birim fiyatı çiftlerini çıkar. SADECE JSON dizi döndür (başka metin yok): [{"urun":"...","fiyat":123.45}]. Fiyat bulamazsan boş dizi [] döndür. Para birimi TL varsay.' . "\n--- MESAJ ---\n" . mb_substr($metin, 0, 1500),
            'Sadece JSON dizi döndür.', 600, null, $sid);
        if (!$ai) return 0;
        $s = strpos($ai, '['); $e = strrpos($ai, ']'); if ($s !== false && $e !== false && $e > $s) $ai = substr($ai, $s, $e - $s + 1);
        $j = json_decode($ai, true); if (!is_array($j) || !count($j)) return 0;
        $kalemler = json_decode($rfq->kalemler_json ?? '[]', true) ?: [];
        $say = 0;
        foreach ($j as $x) {
            $urun = trim((string) ($x['urun'] ?? '')); $fiyat = (float) str_replace(',', '.', (string) ($x['fiyat'] ?? 0));
            if ($urun === '' || $fiyat <= 0) continue;
            $mid = null;
            foreach ($kalemler as $k) { if (mb_stripos($urun, mb_substr($k['ad'], 0, 6)) !== false || mb_stripos($k['ad'], $urun) !== false) { $mid = (int) $k['malzeme_id']; break; } }
            try { DB::table('rfq_teklif')->insert(['sube_id' => (int) $sid, 'rfq_id' => $rfqId, 'tedarikci_id' => $tedId ?: $rfq->tedarikci_id, 'malzeme_id' => $mid, 'urun_ad' => mb_substr($urun, 0, 160), 'fiyat' => $fiyat, 'ham_metin' => mb_substr($metin, 0, 500), 'kaynak' => $kaynak, 'kaynak_ref' => $ref, 'created_at' => now(), 'updated_at' => now()]); $say++; } catch (\Throwable $e) {}
            // AI → TALEP KÖPRÜSÜ: RFQ bir talebe bağlıysa, eşleşen kaleme talep_teklifleri satırı da yaz (elle girmeden detayda görünsün)
            try {
                if ($mid && !empty($rfq->talep_id) && Schema::hasTable('talep_teklifleri')) {
                    $tk = DB::table('talep_kalemleri')->where('talep_id', $rfq->talep_id)->where('malzeme_id', $mid)->value('id');
                    $tedK = $tedId ?: $rfq->tedarikci_id;
                    if ($tk && $tedK && !DB::table('talep_teklifleri')->where('talep_kalem_id', $tk)->where('tedarikci_id', $tedK)->where('fiyat', $fiyat)->exists())
                        DB::table('talep_teklifleri')->insert(['talep_kalem_id' => $tk, 'tedarikci_id' => $tedK, 'fiyat' => $fiyat, 'not' => 'AI okudu (' . $kaynak . ')', 'created_at' => now()]);
                }
            } catch (\Throwable $e) {}
        }
        if ($say) {
            try { DB::table('rfq_gonderim')->where('id', $rfqId)->update(['durum' => 'teklif_geldi', 'updated_at' => now()]); } catch (\Throwable $e) {}
            $tedAd = DB::table('tedarikciler')->where('id', $rfq->tedarikci_id)->value('ad') ?: 'Tedarikçi';
            try { if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($sid, '💬 Fiyat Teklifi Geldi', $tedAd . ' ' . $say . ' ürün için fiyat gönderdi (' . $rfq->kod . ').', ['tur' => 'rfq_teklif', 'rfq' => (string) $rfqId], ['sahip', 'mudur', 'satinalmaci'], 'kritik_stok'); } catch (\Throwable $e) {}
        }
        return $say;
    }
}
// CRON: gelen WhatsApp + Gmail teklifleri oku. curl "/api/patron-ai/teklif-oku?key=SANTRAL_SECRET"
if (!function_exists('_teklifleriOku')) {
    // Bir şubenin TÜM gelen kanallarını tara (WhatsApp + kurumsal IMAP/saf-PHP + Gmail/Graph OAuth), RFQ yanıtlarını işle. İşlenen teklif sayısı döner.
    function _teklifleriOku($sid)
    {
        $n = 0;
        // WhatsApp gelen (son 2 gün)
        try { if (Schema::hasTable('wa_mesaj_loglari')) {
            foreach (DB::table('wa_mesaj_loglari')->where('sube_id', $sid)->where('yon', 'gelen')->where('created_at', '>=', now()->subDays(2))->orderByDesc('id')->limit(50)->get() as $m) {
                $n += _rfqTeklifIsle($sid, $m->mesaj, 'wa', 'wa:' . $m->id);
            }
        } } catch (\Throwable $e) {}
        // Kurumsal IMAP hesapları (ext-imap yoksa saf-PHP okuyucu)
        try { if (Schema::hasTable('eposta_hesaplari') && Schema::hasColumn('eposta_hesaplari', 'imap_host')) {
            foreach (DB::table('eposta_hesaplari')->where('sube_id', $sid)->whereNotNull('imap_host')->where('imap_host', '!=', '')->get() as $hes) {
                foreach (_imapOku($hes, 2, 30) as $mail) $n += _rfqTeklifIsle($sid, $mail['metin'], 'mail', $mail['ref']);
            }
        } } catch (\Throwable $e) {}
        // Gmail OAuth bağlantıları (şube + her departman) — REST oku
        try { if (Schema::hasTable('patron_ai_baglantilar') && function_exists('_oauthAccessToken')) {
            foreach (DB::table('patron_ai_baglantilar')->where('sube_id', $sid)->where('saglayici', 'google')->where('durum', 'aktif')->get() as $bg) {
                $tok = _oauthAccessToken($sid, 'google', $bg->departman_id ?? null); if (!$tok) continue;
                $liste = _oauthHttpGet('https://gmail.googleapis.com/gmail/v1/users/me/messages?q=' . rawurlencode('RFQ- newer_than:2d') . '&maxResults=15', $tok);
                foreach (($liste['messages'] ?? []) as $mm) {
                    $msg = _oauthHttpGet('https://gmail.googleapis.com/gmail/v1/users/me/messages/' . $mm['id'] . '?format=full', $tok);
                    $body = '';
                    foreach (($msg['payload']['parts'] ?? []) as $p) { if (!empty($p['body']['data'])) $body .= base64_decode(strtr($p['body']['data'], '-_', '+/')); }
                    if ($body === '' && !empty($msg['payload']['body']['data'])) $body = base64_decode(strtr($msg['payload']['body']['data'], '-_', '+/'));
                    $snippet = $body ?: ($msg['snippet'] ?? '');
                    $n += _rfqTeklifIsle($sid, $snippet, 'mail', 'gml:' . $bg->id . ':' . $mm['id']);
                }
            }
        } } catch (\Throwable $e) {}
        // Outlook/Graph OAuth bağlantıları — REST oku
        try { if (Schema::hasTable('patron_ai_baglantilar') && function_exists('_oauthAccessToken')) {
            foreach (DB::table('patron_ai_baglantilar')->where('sube_id', $sid)->where('saglayici', 'graph')->where('durum', 'aktif')->get() as $bg) {
                $tok = _oauthAccessToken($sid, 'graph', $bg->departman_id ?? null); if (!$tok) continue;
                $d = _oauthHttpGet('https://graph.microsoft.com/v1.0/me/mailFolders/inbox/messages?$top=20&$select=subject,body,receivedDateTime', $tok);
                foreach (($d['value'] ?? []) as $m) {
                    $metin = ($m['subject'] ?? '') . "\n" . strip_tags((string) ($m['body']['content'] ?? ''));
                    $n += _rfqTeklifIsle($sid, $metin, 'mail', 'grp:' . $bg->id . ':' . ($m['id'] ?? ''));
                }
            }
        } } catch (\Throwable $e) {}
        return $n;
    }
}
Route::get('/api/patron-ai/teklif-oku', function (Request $r) {
    $g = function_exists('_santralAuthGuard') ? _santralAuthGuard($r) : null; if ($g) return $g;
    $n = 0;
    foreach (DB::table('subeler')->pluck('id') as $sid) $n += _teklifleriOku($sid);
    return ['ok' => 1, 'teklif' => $n];
});
// WEB: Gelen Teklifler — AI'nın okuyup çıkardığı fiyatlar + "Şimdi Oku" butonu + test verisi kur
Route::get('/gelen-teklifler', function () {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur', 'satinalmaci'])) return redirect('/patron-ai')->with('hata', 'Yetkisiz.');
    _rfqEnsure(); if (function_exists('_rfqTeklifEnsure')) _rfqTeklifEnsure();
    $sid = _webSubeId();
    $teklifler = collect();
    try {
        $teklifler = DB::table('rfq_teklif')->where('sube_id', $sid)->orderByDesc('id')->limit(200)->get();
        $tedAd = DB::table('tedarikciler')->pluck('ad', 'id');
        $malAd = DB::table('malzemeler')->pluck('ad', 'id');
        // Her ürün için EN UCUZ teklifi bul (malzeme_id yoksa ürün adına göre)
        $minFiyat = [];
        foreach ($teklifler as $t) { $k = $t->malzeme_id ? ('m' . $t->malzeme_id) : ('u' . mb_strtolower(trim($t->urun_ad))); if (!isset($minFiyat[$k]) || (float) $t->fiyat < $minFiyat[$k]) $minFiyat[$k] = (float) $t->fiyat; }
        $ucuzIsaretli = [];
        $teklifler = $teklifler->map(function ($t) use ($tedAd, $malAd, $minFiyat, &$ucuzIsaretli) {
            $t->tedarikci_ad = $tedAd[$t->tedarikci_id] ?? '—';
            $t->malzeme_ad = $t->malzeme_id ? ($malAd[$t->malzeme_id] ?? $t->urun_ad) : $t->urun_ad;
            $k = $t->malzeme_id ? ('m' . $t->malzeme_id) : ('u' . mb_strtolower(trim($t->urun_ad)));
            $t->en_ucuz = (!isset($ucuzIsaretli[$k]) && abs((float) $t->fiyat - ($minFiyat[$k] ?? 0)) < 0.001);
            if ($t->en_ucuz) $ucuzIsaretli[$k] = true;
            return $t;
        });
    } catch (\Throwable $e) {}
    $acikRfq = 0; try { $acikRfq = DB::table('rfq_gonderim')->where('sube_id', $sid)->count(); } catch (\Throwable $e) {}
    return view('gelen_teklifler', ['teklifler' => $teklifler, 'acikRfq' => $acikRfq, 'sahip' => in_array(($bp->rol ?? ''), ['sahip', 'mudur'])]);
});
Route::post('/gelen-teklifler/oku', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur', 'satinalmaci'])) return redirect('/patron-ai')->with('hata', 'Yetkisiz.');
    $sid = _webSubeId();
    $n = 0; try { $n = _teklifleriOku($sid); } catch (\Throwable $e) {}
    return redirect('/gelen-teklifler')->with('ok', $n > 0 ? ('✅ ' . $n . ' yeni teklif okundu ve kaydedildi.') : 'Yeni teklif bulunamadı (gelen kutusunda RFQ kodlu yanıt yok ya da hepsi zaten işlenmiş).');
});
// Seçilen tekliflerden satın alma siparişi oluştur (tedarikçiye göre gruplu)
Route::post('/gelen-teklifler/siparis', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur', 'satinalmaci'])) return redirect('/patron-ai')->with('hata', 'Yetkisiz.');
    $sid = _webSubeId();
    $ids = array_filter(array_map('intval', (array) $r->input('teklif', [])));
    if (!$ids) return redirect('/gelen-teklifler')->with('hata', 'Sipariş için en az bir teklif işaretle.');
    $teklifler = DB::table('rfq_teklif')->where('sube_id', $sid)->whereIn('id', $ids)->get();
    if ($teklifler->isEmpty()) return redirect('/gelen-teklifler')->with('hata', 'Teklif bulunamadı.');
    // miktarları ilgili RFQ'nun kalemlerinden al
    $rfqKalem = [];
    foreach ($teklifler->pluck('rfq_id')->unique()->filter() as $rid) {
        try { $row = DB::table('rfq_gonderim')->where('id', $rid)->first(); if ($row) $rfqKalem[$rid] = json_decode($row->kalemler_json ?? '[]', true) ?: []; } catch (\Throwable $e) {}
    }
    $grup = []; $atlanan = 0;
    foreach ($teklifler as $t) {
        if (!$t->malzeme_id) { $atlanan++; continue; } // eşleşmemiş ürün (siparişe malzeme gerekir)
        $miktar = 1.0;
        foreach (($rfqKalem[$t->rfq_id] ?? []) as $k) { if ((int) ($k['malzeme_id'] ?? 0) === (int) $t->malzeme_id) { $miktar = (float) ($k['miktar'] ?? 1) ?: 1; break; } }
        $grup[(int) $t->tedarikci_id][] = ['malzeme_id' => (int) $t->malzeme_id, 'miktar' => $miktar, 'fiyat' => (float) $t->fiyat];
    }
    if (!$grup) return redirect('/gelen-teklifler')->with('hata', 'Seçilen teklifler stok malzemesine bağlı değil, sipariş oluşturulamadı.');
    $teslim = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $r->input('beklenen_teslim')) ? $r->input('beklenen_teslim') : null;
    $olusan = 0; $gonderildi = 0; $kanalSet = []; $pid = $bp->id ?? null;
    foreach ($grup as $tid => $kalemler) {
        try {
            $ara = 0; foreach ($kalemler as $k) $ara += $k['miktar'] * $k['fiyat'];
            $kdv = round($ara * 0.10, 2); $genel = round($ara + $kdv, 2);
            $sno = 'SA' . date('ymd') . '-' . str_pad((string) (DB::table('satinalma_siparisleri')->where('sube_id', $sid)->count() + 1), 3, '0', STR_PAD_LEFT);
            $spid = (int) DB::table('satinalma_siparisleri')->insertGetId(['sube_id' => $sid, 'tedarikci_id' => $tid ?: null, 'siparis_no' => $sno, 'tarih' => date('Y-m-d'), 'beklenen_teslim' => $teslim, 'durum' => 'siparis', 'ara_toplam' => round($ara, 2), 'kdv_toplam' => $kdv, 'genel_toplam' => $genel, 'notlar' => 'Gelen tekliften oluşturuldu', 'olusturan_personel_id' => $pid, 'created_at' => now(), 'updated_at' => now()]);
            foreach ($kalemler as $k) {
                DB::table('satinalma_siparis_kalemleri')->insert(['siparis_id' => $spid, 'malzeme_id' => $k['malzeme_id'], 'miktar' => $k['miktar'], 'birim_fiyat' => $k['fiyat'], 'kdv_yuzde' => 10, 'satir_toplam' => round($k['miktar'] * $k['fiyat'] * 1.10, 2), 'created_at' => now(), 'updated_at' => now()]);
            }
            $olusan++;
            // TEK TIKTA: oluştur + otomatik tedarikçiye gönder (mail + WhatsApp, onay linkiyle)
            try { $sr = _siparisGonderHelper($sid, $spid); if (!empty($sr['ok'])) { $gonderildi++; foreach ($sr['kanal'] as $kk) $kanalSet[$kk] = true; } } catch (\Throwable $e) {}
        } catch (\Throwable $e) {}
    }
    $kanalMsg = $kanalSet ? (' — ' . implode(' + ', array_keys($kanalSet)) . ' ile onay linki iletildi') : ' (tedarikçi e-postası yoksa iletilemedi — tedarikçi kartına mail ekle)';
    $msg = '✅ ' . $olusan . ' sipariş oluşturuldu, ' . $gonderildi . ' tanesi tedarikçiye otomatik gönderildi' . $kanalMsg . '.' . ($atlanan ? (' (' . $atlanan . ' eşleşmeyen ürün atlandı.)') : '');
    return redirect('/satinalma-siparis')->with('ok', $msg);
});
Route::post('/rfq-test-kur', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur'])) return redirect('/gelen-teklifler')->with('hata', 'Yetkisiz.');
    if (function_exists('_restoTedarikEnsure')) _restoTedarikEnsure();
    $sid = _webSubeId();
    try {
        $birimId = DB::table('birimler')->value('id');
        // Test malzemesi (kritik)
        $mid = DB::table('malzemeler')->where('ad', 'TEST Dana Kıyma')->value('id');
        if (!$mid) {
            $kol = ['ad' => 'TEST Dana Kıyma', 'stok_takipli' => 1, 'kritik_stok' => 9999, 'created_at' => now(), 'updated_at' => now()];
            if (Schema::hasColumn('malzemeler', 'temel_birim_id')) $kol['temel_birim_id'] = $birimId;
            if (Schema::hasColumn('malzemeler', 'sube_id')) $kol['sube_id'] = $sid;
            $mid = (int) DB::table('malzemeler')->insertGetId($kol);
        }
        // Test tedarikçisi — maili varsa departmanın bağlı mailine ayarla (RFQ kendi kutuna düşsün)
        $testMail = null;
        try { $testMail = DB::table('eposta_hesaplari')->where('sube_id', $sid)->orderByDesc('varsayilan')->value('email'); } catch (\Throwable $e) {}
        $tid = DB::table('tedarikciler')->where('ad', 'TEST Tedarik AŞ')->value('id');
        if (!$tid) {
            $tkol = ['ad' => 'TEST Tedarik AŞ', 'aktif' => 1, 'created_at' => now(), 'updated_at' => now()];
            foreach (['email' => $testMail, 'telefon' => null, 'yetkili' => 'Test Yetkili', 'anlasmali' => 1] as $k => $v) if (Schema::hasColumn('tedarikciler', $k)) $tkol[$k] = $v;
            $tid = (int) DB::table('tedarikciler')->insertGetId($tkol);
        } elseif ($testMail && Schema::hasColumn('tedarikciler', 'email')) {
            DB::table('tedarikciler')->where('id', $tid)->update(['email' => $testMail]);
        }
        // Katalog bağ (tedarikci_malzeme)
        if (!DB::table('tedarikci_malzeme')->where('tedarikci_id', $tid)->where('malzeme_id', $mid)->exists()) {
            DB::table('tedarikci_malzeme')->insert(['sube_id' => $sid, 'tedarikci_id' => $tid, 'malzeme_id' => $mid, 'guncel_fiyat' => 240, 'aktif' => 1, 'created_at' => now(), 'updated_at' => now()]);
        }
    } catch (\Throwable $e) { return redirect('/gelen-teklifler')->with('hata', 'Test verisi kurulamadı: ' . mb_substr($e->getMessage(), 0, 100)); }
    return redirect('/gelen-teklifler')->with('ok', 'Test verisi hazır: "TEST Dana Kıyma" malzemesi + "TEST Tedarik AŞ" tedarikçisi' . ($testMail ? (' (mail: ' . $testMail . ')') : '') . ' bağlandı. Şimdi "Fiyat Araştır" ile RFQ gönder.');
});
// TEST VERİLERİNİ SIFIRLA — RFQ/teklif/test siparişleri + TEST tedarikçi/malzeme temizle (sıfırdan test için)
Route::post('/rfq-test-sifirla', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur'])) return redirect('/gelen-teklifler')->with('hata', 'Yetkisiz.');
    $sid = _webSubeId(); $sil = [];
    try {
        // Gelen teklifler + RFQ kayıtları (hepsi test kaynaklı)
        if (Schema::hasTable('rfq_teklif')) { $n = DB::table('rfq_teklif')->where('sube_id', $sid)->delete(); if ($n) $sil[] = $n . ' teklif'; }
        if (Schema::hasTable('rfq_gonderim')) { $n = DB::table('rfq_gonderim')->where('sube_id', $sid)->delete(); if ($n) $sil[] = $n . ' RFQ'; }
        // Tekliften oluşturulan siparişler + kalemleri
        if (Schema::hasTable('satinalma_siparisleri')) {
            $spIds = DB::table('satinalma_siparisleri')->where('sube_id', $sid)->where('notlar', 'Gelen tekliften oluşturuldu')->pluck('id')->all();
            if ($spIds) {
                if (Schema::hasTable('satinalma_siparis_kalemleri')) DB::table('satinalma_siparis_kalemleri')->whereIn('siparis_id', $spIds)->delete();
                $n = DB::table('satinalma_siparisleri')->whereIn('id', $spIds)->delete(); if ($n) $sil[] = $n . ' sipariş';
            }
        }
        // TEST tedarikçi + malzeme + katalog bağ
        $tid = DB::table('tedarikciler')->where('ad', 'TEST Tedarik AŞ')->value('id');
        $mid = DB::table('malzemeler')->where('ad', 'TEST Dana Kıyma')->value('id');
        if ($tid) { try { DB::table('tedarikci_malzeme')->where('tedarikci_id', $tid)->delete(); } catch (\Throwable $e) {} DB::table('tedarikciler')->where('id', $tid)->delete(); $sil[] = 'TEST tedarikçi'; }
        if ($mid) { try { DB::table('tedarikci_malzeme')->where('malzeme_id', $mid)->delete(); } catch (\Throwable $e) {} DB::table('malzemeler')->where('id', $mid)->delete(); $sil[] = 'TEST malzeme'; }
    } catch (\Throwable $e) { return redirect('/gelen-teklifler')->with('hata', 'Sıfırlanamadı: ' . mb_substr($e->getMessage(), 0, 100)); }
    return redirect('/gelen-teklifler')->with('ok', '🔄 Sıfırlandı: ' . ($sil ? implode(', ', $sil) . ' silindi' : 'silinecek test verisi yoktu') . '. "Test Verisi Kur" ile baştan başlayabilirsin.');
});

// ============================ P4 — TESLİM TAKİBİ (hatırlatma + gecikme) ============================
if (!function_exists('_gecikenSiparisler')) {
    function _gecikenSiparisler($sid)
    {
        try { return DB::table('satinalma_siparisleri')->where('sube_id', (int) $sid)->whereIn('durum', ['siparis', 'onaylandi'])
            ->whereNotNull('beklenen_teslim')->whereDate('beklenen_teslim', '<', today())->count(); } catch (\Throwable $e) { return 0; }
    }
}
// CRON: teslim takibi. curl "/api/patron-ai/teslim-takip?key=SANTRAL_SECRET"
Route::get('/api/patron-ai/teslim-takip', function (Request $r) {
    $g = function_exists('_santralAuthGuard') ? _santralAuthGuard($r) : null; if ($g) return $g;
    $hat = 0; $gec = 0;
    foreach (DB::table('subeler')->pluck('id') as $sid) {
        $subeAd = optional(DB::table('subeler')->where('id', $sid)->first())->ad ?: 'İşletme';
        try {
            $acik = DB::table('satinalma_siparisleri')->where('sube_id', $sid)->whereIn('durum', ['siparis', 'onaylandi'])->whereNotNull('beklenen_teslim')->get();
            foreach ($acik as $s) {
                $ted = DB::table('tedarikciler')->where('id', $s->tedarikci_id)->first();
                $gun = \Carbon\Carbon::parse($s->beklenen_teslim);
                // 1 gün önce hatırlatma (günde 1)
                if ($gun->isTomorrow()) {
                    $ck = 'teslim_hat:' . $s->id . ':' . today()->toDateString();
                    if (!cache()->get($ck)) {
                        $msg = ($ted && $ted->yetkili ? ($ted->yetkili . ' Bey/Hanım, ') : 'Merhaba, ') . $subeAd . ' siparişi (' . $s->siparis_no . ') için YARIN teslim bekliyoruz. Teşekkürler.';
                        if ($ted && !empty($ted->telefon) && function_exists('_restoWaGonder')) _restoWaGonder($sid, $ted->telefon, $msg);
                        if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($sid, '📦 Teslim Yarın', ($ted->ad ?? 'Tedarikçi') . ' siparişi (' . $s->siparis_no . ') yarın teslim edilmeli.', ['tur' => 'teslim', 'id' => (string) $s->id], ['sahip', 'mudur', 'satinalmaci']);
                        cache()->put($ck, 1, now()->addDay()); $hat++;
                    }
                }
                // Gecikme (günde 1 patrona)
                if ($gun->lt(today())) {
                    $ck = 'teslim_gec:' . $s->id . ':' . today()->toDateString();
                    if (!cache()->get($ck)) {
                        $kacGun = (int) $gun->diffInDays(today());
                        if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($sid, '⏰ Teslimat Gecikti', ($ted->ad ?? 'Tedarikçi') . ' siparişi (' . $s->siparis_no . ') ' . $kacGun . ' gün gecikti.', ['tur' => 'teslim_gec', 'id' => (string) $s->id], ['sahip', 'mudur', 'satinalmaci'], 'gec_tedarik');
                        if ($ted && !empty($ted->telefon) && function_exists('_restoWaGonder')) _restoWaGonder($sid, $ted->telefon, ($ted->yetkili ? $ted->yetkili . ' Bey/Hanım, ' : 'Merhaba, ') . $subeAd . ' siparişi (' . $s->siparis_no . ') ' . $kacGun . ' gün gecikti; durum bilgisi rica ederiz.');
                        cache()->put($ck, 1, now()->addDay()); $gec++;
                    }
                }
            }
        } catch (\Throwable $e) {}
    }
    return ['ok' => 1, 'hatirlatma' => $hat, 'gecikme' => $gec];
});

// ============================ P5 — FİYAT RE-ONAY DÖNGÜSÜ (satınalmacı → üst yönetici → geri) ============================
Route::post('/satinalma-fiyat-onaya', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur', 'satinalmaci'])) return redirect('/satinalma-talep')->with('hata', 'Yetkisiz.');
    $sid = _webSubeId(); $id = (int) $r->input('talep');
    try {
        $t = DB::table('satinalma_talepleri')->where('id', $id)->where('sube_id', $sid)->first();
        if (!$t) return redirect('/satinalma-talep')->with('hata', 'Talep bulunamadı.');
        DB::table('satinalma_talepleri')->where('id', $id)->update(['durum' => 'fiyat_onay', 'not' => trim(($t->not ?? '') . "\n[Fiyat onayına gönderildi: " . ($bp->ad ?? '') . ']'), 'updated_at' => now()]);
        if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($sid, '💰 Fiyat Onayı Bekliyor', ($t->departman ?? 'Talep') . ' için satın alma fiyat onayınızı bekliyor.', ['tur' => 'satinalma_talep', 'id' => (string) $id], ['sahip', 'mudur']);
    } catch (\Throwable $e) { return redirect('/satinalma-talep')->with('hata', 'İşlem başarısız.'); }
    return redirect('/satinalma-talep')->with('ok', 'Talep üst yönetici fiyat onayına gönderildi.');
});
Route::post('/satinalma-fiyat-onayla', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur'])) return redirect('/satinalma-talep')->with('hata', 'Yalnızca üst yönetici.');
    $sid = _webSubeId(); $id = (int) $r->input('talep'); $karar = $r->input('karar') === 'ret' ? 'ret' : 'onay';
    try {
        $t = DB::table('satinalma_talepleri')->where('id', $id)->where('sube_id', $sid)->first();
        if (!$t) return redirect('/satinalma-talep')->with('hata', 'Talep bulunamadı.');
        $yeni = $karar === 'onay' ? 'onaylandi' : 'teklif';
        DB::table('satinalma_talepleri')->where('id', $id)->update(['durum' => $yeni, 'not' => trim(($t->not ?? '') . "\n[Fiyat " . ($karar === 'onay' ? 'ONAYLANDI' : 'REDDEDİLDİ') . ': ' . ($bp->ad ?? '') . ']'), 'updated_at' => now()]);
        if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($sid, ($karar === 'onay' ? '✅ Fiyat Onaylandı' : '❌ Fiyat Reddedildi'), ($t->departman ?? 'Talep') . ' fiyatı ' . ($karar === 'onay' ? 'onaylandı — sipariş geçebilirsin' : 'reddedildi — tekrar fiyat araştır') . '.', ['tur' => 'satinalma_talep', 'id' => (string) $id], ['satinalmaci', 'sahip', 'mudur']);
    } catch (\Throwable $e) { return redirect('/satinalma-talep')->with('hata', 'İşlem başarısız.'); }
    return redirect('/satinalma-talep')->with('ok', 'Fiyat ' . ($karar === 'onay' ? 'onaylandı' : 'reddedildi') . '.');
});

// Yetki kolonlarini kur + varsayilanlari doldur (tek sefer, migrate beklemeden)
Route::get('/yetki-kur', function () {
    if (!Schema::hasColumn('personeller', 'yetkiler')) {
        Schema::table('personeller', fn ($t) => $t->text('yetkiler')->nullable());
    }
    if (!Schema::hasColumn('personeller', 'iskonto_limit')) {
        Schema::table('personeller', fn ($t) => $t->decimal('iskonto_limit', 5, 2)->default(0));
    }
    if (!Schema::hasColumn('personeller', 'ikram_limit')) {
        Schema::table('personeller', fn ($t) => $t->decimal('ikram_limit', 12, 2)->nullable());
    }
    $n = 0;
    foreach (DB::table('personeller')->get(['id', 'rol', 'yetkiler', 'ikram_limit']) as $p) {
        $d = _restoYetkiVarsayilan($p->rol);
        if (!$p->yetkiler) {
            DB::table('personeller')->where('id', $p->id)->update(['yetkiler' => json_encode($d['yetkiler']), 'iskonto_limit' => $d['iskonto_limit'], 'ikram_limit' => $d['ikram_limit']]);
            $n++;
        } elseif ($p->ikram_limit === null) {
            DB::table('personeller')->where('id', $p->id)->update(['ikram_limit' => $d['ikram_limit']]);
        }
    }
    return "Yetkiler kuruldu: $n yeni + ikram limitleri güncellendi. ✅";
});

// ============================ FLUTTER API (token = personel PIN girisi) ============================
if (!function_exists('_apiPersonel')) {
    function _apiPersonel(Request $r)
    {
        $token = $r->bearerToken();
        if ($token) {
            $p = DB::table('personeller')->where('api_token', $token)->first();
            if ($p) {
                // Lisans/askı zorlaması (çok-şubeli; sahip ve tek-restoran muaf)
                if (($p->rol ?? '') !== 'sahip' && _subeKilitli($p->sube_id)) return null;
                return $p;
            }
        }
        // Web panel oturumu (POS session) — Bearer yoksa/geçersizse aktif oturumdaki personele düş.
        // Flutter her istekte Bearer gönderir (üstteki dal), bu dal yalnızca tarayıcı panelini etkiler.
        if (function_exists('_posPersonel')) {
            $sp = _posPersonel();
            if ($sp) {
                if (($sp->rol ?? '') !== 'sahip' && _subeKilitli($sp->sube_id)) return null;
                return $sp;
            }
        }
        return null;
    }
}

// WHITE-LABEL: subeye bagli marka konfigurasyonu (uygulama basligi/logo/tema).
// Kolonlar yoksa (eski kurulum) sessizce sube adina duser; appBundle app'ten gelir, echo edilir.
if (!function_exists('_markaConfig')) {
    function _markaConfig($sube, $appBundle = null)
    {
        $subeAd = is_object($sube) ? ($sube->ad ?? '') : '';
        $marka = [
            'ad' => $subeAd,
            'logo' => null,
            'renk' => null,
            'app_bundle' => $appBundle ?: null,
        ];
        if (is_object($sube)) {
            if (!empty($sube->marka_ad)) $marka['ad'] = $sube->marka_ad;
            if (!empty($sube->marka_logo)) $marka['logo'] = $sube->marka_logo;
            if (!empty($sube->marka_renk)) $marka['renk'] = $sube->marka_renk;
            if (!empty($sube->app_bundle)) $marka['app_bundle'] = $sube->app_bundle;
        }
        return $marka;
    }
}

Route::post('/api/login', function (Request $r) {
    // Patron app: sahip/mudur PIN ile giris
    // Tum AKTIF personel giris yapabilir (garson terminali dahil); UI role gore acilir.
    $pin = (string) $r->pin;
    // WHITE-LABEL: uygulama kendi bundle id'sini gonderir -> markali uygulama dogru markayi/subeyi acar.
    $appBundle = (string) ($r->appBundle ?? $r->app_bundle ?? '');
    // GUVENLIK: PIN brute-force korumasi. IP(+appBundle) basina SADECE basarisiz denemeleri say;
    // esik asilirsa kilit (429). Basarili giris sayaci sifirlar -> yogun terminal kilitlenmez.
    $rlKey = 'apilogin:' . $r->ip() . ':' . ($appBundle ?: 'global');
    if (\Illuminate\Support\Facades\RateLimiter::tooManyAttempts($rlKey, 10)) {
        $kalan = \Illuminate\Support\Facades\RateLimiter::availableIn($rlKey);
        return response()->json(['ok' => 0, 'hata' => 'Çok fazla hatalı deneme. ' . (int) ceil($kalan / 60) . ' dk sonra tekrar deneyin.'], 429);
    }
    // Markali uygulamadan giriliyorsa PIN'i O MARKANIN sube(ler)i icinde ara:
    //  - farkli restoranlarda ayni PIN cakissa bile dogru sube bulunur
    //  - baska markaya ait personel bu uygulamadan giremez
    // app_bundle bos ya da hicbir subeye atanmamissa (kurulum gecis donemi) -> eski global arama.
    $q = DB::table('personeller')->where('pin', $pin)->where('aktif', 1);
    if ($appBundle !== '' && Schema::hasColumn('subeler', 'app_bundle')) {
        $markaSubeIds = DB::table('subeler')->where('app_bundle', $appBundle)->pluck('id')->all();
        if (!empty($markaSubeIds)) $q->whereIn('sube_id', $markaSubeIds);
    }
    $p = $q->first();
    if (!$p) {
        \Illuminate\Support\Facades\RateLimiter::hit($rlKey, 600); // basarisiz -> 10 dk'lik pencerede say
        return response()->json(['ok' => 0, 'hata' => 'PIN hatalı'], 401);
    }
    \Illuminate\Support\Facades\RateLimiter::clear($rlKey); // basarili -> sayaci temizle
    // Mevcut token'i KORU (yeni login eskisini gecersiz kilmasin -> es zamanli oturumlar/testler bozulmaz)
    $token = $p->api_token ?: \Illuminate\Support\Str::random(48);
    if (!$p->api_token) DB::table('personeller')->where('id', $p->id)->update(['api_token' => $token]);
    $subeRow = DB::table('subeler')->where('id', $p->sube_id)->first();
    return [
        'ok' => 1, 'token' => $token,
        'personel' => ['id' => $p->id, 'ad' => $p->ad, 'rol' => $p->rol],
        'sube' => $subeRow->ad ?? null,
        'sube_id' => (int) $p->sube_id,
        'marka' => _markaConfig($subeRow, $appBundle),
    ];
});

// -------- FCM PUSH: cihaz token kayit/sil/test (mobil uygulama) --------
// Uygulama login sonrasi FCM token'ini buraya kaydeder; push bildirimleri bu tokenlara gider.
Route::post('/api/bildirim/cihaz-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $ok = _fcmTokenKaydet(
        $p->sube_id, $p->id,
        (string) ($r->token ?? ''),
        (string) ($r->platform ?? ''),
        (string) ($r->appBundle ?? $r->app_bundle ?? ''),
        'personel'
    );
    if (!$ok) return response()->json(['ok' => 0, 'hata' => 'Gecersiz token'], 422);
    return ['ok' => 1];
});
Route::post('/api/bildirim/cihaz-sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $token = trim((string) ($r->token ?? ''));
