    try {
        $q = DB::table('cihaz_tokenlari')->where('personel_id', (int) $p->id);
        if ($token !== '') $q->where('token', $token);
        $q->delete();
    } catch (\Throwable $e) {
    }
    return ['ok' => 1];
});
Route::post('/api/bildirim/test', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _fcmTokenEnsure();
