// ===== WEB PANEL: Rezervasyon (Flutter rezervasyon_screen karşılığı) =====
Route::get('/rezervasyon', function (\Illuminate\Http\Request $r) {
    $sube = _webSubeId();
    if (function_exists('_rezervasyonEnsure')) { try { _rezervasyonEnsure($sube); } catch (\Throwable $e) {} }
    $tarih = $r->query('tarih') ?: \Carbon\Carbon::now()->format('Y-m-d');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $tarih)) $tarih = \Carbon\Carbon::now()->format('Y-m-d');
    $rezervasyonlar = collect(); $masalar = collect();
    try {
        $rezervasyonlar = DB::table('rezervasyonlar')->leftJoin('masalar', 'rezervasyonlar.masa_id', '=', 'masalar.id')
            ->where('rezervasyonlar.sube_id', $sube)->where('rezervasyonlar.tarih', $tarih)->orderBy('rezervasyonlar.saat')
            ->select('rezervasyonlar.*', 'masalar.ad as masa_ad')->get();
    } catch (\Throwable $e) {}
    try { $masalar = DB::table('masalar')->where('sube_id', $sube)->orderBy('ad')->get(['id', 'ad', 'kapasite']); } catch (\Throwable $e) {}
    $ozet = ['toplam' => $rezervasyonlar->count(), 'bekleyen' => $rezervasyonlar->where('durum', 'bekliyor')->count(),
        'onaylanan' => $rezervasyonlar->where('durum', 'onaylandi')->count(),
        'misafir' => (int) $rezervasyonlar->whereIn('durum', ['bekliyor', 'onaylandi', 'geldi'])->sum('kisi')];
    $gunler = [];
    for ($i = 0; $i < 7; $i++) {
        $g = \Carbon\Carbon::now()->addDays($i)->format('Y-m-d'); $adet = 0;
        try { $adet = DB::table('rezervasyonlar')->where('sube_id', $sube)->where('tarih', $g)->whereIn('durum', ['bekliyor', 'onaylandi', 'geldi'])->count(); } catch (\Throwable $e) {}
        $gunler[] = ['tarih' => $g, 'adet' => $adet];
    }
    return view('rezervasyon', compact('tarih', 'rezervasyonlar', 'masalar', 'ozet', 'gunler'));
});
Route::post('/rezervasyon/ekle', function (\Illuminate\Http\Request $r) {
    $sube = _webSubeId();
    if (function_exists('_rezervasyonEnsure')) { try { _rezervasyonEnsure($sube); } catch (\Throwable $e) {} }
    $ad = trim((string) $r->input('ad'));
    $tarih = $r->input('tarih') ?: \Carbon\Carbon::now()->format('Y-m-d');
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $tarih)) $tarih = \Carbon\Carbon::now()->format('Y-m-d');
    $don = fn () => redirect('/rezervasyon?tarih=' . urlencode($tarih));
    if ($ad === '') return $don()->with('rez_hata', 'İsim gerekli.');
    $saat = substr(trim((string) $r->input('saat', '19:00')), 0, 5);
    $tel = trim((string) $r->input('telefon'));
    if ($tarih < \Carbon\Carbon::now()->format('Y-m-d')) return $don()->with('rez_hata', 'Geçmiş tarihe rezervasyon alınamaz.');
    if ($tarih === \Carbon\Carbon::now()->format('Y-m-d') && $saat < \Carbon\Carbon::now()->format('H:i')) return $don()->with('rez_hata', 'Geçmiş saate rezervasyon alınamaz.');
    $masaId = (int) $r->input('masa_id');
    try { if ($masaId && !DB::table('masalar')->where('id', $masaId)->where('sube_id', $sube)->exists()) $masaId = 0; } catch (\Throwable $e) { $masaId = 0; }
    if ($masaId) {
        try {
            $dk = fn ($s) => ((int) substr((string) $s, 0, 2)) * 60 + (int) substr((string) $s, 3, 2);
            $yeniDk = $dk($saat);
            foreach (DB::table('rezervasyonlar')->where('sube_id', $sube)->where('masa_id', $masaId)->where('tarih', $tarih)->whereIn('durum', ['bekliyor', 'onaylandi', 'geldi'])->pluck('saat') as $cs) {
                if (abs($dk(substr((string) $cs, 0, 5)) - $yeniDk) < 90) return $don()->with('rez_hata', 'Bu masa ' . substr((string) $cs, 0, 5) . ' civarında zaten rezerve.');
            }
        } catch (\Throwable $e) {}
    }
    try {
        $data = ['sube_id' => $sube, 'masa_id' => $masaId ?: null, 'ad' => $ad, 'telefon' => $tel ?: null,
            'kisi' => max(1, (int) $r->input('kisi', 2)), 'tarih' => $tarih, 'saat' => $saat, 'durum' => 'onaylandi',
            'kaynak' => 'admin', 'not' => trim((string) $r->input('not')) ?: null, 'created_at' => \Carbon\Carbon::now()];
        if (function_exists('_rezMusteriCozumle')) { try { $mid = _rezMusteriCozumle($sube, $ad, $tel, ''); if ($mid) $data['musteri_id'] = $mid; } catch (\Throwable $e) {} }
        DB::table('rezervasyonlar')->insert($data);
    } catch (\Throwable $e) { return $don()->with('rez_hata', 'Rezervasyon eklenemedi.'); }
    return $don()->with('rez_ok', "$ad · $tarih $saat rezervasyonu eklendi.");
});
Route::post('/rezervasyon/durum', function (\Illuminate\Http\Request $r) {
    $sube = _webSubeId();
    $geri = $r->input('tarih') ?: \Carbon\Carbon::now()->format('Y-m-d');
    $don = fn () => redirect('/rezervasyon?tarih=' . urlencode($geri));
    $durum = (string) $r->input('durum');
    if (!in_array($durum, ['bekliyor', 'onaylandi', 'geldi', 'iptal', 'gelmedi'])) return $don()->with('rez_hata', 'Geçersiz işlem.');
    try {
        $rez = DB::table('rezervasyonlar')->where('id', (int) $r->input('id'))->where('sube_id', $sube)->first();
        if (!$rez) return $don()->with('rez_hata', 'Rezervasyon bulunamadı.');
        DB::table('rezervasyonlar')->where('id', $rez->id)->update(['durum' => $durum]);
        if (!empty($rez->masa_id)) {
            $m = DB::table('masalar')->where('id', $rez->masa_id)->first();
            if ($m) {
                if ($durum === 'onaylandi' && $m->durum === 'bos') DB::table('masalar')->where('id', $rez->masa_id)->update(['durum' => 'rezerve']);
                if (in_array($durum, ['iptal', 'gelmedi', 'geldi']) && $m->durum === 'rezerve') DB::table('masalar')->where('id', $rez->masa_id)->update(['durum' => 'bos']);
            }
        }
    } catch (\Throwable $e) { return $don()->with('rez_hata', 'Durum güncellenemedi.'); }
    return $don()->with('rez_ok', 'Rezervasyon durumu güncellendi.');
});
// ===== WEB PANEL: Personel & Yetki (Flutter personel_screen karşılığı) =====
Route::get('/personel', function () {
    $sid = _webSubeId();
    try {
        if (!Schema::hasColumn('personeller', 'yetkiler')) Schema::table('personeller', fn ($t) => $t->text('yetkiler')->nullable());
        if (!Schema::hasColumn('personeller', 'iskonto_limit')) Schema::table('personeller', fn ($t) => $t->decimal('iskonto_limit', 5, 2)->default(0));
        if (!Schema::hasColumn('personeller', 'ikram_limit')) Schema::table('personeller', fn ($t) => $t->decimal('ikram_limit', 12, 2)->nullable());
    } catch (\Throwable $e) {}
    _panelYetkiEnsure();
    _departmanEnsure();
    $benSahip = false;
    try { $bp = _posPersonel(); $benSahip = $bp && ($bp->rol ?? '') === 'sahip'; } catch (\Throwable $e) {}
    $kolonlar = ['id', 'ad', 'telefon', 'rol', 'pin', 'aktif', 'yetkiler', 'iskonto_limit', 'ikram_limit', 'kademe', 'sayfa_yetki'];
    foreach (['departman_id', 'departman_unvan', 'departman_sorumlu'] as $dk) if (Schema::hasColumn('personeller', $dk)) $kolonlar[] = $dk;
    $personeller = DB::table('personeller')->where('sube_id', $sid)
        ->orderByRaw("FIELD(rol,'sahip','mudur','satinalmaci','kasa','garson','mutfak')")->orderBy('ad')
        ->get($kolonlar)
        ->map(function ($x) {
            $y = $x->yetkiler ? json_decode($x->yetkiler, true) : _restoYetkiVarsayilan($x->rol)['yetkiler'];
            $y = array_merge(array_fill_keys(_restoYetkiKeys(), false), is_array($y) ? $y : []);
            $kademe = $x->kademe ?: _rolKademe($x->rol);
            $sy = $x->sayfa_yetki ? json_decode($x->sayfa_yetki, true) : null;
            $sayfa = [];
            foreach (_panelSayfaKeys() as $k) {
                if (($x->rol ?? '') === 'sahip') { $sayfa[$k] = true; continue; }
                if (is_array($sy) && array_key_exists($k, $sy)) $sayfa[$k] = !empty($sy[$k]);
                else $sayfa[$k] = in_array($k, _kademeSayfalar($kademe));
            }
            return ['id' => (int) $x->id, 'ad' => $x->ad, 'telefon' => $x->telefon, 'rol' => $x->rol, 'pin' => $x->pin,
                'aktif' => (int) $x->aktif, 'yetkiler' => $y, 'iskonto_limit' => (float) $x->iskonto_limit,
                'ikram_limit' => $x->ikram_limit === null ? (float) _restoYetkiVarsayilan($x->rol)['ikram_limit'] : (float) $x->ikram_limit,
                'kademe' => $kademe, 'sayfa' => $sayfa, 'departman_id' => (int) ($x->departman_id ?? 0),
                'departman_unvan' => $x->departman_unvan ?? '', 'departman_sorumlu' => (int) ($x->departman_sorumlu ?? 0)];
        })->toArray();
    $kademeSayfa = [];
    foreach (array_keys(_panelKademeler()) as $kd) $kademeSayfa[$kd] = _kademeSayfalar($kd);
    $departmanlar = collect();
    try { $departmanlar = DB::table('departmanlar')->where('sube_id', $sid)->where('aktif', 1)->orderBy('grup')->orderBy('ad')->get(['id', 'ad', 'grup', 'renk', 'sayfa_yetki', 'sorumlu_ek', 'unvanlar']); } catch (\Throwable $e) {}
    // Editör haritaları: departman -> üye sayfaları / sorumlu ek sayfaları / ünvan listesi
    $departmanSayfa = []; $departmanEk = []; $departmanUnvan = [];
    foreach ($departmanlar as $d) {
        $departmanSayfa[(int) $d->id] = _departmanSayfaAcik($d);
        $ek = $d->sorumlu_ek ? json_decode($d->sorumlu_ek, true) : [];
        $departmanEk[(int) $d->id] = is_array($ek) ? array_values($ek) : [];
        $uv = $d->unvanlar ? json_decode($d->unvanlar, true) : [];
        $departmanUnvan[(int) $d->id] = is_array($uv) ? array_values($uv) : [];
    }
    return view('personel', ['personeller' => $personeller, 'duzenleyebilir' => $benSahip,
        'kademeler' => _panelKademeler(), 'sayfaKategori' => _panelSayfaKategori(), 'kademeSayfa' => $kademeSayfa, 'tumSayfa' => _panelSayfaKeys(),
        'departmanlar' => $departmanlar, 'departmanSayfa' => $departmanSayfa, 'departmanEk' => $departmanEk, 'departmanUnvan' => $departmanUnvan]);
});
Route::post('/personel/kaydet', function (Request $r) {
    $sid = _webSubeId();
    try {
        $ad = trim((string) $r->ad); $pid = (int) $r->id;
        if ($pid > 0 && $ad === '' && $r->has('aktif') && !$r->filled('rol')) {
            DB::table('personeller')->where('id', $pid)->where('sube_id', $sid)->update(['aktif' => $r->aktif === '0' ? 0 : 1, 'updated_at' => now()]);
            return redirect('/personel')->with('ok', 'Durum güncellendi.');
        }
        if ($ad === '') return redirect('/personel')->with('hata', 'İsim boş olamaz.');
        $rol = in_array($r->rol, ['sahip', 'mudur', 'kasa', 'garson', 'mutfak', 'satinalmaci']) ? $r->rol : 'garson';
        $pin = preg_replace('/\D/', '', (string) $r->pin);
        $veri = ['ad' => $ad, 'telefon' => $r->telefon ? (string) $r->telefon : null, 'rol' => $rol, 'aktif' => $r->aktif === '0' ? 0 : 1, 'updated_at' => now()];
        if ($pin !== '') {
            if (strlen($pin) < 4) return redirect('/personel')->with('hata', 'PIN en az 4 haneli olmalı.');
            $cak = DB::table('personeller')->where('sube_id', $sid)->where('pin', $pin)->where('id', '!=', $pid)->exists();
            if ($cak) return redirect('/personel')->with('hata', 'Bu PIN başka personelde kullanılıyor.');
            $veri['pin'] = $pin;
        }
        if ($pid > 0) {
            $hedef = DB::table('personeller')->where('id', $pid)->where('sube_id', $sid)->first();
            if (!$hedef) return redirect('/personel')->with('hata', 'Personel bulunamadı.');
            DB::table('personeller')->where('id', $pid)->update($veri);
            return redirect('/personel')->with('ok', 'Personel güncellendi.');
        }
        if ($pin === '') return redirect('/personel')->with('hata', 'Yeni personel için PIN zorunlu.');
        $veri['sube_id'] = $sid; $veri['created_at'] = now();
        DB::table('personeller')->insert($veri);
        return redirect('/personel')->with('ok', 'Personel eklendi.');
    } catch (\Throwable $e) { return redirect('/personel')->with('hata', 'Kaydedilemedi.'); }
});
Route::post('/personel/sil', function (Request $r) {
    $sid = _webSubeId();
    try {
        $hedef = DB::table('personeller')->where('id', (int) $r->id)->where('sube_id', $sid)->first();
        if (!$hedef) return redirect('/personel')->with('hata', 'Personel bulunamadı.');
        DB::table('personeller')->where('id', (int) $r->id)->where('sube_id', $sid)->delete();
        return redirect('/personel')->with('ok', $hedef->ad . ' silindi.');
    } catch (\Throwable $e) { return redirect('/personel')->with('hata', 'Silinemedi (bağlı kayıt olabilir).'); }
});
Route::post('/personel/yetki', function (Request $r) {
    $sid = _webSubeId();
    try {
        $bp = function_exists('_posPersonel') ? _posPersonel() : null;
        if (!$bp || ($bp->rol ?? '') !== 'sahip') return redirect('/personel')->with('hata', 'Yetki düzenlemeyi yalnızca işletme sahibi yapabilir.');
        _panelYetkiEnsure();
        $hedef = DB::table('personeller')->where('id', (int) $r->id)->where('sube_id', $sid)->first();
        if (!$hedef) return redirect('/personel')->with('hata', 'Personel bulunamadı.');
        $temiz = [];
        foreach (_restoYetkiKeys() as $k) $temiz[$k] = $r->has('yetki_' . $k);
        $kademe = in_array($r->kademe, array_keys(_panelKademeler())) ? $r->kademe : _rolKademe($hedef->rol);
        $sayfa = [];
        foreach (_panelSayfaKeys() as $k) $sayfa[$k] = $r->has('sayfa_' . $k);
        $guncelle = ['yetkiler' => json_encode($temiz),
            'kademe' => $kademe, 'sayfa_yetki' => json_encode($sayfa),
            'iskonto_limit' => max(0, min(100, (float) $r->iskonto_limit)), 'ikram_limit' => max(0, (float) $r->ikram_limit), 'updated_at' => now()];
        // Departman ataması (additif) — yalnız kolon varsa ve geçerli departman ise
        if (Schema::hasColumn('personeller', 'departman_id')) {
            $did = (int) $r->departman_id;
            $gecerli = $did > 0 && DB::table('departmanlar')->where('id', $did)->where('sube_id', $sid)->exists();
            $guncelle['departman_id'] = $gecerli ? $did : null;
            if (Schema::hasColumn('personeller', 'departman_unvan'))
                $guncelle['departman_unvan'] = ($gecerli && $r->filled('departman_unvan')) ? mb_substr((string) $r->departman_unvan, 0, 60) : null;
            if (Schema::hasColumn('personeller', 'departman_sorumlu'))
                $guncelle['departman_sorumlu'] = ($gecerli && $r->has('departman_sorumlu')) ? 1 : 0;
        }
        DB::table('personeller')->where('id', (int) $r->id)->update($guncelle);
        return redirect('/personel')->with('ok', 'Yetkiler kaydedildi.');
    } catch (\Throwable $e) { return redirect('/personel')->with('hata', 'Yetki kaydedilemedi.'); }
});
// ===== WEB PANEL: Kasa (nakit çekmece/vardiya) — Flutter kasa_screen karşılığı =====
Route::get('/kasa', function (Request $r) {
    $sube = _webSubeId();
    $period = in_array($r->period, ['gun', 'hafta', 'ay']) ? $r->period : 'gun';
    $data = ['period' => $period, 'acik' => false, 'son_devir' => 0, 'giris' => 0, 'cikis' => 0, 'beklenen' => 0, 'devir' => 0, 'hareketler' => [],
        'coklu' => false, 'kasa_ad' => null, 'kasa_id' => null];
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        if (!Schema::hasTable('kasa_hareketleri')) return view('kasa', $data);
        // ÇOKLU KASA: oturumdaki kasa noktasına odaklan (yoksa tek-havuz, bugünkü davranış)
        $kasaId = session('pos_kasa_id');
        $data['coklu'] = _kasalarAktif($sube)->count() > 0;
        if ($kasaId) { $data['kasa_id'] = $kasaId; $data['kasa_ad'] = DB::table('kasalar')->where('id', $kasaId)->value('ad'); }
        $o = null;
        if (Schema::hasTable('kasa_oturumlari')) {
            // seçili kasanın vardiyası; yoksa tek-havuz (kasa_id NULL) vardiyaya düşer — Flutter ile birebir
            $o = _kasaAcikOturum($sube, $kasaId);
            if ($o) {
                $data['acik'] = true; $data['devir'] = (float) $o->acilis_devir;
                $data['acilis'] = $o->acilis_zamani ? \Carbon\Carbon::parse($o->acilis_zamani)->format('d.m H:i') : '';
                $data['acan'] = DB::table('personeller')->where('id', $o->acan_personel_id)->value('ad') ?: '-';
                $data['giris'] = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'giris')->sum('tutar');
                $data['cikis'] = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'cikis')->sum('tutar');
                $data['beklenen'] = round($data['giris'] - $data['cikis'], 2);
            } else {
                $sonq = DB::table('kasa_oturumlari')->where('sube_id', $sube)->where('durum', 'kapali');
                if ($kasaId) $sonq->where(fn ($w) => $w->where('kasa_id', $kasaId)->orWhereNull('kasa_id'));
                $son = $sonq->orderByDesc('id')->first();
                $data['son_devir'] = $son ? (float) $son->sayilan_nakit : 0;
            }
        }
        // hareketler kasa filtresi: açık vardiya tek-havuz (NULL) ise kasa'ya göre kısma (Flutter aynısını gösterir)
        $effKasa = $o ? ($o->kasa_id ?? null) : $kasaId;
        $to = now();
        $from = $period === 'ay' ? (clone $to)->startOfMonth() : ($period === 'hafta' ? (clone $to)->subDays(7) : (clone $to)->startOfDay());
        $data['hareketler'] = DB::table('kasa_hareketleri as h')->leftJoin('personeller as pe', 'h.personel_id', '=', 'pe.id')
            ->where('h.sube_id', $sube)->when($effKasa, fn ($q) => $q->where('h.kasa_id', $effKasa))->whereBetween('h.created_at', [$from, $to])->orderByDesc('h.id')->limit(500)
            ->select('h.tip', 'h.yon', 'h.tutar', 'h.aciklama', 'h.created_at', 'pe.ad as personel')->get()
            ->map(fn ($h) => ['tip' => $h->tip, 'yon' => $h->yon, 'tutar' => (float) $h->tutar, 'aciklama' => $h->aciklama, 'personel' => $h->personel, 'zaman' => \Carbon\Carbon::parse($h->created_at)->format('d.m H:i')])->toArray();
    } catch (\Throwable $e) {}
    return view('kasa', $data);
});
Route::post('/kasa/hareket', function (Request $r) {
    $sube = _webSubeId();
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        if (!Schema::hasTable('kasa_hareketleri') || !Schema::hasTable('kasa_oturumlari')) return redirect('/kasa')->with('hata', 'Kasa tablosu bulunamadı.');
        $o = _kasaAcikOturum($sube, session('pos_kasa_id'));
        if (!$o) return redirect('/kasa')->with('hata', 'Açık kasa yok. Önce "Kasa Aç" ile vardiya başlatın.');
        $yon = in_array($r->yon, ['giris', 'cikis']) ? $r->yon : 'cikis';
        $tutar = round((float) $r->tutar, 2);
        if ($tutar <= 0) return redirect('/kasa')->with('hata', 'Geçerli bir tutar girin.');
        $hrow = ['sube_id' => $sube, 'oturum_id' => $o->id, 'tip' => $yon === 'giris' ? 'koy' : 'al', 'yon' => $yon, 'tutar' => $tutar,
            'aciklama' => $r->aciklama ? (string) $r->aciklama : ($yon === 'giris' ? 'Kasaya para konuldu' : 'Kasadan para alındı'), 'kaynak_tip' => 'manuel', 'kaynak_id' => null, 'personel_id' => null, 'created_at' => now()];
        if (cache()->get('resto_kasa_coklu_ok')) $hrow['kasa_id'] = $o->kasa_id ?? null;
        DB::table('kasa_hareketleri')->insert($hrow);
        return redirect('/kasa')->with('ok', $yon === 'giris' ? 'Kasaya eklendi.' : 'Kasadan düşüldü.');
    } catch (\Throwable $e) { return redirect('/kasa')->with('hata', 'İşlem sırasında hata oluştu.'); }
});
// ===== ÇOKLU KASA: Kasa (nokta/istasyon) Yönetimi =====
Route::get('/kasalar', function () {
    $sube = _webSubeId();
    $data = ['kasalar' => collect(), 'personeller' => collect()];
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        $kasalar = _kasalarAktif($sube);
        // açık vardiya durumu her kasa için
        $acik = Schema::hasTable('kasa_oturumlari')
            ? DB::table('kasa_oturumlari')->where('sube_id', $sube)->where('durum', 'acik')->whereNotNull('kasa_id')->pluck('id', 'kasa_id')
            : collect();
        // pasif kasalar da yönetimde görünsün
        $tum = Schema::hasTable('kasalar') ? DB::table('kasalar')->where('sube_id', $sube)->orderBy('sira')->orderBy('id')->get() : collect();
        $data['kasalar'] = $tum->map(function ($k) use ($acik) {
            $k->acik = isset($acik[$k->id]); return $k;
        });
        $data['personeller'] = DB::table('personeller')->where('sube_id', $sube)->where('aktif', 1)
            ->orderBy('ad')->get(['id', 'ad', 'rol', 'varsayilan_kasa_id']);
    } catch (\Throwable $e) {}
    return view('kasalar', $data);
});
Route::post('/kasalar/ekle', function (Request $r) {
    $sube = _webSubeId();
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        $ad = trim((string) $r->input('ad'));
        if ($ad === '') return redirect()->back()->with('hata', 'Kasa adı girin.');
        $sira = (int) (DB::table('kasalar')->where('sube_id', $sube)->max('sira') ?? 0) + 1;
        DB::table('kasalar')->insert(['sube_id' => $sube, 'ad' => mb_substr($ad, 0, 60), 'aktif' => 1, 'sira' => $sira, 'created_at' => now(), 'updated_at' => now()]);
        return redirect()->back()->with('ok', $ad . ' eklendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Kasa eklenemedi.'); }
});
Route::post('/kasalar/duzenle', function (Request $r) {
    $sube = _webSubeId();
    try {
        $k = DB::table('kasalar')->where('id', (int) $r->input('id'))->where('sube_id', $sube)->first();
        if (!$k) return redirect()->back()->with('hata', 'Kasa bulunamadı.');
        $upd = [];
        if ($r->filled('ad')) $upd['ad'] = mb_substr(trim((string) $r->input('ad')), 0, 60);
        if ($r->has('aktif')) $upd['aktif'] = $r->input('aktif') ? 1 : 0;
        if ($upd) { $upd['updated_at'] = now(); DB::table('kasalar')->where('id', $k->id)->update($upd); }
        return redirect()->back()->with('ok', 'Güncellendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Güncellenemedi.'); }
});
Route::post('/kasalar/sil', function (Request $r) {
    $sube = _webSubeId();
    try {
        $k = DB::table('kasalar')->where('id', (int) $r->input('id'))->where('sube_id', $sube)->first();
        if (!$k) return redirect()->back()->with('hata', 'Kasa bulunamadı.');
        if (Schema::hasTable('kasa_oturumlari') && DB::table('kasa_oturumlari')->where('kasa_id', $k->id)->where('durum', 'acik')->exists())
            return redirect()->back()->with('hata', 'Bu kasada açık vardiya var, önce kapatın.');
        // kayıtlar kalsın (geçmiş bozulmasın) → sadece pasife çek
        DB::table('kasalar')->where('id', $k->id)->update(['aktif' => 0, 'updated_at' => now()]);
        DB::table('personeller')->where('varsayilan_kasa_id', $k->id)->update(['varsayilan_kasa_id' => null]);
        return redirect()->back()->with('ok', $k->ad . ' kapatıldı (pasif).');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Kapatılamadı.'); }
});
Route::post('/kasalar/atama', function (Request $r) {
    $sube = _webSubeId();
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        $pid = (int) $r->input('personel_id');
        $per = DB::table('personeller')->where('id', $pid)->where('sube_id', $sube)->first();
        if (!$per) return redirect()->back()->with('hata', 'Personel bulunamadı.');
        $kid = (int) $r->input('kasa_id');
        $gecerli = $kid && DB::table('kasalar')->where('id', $kid)->where('sube_id', $sube)->exists();
        DB::table('personeller')->where('id', $pid)->update(['varsayilan_kasa_id' => $gecerli ? $kid : null, 'updated_at' => now()]);
        return redirect()->back()->with('ok', $per->ad . ' ataması güncellendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Atama yapılamadı.'); }
});

// ============================================================================
// İŞLETME DÜZENİ — tek sayfada: Bölge → Masa → Garson Ataması → Kasa (personel+masa)
// Mevcut tabloları (bolgeler/masalar/personel_atama/kasalar) kullanır; dağınık
// yönetim sayfalarını (masa-yonetim, salon-sema, kasalar) tek akışta toplar.
// ============================================================================
Route::get('/isletme-duzeni', function () {
    $sid = _webSubeId();
    $d = ['bolgeler' => collect(), 'masalar' => collect(), 'garsonlar' => collect(), 'kasalar' => collect(), 'personeller' => collect(), 'coklu' => false, 'subeAd' => 'Restoran'];
    try {
        $d['subeAd'] = DB::table('subeler')->where('id', $sid)->value('ad') ?: 'Restoran';
        if (function_exists('_masaQrEnsure')) _masaQrEnsure($sid);
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        if (function_exists('_atamaTablo')) _atamaTablo();

        $d['bolgeler'] = DB::table('bolgeler')->where('sube_id', $sid)->orderBy('sira')->orderBy('id')->get(['id', 'ad']);
        $kasaIdVar = Schema::hasColumn('masalar', 'kasa_id');
        $masaSel = ['id', 'ad', 'kapasite', 'bolge_id', 'durum', 'arsiv'];
        if (Schema::hasColumn('masalar', 'qr_token')) $masaSel[] = 'qr_token';
        if ($kasaIdVar) $masaSel[] = 'kasa_id';
        $d['masalar'] = DB::table('masalar')->where('sube_id', $sid)->where('arsiv', 0)->orderBy('bolge_id')->orderBy('id')->get($masaSel);

        // garson atamaları (bölge/masa)
        $atama = DB::table('personel_atama')->where('sube_id', $sid)->get(['personel_id', 'tip', 'hedef_id']);
        $bMap = []; $mMap = [];
        foreach ($atama as $a) { if ($a->tip === 'bolge') $bMap[$a->personel_id][] = (int) $a->hedef_id; else $mMap[$a->personel_id][] = (int) $a->hedef_id; }
        $d['garsonlar'] = DB::table('personeller')->where('sube_id', $sid)->where('aktif', 1)
            ->whereIn('rol', ['garson', 'mudur', 'sahip'])->orderBy('ad')->get(['id', 'ad', 'rol'])
            ->map(function ($g) use ($bMap, $mMap) { $g->bolge_idler = $bMap[$g->id] ?? []; $g->masa_idler = $mMap[$g->id] ?? []; return $g; });

        // kasalar + atanmış personel + atanmış masa
        $d['coklu'] = Schema::hasTable('kasalar');
        $kasalar = Schema::hasTable('kasalar') ? DB::table('kasalar')->where('sube_id', $sid)->where('aktif', 1)->orderBy('sira')->orderBy('id')->get(['id', 'ad']) : collect();
        $d['kasalar'] = $kasalar->map(function ($k) use ($sid, $kasaIdVar) {
            $k->masa_idler = $kasaIdVar ? DB::table('masalar')->where('sube_id', $sid)->where('kasa_id', $k->id)->pluck('id')->map(fn ($x) => (int) $x)->all() : [];
            return $k;
        });
        $d['personeller'] = DB::table('personeller')->where('sube_id', $sid)->where('aktif', 1)->orderBy('ad')->get(['id', 'ad', 'rol', 'varsayilan_kasa_id']);
    } catch (\Throwable $e) {}
    return view('isletme_duzeni', $d);
});
// --- Bölge CRUD ---
Route::post('/isletme-duzeni/bolge-ekle', function (Request $r) {
    $sid = _webSubeId();
    try {
        $ad = trim((string) $r->input('ad'));
        if ($ad === '') return redirect()->back()->with('hata', 'Bölge adı girin.');
        $sira = (int) (DB::table('bolgeler')->where('sube_id', $sid)->max('sira') ?? 0) + 1;
        $row = ['sube_id' => $sid, 'ad' => mb_substr($ad, 0, 60), 'sira' => $sira];
        if (Schema::hasColumn('bolgeler', 'created_at')) { $row['created_at'] = now(); $row['updated_at'] = now(); }
        DB::table('bolgeler')->insert($row);
        return redirect()->back()->with('ok', $ad . ' bölgesi eklendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Bölge eklenemedi.'); }
});
Route::post('/isletme-duzeni/bolge-duzenle', function (Request $r) {
    $sid = _webSubeId();
    try {
        $b = DB::table('bolgeler')->where('id', (int) $r->input('id'))->where('sube_id', $sid)->first();
        if (!$b) return redirect()->back()->with('hata', 'Bölge bulunamadı.');
        $ad = trim((string) $r->input('ad'));
        if ($ad === '') return redirect()->back()->with('hata', 'Bölge adı boş olamaz.');
        $upd = ['ad' => mb_substr($ad, 0, 60)];
        if (Schema::hasColumn('bolgeler', 'updated_at')) $upd['updated_at'] = now();
        DB::table('bolgeler')->where('id', $b->id)->update($upd);
        return redirect()->back()->with('ok', 'Bölge güncellendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Güncellenemedi.'); }
});
Route::post('/isletme-duzeni/bolge-sil', function (Request $r) {
    $sid = _webSubeId();
    try {
        $b = DB::table('bolgeler')->where('id', (int) $r->input('id'))->where('sube_id', $sid)->first();
        if (!$b) return redirect()->back()->with('hata', 'Bölge bulunamadı.');
        if (DB::table('masalar')->where('sube_id', $sid)->where('bolge_id', $b->id)->where('arsiv', 0)->exists())
            return redirect()->back()->with('hata', 'Bu bölgede masa var. Önce masaları başka bölgeye taşıyın.');
        DB::table('bolgeler')->where('id', $b->id)->delete();
        return redirect()->back()->with('ok', $b->ad . ' bölgesi silindi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Silinemedi.'); }
});
// Masanın bölgesini değiştir
Route::post('/isletme-duzeni/masa-bolge', function (Request $r) {
    $sid = _webSubeId();
    try {
        $m = DB::table('masalar')->where('id', (int) $r->input('id'))->where('sube_id', $sid)->first();
        if (!$m) return redirect()->back()->with('hata', 'Masa bulunamadı.');
        $bid = $r->filled('bolge_id') ? (int) $r->input('bolge_id') : null;
        if ($bid && !DB::table('bolgeler')->where('id', $bid)->where('sube_id', $sid)->exists()) $bid = null;
        $upd = ['bolge_id' => $bid];
        if (Schema::hasColumn('masalar', 'updated_at')) $upd['updated_at'] = now();
        DB::table('masalar')->where('id', $m->id)->update($upd);
        return redirect()->back()->with('ok', $m->ad . ' bölgesi güncellendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Güncellenemedi.'); }
});
// --- Garson ataması (bölge ∪ ekstra masa) — /api/patron/atama-kaydet ile aynı mantık ---
Route::post('/isletme-duzeni/garson-ata', function (Request $r) {
    $sid = _webSubeId();
    try {
        if (function_exists('_atamaTablo')) _atamaTablo();
        $pid = (int) $r->input('personel_id');
        if (!DB::table('personeller')->where('id', $pid)->where('sube_id', $sid)->exists())
            return redirect()->back()->with('hata', 'Personel bulunamadı.');
        $bolgeIdler = array_map('intval', (array) $r->input('bolge_idler', []));
        $masaIdler  = array_map('intval', (array) $r->input('masa_idler', []));
        DB::table('personel_atama')->where('sube_id', $sid)->where('personel_id', $pid)->delete();
        foreach (array_unique($bolgeIdler) as $bid) if ($bid > 0) { try { DB::table('personel_atama')->insert(['sube_id' => $sid, 'personel_id' => $pid, 'tip' => 'bolge', 'hedef_id' => $bid, 'created_at' => now()]); } catch (\Throwable $e) {} }
        foreach (array_unique($masaIdler) as $mid) if ($mid > 0) { try { DB::table('personel_atama')->insert(['sube_id' => $sid, 'personel_id' => $pid, 'tip' => 'masa', 'hedef_id' => $mid, 'created_at' => now()]); } catch (\Throwable $e) {} }
        return redirect()->back()->with('ok', 'Garson ataması kaydedildi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Atama kaydedilemedi.'); }
});
// --- Kasa -> masa ataması (bu kasaya bağlı masalar) ---
Route::post('/isletme-duzeni/kasa-masa', function (Request $r) {
    $sid = _webSubeId();
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        if (!Schema::hasColumn('masalar', 'kasa_id')) return redirect()->back()->with('hata', 'Kasa-masa kolonu yok.');
        $kid = (int) $r->input('kasa_id');
        if (!DB::table('kasalar')->where('id', $kid)->where('sube_id', $sid)->exists())
            return redirect()->back()->with('hata', 'Kasa bulunamadı.');
        $masaIdler = array_values(array_filter(array_map('intval', (array) $r->input('masa_idler', [])), fn ($x) => $x > 0));
        // önce bu kasaya bağlı tüm masaları çöz, sonra seçilenleri bağla (toggle set)
        DB::table('masalar')->where('sube_id', $sid)->where('kasa_id', $kid)->update(['kasa_id' => null]);
        if ($masaIdler) DB::table('masalar')->where('sube_id', $sid)->whereIn('id', $masaIdler)->update(['kasa_id' => $kid]);
        return redirect()->back()->with('ok', 'Kasaya bağlı masalar güncellendi.');
    } catch (\Throwable $e) { return redirect()->back()->with('hata', 'Masa ataması yapılamadı.'); }
});
// Web'den Kasa Aç (vardiya başlat) — oturumdaki kasa noktasına (çok-kasa) ya da tek-havuza
Route::post('/kasa/ac', function (Request $r) {
    $sube = _webSubeId();
    try {
        if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
        $pp = _posPersonel();
        $kasaId = session('pos_kasa_id');   // çok-kasa açıksa buradaki kasa; yoksa null (tek-havuz)
        if (_kasaAcikOturum($sube, $kasaId)) return redirect('/kasa')->with('hata', 'Zaten açık bir vardiya var.');
        $devir = max(0, round((float) $r->input('devir'), 2));
        $row = ['sube_id' => $sube, 'acan_personel_id' => $pp->id ?? null, 'acilis_devir' => $devir,
            'acilis_zamani' => now(), 'durum' => 'acik', 'created_at' => now(), 'updated_at' => now()];
        if (cache()->get('resto_kasa_coklu_ok') && $kasaId) $row['kasa_id'] = $kasaId;
        $oid = DB::table('kasa_oturumlari')->insertGetId($row);
        if ($devir > 0) {
            $h = ['sube_id' => $sube, 'oturum_id' => $oid, 'tip' => 'devir', 'yon' => 'giris', 'tutar' => $devir,
                'aciklama' => 'Açılış devir', 'kaynak_tip' => 'manuel', 'personel_id' => $pp->id ?? null, 'created_at' => now()];
            if (cache()->get('resto_kasa_coklu_ok') && $kasaId) $h['kasa_id'] = $kasaId;
            DB::table('kasa_hareketleri')->insert($h);
        }
        return redirect('/kasa')->with('ok', 'Kasa açıldı.');
    } catch (\Throwable $e) { return redirect('/kasa')->with('hata', 'Kasa açılamadı.'); }
});
// Web'den Kasa Kapat (say) — beklenen vs sayılan = fark
Route::post('/kasa/kapat', function (Request $r) {
    $sube = _webSubeId();
    try {
        $pp = _posPersonel();
        $kasaId = session('pos_kasa_id');
        $o = _kasaAcikOturum($sube, $kasaId);
        if (!$o) return redirect('/kasa')->with('hata', 'Açık kasa yok.');
        $giris = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'giris')->sum('tutar');
        $cikis = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'cikis')->sum('tutar');
        $beklenen = round($giris - $cikis, 2);
        $sayilan = round((float) $r->input('sayilan'), 2);
        DB::table('kasa_oturumlari')->where('id', $o->id)->update([
            'kapanis_zamani' => now(), 'beklenen_nakit' => $beklenen, 'sayilan_nakit' => $sayilan, 'fark' => round($sayilan - $beklenen, 2),
            'kapatan_personel_id' => $pp->id ?? null, 'durum' => 'kapali', 'not' => $r->input('not') ? (string) $r->input('not') : null, 'updated_at' => now()]);
        $fark = round($sayilan - $beklenen, 2);
        return redirect('/kasa')->with('ok', 'Kasa kapatıldı. ' . ($fark == 0 ? 'Tuttu ✓' : ($fark > 0 ? 'Fazla: ' : 'Açık: ') . number_format(abs($fark), 2, ',', '.') . ' ₺'));
    } catch (\Throwable $e) { return redirect('/kasa')->with('hata', 'Kasa kapatılamadı.'); }
});
// ===== WEB PANEL: Z Raporu — Flutter z_raporu_screen karşılığı =====
Route::get('/z-raporu', function (\Illuminate\Http\Request $r) {
    $sid = _webSubeId();
    $tarih = $r->tarih ? \Carbon\Carbon::parse($r->tarih) : today();
    $bugunC = today();
    $ymd = $tarih->format('Y-m-d');
    $onceki = (clone $tarih)->subDay()->format('Y-m-d');
    $sonraki = $tarih->lt($bugunC) ? (clone $tarih)->addDay()->format('Y-m-d') : null;
    $z = ['hata' => null, 'odeme' => collect(), 'servis' => collect(), 'top' => collect()];
    try {
        $from = (clone $tarih)->startOfDay(); $to = (clone $tarih)->endOfDay();
        $sube = DB::table('subeler')->find($sid);
        $ciro = (float) DB::table('odemeler')->join('adisyonlar', 'odemeler.adisyon_id', '=', 'adisyonlar.id')->where('adisyonlar.sube_id', $sid)->whereBetween('odemeler.created_at', [$from, $to])->sum('odemeler.tutar');
        $odeme = DB::table('odemeler')->join('adisyonlar', 'odemeler.adisyon_id', '=', 'adisyonlar.id')->where('adisyonlar.sube_id', $sid)->whereBetween('odemeler.created_at', [$from, $to])
            ->select('odemeler.tip as tip', DB::raw('COUNT(*) as adet'), DB::raw('SUM(odemeler.tutar) as tutar'))->groupBy('odemeler.tip')->orderByDesc('tutar')->get();
        $kapananQ = DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'odendi')->whereBetween('kapanis', [$from, $to]);
        $kapanan = (clone $kapananQ)->count();
        $misafir = (int) (clone $kapananQ)->sum('misafir_sayisi');
        $iskonto = (float) (clone $kapananQ)->sum('indirim');
        $ikram = (float) (clone $kapananQ)->sum('ikram');
        $iptalAdet = DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'iptal')->whereBetween('acilis', [$from, $to])->count();
        $iptalTutar = (float) DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'iptal')->whereBetween('acilis', [$from, $to])->sum('toplam');
        $void = (float) DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyon_kalemleri.adisyon_id', '=', 'adisyonlar.id')->where('adisyonlar.sube_id', $sid)->where('adisyon_kalemleri.durum', 'iptal')->whereBetween('adisyonlar.acilis', [$from, $to])->sum('adisyon_kalemleri.tutar');
        $fire = 0.0;
        try { $fire = (float) DB::table('stok_hareketleri')->where('sube_id', $sid)->where('tip', 'fire')->whereBetween('created_at', [$from, $to])->select(DB::raw('COALESCE(SUM(ABS(miktar)*birim_maliyet),0) as t'))->value('t'); } catch (\Throwable $e) {}
        $maliyet = 0.0;
        if (function_exists('_restoUrunMaliyetMap')) {
            $map = _restoUrunMaliyetMap();
            $satir = DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyon_kalemleri.adisyon_id', '=', 'adisyonlar.id')->where('adisyonlar.sube_id', $sid)->where('adisyonlar.durum', 'odendi')->whereBetween('adisyonlar.kapanis', [$from, $to])->where('adisyon_kalemleri.durum', '!=', 'iptal')
                ->select('adisyon_kalemleri.urun_id', 'adisyon_kalemleri.urun_adi', DB::raw('SUM(adet) as adet'), DB::raw('SUM(adisyon_kalemleri.tutar) as satis'))->groupBy('adisyon_kalemleri.urun_id', 'adisyon_kalemleri.urun_adi')->get();
            foreach ($satir as $s) { $b = $map['id'][(int) $s->urun_id] ?? ($map['ad'][$s->urun_adi] ?? 0); $m = (float) $s->adet * (float) $b; if ($m <= 0 && $s->satis > 0) $m = (float) $s->satis * 0.30; $maliyet += $m; }
        }
        $servis = DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'odendi')->whereBetween('kapanis', [$from, $to])->select('kanal', DB::raw('COUNT(*) as adet'), DB::raw('SUM(toplam) as tutar'))->groupBy('kanal')->get()
            ->map(fn ($k) => ['ad' => ['salon' => 'Masa', 'paket' => 'Paket', 'qr' => 'QR'][$k->kanal] ?? ucfirst((string) $k->kanal), 'adet' => $k->adet, 'tutar' => (float) $k->tutar]);
        $top = DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyon_kalemleri.adisyon_id', '=', 'adisyonlar.id')->where('adisyonlar.sube_id', $sid)->where('adisyonlar.durum', 'odendi')->whereBetween('adisyonlar.kapanis', [$from, $to])->where('adisyon_kalemleri.durum', '!=', 'iptal')
            ->select('urun_adi', DB::raw('SUM(adet) as adet'), DB::raw('SUM(adisyon_kalemleri.tutar) as ciro'))->groupBy('urun_adi')->orderByDesc('adet')->limit(5)->get();
        $acikKalan = DB::table('adisyonlar')->where('sube_id', $sid)->where('durum', 'acik')->count();
        $z = ['hata' => null, 'isletme' => $sube->ad ?? 'ResteOS', 'tarih' => $tarih->format('d.m.Y'), 'ciro' => $ciro, 'kapanan' => $kapanan, 'misafir' => $misafir,
            'ortalama' => $kapanan > 0 ? round($ciro / $kapanan) : 0, 'kisi_basi' => $misafir > 0 ? round($ciro / $misafir) : 0, 'odeme' => $odeme, 'servis' => $servis, 'top' => $top,
            'iskonto' => $iskonto, 'ikram' => $ikram, 'iptal_adet' => $iptalAdet, 'iptal_tutar' => $iptalTutar, 'void' => $void, 'fire' => $fire,
            'maliyet' => round($maliyet), 'maliyet_yuzde' => $ciro > 0 ? round($maliyet / $ciro * 100) : 0, 'brut_kar' => round($ciro - $maliyet), 'acik_kalan' => $acikKalan];
    } catch (\Throwable $e) { $z = ['hata' => $e->getMessage(), 'odeme' => collect(), 'servis' => collect(), 'top' => collect()]; }
    $bugun = $bugunC->format('Y-m-d');
    return view('z_raporu', compact('z', 'ymd', 'bugun', 'onceki', 'sonraki'));
});
