Route::post('/cari/tahsilat', function (Request $r) {
    $sid = _webSubeId();
    try {
        if (!Schema::hasTable('cari_hareketler')) return redirect('/cari')->with('cari_hata', 'Cari tablosu kurulu değil.');
        $c = DB::table('cari_hesaplar')->where('id', (int) $r->input('cari_id'))->where('sube_id', $sid)->first();
        if (!$c) return redirect('/cari')->with('cari_hata', 'Cari bulunamadı.');
        $tutar = max(0, (float) str_replace(',', '.', (string) $r->input('tutar')));
        if ($tutar <= 0) return redirect('/cari?id=' . $c->id)->with('cari_hata', 'Geçerli bir tutar girin.');
        $sekil = in_array($r->input('odeme_sekli'), ['nakit', 'havale', 'kredi']) ? $r->input('odeme_sekli') : 'nakit';
        DB::table('cari_hareketler')->insert(['sube_id' => $sid, 'cari_id' => $c->id, 'tip' => 'tahsilat', 'tutar' => $tutar, 'odeme_sekli' => $sekil, 'aciklama' => 'Tahsilat (web panel)', 'created_at' => now()]);
        if ($sekil === 'nakit' && function_exists('_kasaYaz')) { try { _kasaYaz($sid, 'tahsilat', 'giris', $tutar, $c->ad . ' cari tahsilat', 'cari', $c->id, null); } catch (\Throwable $e) {} }
        return redirect('/cari?id=' . $c->id)->with('cari_ok', number_format($tutar, 0, ',', '.') . '₺ tahsil edildi.');
    } catch (\Throwable $e) { return redirect('/cari')->with('cari_hata', 'Tahsilat kaydedilemedi.'); }
});
// ===== WEB PANEL: Tedarikçiler — Flutter tedarikci_screen karşılığı =====
// ============================================================================
// FAZ 1 — TEDARİKÇİ BAĞLARI: zengin tedarikçi kartı + malzeme-tedarikçi katalog/fiyat + tedarikçi cari.
// Çekirdek KORUNUR; hepsi additive + guard'lı (Flutter/canlı bozulmaz). Tüm yüzeyler (web/Flutter/app)
// bu çekirdeği besler → birebir parite. stok_hareketleri tek doğruluk kaynağı.
// ============================================================================
if (!function_exists('_restoTedarikEnsure')) {
    function _restoTedarikEnsure()
    {
        if (cache()->get('resto_tedarik_ensure_ok')) return;
        try {
            if (Schema::hasTable('tedarikciler')) {
                $ek = [
                    'unvan'          => fn ($t) => $t->string('unvan', 160)->nullable(),
                    'vkn_tckn'       => fn ($t) => $t->string('vkn_tckn', 16)->nullable(),
                    'vergi_dairesi'  => fn ($t) => $t->string('vergi_dairesi', 80)->nullable(),
                    'adres'          => fn ($t) => $t->string('adres', 255)->nullable(),
                    'yetkili'        => fn ($t) => $t->string('yetkili', 120)->nullable(),
                    'email'          => fn ($t) => $t->string('email', 120)->nullable(),
                    'iban'           => fn ($t) => $t->string('iban', 34)->nullable(),
                    'odeme_vade_gun' => fn ($t) => $t->integer('odeme_vade_gun')->nullable(),
                    'aktif'          => fn ($t) => $t->tinyInteger('aktif')->default(1),
                    'cari_id'        => fn ($t) => $t->unsignedBigInteger('cari_id')->nullable(),
                    'anlasmali'      => fn ($t) => $t->tinyInteger('anlasmali')->default(0), // anlaşmalı → satın almacı onaysız direkt sipariş geçebilir
                ];
                foreach ($ek as $kol => $fn) {
                    if (!Schema::hasColumn('tedarikciler', $kol)) Schema::table('tedarikciler', $fn);
                }
            }
            // Katalog / fiyat listesi — radar + RFQ + gizli-zam dedektörünün beyni; faturalardan kendiliğinden dolar
            if (!Schema::hasTable('tedarikci_malzeme')) {
                Schema::create('tedarikci_malzeme', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id');
                    $t->unsignedBigInteger('tedarikci_id');
                    $t->unsignedBigInteger('malzeme_id');
                    $t->string('tedarikci_urun_kodu', 60)->nullable();
                    $t->unsignedBigInteger('alis_birim_id')->nullable();
                    $t->decimal('guncel_fiyat', 14, 4)->nullable();
                    $t->decimal('son_fiyat', 14, 4)->nullable();
                    $t->date('son_alis_tarihi')->nullable();
                    $t->decimal('min_siparis', 14, 3)->nullable();
                    $t->integer('teslim_suresi_gun')->nullable();
                    $t->tinyInteger('aktif')->default(1);
                    $t->timestamps();
                    $t->unique(['tedarikci_id', 'malzeme_id']);
                    $t->index(['sube_id', 'malzeme_id']);
                });
            }
            cache()->put('resto_tedarik_ensure_ok', 1, now()->addHours(12));
        } catch (\Throwable $e) {}
    }
}
// Tedarikçinin cari hesabını getir/oluştur (cari_hesaplar tip=tedarikci) — borç/ödeme/vade için
if (!function_exists('_tedarikciCari')) {
    function _tedarikciCari($subeId, $tedarikciId)
    {
        try {
            _restoTedarikEnsure();
            if (!Schema::hasTable('cari_hesaplar') || !Schema::hasTable('tedarikciler')) return null;
            $ted = DB::table('tedarikciler')->where('id', $tedarikciId)->first();
            if (!$ted) return null;
            if (!empty($ted->cari_id) && DB::table('cari_hesaplar')->where('id', $ted->cari_id)->exists()) return (int) $ted->cari_id;
            $cid = DB::table('cari_hesaplar')->insertGetId(['sube_id' => $subeId, 'ad' => $ted->ad, 'tip' => 'tedarikci', 'telefon' => $ted->telefon ?? null, 'aktif' => 1, 'created_at' => now()]);
            DB::table('tedarikciler')->where('id', $tedarikciId)->update(['cari_id' => $cid]);
            return (int) $cid;
        } catch (\Throwable $e) { return null; }
    }
}
// Fatura/mal kabul satırından katalog fiyatını güncelle (otomatik tedarikçi fiyat zekâsı)
if (!function_exists('_tedarikMalzemeFiyat')) {
    function _tedarikMalzemeFiyat($subeId, $tedarikciId, $malzemeId, $alisBirimId, $fiyat, $tarih = null)
    {
        try {
            if (!$tedarikciId || !$malzemeId) return;
            _restoTedarikEnsure();
            if (!Schema::hasTable('tedarikci_malzeme')) return;
            $fiyat = round((float) $fiyat, 4);
            if ($fiyat <= 0) return;
            $tarih = $tarih ?: now()->toDateString();
            $row = DB::table('tedarikci_malzeme')->where('tedarikci_id', $tedarikciId)->where('malzeme_id', $malzemeId)->first();
            if ($row) {
                DB::table('tedarikci_malzeme')->where('id', $row->id)->update(['son_fiyat' => $row->guncel_fiyat, 'guncel_fiyat' => $fiyat, 'alis_birim_id' => $alisBirimId ?: $row->alis_birim_id, 'son_alis_tarihi' => $tarih, 'updated_at' => now()]);
            } else {
                DB::table('tedarikci_malzeme')->insert(['sube_id' => $subeId, 'tedarikci_id' => $tedarikciId, 'malzeme_id' => $malzemeId, 'alis_birim_id' => $alisBirimId, 'guncel_fiyat' => $fiyat, 'son_alis_tarihi' => $tarih, 'aktif' => 1, 'created_at' => now(), 'updated_at' => now()]);
            }
        } catch (\Throwable $e) {}
    }
}

// ============================================================================
// FAZ 2 — SATINALMA DÖNGÜSÜ: PO (sipariş) → mal kabul (irsaliye/GRN) → fatura + 3'lü eşleştirme.
// Hepsi additive + guard'lı. stok_hareketleri tek doğruluk kaynağı (mal kabul onayı stok yazar).
// ============================================================================
if (!function_exists('_restoSatinalmaEnsure')) {
    function _restoSatinalmaEnsure()
    {
        if (cache()->get('resto_satinalma_ensure_ok4')) return;
        try {
            if (!Schema::hasTable('satinalma_siparisleri')) {
                Schema::create('satinalma_siparisleri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id');
                    $t->unsignedBigInteger('tedarikci_id')->nullable();
                    $t->string('siparis_no', 40)->nullable();
                    $t->date('tarih')->nullable();
                    $t->date('beklenen_teslim')->nullable();
                    $t->string('durum', 16)->default('taslak'); // taslak|gonderildi|kismi|tamamlandi|iptal
                    $t->decimal('ara_toplam', 14, 2)->default(0);
                    $t->decimal('iskonto', 14, 2)->default(0);
                    $t->decimal('kdv_toplam', 14, 2)->default(0);
                    $t->decimal('genel_toplam', 14, 2)->default(0);
                    $t->string('notlar', 255)->nullable();
                    $t->unsignedBigInteger('olusturan_personel_id')->nullable();
                    $t->timestamps();
                    $t->index(['sube_id', 'durum']);
                });
            }
            if (!Schema::hasTable('satinalma_siparis_kalemleri')) {
                Schema::create('satinalma_siparis_kalemleri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('siparis_id');
                    $t->unsignedBigInteger('malzeme_id');
                    $t->unsignedBigInteger('alis_birim_id')->nullable();
                    $t->decimal('miktar', 14, 3)->default(0);
                    $t->decimal('birim_fiyat', 14, 4)->default(0);
                    $t->decimal('iskonto_yuzde', 6, 2)->default(0);
                    $t->decimal('kdv_yuzde', 6, 2)->default(0);
                    $t->decimal('satir_toplam', 14, 2)->default(0);
                    $t->decimal('teslim_edilen', 14, 3)->default(0);
                    $t->timestamps();
                    $t->index('siparis_id');
                });
            }
            if (!Schema::hasTable('mal_kabuller')) {
                Schema::create('mal_kabuller', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id');
                    $t->unsignedBigInteger('tedarikci_id')->nullable();
                    $t->unsignedBigInteger('siparis_id')->nullable();
                    $t->string('irsaliye_no', 40)->nullable();
                    $t->date('tarih')->nullable();
                    $t->unsignedBigInteger('teslim_alan_personel_id')->nullable();
                    $t->string('durum', 16)->default('tam'); // kismi|tam
                    $t->string('notlar', 255)->nullable();
                    $t->tinyInteger('stok_islendi')->default(0);
                    $t->timestamps();
                    $t->index(['sube_id', 'tarih']);
                });
            }
            if (!Schema::hasTable('mal_kabul_kalemleri')) {
                Schema::create('mal_kabul_kalemleri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('mal_kabul_id');
                    $t->unsignedBigInteger('siparis_kalem_id')->nullable();
                    $t->unsignedBigInteger('malzeme_id');
                    $t->unsignedBigInteger('alis_birim_id')->nullable();
                    $t->decimal('siparis_miktar', 14, 3)->nullable();
                    $t->decimal('gelen_miktar', 14, 3)->default(0);
                    $t->decimal('kabul_miktar', 14, 3)->default(0);
                    $t->decimal('red_miktar', 14, 3)->default(0);
                    $t->string('red_sebep', 120)->nullable();
                    $t->decimal('birim_fiyat', 14, 4)->default(0);
                    $t->string('lot_no', 60)->nullable();
                    $t->date('uretim_tarihi')->nullable();
                    $t->date('skt')->nullable();
                    $t->timestamps();
                    $t->index('mal_kabul_id');
                });
            }
            // alis_faturalari genişlet (3-way match + iskonto/KDV/irsaliye/vade)
            if (Schema::hasTable('alis_faturalari')) {
                $fek = [
                    'irsaliye_no'     => fn ($t) => $t->string('irsaliye_no', 40)->nullable(),
                    'mal_kabul_id'    => fn ($t) => $t->unsignedBigInteger('mal_kabul_id')->nullable(),
                    'siparis_id'      => fn ($t) => $t->unsignedBigInteger('siparis_id')->nullable(),
                    'ara_toplam'      => fn ($t) => $t->decimal('ara_toplam', 14, 2)->nullable(),
                    'iskonto'         => fn ($t) => $t->decimal('iskonto', 14, 2)->default(0),
                    'kdv_toplam'      => fn ($t) => $t->decimal('kdv_toplam', 14, 2)->default(0),
                    'vade_tarihi'     => fn ($t) => $t->date('vade_tarihi')->nullable(),
                    'eslesme_durumu'  => fn ($t) => $t->string('eslesme_durumu', 16)->nullable(), // beklemede|eslesti|fark_var
                ];
                foreach ($fek as $kol => $fn) { if (!Schema::hasColumn('alis_faturalari', $kol)) Schema::table('alis_faturalari', $fn); }
            }
            if (Schema::hasTable('alis_fatura_kalemleri')) {
                $kek = [
                    'iskonto_yuzde' => fn ($t) => $t->decimal('iskonto_yuzde', 6, 2)->default(0),
                    'kdv_yuzde'     => fn ($t) => $t->decimal('kdv_yuzde', 6, 2)->default(0),
                    'kdv_tutar'     => fn ($t) => $t->decimal('kdv_tutar', 14, 2)->default(0),
                ];
                foreach ($kek as $kol => $fn) { if (!Schema::hasColumn('alis_fatura_kalemleri', $kol)) Schema::table('alis_fatura_kalemleri', $fn); }
            }
            // Faz 4: par / hedef stok (otomatik sipariş önerisi için)
            if (Schema::hasTable('malzemeler') && !Schema::hasColumn('malzemeler', 'hedef_stok')) {
                Schema::table('malzemeler', fn ($t) => $t->decimal('hedef_stok', 14, 3)->default(0));
            }
            // Mal kabulde fatura toplamları + başlık bilgileri (foto-OCR; 3-way fatura eşleştirme için)
            if (Schema::hasTable('mal_kabuller')) {
                $mkt = [
                    'ara_toplam'   => fn ($t) => $t->decimal('ara_toplam', 14, 2)->nullable(),
                    'kdv_tutar'    => fn ($t) => $t->decimal('kdv_tutar', 14, 2)->nullable(),
                    'genel_toplam' => fn ($t) => $t->decimal('genel_toplam', 14, 2)->nullable(),
                    'fatura_bilgi' => fn ($t) => $t->text('fatura_bilgi')->nullable(), // seri/sıra/sevk/saat/alıcı/satıcı/teslim eden JSON
                ];
                foreach ($mkt as $kol => $fn) { if (!Schema::hasColumn('mal_kabuller', $kol)) Schema::table('mal_kabuller', $fn); }
            }
            // "Kasa" birimi (kasa/kasa fiyatıyla alım için) — yoksa ekle
            if (Schema::hasTable('birimler') && !DB::table('birimler')->where('kisaltma', 'kasa')->exists()) {
                DB::table('birimler')->insert(['ad' => 'Kasa', 'kisaltma' => 'kasa', 'tip' => 'adet']);
            }
            cache()->put('resto_satinalma_ensure_ok4', 1, now()->addHours(12));
        } catch (\Throwable $e) {}
    }
}

// ============================================================================
// FAZ 3 — LOT/PARTI + SKT + FEFO: stok_partileri defteri. Mal kabul giriş yazar,
// satış tüketimi FEFO (ilk bozulan ilk çıkar) ile düşer. Gıda izlenebilirliği.
// ============================================================================
if (!function_exists('_restoPartiEnsure')) {
    function _restoPartiEnsure()
    {
        if (cache()->get('resto_parti_ensure_ok')) return;
        try {
            if (!Schema::hasTable('stok_partileri')) {
                Schema::create('stok_partileri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id');
                    $t->unsignedBigInteger('malzeme_id');
                    $t->string('lot_no', 60)->nullable();
                    $t->date('skt')->nullable();
                    $t->decimal('giris_miktar', 16, 4)->default(0);  // temel birim
                    $t->decimal('kalan_miktar', 16, 4)->default(0);  // temel birim
                    $t->decimal('birim_maliyet', 14, 4)->default(0);
                    $t->unsignedBigInteger('tedarikci_id')->nullable();
                    $t->unsignedBigInteger('mal_kabul_id')->nullable();
                    $t->date('giris_tarihi')->nullable();
                    $t->timestamps();
                    $t->index(['sube_id', 'malzeme_id']);
                    $t->index(['sube_id', 'skt']);
                });
            }
            cache()->put('resto_parti_ensure_ok', 1, now()->addHours(12));
        } catch (\Throwable $e) {}
    }
}
// Parti giriş (mal kabulde) — temel birimde
if (!function_exists('_partiGir')) {
    function _partiGir($sube, $malzemeId, $temelMiktar, $birimMaliyet, $lot = null, $skt = null, $tedId = null, $mkId = null, $tarih = null)
    {
        try {
            _restoPartiEnsure();
            if (!Schema::hasTable('stok_partileri') || $temelMiktar <= 0) return;
            DB::table('stok_partileri')->insert([
                'sube_id' => $sube, 'malzeme_id' => $malzemeId, 'lot_no' => $lot ?: null, 'skt' => $skt ?: null,
                'giris_miktar' => round($temelMiktar, 4), 'kalan_miktar' => round($temelMiktar, 4), 'birim_maliyet' => round($birimMaliyet, 4),
                'tedarikci_id' => $tedId, 'mal_kabul_id' => $mkId, 'giris_tarihi' => $tarih ?: now()->toDateString(), 'created_at' => now(), 'updated_at' => now(),
            ]);
        } catch (\Throwable $e) {}
    }
}
// FEFO düşüm — en yakın SKT'li partiden tüket (SKT yoksa en sona); satış tüketiminde çağrılır
if (!function_exists('_partiDus')) {
    function _partiDus($sube, $malzemeId, $temelMiktar)
    {
        try {
            _restoPartiEnsure();
            if (!Schema::hasTable('stok_partileri') || $temelMiktar <= 0) return;
            $kalanDus = (float) $temelMiktar;
            $partiler = DB::table('stok_partileri')->where('sube_id', $sube)->where('malzeme_id', $malzemeId)->where('kalan_miktar', '>', 0)
                ->orderByRaw('skt IS NULL, skt ASC')->orderBy('id')->get(['id', 'kalan_miktar']);
            foreach ($partiler as $p) {
                if ($kalanDus <= 0) break;
                $al = min((float) $p->kalan_miktar, $kalanDus);
                DB::table('stok_partileri')->where('id', $p->id)->update(['kalan_miktar' => DB::raw('kalan_miktar - ' . $al), 'updated_at' => now()]);
                $kalanDus -= $al;
            }
        } catch (\Throwable $e) {}
    }
}

Route::get('/tedarikci', function () {
    $sid = _webSubeId();
    $tedarikciler = [];
    try {
        if (function_exists('_restoTedarikEnsure')) _restoTedarikEnsure();
        if (Schema::hasTable('tedarikciler')) {
            $alis = collect();
            if (Schema::hasTable('alis_faturalari')) $alis = DB::table('alis_faturalari')->where('sube_id', $sid)->selectRaw('tedarikci_id, SUM(toplam) t, COUNT(*) c')->groupBy('tedarikci_id')->get()->keyBy('tedarikci_id');
            $kolonlar = ['id', 'ad', 'telefon', 'aciklama'];
            foreach (['unvan', 'vkn_tckn', 'vergi_dairesi', 'adres', 'yetkili', 'email', 'iban', 'odeme_vade_gun', 'aktif', 'cari_id', 'anlasmali'] as $k) { if (Schema::hasColumn('tedarikciler', $k)) $kolonlar[] = $k; }
            $tedarikciler = DB::table('tedarikciler')->orderBy('ad')->get($kolonlar)->map(function ($x) use ($alis) {
                $a = $alis[$x->id] ?? null; $x->toplam_alis = $a ? (float) $a->t : 0.0; $x->fatura_sayisi = $a ? (int) $a->c : 0; return $x;
            });
        }
    } catch (\Throwable $e) { $tedarikciler = []; }
    return view('tedarikci', compact('tedarikciler'));
});
Route::post('/tedarikci/kaydet', function (Request $r) {
    try {
        if (!Schema::hasTable('tedarikciler')) return redirect('/tedarikci')->with('ted_hata', 'Tedarikçi tablosu bulunamadı.');
        if (function_exists('_restoTedarikEnsure')) _restoTedarikEnsure();
        $ad = trim((string) $r->ad);
        if ($ad === '') return redirect('/tedarikci')->with('ted_hata', 'Ad boş olamaz.');
        $veri = ['ad' => $ad, 'telefon' => $r->telefon ? (string) $r->telefon : null, 'aciklama' => $r->aciklama ? (string) $r->aciklama : null, 'updated_at' => now()];
        // zengin kart alanları (kolon varsa)
        $zengin = ['unvan' => 160, 'vkn_tckn' => 16, 'vergi_dairesi' => 80, 'adres' => 255, 'yetkili' => 120, 'email' => 120, 'iban' => 34];
        foreach ($zengin as $k => $len) { if (Schema::hasColumn('tedarikciler', $k)) $veri[$k] = $r->filled($k) ? mb_substr(trim((string) $r->input($k)), 0, $len) : null; }
        if (Schema::hasColumn('tedarikciler', 'odeme_vade_gun')) $veri['odeme_vade_gun'] = $r->filled('odeme_vade_gun') ? max(0, (int) $r->input('odeme_vade_gun')) : null;
        if (Schema::hasColumn('tedarikciler', 'anlasmali')) $veri['anlasmali'] = $r->input('anlasmali') ? 1 : 0;
        $id = (int) $r->id;
        if ($id > 0) { DB::table('tedarikciler')->where('id', $id)->update($veri); return redirect('/tedarikci')->with('ted_ok', 'Tedarikçi güncellendi.'); }
        $veri['created_at'] = now();
        DB::table('tedarikciler')->insert($veri);
        return redirect('/tedarikci')->with('ted_ok', 'Tedarikçi eklendi.');
    } catch (\Throwable $e) { return redirect('/tedarikci')->with('ted_hata', 'Kaydedilemedi.'); }
});
Route::post('/tedarikci/sil', function (Request $r) {
    try {
        if (!Schema::hasTable('tedarikciler')) return redirect('/tedarikci')->with('ted_hata', 'Tedarikçi tablosu bulunamadı.');
        $id = (int) $r->id;
        if ($id <= 0) return redirect('/tedarikci')->with('ted_hata', 'Geçersiz kayıt.');
        if (Schema::hasTable('alis_faturalari') && DB::table('alis_faturalari')->where('tedarikci_id', $id)->exists()) return redirect('/tedarikci')->with('ted_hata', 'Bu tedarikçinin faturaları var, silinemez.');
        DB::table('tedarikciler')->where('id', $id)->delete();
        return redirect('/tedarikci')->with('ted_ok', 'Tedarikçi silindi.');
    } catch (\Throwable $e) { return redirect('/tedarikci')->with('ted_hata', 'Silinemedi.'); }
});
// ===== FAZ 1: Tedarikçi DETAY (kart + katalog/fiyat geçmişi + cari borç/ödeme/vade) =====
Route::get('/tedarikci-detay', function (Request $r) {
    $sid = _webSubeId();
    $id = (int) $r->query('id');
    $d = ['ted' => null, 'katalog' => collect(), 'ekstre' => collect(), 'borc' => 0.0, 'odeme' => 0.0, 'bakiye' => 0.0];
    try {
        if (function_exists('_restoTedarikEnsure')) _restoTedarikEnsure();
        $ted = DB::table('tedarikciler')->where('id', $id)->first();
        if (!$ted) return redirect('/tedarikci')->with('ted_hata', 'Tedarikçi bulunamadı.');
        $d['ted'] = $ted;
        // Katalog = bu tedarikçinin faturalarından (gerçek alış geçmişi + fiyat bandı + trend)
        if (Schema::hasTable('alis_fatura_kalemleri') && Schema::hasTable('alis_faturalari')) {
            $birim = DB::table('birimler')->pluck('kisaltma', 'id');
            $d['katalog'] = DB::table('alis_fatura_kalemleri as k')
                ->join('alis_faturalari as f', 'k.fatura_id', '=', 'f.id')
                ->join('malzemeler as m', 'k.malzeme_id', '=', 'm.id')
                ->where('f.tedarikci_id', $id)->where('f.sube_id', $sid)
                ->select('m.ad', 'k.malzeme_id', 'k.alis_birim_id', DB::raw('COUNT(*) adet'), DB::raw('MAX(f.tarih) son_tarih'),
                    DB::raw('AVG(k.birim_fiyat) ort_fiyat'), DB::raw('MIN(k.birim_fiyat) min_fiyat'), DB::raw('MAX(k.birim_fiyat) max_fiyat'))
                ->groupBy('k.malzeme_id', 'm.ad', 'k.alis_birim_id')->orderBy('m.ad')->get()
                ->map(function ($x) use ($birim, $id) {
                    $son = DB::table('alis_fatura_kalemleri as k')->join('alis_faturalari as f', 'k.fatura_id', '=', 'f.id')
                        ->where('f.tedarikci_id', $id)->where('k.malzeme_id', $x->malzeme_id)->orderByDesc('f.tarih')->orderByDesc('k.id')->value('k.birim_fiyat');
                    $x->son_fiyat = (float) $son; $x->birim = $birim[$x->alis_birim_id] ?? '';
                    $x->trend = ($x->son_fiyat > 0 && $x->ort_fiyat > 0) ? round(($x->son_fiyat - $x->ort_fiyat) / $x->ort_fiyat * 100, 1) : 0.0;
                    return $x;
                });
        }
        // Cari: borç = fatura toplamları; ödeme = tahsilatlar (cari_hareketler)
        $d['borc'] = (float) (Schema::hasTable('alis_faturalari') ? DB::table('alis_faturalari')->where('tedarikci_id', $id)->where('sube_id', $sid)->sum('toplam') : 0);
        $cid = function_exists('_tedarikciCari') ? _tedarikciCari($sid, $id) : null;
        if ($cid && Schema::hasTable('cari_hareketler')) $d['odeme'] = (float) DB::table('cari_hareketler')->where('cari_id', $cid)->where('tip', 'tahsilat')->sum('tutar');
        $d['bakiye'] = round($d['borc'] - $d['odeme'], 2);
        // Birleşik ekstre
        $ek = collect();
        if (Schema::hasTable('alis_faturalari')) {
            foreach (DB::table('alis_faturalari')->where('tedarikci_id', $id)->where('sube_id', $sid)->orderByDesc('tarih')->orderByDesc('id')->limit(80)->get(['fatura_no', 'tarih', 'toplam']) as $f) {
                $ek->push((object) ['tarih' => (string) $f->tarih, 'tip' => 'borc', 'tutar' => (float) $f->toplam, 'aciklama' => 'Alış faturası' . ($f->fatura_no ? ' · ' . $f->fatura_no : '')]);
            }
        }
        if ($cid && Schema::hasTable('cari_hareketler')) {
            foreach (DB::table('cari_hareketler')->where('cari_id', $cid)->where('tip', 'tahsilat')->orderByDesc('created_at')->limit(80)->get() as $h) {
                $ek->push((object) ['tarih' => \Carbon\Carbon::parse($h->created_at)->toDateString(), 'tip' => 'tahsilat', 'tutar' => (float) $h->tutar, 'aciklama' => $h->aciklama ?: 'Ödeme']);
            }
        }
        $d['ekstre'] = $ek->sortByDesc('tarih')->values();
    } catch (\Throwable $e) {}
    return view('tedarikci_detay', $d);
});
Route::post('/tedarikci-detay/odeme', function (Request $r) {
    $sid = _webSubeId();
    $id = (int) $r->input('tedarikci_id');
    try {
        if (!DB::table('tedarikciler')->where('id', $id)->exists()) return redirect('/tedarikci')->with('ted_hata', 'Tedarikçi bulunamadı.');
        $tutar = round((float) $r->input('tutar'), 2);
        if ($tutar <= 0) return redirect('/tedarikci-detay?id=' . $id)->with('ted_hata', 'Geçerli tutar girin.');
        $cid = function_exists('_tedarikciCari') ? _tedarikciCari($sid, $id) : null;
        if (!$cid || !Schema::hasTable('cari_hareketler')) return redirect('/tedarikci-detay?id=' . $id)->with('ted_hata', 'Cari kurulamadı.');
        $sekil = in_array($r->input('odeme_sekli'), ['nakit', 'havale', 'kart']) ? $r->input('odeme_sekli') : 'nakit';
        $pp = function_exists('_posPersonel') ? _posPersonel() : null;
        DB::table('cari_hareketler')->insert(['sube_id' => $sid, 'cari_id' => $cid, 'tip' => 'tahsilat', 'tutar' => $tutar, 'odeme_sekli' => $sekil,
            'aciklama' => 'Tedarikçi ödemesi' . ($r->input('not') ? ' · ' . $r->input('not') : ''), 'personel_id' => $pp->id ?? null, 'created_at' => now()]);
        return redirect('/tedarikci-detay?id=' . $id)->with('ted_ok', 'Ödeme kaydedildi (' . number_format($tutar, 0, ',', '.') . '₺).');
    } catch (\Throwable $e) { return redirect('/tedarikci-detay?id=' . $id)->with('ted_hata', 'Ödeme kaydedilemedi.'); }
});

