Route::post('/siparis-onerisi/olustur', function (Request $r) {
    $sid = _webSubeId();
    try {
        if (function_exists('_restoSatinalmaEnsure')) _restoSatinalmaEnsure();
        $kalemler = json_decode((string) $r->input('kalemler'), true);
        if (!is_array($kalemler) || !count($kalemler)) return redirect('/siparis-onerisi')->with('so_hata', 'Ürün seçilmedi.');
        $pp = function_exists('_posPersonel') ? _posPersonel() : null;
        $grup = [];
        foreach ($kalemler as $k) {
            $mid = (int) ($k['malzeme_id'] ?? 0); $miktar = (float) ($k['miktar'] ?? 0);
            if (!$mid || $miktar <= 0) continue;
            $tid = (int) ($k['tedarikci_id'] ?? 0);
            $grup[$tid][] = ['malzeme_id' => $mid, 'alis_birim_id' => ((int) ($k['birim_id'] ?? 0)) ?: null, 'miktar' => $miktar, 'birim_fiyat' => (float) ($k['fiyat'] ?? 0)];
        }
        if (!count($grup)) return redirect('/siparis-onerisi')->with('so_hata', 'Geçerli kalem yok.');
        $olusan = 0;
        foreach ($grup as $tid => $lines) {
            $ara = 0.0; $kdvT = 0.0; $hazir = [];
            foreach ($lines as $l) { $net = $l['miktar'] * $l['birim_fiyat']; $ara += $net; $kdvT += $net * 0.10; $hazir[] = $l + ['iskonto_yuzde' => 0, 'kdv_yuzde' => 10, 'satir_toplam' => round($net, 2)]; }
            $sno = 'SA' . date('ymd') . '-' . str_pad((string) (DB::table('satinalma_siparisleri')->where('sube_id', $sid)->count() + 1), 3, '0', STR_PAD_LEFT);
            $spid = DB::table('satinalma_siparisleri')->insertGetId(['sube_id' => $sid, 'tedarikci_id' => $tid ?: null, 'siparis_no' => $sno, 'tarih' => date('Y-m-d'), 'durum' => 'taslak',
                'ara_toplam' => round($ara, 2), 'iskonto' => 0, 'kdv_toplam' => round($kdvT, 2), 'genel_toplam' => round($ara + $kdvT, 2), 'notlar' => 'Otomatik sipariş önerisinden', 'olusturan_personel_id' => $pp->id ?? null, 'created_at' => now(), 'updated_at' => now()]);
            foreach ($hazir as $h) { $h['siparis_id'] = $spid; $h['created_at'] = now(); $h['updated_at'] = now(); DB::table('satinalma_siparis_kalemleri')->insert($h); }
            $olusan++;
        }
        return redirect('/satinalma-siparis')->with('sa_ok', $olusan . ' sipariş taslağı oluşturuldu (tedarikçiye göre gruplandı).');
    } catch (\Throwable $e) { return redirect('/siparis-onerisi')->with('so_hata', 'Sipariş oluşturulamadı.'); }
});
// PATRON → SATIN ALMAYA GÖNDER: öneri listesini talep olarak satın alma ekibine yolla (direkt sipariş DEĞİL)
Route::post('/siparis-onerisi/talep', function (Request $r) {
    $bp = null; try { $bp = _posPersonel(); } catch (\Throwable $e) {}
    if (!$bp || !in_array(($bp->rol ?? ''), ['sahip', 'mudur', 'satinalmaci'])) return redirect('/siparis-onerisi')->with('so_hata', 'Yetkisiz.');
    $sid = _webSubeId();
    try {
        if (function_exists('_satinalmaTalepEnsure')) _satinalmaTalepEnsure();
        $kalemler = json_decode((string) $r->input('kalemler'), true);
        if (!is_array($kalemler) || !count($kalemler)) return redirect('/siparis-onerisi')->with('so_hata', 'Ürün seçilmedi.');
        $malAd = DB::table('malzemeler')->pluck('ad', 'id'); $birimKis = DB::table('birimler')->pluck('kisaltma', 'id');
        $talepId = (int) DB::table('satinalma_talepleri')->insertGetId(['sube_id' => $sid, 'departman' => 'Üst Yönetim (öneri)', 'isteyen_id' => $bp->id ?? null, 'isteyen_ad' => $bp->ad ?? 'Patron', 'aciliyet' => 'normal', 'durum' => 'yeni', 'not' => 'Otomatik sipariş önerisinden satın almaya gönderildi', 'created_at' => now(), 'updated_at' => now()]);
        $say = 0;
        foreach ($kalemler as $k) {
            $mid = (int) ($k['malzeme_id'] ?? 0); $miktar = (float) ($k['miktar'] ?? 0); if (!$mid || $miktar <= 0) continue;
            $tid = (int) ($k['tedarikci_id'] ?? 0);
            DB::table('talep_kalemleri')->insert(['talep_id' => $talepId, 'malzeme_id' => $mid, 'ad' => $malAd[$mid] ?? 'Ürün', 'miktar' => $miktar, 'birim' => $birimKis[(int) ($k['birim_id'] ?? 0)] ?? '', 'onerilen_tedarikci_id' => $tid ?: null, 'created_at' => now(), 'updated_at' => now()]);
            $say++;
        }
        if (!$say) { DB::table('satinalma_talepleri')->where('id', $talepId)->delete(); return redirect('/siparis-onerisi')->with('so_hata', 'Geçerli ürün yok.'); }
        try { if (function_exists('_fcmSubeyeGonder')) _fcmSubeyeGonder($sid, '🛒 Yeni Satın Alma Talebi', $say . ' kalemlik talep satın almaya gönderildi.', ['tur' => 'satinalma_talep', 'id' => (string) $talepId], ['satinalmaci', 'sahip', 'mudur']); } catch (\Throwable $e) {}
        return redirect('/satinalma-talep')->with('ok', '✅ ' . $say . ' kalemlik talep satın almaya gönderildi. Satın alma ekibi "Fiyat Araştır" veya "Hemen Sipariş" ile devam edebilir.');
    } catch (\Throwable $e) { return redirect('/siparis-onerisi')->with('so_hata', 'Talep gönderilemedi.'); }
});

// ===== FAZ 5 (temel): Fiyat Radarı — Gizli Zam Dedektörü + daha ucuz tedarikçi (kendi alış geçmişi + katalog) =====
Route::get('/fiyat-radari', function () {
    $sid = _webSubeId();
    $d = ['zamlar' => collect(), 'firsatlar' => collect(), 'esik' => 8];
    try {
        if (function_exists('_restoTedarikEnsure')) _restoTedarikEnsure();
        if (!Schema::hasTable('alis_fatura_kalemleri') || !Schema::hasTable('alis_faturalari')) return view('fiyat_radari', $d);
        $malAd = DB::table('malzemeler')->pluck('ad', 'id'); $birimKis = DB::table('birimler')->pluck('kisaltma', 'id');
        $from = today()->subDays(120);
        $lines = DB::table('alis_fatura_kalemleri as k')->join('alis_faturalari as f', 'k.fatura_id', '=', 'f.id')
            ->where('f.sube_id', $sid)->whereDate('f.tarih', '>=', $from)
            ->orderBy('k.malzeme_id')->orderBy('f.tarih')->orderBy('k.id')
            ->get(['k.malzeme_id', 'k.alis_birim_id', 'k.birim_fiyat', 'k.miktar', 'f.tarih']);
        $esik = 8; $zamlar = collect();
        foreach ($lines->groupBy('malzeme_id') as $mid => $g) {
            if ($g->count() < 2) continue;
            $ilk = (float) $g->first()->birim_fiyat; $son = (float) $g->last()->birim_fiyat;
            if ($ilk <= 0) continue;
            $yuzde = round(($son - $ilk) / $ilk * 100, 1);
            if ($yuzde < $esik) continue;
            $yillikMik = (float) $g->sum('miktar') * (365 / 120);
            $zamlar->push((object) ['ad' => $malAd[$mid] ?? '—', 'birim' => $birimKis[$g->first()->alis_birim_id] ?? '', 'ilk' => $ilk, 'son' => $son, 'yuzde' => $yuzde,
                'adet' => $g->count(), 'ilk_tarih' => $g->first()->tarih, 'son_tarih' => $g->last()->tarih, 'yillik_etki' => round(($son - $ilk) * $yillikMik, 0)]);
        }
        $d['zamlar'] = $zamlar->sortByDesc('yillik_etki')->values();
        if (Schema::hasTable('tedarikci_malzeme')) {
            $tedAd = DB::table('tedarikciler')->pluck('ad', 'id');
            $kat = DB::table('tedarikci_malzeme')->where('sube_id', $sid)->where('aktif', 1)->whereNotNull('guncel_fiyat')->where('guncel_fiyat', '>', 0)->get();
            $firsat = collect();
            foreach ($kat->groupBy('malzeme_id') as $mid => $cs) {
                if ($cs->count() < 2) continue;
                $sorted = $cs->sortBy('guncel_fiyat')->values();
                $enUcuz = $sorted->first(); $enPahali = $sorted->last();
                if ((float) $enPahali->guncel_fiyat <= 0) continue;
                $tasarruf = round(((float) $enPahali->guncel_fiyat - (float) $enUcuz->guncel_fiyat) / (float) $enPahali->guncel_fiyat * 100, 1);
                if ($tasarruf < 5) continue;
                $firsat->push((object) ['ad' => $malAd[$mid] ?? '—', 'en_ucuz_ted' => $tedAd[$enUcuz->tedarikci_id] ?? '—', 'en_ucuz_fiyat' => (float) $enUcuz->guncel_fiyat,
                    'en_pahali_fiyat' => (float) $enPahali->guncel_fiyat, 'tasarruf' => $tasarruf, 'ted_say' => $cs->count()]);
            }
            $d['firsatlar'] = $firsat->sortByDesc('tasarruf')->values();
        }
    } catch (\Throwable $e) {}
    return view('fiyat_radari', $d);
});

// ===== FAZ 5 (temel): Hal Fiyatı — manuel referans (+ ileride oto-çekim) + "sen vs hal" karşılaştırma =====
if (!function_exists('_restoHalEnsure')) {
    function _restoHalEnsure()
    {
        if (cache()->get('resto_hal_ensure_ok2')) return;
        try {
            if (!Schema::hasTable('hal_fiyatlari')) {
                Schema::create('hal_fiyatlari', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id');
                    $t->string('urun_ad', 80);
                    $t->string('birim', 12)->nullable();
                    $t->decimal('asgari', 12, 2)->nullable();
                    $t->decimal('azami', 12, 2)->nullable();
                    $t->decimal('ortalama', 12, 2)->nullable();
                    $t->date('tarih')->nullable();
                    $t->string('kaynak', 30)->nullable(); // manuel | api
                    $t->timestamps();
                    $t->index(['sube_id', 'tarih']);
                });
            }
            // SİSTEM GENELİ ürün adı kataloğu (tüm restoranlar ortak kullanır; küratörlü liste + hal)
            if (!Schema::hasTable('urun_katalogu')) {
                Schema::create('urun_katalogu', function ($t) {
                    $t->id();
                    $t->string('ad', 80);                 // görünen ad (Soğan)
                    $t->string('ad_norm', 80)->unique();  // eşleşme/tekille (soğan)
                    $t->string('birim', 12)->nullable();  // varsayılan birim
                    $t->string('tip', 40)->nullable();    // kategori (Et & Tavuk, Süt Ürünleri...)
                    $t->tinyInteger('aktif')->default(1);
                    $t->timestamps();
                });
            }
            if (Schema::hasTable('urun_katalogu')) {
                if (function_exists('_urunKatalogSeedSistem')) _urunKatalogSeedSistem(); // küratörlü tüm kategoriler (idempotent)
                // mevcut hal verisinden sebze/meyve isimleri (idempotent)
                if (Schema::hasTable('hal_fiyatlari')) {
                    foreach (DB::table('hal_fiyatlari')->select('urun_ad', 'birim')->distinct()->get() as $h) {
                        if (function_exists('_urunKatalogEkle')) _urunKatalogEkle($h->urun_ad, 'Sebze & Meyve', $h->birim);
                    }
                }
            }
            cache()->put('resto_hal_ensure_ok2', 1, now()->addHours(12));
        } catch (\Throwable $e) {}
    }
}
// Ürün adı normalize (eşleşme/tekille): küçük harf + Türkçe sade + tek boşluk.
if (!function_exists('_urunNorm')) {
    function _urunNorm($s)
    {
        $s = mb_strtolower(trim((string) $s), 'UTF-8');
        $s = preg_replace('/\s+/', ' ', $s);
        return mb_substr($s, 0, 80);
    }
}
