});
Route::post('/satinalma-asistan/sor', function (Request $r) {
    $sid = _webSubeId();
    $soru = trim((string) $r->input('soru'));
    if ($soru === '') return response()->json(['ok' => 0, 'cevap' => 'Bir soru yaz.']);
    try {
        $baglam = _satinalmaBaglam($sid);
        $apiKey = config('services.anthropic.key') ?: env('ANTHROPIC_API_KEY');
        if (!$apiKey) return response()->json(['ok' => 1, 'kaynak' => 'kural', 'cevap' => _satinalmaKuralCevap($soru, $baglam)]);
        $sys = 'Sen bir restoranın SATIN ALMA danışmanısın. SADECE verilen JSON verisine dayan. Türkçe, kısa, net, EYLEME DÖNÜK cevap ver (en fazla 5 cümle veya madde). Fiyat/stok/tedarikçi rakamlarını yorumla, somut aksiyon öner. Veri yetersizse dürüstçe söyle. Uydurma.';
        $resp = \Illuminate\Support\Facades\Http::withHeaders(['x-api-key' => $apiKey, 'anthropic-version' => '2023-06-01', 'content-type' => 'application/json'])
            ->timeout(25)->post('https://api.anthropic.com/v1/messages', [
                'model' => 'claude-haiku-4-5-20251001', 'max_tokens' => 500, 'system' => $sys,
                'messages' => [['role' => 'user', 'content' => 'Veri: ' . json_encode($baglam, JSON_UNESCAPED_UNICODE) . "\n\nSoru: " . $soru]],
            ]);
        if (!$resp->successful()) return response()->json(['ok' => 1, 'kaynak' => 'kural', 'cevap' => _satinalmaKuralCevap($soru, $baglam)]);
        $metin = trim((string) ($resp->json('content.0.text') ?? ''));
        if ($metin === '') $metin = _satinalmaKuralCevap($soru, $baglam);
        return response()->json(['ok' => 1, 'kaynak' => 'haiku', 'cevap' => $metin]);
    } catch (\Throwable $e) {
        return response()->json(['ok' => 1, 'kaynak' => 'kural', 'cevap' => 'Şu an cevap veremedim, tekrar dene.']);
    }
});

// ===== API (Flutter patron app) — Fiyat Radarı (native parite) =====
Route::get('/api/patron/fiyat-radari', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $sid = $p->sube_id;
    $out = ['ok' => 1, 'zamlar' => [], 'firsatlar' => [], 'toplam_etki' => 0];
    try {
        if (function_exists('_restoTedarikEnsure')) _restoTedarikEnsure();
        if (Schema::hasTable('alis_fatura_kalemleri') && Schema::hasTable('alis_faturalari')) {
            $malAd = DB::table('malzemeler')->pluck('ad', 'id'); $birimKis = DB::table('birimler')->pluck('kisaltma', 'id');
            $from = today()->subDays(120);
            $lines = DB::table('alis_fatura_kalemleri as k')->join('alis_faturalari as f', 'k.fatura_id', '=', 'f.id')
                ->where('f.sube_id', $sid)->whereDate('f.tarih', '>=', $from)->orderBy('k.malzeme_id')->orderBy('f.tarih')->orderBy('k.id')
                ->get(['k.malzeme_id', 'k.alis_birim_id', 'k.birim_fiyat', 'k.miktar', 'f.tarih']);
            $zamlar = [];
            foreach ($lines->groupBy('malzeme_id') as $mid => $g) {
                if ($g->count() < 2) continue;
                $ilk = (float) $g->first()->birim_fiyat; $son = (float) $g->last()->birim_fiyat;
                if ($ilk <= 0) continue;
                $yuzde = round(($son - $ilk) / $ilk * 100, 1);
                if ($yuzde < 8) continue;
                $yillik = round(($son - $ilk) * ((float) $g->sum('miktar') * (365 / 120)), 0);
                $zamlar[] = ['ad' => $malAd[$mid] ?? '—', 'birim' => $birimKis[$g->first()->alis_birim_id] ?? '', 'ilk' => $ilk, 'son' => $son, 'yuzde' => $yuzde, 'adet' => $g->count(), 'yillik_etki' => $yillik];
            }
            usort($zamlar, fn ($a, $b) => $b['yillik_etki'] <=> $a['yillik_etki']);
            $out['zamlar'] = $zamlar; $out['toplam_etki'] = round(array_sum(array_column($zamlar, 'yillik_etki')), 0);
        }
        if (Schema::hasTable('tedarikci_malzeme')) {
            $malAd = DB::table('malzemeler')->pluck('ad', 'id'); $tedAd = DB::table('tedarikciler')->pluck('ad', 'id');
            $kat = DB::table('tedarikci_malzeme')->where('sube_id', $sid)->where('aktif', 1)->whereNotNull('guncel_fiyat')->where('guncel_fiyat', '>', 0)->get();
            $firsat = [];
            foreach ($kat->groupBy('malzeme_id') as $mid => $cs) {
                if ($cs->count() < 2) continue;
                $s = $cs->sortBy('guncel_fiyat')->values(); $uc = $s->first(); $pa = $s->last();
                if ((float) $pa->guncel_fiyat <= 0) continue;
                $tas = round(((float) $pa->guncel_fiyat - (float) $uc->guncel_fiyat) / (float) $pa->guncel_fiyat * 100, 1);
                if ($tas < 5) continue;
                $firsat[] = ['ad' => $malAd[$mid] ?? '—', 'en_ucuz_ted' => $tedAd[$uc->tedarikci_id] ?? '—', 'en_ucuz' => (float) $uc->guncel_fiyat, 'en_pahali' => (float) $pa->guncel_fiyat, 'tasarruf' => $tas];
            }
            usort($firsat, fn ($a, $b) => $b['tasarruf'] <=> $a['tasarruf']);
            $out['firsatlar'] = $firsat;
        }
    } catch (\Throwable $e) {}
    return response()->json($out);
});
// ===== API (Flutter): Satınalma Analizi — tedarikçi karne + aylık harcama =====
Route::get('/api/patron/satinalma-analiz', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $sid = $p->sube_id;
    $out = ['ok' => 1, 'karne' => [], 'aylik' => [], 'toplam_alis' => 0];
    try {
        if (function_exists('_restoSatinalmaEnsure')) _restoSatinalmaEnsure();
        if (!Schema::hasTable('alis_faturalari')) return response()->json($out);
        $tedAd = DB::table('tedarikciler')->pluck('ad', 'id');
        $alis = DB::table('alis_faturalari')->where('sube_id', $sid)->selectRaw('tedarikci_id, SUM(toplam) t, COUNT(*) c')->groupBy('tedarikci_id')->get()->keyBy('tedarikci_id');
        $out['toplam_alis'] = round((float) DB::table('alis_faturalari')->where('sube_id', $sid)->sum('toplam'), 0);
        $zaman = [];
        if (Schema::hasTable('mal_kabuller') && Schema::hasTable('satinalma_siparisleri')) {
            foreach (DB::table('mal_kabuller as mk')->join('satinalma_siparisleri as s', 'mk.siparis_id', '=', 's.id')->where('mk.sube_id', $sid)->whereNotNull('s.beklenen_teslim')->get(['mk.tedarikci_id', 'mk.tarih as mt', 's.beklenen_teslim']) as $x) {
                $tid = (int) $x->tedarikci_id; $zaman[$tid] = $zaman[$tid] ?? ['tam' => 0, 'top' => 0]; $zaman[$tid]['top']++;
                if ($x->mt && $x->beklenen_teslim && $x->mt <= $x->beklenen_teslim) $zaman[$tid]['tam']++;
            }
        }
        $red = [];
        if (Schema::hasTable('mal_kabul_kalemleri') && Schema::hasTable('mal_kabuller')) {
            foreach (DB::table('mal_kabul_kalemleri as k')->join('mal_kabuller as mk', 'k.mal_kabul_id', '=', 'mk.id')->where('mk.sube_id', $sid)->selectRaw('mk.tedarikci_id, SUM(k.red_miktar) r, SUM(k.gelen_miktar) g')->groupBy('mk.tedarikci_id')->get() as $x) {
                $red[(int) $x->tedarikci_id] = ['r' => (float) $x->r, 'g' => (float) $x->g];
            }
        }
        $karne = [];
        foreach ($alis as $tid => $a) {
            if (!$tid) continue;
            $zt = $zaman[$tid] ?? null; $zm = ($zt && $zt['top'] > 0) ? (int) round($zt['tam'] / $zt['top'] * 100) : null;
            $rd = $red[$tid] ?? null; $ro = ($rd && $rd['g'] > 0) ? round($rd['r'] / $rd['g'] * 100, 1) : 0;
            $pn = 3.0; if ($zm !== null) $pn = 2.5 + ($zm / 100) * 2.0; $pn -= min(1.5, $ro / 10); $pn = max(1, min(5, round($pn, 1)));
            $karne[] = ['ad' => $tedAd[$tid] ?? '—', 'toplam' => (float) $a->t, 'fatura' => (int) $a->c, 'zamaninda' => $zm, 'red_oran' => $ro, 'puan' => $pn];
        }
        usort($karne, fn ($x, $y) => $y['toplam'] <=> $x['toplam']);
        $out['karne'] = $karne;
        $out['aylik'] = DB::table('alis_faturalari')->where('sube_id', $sid)->where('tarih', '>=', today()->subMonths(6)->startOfMonth())
            ->selectRaw("DATE_FORMAT(tarih,'%Y-%m') ay, SUM(toplam) t")->groupBy('ay')->orderBy('ay')->get()->map(fn ($x) => ['ay' => $x->ay, 't' => (float) $x->t])->all();
    } catch (\Throwable $e) {}
    return response()->json($out);
});
