// ============================ KASA (vardiya bazli nakit cekmece) ============================
// Tek "nakit gercegi": tum nakit hareketler kasa_hareketleri'ne yazilir. Vardiya acilir (devir),
// gun sonu sayilir -> beklenen vs sayilan = fark (acik/fazla). Nakit satis/gider/tahsilat/avans OTOMATIK baglanir.
function _restoKasaEnsure()
{
    if (!Schema::hasTable('kasa_oturumlari')) {
        Schema::create('kasa_oturumlari', function ($t) {
            $t->id();
            $t->unsignedBigInteger('sube_id');
            $t->unsignedBigInteger('acan_personel_id')->nullable();
            $t->decimal('acilis_devir', 12, 2)->default(0);
            $t->timestamp('acilis_zamani')->nullable();
            $t->timestamp('kapanis_zamani')->nullable();
            $t->decimal('beklenen_nakit', 12, 2)->nullable();
            $t->decimal('sayilan_nakit', 12, 2)->nullable();
            $t->decimal('fark', 12, 2)->nullable();
            $t->unsignedBigInteger('kapatan_personel_id')->nullable();
            $t->string('durum', 10)->default('acik');
            $t->string('not', 255)->nullable();
            $t->timestamps();
            $t->index(['sube_id', 'durum']);
        });
    }
    if (!Schema::hasTable('kasa_hareketleri')) {
        Schema::create('kasa_hareketleri', function ($t) {
            $t->id();
            $t->unsignedBigInteger('sube_id');
            $t->unsignedBigInteger('oturum_id');
            $t->string('tip', 20);   // devir | satis | tahsilat | gider | personel | al | koy
            $t->string('yon', 6);    // giris | cikis
            $t->decimal('tutar', 12, 2)->default(0);
            $t->string('aciklama', 255)->nullable();
            $t->string('kaynak_tip', 20)->nullable();
            $t->unsignedBigInteger('kaynak_id')->nullable();
            $t->unsignedBigInteger('personel_id')->nullable();
            $t->timestamp('created_at')->nullable();
            $t->index(['oturum_id']);
            $t->index(['sube_id', 'created_at']);
        });
    }
    // ÇOKLU KASA (kasa noktası / istasyon) — OPSİYONEL. Hiç kasa tanımlanmazsa sistem
    // bugünkü gibi TEK-HAVUZ çalışır (kasa_id=null). Tanımlanırsa her kasanın ayrı
    // vardiyası/çekmecesi olur. Geriye dönük tam uyumlu.
    if (!cache()->get('resto_kasa_coklu_ok')) {
        try {
            if (!Schema::hasTable('kasalar')) {
                Schema::create('kasalar', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id');
                    $t->string('ad', 60);
                    $t->tinyInteger('aktif')->default(1);
                    $t->integer('sira')->default(0);
                    $t->timestamps();
                    $t->index(['sube_id', 'aktif']);
                });
            }
            if (!Schema::hasColumn('kasa_oturumlari', 'kasa_id')) {
                Schema::table('kasa_oturumlari', fn ($t) => $t->unsignedBigInteger('kasa_id')->nullable()->after('sube_id'));
            }
            if (!Schema::hasColumn('kasa_hareketleri', 'kasa_id')) {
                Schema::table('kasa_hareketleri', fn ($t) => $t->unsignedBigInteger('kasa_id')->nullable()->after('sube_id'));
            }
            if (Schema::hasTable('personeller') && !Schema::hasColumn('personeller', 'varsayilan_kasa_id')) {
                Schema::table('personeller', fn ($t) => $t->unsignedBigInteger('varsayilan_kasa_id')->nullable());
            }
            // kasa -> masa bağı (hangi masalar bu kasaya ait); null = bağsız
            if (Schema::hasTable('masalar') && !Schema::hasColumn('masalar', 'kasa_id')) {
                Schema::table('masalar', fn ($t) => $t->unsignedBigInteger('kasa_id')->nullable());
            }
            cache()->put('resto_kasa_coklu_ok', 1, now()->addHours(12));
        } catch (\Throwable $e) {}
    }
}
// Şubenin aktif kasa (nokta) listesi — boşsa TEK-HAVUZ modu demektir
if (!function_exists('_kasalarAktif')) {
    function _kasalarAktif($subeId)
    {
        try {
            if (function_exists('_restoKasaEnsure')) _restoKasaEnsure();
            if (!Schema::hasTable('kasalar')) return collect();
            return DB::table('kasalar')->where('sube_id', $subeId)->where('aktif', 1)->orderBy('sira')->orderBy('id')->get();
        } catch (\Throwable $e) { return collect(); }
    }
}
if (!function_exists('_kasaAcikOturum')) {
    // $kasaId: belirli kasa noktasının açık vardiyası. null ise önce session('pos_kasa_id')
    // denenir (web POS bağlamı), o da yoksa şubenin herhangi açık vardiyası (tek-havuz, bugünkü davranış).
    function _kasaAcikOturum($subeId, $kasaId = null)
    {
        _restoKasaEnsure();
        if ($kasaId === null) { try { $kasaId = session('pos_kasa_id'); } catch (\Throwable $e) {} }
        $base = DB::table('kasa_oturumlari')->where('sube_id', $subeId)->where('durum', 'acik');
        if ($kasaId) {
            // önce bu kasanın kendi açık vardiyası
            $o = (clone $base)->where('kasa_id', $kasaId)->orderByDesc('id')->first();
            if ($o) return $o;
            // yoksa tek-havuz / eski (kasa_id NULL) vardiya — Flutter & web AYNI vardiyayı görsün
            return (clone $base)->whereNull('kasa_id')->orderByDesc('id')->first();
        }
        return $base->orderByDesc('id')->first();
    }
}
// Nakit hareketi kasaya yaz — SADECE acik oturum varsa (yoksa sessiz gecer, akisi bozmaz)
if (!function_exists('_kasaYaz')) {
    function _kasaYaz($subeId, $tip, $yon, $tutar, $aciklama, $kaynakTip = 'manuel', $kaynakId = null, $personelId = null, $kasaId = null)
    {
        try {
            $tutar = round((float) $tutar, 2);
            if ($tutar <= 0) return;
            $o = _kasaAcikOturum($subeId, $kasaId);
            if (!$o) return;
            $row = [
                'sube_id' => $subeId, 'oturum_id' => $o->id, 'tip' => $tip, 'yon' => $yon, 'tutar' => $tutar,
                'aciklama' => $aciklama, 'kaynak_tip' => $kaynakTip, 'kaynak_id' => $kaynakId,
                'personel_id' => $personelId, 'created_at' => now(),
            ];
            // çok-kasa açıksa hareketi ait olduğu kasaya da işaretle (hızlı rapor için)
            if (cache()->get('resto_kasa_coklu_ok')) $row['kasa_id'] = $o->kasa_id ?? null;
            DB::table('kasa_hareketleri')->insert($row);
        } catch (\Throwable $e) {
        }
    }
}

// KASA DURUMU
Route::get('/api/patron/kasa', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $o = _kasaAcikOturum($p->sube_id);
    if (!$o) {
        $son = DB::table('kasa_oturumlari')->where('sube_id', $p->sube_id)->where('durum', 'kapali')->orderByDesc('id')->first();
        return ['ok' => 1, 'acik' => false, 'son_devir' => $son ? (float) $son->sayilan_nakit : 0];
    }
    $har = DB::table('kasa_hareketleri as h')->leftJoin('personeller as pe', 'h.personel_id', '=', 'pe.id')
        ->where('h.oturum_id', $o->id)->orderByDesc('h.id')
        ->select('h.tip', 'h.yon', 'h.tutar', 'h.aciklama', 'h.created_at', 'pe.ad as personel')->get()
        ->map(fn ($h) => ['tip' => $h->tip, 'yon' => $h->yon, 'tutar' => (float) $h->tutar, 'aciklama' => $h->aciklama,
            'personel' => $h->personel, 'zaman' => \Carbon\Carbon::parse($h->created_at)->format('H:i')]);
    $giris = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'giris')->sum('tutar');
    $cikis = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'cikis')->sum('tutar');
    $kirilim = DB::table('kasa_hareketleri')->where('oturum_id', $o->id)
        ->select('tip', 'yon', DB::raw('SUM(tutar) as t'))->groupBy('tip', 'yon')->get()
        ->map(fn ($k) => ['tip' => $k->tip, 'yon' => $k->yon, 'tutar' => (float) $k->t]);
    return ['ok' => 1, 'acik' => true, 'oturum_id' => $o->id,
        'devir' => (float) $o->acilis_devir, 'acan' => DB::table('personeller')->where('id', $o->acan_personel_id)->value('ad'),
        'acilis' => \Carbon\Carbon::parse($o->acilis_zamani)->format('d.m H:i'),
        'sure_dk' => (int) round(\Carbon\Carbon::parse($o->acilis_zamani)->diffInMinutes(now())),
        'giris' => $giris, 'cikis' => $cikis, 'beklenen' => round($giris - $cikis, 2),
        'kirilim' => $kirilim, 'hareketler' => $har];
});

// KASA AC (vardiya) — devir gir
Route::post('/api/patron/kasa-ac', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array($p->rol, ['sahip', 'mudur', 'kasa'])) return ['ok' => 0, 'hata' => 'Kasa açma yetkiniz yok.'];
    if (_kasaAcikOturum($p->sube_id)) return ['ok' => 0, 'hata' => 'Zaten açık bir kasa var. Önce onu kapatın.'];
    $devir = max(0, round((float) $r->devir, 2));
    $oid = DB::table('kasa_oturumlari')->insertGetId([
        'sube_id' => $p->sube_id, 'acan_personel_id' => $p->id, 'acilis_devir' => $devir,
        'acilis_zamani' => now(), 'durum' => 'acik', 'created_at' => now(), 'updated_at' => now(),
    ]);
    if ($devir > 0) {
        DB::table('kasa_hareketleri')->insert(['sube_id' => $p->sube_id, 'oturum_id' => $oid, 'tip' => 'devir', 'yon' => 'giris',
            'tutar' => $devir, 'aciklama' => 'Açılış devir', 'kaynak_tip' => 'manuel', 'personel_id' => $p->id, 'created_at' => now()]);
    }
    return ['ok' => 1, 'mesaj' => 'Kasa açıldı.', 'oturum_id' => $oid];
});

// KASA HAREKET (elle al/koy) — satis disi nakit
Route::post('/api/patron/kasa-hareket', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $o = _kasaAcikOturum($p->sube_id);
    if (!$o) return ['ok' => 0, 'hata' => 'Açık kasa yok. Önce kasa açın.'];
    $yon = in_array($r->yon, ['giris', 'cikis']) ? $r->yon : 'cikis';
    $tutar = round((float) $r->tutar, 2);
    if ($tutar <= 0) return ['ok' => 0, 'hata' => 'Geçerli tutar girin.'];
    DB::table('kasa_hareketleri')->insert([
        'sube_id' => $p->sube_id, 'oturum_id' => $o->id, 'tip' => $yon === 'giris' ? 'koy' : 'al', 'yon' => $yon,
        'tutar' => $tutar, 'aciklama' => $r->aciklama ? (string) $r->aciklama : ($yon === 'giris' ? 'Kasaya para konuldu' : 'Kasadan para alındı'),
        'kaynak_tip' => 'manuel', 'personel_id' => $p->id, 'created_at' => now(),
    ]);
    return ['ok' => 1, 'mesaj' => $yon === 'giris' ? 'Kasaya eklendi.' : 'Kasadan düşüldü.'];
});

// KASA KAPAT (say) — beklenen vs sayilan = fark
Route::post('/api/patron/kasa-kapat', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array($p->rol, ['sahip', 'mudur', 'kasa'])) return ['ok' => 0, 'hata' => 'Kasa kapatma yetkiniz yok.'];
    $o = _kasaAcikOturum($p->sube_id);
    if (!$o) return ['ok' => 0, 'hata' => 'Açık kasa yok.'];
    $giris = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'giris')->sum('tutar');
    $cikis = (float) DB::table('kasa_hareketleri')->where('oturum_id', $o->id)->where('yon', 'cikis')->sum('tutar');
    $beklenen = round($giris - $cikis, 2);
    $sayilan = round((float) $r->sayilan, 2);
    $fark = round($sayilan - $beklenen, 2);
    DB::table('kasa_oturumlari')->where('id', $o->id)->update([
        'kapanis_zamani' => now(), 'beklenen_nakit' => $beklenen, 'sayilan_nakit' => $sayilan, 'fark' => $fark,
        'kapatan_personel_id' => $p->id, 'durum' => 'kapali', 'not' => $r->not ? (string) $r->not : null, 'updated_at' => now(),
    ]);
    return ['ok' => 1, 'mesaj' => 'Kasa kapatıldı. ' . ($fark == 0 ? 'Kasa tuttu ✓' : ($fark > 0 ? 'Fazla' : 'Açık')),
        'beklenen' => $beklenen, 'sayilan' => $sayilan, 'fark' => $fark];
});

// KASA GECMIS (kapali vardiyalar)
Route::get('/api/patron/kasa-gecmis', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _restoKasaEnsure();
    $liste = DB::table('kasa_oturumlari as o')->leftJoin('personeller as a', 'o.acan_personel_id', '=', 'a.id')
        ->leftJoin('personeller as k', 'o.kapatan_personel_id', '=', 'k.id')
        ->where('o.sube_id', $p->sube_id)->where('o.durum', 'kapali')->orderByDesc('o.id')->limit(30)
        ->select('o.id', 'o.acilis_devir', 'o.beklenen_nakit', 'o.sayilan_nakit', 'o.fark', 'o.acilis_zamani', 'o.kapanis_zamani',
            'a.ad as acan', 'k.ad as kapatan')->get()
        ->map(fn ($o) => [
            'id' => $o->id, 'devir' => (float) $o->acilis_devir, 'beklenen' => (float) $o->beklenen_nakit,
            'sayilan' => (float) $o->sayilan_nakit, 'fark' => (float) $o->fark, 'acan' => $o->acan, 'kapatan' => $o->kapatan,
            'acilis' => $o->acilis_zamani ? \Carbon\Carbon::parse($o->acilis_zamani)->format('d.m H:i') : '-',
            'kapanis' => $o->kapanis_zamani ? \Carbon\Carbon::parse($o->kapanis_zamani)->format('d.m H:i') : '-',
        ]);
    return ['ok' => 1, 'oturumlar' => $liste];
});

// ============================================================================
// STOK / REÇETE / SATIN ALMA / FİNANS modülü. Tablolar zaten var (malzemeler,
// birimler, receteler, stok_hareketleri, tedarikciler, alis_faturalari...).
// Burada YÖNETİM UÇLARI: malzeme/tedarikçi/reçete girişi, alış faturası (stok
// girişi + fiyat uyarısı + maliyet güncelleme + otomatik gider) ve finans özeti.
// ============================================================================

// Birimler/kategoriler boşsa yaygın olanları ekle (formlar boş kalmasın).
function _restoStokSeedEnsure()
{
    if (DB::table('birimler')->count() === 0) {
        DB::table('birimler')->insert([
            ['ad' => 'Gram', 'kisaltma' => 'g', 'tip' => 'agirlik'],
            ['ad' => 'Kilogram', 'kisaltma' => 'kg', 'tip' => 'agirlik'],
            ['ad' => 'Mililitre', 'kisaltma' => 'ml', 'tip' => 'hacim'],
            ['ad' => 'Litre', 'kisaltma' => 'lt', 'tip' => 'hacim'],
            ['ad' => 'Adet', 'kisaltma' => 'ad', 'tip' => 'adet'],
            ['ad' => 'Paket', 'kisaltma' => 'pk', 'tip' => 'adet'],
            ['ad' => 'Koli', 'kisaltma' => 'koli', 'tip' => 'adet'],
            ['ad' => 'Kasa', 'kisaltma' => 'kasa', 'tip' => 'adet'],
            ['ad' => 'Demet', 'kisaltma' => 'demet', 'tip' => 'adet'],
        ]);
    }
    if (DB::table('malzeme_kategorileri')->count() === 0) {
        foreach (['Et & Tavuk', 'Sebze & Meyve', 'Süt Ürünleri', 'Bakliyat & Kuru Gıda', 'İçecek', 'Baharat & Sos', 'Temizlik', 'Diğer'] as $ad) {
            DB::table('malzeme_kategorileri')->insert(['ad' => $ad]);
        }
    }
}

// Bir malzemenin verilen birimi kaç TEMEL birim eder (çevrim faktörü).
function _restoBirimKarsilik($malzemeId, $birimId, $temelBirimId = null)
{
    if ($temelBirimId === null) $temelBirimId = DB::table('malzemeler')->where('id', $malzemeId)->value('temel_birim_id');
    if ((int) $birimId === (int) $temelBirimId) return 1.0;
    $c = DB::table('birim_cevrimleri')->where('malzeme_id', $malzemeId)->where('birim_id', $birimId)->value('temel_birim_karsiligi');
    if ($c) return (float) $c;
    // Bilinen genel çevrimler (kg->g, lt->ml) — malzeme çevrimi tanımlı değilse
    $b = DB::table('birimler')->where('id', $birimId)->value('kisaltma');
    $t = DB::table('birimler')->where('id', $temelBirimId)->value('kisaltma');
    $genel = ['kg' => ['g' => 1000], 'lt' => ['ml' => 1000], 'g' => ['kg' => 0.001], 'ml' => ['lt' => 0.001]];
    if (isset($genel[$b][$t])) return (float) $genel[$b][$t];
    return 1.0;
}

// Şubedeki her malzemenin mevcut stok miktarı (temel birim) — imzalı SUM.
function _restoStokMevcut($subeId)
{
    return DB::table('stok_hareketleri')->where('sube_id', $subeId)
        ->selectRaw('malzeme_id, SUM(miktar) m')->groupBy('malzeme_id')->pluck('m', 'malzeme_id');
}

// Bir recetenin hammadde ihtiyacini PATLATARAK (yari mamul/alt recete dahil) toplar.
// $sonuc[malzeme_id] += temel birim miktar. $carpan = kac adet. Dongu korumali.
// Sadece stok_takipli hammaddeyi ekler; yari mamulun kendi stogu tutulmaz (patlatma modeli).
function _restoReceteHammadde($receteId, $carpan, array &$sonuc, array $ziyaret = [])
{
    $receteId = (int) $receteId;
    if ($receteId <= 0 || $carpan <= 0 || isset($ziyaret[$receteId])) return;
    $ziyaret[$receteId] = true;
    foreach (DB::table('recete_kalemleri')->where('recete_id', $receteId)->get() as $k) {
        if ($k->malzeme_id) {
            $m = DB::table('malzemeler')->where('id', $k->malzeme_id)->first(['temel_birim_id', 'stok_takipli']);
            if (!$m || !$m->stok_takipli) continue;
            $kars = _restoBirimKarsilik($k->malzeme_id, $k->birim_id, $m->temel_birim_id);
            $sonuc[$k->malzeme_id] = ($sonuc[$k->malzeme_id] ?? 0) + (float) $k->miktar * $kars * $carpan;
        } elseif ($k->alt_recete_id) {
            $alt = DB::table('receteler')->where('id', $k->alt_recete_id)->first();
            $altMid = $alt ? ($alt->malzeme_id ?? null) : null;
            // STOKLU yarı mamül (üretim partisi var): üretimde hammadde zaten düştü → burada AYNA MALZEME'yi düş.
            // Çift düşme olmaz; ayna normal stok kalemi olduğu için FEFO/SKT (_partiDus) otomatik uygulanır.
            if (!empty($altMid)) {
                $mm = DB::table('malzemeler')->where('id', $altMid)->first(['temel_birim_id', 'stok_takipli']);
                if ($mm && $mm->stok_takipli) {
                    $kars = _restoBirimKarsilik((int) $altMid, $k->birim_id, $mm->temel_birim_id);
                    $sonuc[$altMid] = ($sonuc[$altMid] ?? 0) + (float) $k->miktar * $kars * $carpan;
                }
            } else {
                $verim = ($alt && (float) $alt->verim_miktar > 0) ? (float) $alt->verim_miktar : 1.0;
                // ust recetede alt receteden $k->miktar (verim biriminde) kullaniliyor -> alt recetenin miktar/verim kati
                _restoReceteHammadde($k->alt_recete_id, $carpan * ((float) $k->miktar / $verim), $sonuc, $ziyaret);
            }
        }
    }
}

// ============================================================================
// YARI MAMÜL ÜRETİM PARTİSİ: üret → hammadde düş + AYNA stok kalemi (SKT'li parti + barkod).
// Satışta hammaddeye patlamak yerine ayna kalemi düşer (FEFO) → çift düşme YOK. Ayna = receteler.malzeme_id.
// ============================================================================
if (!function_exists('_yariMamulMirror')) {
    function _yariMamulMirror($receteId)
    {
        try { if (!Schema::hasColumn('receteler', 'malzeme_id')) Schema::table('receteler', function ($t) { $t->unsignedBigInteger('malzeme_id')->nullable(); }); } catch (\Throwable $e) {}
        $rec = DB::table('receteler')->where('id', $receteId)->where('tip', 'yari_mamul')->first();
        if (!$rec) return null;
        if (!empty($rec->malzeme_id) && DB::table('malzemeler')->where('id', $rec->malzeme_id)->exists()) return (int) $rec->malzeme_id;
        $katId = DB::table('malzeme_kategorileri')->where('ad', 'Yarı Mamül')->value('id');
        if (!$katId) $katId = DB::table('malzeme_kategorileri')->insertGetId(['ad' => 'Yarı Mamül']);
        $birim = (int) ($rec->verim_birim_id ?? 0) ?: (int) DB::table('birimler')->min('id');
        $verim = (float) $rec->verim_miktar > 0 ? (float) $rec->verim_miktar : 1.0;
        $birimMaliyet = function_exists('_restoReceteToplamMaliyet') ? (_restoReceteToplamMaliyet($receteId) / $verim) : 0;
        $mid = DB::table('malzemeler')->insertGetId([
            'ad' => $rec->ad, 'kategori_id' => $katId, 'temel_birim_id' => $birim,
            'kritik_stok' => 0, 'stok_takipli' => 1, 'guncel_maliyet' => round($birimMaliyet, 4),
            'created_at' => now(), 'updated_at' => now(),
        ]);
        DB::table('receteler')->where('id', $receteId)->update(['malzeme_id' => $mid]);
        return (int) $mid;
    }
}
// Üret: hammadde düş + ayna stoğa giriş + SKT'li parti + barkod
Route::post('/api/patron/yarimamul-uret', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if (!in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkiniz yok'], 403);
    $recId = (int) $r->recete_id;
    $rec = DB::table('receteler')->where('id', $recId)->where('tip', 'yari_mamul')->first();
    if (!$rec) return ['ok' => 0, 'hata' => 'Yarı mamül bulunamadı'];
    $uretilen = (float) str_replace(',', '.', (string) $r->miktar);
    if ($uretilen <= 0) return ['ok' => 0, 'hata' => 'Üretilen miktar 0 olamaz'];
    $verim = (float) $rec->verim_miktar > 0 ? (float) $rec->verim_miktar : 1.0;
    $skt = ($r->filled('skt') && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $r->skt)) ? (string) $r->skt : null;
    // Ayna malzeme + birim maliyet
    $mid = _yariMamulMirror($recId);
    if (!$mid) return ['ok' => 0, 'hata' => 'Ayna stok kalemi oluşturulamadı'];
    $birimMaliyet = function_exists('_restoReceteToplamMaliyet') ? (_restoReceteToplamMaliyet($recId) / $verim) : 0;
    DB::table('malzemeler')->where('id', $mid)->update(['guncel_maliyet' => round($birimMaliyet, 4), 'updated_at' => now()]);
    // Barkod (elle veya iç üret)
    $barkod = trim((string) $r->input('barkod', ''));
    if (function_exists('_barkodKur')) { try { _barkodKur(); } catch (\Throwable $e) {} }
    if ($barkod === '') $barkod = 'YM' . str_pad((string) $mid, 5, '0', STR_PAD_LEFT) . str_pad((string) random_int(0, 9999), 4, '0', STR_PAD_LEFT);
    // PARTİ ÖNCE: parti_id = üretim kimliği; tüm hareketler buna bağlanır → GERİ ALINABİLİR.
    $partiId = 0;
    if (function_exists('_restoPartiEnsure')) { try { _restoPartiEnsure(); } catch (\Throwable $e) {} }
    try {
        if (Schema::hasTable('stok_partileri')) {
            $partiId = DB::table('stok_partileri')->insertGetId([
                'sube_id' => $p->sube_id, 'malzeme_id' => $mid, 'lot_no' => $barkod, 'skt' => $skt,
                'giris_miktar' => round($uretilen, 4), 'kalan_miktar' => round($uretilen, 4),
                'birim_maliyet' => round($birimMaliyet, 4), 'giris_tarihi' => now()->toDateString(),
                'created_at' => now(), 'updated_at' => now(),
            ]);
        }
    } catch (\Throwable $e) {}
    $kaynakId = $partiId ?: $recId;
    // 1) Hammadde düş (reçeteyi uretilen/verim ile patlat) — kaynak_id = parti_id
    $ihtiyac = [];
    _restoReceteHammadde($recId, $uretilen / $verim, $ihtiyac);
    foreach ($ihtiyac as $malzemeId => $temelMiktar) {
        if ($temelMiktar <= 0) continue;
        $mm = DB::table('malzemeler')->where('id', $malzemeId)->first(['guncel_maliyet']);
        DB::table('stok_hareketleri')->insert([
            'sube_id' => $p->sube_id, 'malzeme_id' => (int) $malzemeId, 'tip' => 'tuketim', 'miktar' => -$temelMiktar,
            'birim_maliyet' => $mm ? (float) $mm->guncel_maliyet : 0, 'kaynak_tip' => 'uretim_hammadde', 'kaynak_id' => $kaynakId,
            'aciklama' => 'Yarı mamül üretim: ' . $rec->ad, 'personel_id' => $p->id, 'created_at' => now(),
        ]);
        if (function_exists('_partiDus')) _partiDus($p->sube_id, (int) $malzemeId, $temelMiktar);
    }
    // 2) Ayna malzeme stok girişi — kaynak_id = parti_id
    DB::table('stok_hareketleri')->insert([
        'sube_id' => $p->sube_id, 'malzeme_id' => $mid, 'tip' => 'iade', 'miktar' => abs($uretilen),
        'birim_maliyet' => round($birimMaliyet, 4), 'kaynak_tip' => 'uretim', 'kaynak_id' => $kaynakId,
        'aciklama' => 'Yarı mamül üretim (giriş)', 'personel_id' => $p->id, 'created_at' => now(),
    ]);
    // 3) Barkod → ayna malzeme
    try {
        if (Schema::hasTable('barkodlar') && !DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('barkod', $barkod)->exists()) {
            DB::table('barkodlar')->insert(['sube_id' => $p->sube_id, 'barkod' => $barkod, 'tur' => 'malzeme', 'hedef_id' => $mid, 'created_at' => now()]);
        }
    } catch (\Throwable $e) {}
    return ['ok' => 1, 'malzeme_id' => $mid, 'parti_id' => $partiId, 'barkod' => $barkod, 'skt' => $skt, 'miktar' => $uretilen];
});
// Üretimi GERİ AL / SİL — sahip/mudur direkt; değilse Müdür/Sahip PIN onayı ŞART. Satılmamış parti geri alınır.
Route::post('/api/patron/yarimamul-uretim-sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $partiId = (int) $r->parti_id;
    if (!$partiId || !Schema::hasTable('stok_partileri')) return ['ok' => 0, 'hata' => 'Parti bulunamadı'];
    $parti = DB::table('stok_partileri')->where('id', $partiId)->where('sube_id', $p->sube_id)->first();
    if (!$parti) return ['ok' => 0, 'hata' => 'Parti bulunamadı'];
    // Onay: sahip/mudur direkt; değilse Müdür/Sahip PIN'i şart (garson sipariş iptal deseni)
    $onaylayan = null;
    if (in_array($p->rol, ['sahip', 'mudur'])) { $onaylayan = $p; }
    else {
        $pin = trim((string) $r->input('onay_pin', ''));
        if ($pin === '') return ['ok' => 0, 'onay_gerek' => true, 'hata' => 'Üretim geri alma için Müdür/Sahip PIN onayı gerekli.'];
        $y = DB::table('personeller')->where('sube_id', $p->sube_id)->where('pin', $pin)->where('aktif', 1)->whereIn('rol', ['sahip', 'mudur'])->first();
        if (!$y) return ['ok' => 0, 'onay_gerek' => true, 'hata' => 'PIN geçersiz veya yetkisiz.'];
        $onaylayan = $y;
    }
    // Bu partiden satış/kullanım yapılmışsa (kalan < giris) geri alınamaz
    if ((float) $parti->kalan_miktar + 0.0001 < (float) $parti->giris_miktar) {
        return ['ok' => 0, 'hata' => 'Bu partiden satış/kullanım yapılmış, geri alınamaz.'];
    }
    DB::transaction(function () use ($parti, $p, $onaylayan) {
        $hareketler = DB::table('stok_hareketleri')->where('sube_id', $p->sube_id)
            ->whereIn('kaynak_tip', ['uretim', 'uretim_hammadde'])->where('kaynak_id', $parti->id)->get();
        foreach ($hareketler as $h) {
            DB::table('stok_hareketleri')->insert([
                'sube_id' => $p->sube_id, 'malzeme_id' => $h->malzeme_id, 'tip' => ((float) $h->miktar) < 0 ? 'iade' : 'tuketim',
                'miktar' => -(float) $h->miktar, 'birim_maliyet' => (float) $h->birim_maliyet, 'kaynak_tip' => 'uretim_iptal',
                'kaynak_id' => $parti->id, 'aciklama' => 'Üretim geri alındı (onay: ' . ($onaylayan->ad ?? '') . ')', 'personel_id' => $p->id, 'created_at' => now(),
            ]);
        }
        DB::table('stok_partileri')->where('id', $parti->id)->delete();
        try { if (Schema::hasTable('barkodlar') && $parti->lot_no) DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('barkod', $parti->lot_no)->delete(); } catch (\Throwable $e) {}
        try { if (Schema::hasTable('iptal_indirim_loglari')) DB::table('iptal_indirim_loglari')->insert(['sube_id' => $p->sube_id, 'adisyon_id' => null, 'tip' => 'uretim_iptal', 'tutar' => round((float) $parti->giris_miktar * (float) $parti->birim_maliyet, 2), 'sebep' => 'Yarı mamül üretim geri alındı · parti ' . ($parti->lot_no ?? $parti->id) . ' · onay: ' . ($onaylayan->ad ?? ''), 'personel_id' => $onaylayan->id ?? $p->id, 'created_at' => now()]); } catch (\Throwable $e) {}
    });
    return ['ok' => 1, 'mesaj' => 'Üretim geri alındı — malzemeler stoğa döndü · onay: ' . ($onaylayan->ad ?? '')];
});

// ============================================================================
// SATIN ALMA TALEBİ (Requisition) — Faz 1: departman talebi + satın alma gelen kutusu.
// Döngü: departman → talep → (sonraki faz) teklif/öneri → üst onay → PO.
// ============================================================================
if (!function_exists('_satinalmaTalepEnsure')) {
    function _satinalmaTalepEnsure()
    {
        if (cache()->get('resto_satinalma_talep_ensure_ok')) return;
        try {
            if (!Schema::hasTable('satinalma_talepleri')) {
                Schema::create('satinalma_talepleri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('sube_id')->default(1);
                    $t->string('departman', 80);
                    $t->unsignedBigInteger('isteyen_id')->nullable();
                    $t->string('isteyen_ad', 120)->nullable();
                    $t->string('aciliyet', 10)->default('normal');
                    $t->string('durum', 15)->default('yeni');
                    $t->text('not')->nullable();
                    $t->timestamps();
                    $t->index(['sube_id', 'durum']);
                });
            }
            if (!Schema::hasTable('talep_kalemleri')) {
                Schema::create('talep_kalemleri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('talep_id');
                    $t->unsignedBigInteger('malzeme_id')->nullable();
                    $t->string('ad', 200)->nullable();
                    $t->decimal('miktar', 12, 3)->default(0);
                    $t->string('birim', 30)->nullable();
                    $t->unsignedBigInteger('onerilen_tedarikci_id')->nullable();
                    $t->text('oneri_gerekce')->nullable();
                    $t->unsignedBigInteger('secilen_tedarikci_id')->nullable();
                    $t->text('patron_not')->nullable();
                    $t->timestamps();
                    $t->index('talep_id');
                });
            }
            if (!Schema::hasTable('talep_teklifleri')) {
                Schema::create('talep_teklifleri', function ($t) {
                    $t->id();
                    $t->unsignedBigInteger('talep_kalem_id');
                    $t->unsignedBigInteger('tedarikci_id')->nullable();
                    $t->decimal('fiyat', 14, 2)->default(0);
                    $t->string('vade', 80)->nullable();
                    $t->integer('teslim_gun')->nullable();
                    $t->date('gecerlilik')->nullable();
                    $t->text('not')->nullable();
                    $t->timestamp('created_at')->nullable();
                    $t->index('talep_kalem_id');
                });
            }
            cache()->put('resto_satinalma_talep_ensure_ok', 1, now()->addHours(12));
        } catch (\Throwable $e) {}
    }
}
// Kritik seviyedeki malzemeler (proaktif izleme) — önerilen sipariş miktarıyla
if (!function_exists('_kritikStokListesi')) {
    function _kritikStokListesi($sid)
    {
        $out = [];
        try {
            $stok = DB::table('stok_hareketleri')->where('sube_id', $sid)->selectRaw('malzeme_id, SUM(miktar) m')->groupBy('malzeme_id')->pluck('m', 'malzeme_id');
            $hedefVar = Schema::hasColumn('malzemeler', 'hedef_stok');
            $kol = ['id', 'ad', 'kritik_stok', 'temel_birim_id']; if ($hedefVar) $kol[] = 'hedef_stok';
            $birim = DB::table('birimler')->pluck('kisaltma', 'id');
            foreach (DB::table('malzemeler')->where('stok_takipli', 1)->get($kol) as $m) {
                $mevcut = (float) ($stok[$m->id] ?? 0); $kritik = (float) $m->kritik_stok; $hedef = $hedefVar ? (float) ($m->hedef_stok ?? 0) : 0;
                if ($kritik <= 0 || $mevcut > $kritik) continue;
                $hedefRef = $hedef > 0 ? $hedef : $kritik * 2;
                $oneri = max(0, round($hedefRef - $mevcut, 3));
                $out[] = ['id' => (int) $m->id, 'ad' => $m->ad, 'mevcut' => round($mevcut, 3), 'kritik' => round($kritik, 3),
                    'oneri' => $oneri ?: round($kritik, 3), 'birim' => $birim[$m->temel_birim_id] ?? ''];
            }
        } catch (\Throwable $e) {}
        return $out;
    }
}
Route::get('/satinalma-talep', function () {
    _satinalmaTalepEnsure();
    $sid = _webSubeId();
    $pp = function_exists('_posPersonel') ? _posPersonel() : null;
    $rol = $pp->rol ?? '';
    $patronMu = in_array($rol, ['sahip', 'mudur']);
    // ROL KAPISI: talep havuzunu sahip/müdür/satın almacı GÖRÜR+YÖNETİR; diğerleri (mutfak vb.) SADECE kendi taleplerini görür
    $satinalmaci = in_array($rol, ['sahip', 'mudur', 'satinalmaci']);
    $kritikler = $satinalmaci ? _kritikStokListesi($sid) : [];
    $q = DB::table('satinalma_talepleri')->where('sube_id', $sid);
    if (!$satinalmaci) $q->where('isteyen_id', $pp->id ?? 0);
    $talepler = $q->orderByRaw("CASE durum WHEN 'yeni' THEN 1 WHEN 'teklif' THEN 2 WHEN 'onayda' THEN 3 WHEN 'onaylandi' THEN 4 WHEN 'siparis' THEN 5 WHEN 'tamamlandi' THEN 6 ELSE 9 END")
        ->orderByDesc('created_at')->limit(200)
        ->get(['id', 'departman', 'isteyen_ad', 'aciliyet', 'durum', 'created_at'])
        ->map(function ($t) { $t->kalem_sayisi = DB::table('talep_kalemleri')->where('talep_id', $t->id)->count(); return $t; });
    $ozet = (object) [
        'yeni' => $talepler->where('durum', 'yeni')->count(),
        'onayda' => $talepler->whereIn('durum', ['teklif', 'onayda'])->count(),
        'tamamlanan' => $talepler->where('durum', 'tamamlandi')->count(),
    ];
    $malzemeler = DB::table('malzemeler')->leftJoin('birimler', 'malzemeler.temel_birim_id', '=', 'birimler.id')
        ->orderBy('malzemeler.ad')->get(['malzemeler.id', 'malzemeler.ad', 'birimler.kisaltma as birim_kisaltma']);
    $birimler = DB::table('birimler')->orderBy('id')->get(['id', 'ad', 'kisaltma']);
    $waTel = resto_ayar_al('satinalma_wa_tel_' . $sid, '');
    return view('satinalma_talep', compact('talepler', 'ozet', 'malzemeler', 'birimler', 'rol', 'patronMu', 'satinalmaci', 'kritikler', 'waTel'));
});
