Route::post('/satinalma-talep/olustur', function (Request $r) {
    _satinalmaTalepEnsure();
    $p = _apiPersonel($r);
    $sid = _webSubeId();
    $dept = trim((string) $r->input('departman', 'Diğer')) ?: 'Diğer';
    $aciliyet = in_array($r->input('aciliyet'), ['normal', 'acil']) ? $r->input('aciliyet') : 'normal';
    $kalemler = $r->input('kalemler', []);
    if (is_string($kalemler)) $kalemler = json_decode($kalemler, true) ?: []; // mobil app JSON-string yollar
    if (empty($kalemler) || !is_array($kalemler)) return response()->json(['ok' => false, 'mesaj' => 'En az bir kalem gerekli.']);
    $talepId = DB::table('satinalma_talepleri')->insertGetId([
        'sube_id' => $sid, 'departman' => mb_substr($dept, 0, 80),
        'isteyen_id' => $p->id ?? null, 'isteyen_ad' => $p->ad ?? 'Panel',
        'aciliyet' => $aciliyet, 'durum' => 'yeni', 'not' => $r->filled('not') ? mb_substr((string) $r->input('not'), 0, 500) : null,
        'created_at' => now(), 'updated_at' => now(),
    ]);
    foreach ($kalemler as $k) {
        $mid = (int) ($k['malzeme_id'] ?? 0);
        $ad = trim((string) ($k['ad'] ?? ''));
        if (!$mid && $ad === '') continue;
        DB::table('talep_kalemleri')->insert([
            'talep_id' => $talepId, 'malzeme_id' => $mid ?: null, 'ad' => $ad ?: null,
            'miktar' => max(0, (float) ($k['miktar'] ?? 0)), 'birim' => mb_substr(trim((string) ($k['birim'] ?? '')), 0, 30),
            'created_at' => now(), 'updated_at' => now(),
        ]);
    }
    // Satın almaya bildirim (WhatsApp, best-effort — ayar yoksa/sessizce atlanır, akış kırılmaz)
    try {
        $tel = resto_ayar_al('satinalma_wa_tel_' . $sid, null);
        if ($tel && function_exists('_restoWaGonder')) {
            $ks = DB::table('talep_kalemleri')->where('talep_id', $talepId)->count();
            $acilMetin = $aciliyet === 'acil' ? '🔴 ACİL ' : '';
            $msg = $acilMetin . "Yeni satın alma talebi\n🏷️ " . $dept . " departmanı\n👤 " . ($p->ad ?? 'Panel') . "\n📦 " . $ks . " kalem\nPanelden incele: Satın Alma Talepleri";
            _restoWaGonder($sid, $tel, $msg);
        }
    } catch (\Throwable $e) {}
    // Uygulama-içi push (ikili bildirim): şubedeki cihazlara — satın almacı/patron görür
    try {
        if (function_exists('_fcmSubeyeGonder')) {
            $ks = DB::table('talep_kalemleri')->where('talep_id', $talepId)->count();
            $baslik = ($aciliyet === 'acil' ? '🔴 ACİL satın alma talebi' : '🛒 Yeni satın alma talebi');
            _fcmSubeyeGonder($sid, $baslik, $dept . ' · ' . $ks . ' kalem · ' . ($p->ad ?? 'Panel'), ['tur' => 'satinalma_talep', 'id' => (string) $talepId]);
        }
    } catch (\Throwable $e) {}
    return response()->json(['ok' => true, 'id' => $talepId]);
});
Route::get('/api/patron/talep-detay', function (Request $r) {
    _satinalmaTalepEnsure();
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => false], 401);
    $id = (int) $r->query('id');
    if (!$id) return response()->json(['ok' => false, 'mesaj' => 'id gerekli.']);
    $talep = DB::table('satinalma_talepleri')->where('id', $id)->where('sube_id', $p->sube_id)->first();
    if (!$talep) return response()->json(['ok' => false, 'mesaj' => 'Bulunamadı.']);
    $malAd = DB::table('malzemeler')->pluck('ad', 'id');
    $tedAd = DB::table('tedarikciler')->pluck('ad', 'id');
    $kalemler = DB::table('talep_kalemleri')->where('talep_id', $id)->get(['id', 'malzeme_id', 'ad', 'miktar', 'birim', 'onerilen_tedarikci_id', 'oneri_gerekce', 'secilen_tedarikci_id', 'patron_not'])
        ->map(function ($k) use ($malAd, $tedAd) {
            $k->ad = $k->ad ?: ($malAd[$k->malzeme_id] ?? '—');
            $k->onerilen_ad = $k->onerilen_tedarikci_id ? ($tedAd[$k->onerilen_tedarikci_id] ?? null) : null;
            $k->secilen_ad = $k->secilen_tedarikci_id ? ($tedAd[$k->secilen_tedarikci_id] ?? null) : null;
            $k->teklifler = DB::table('talep_teklifleri')->where('talep_kalem_id', $k->id)->orderBy('fiyat')->get()
                ->map(function ($t) use ($tedAd) { $t->tedarikci_ad = $tedAd[$t->tedarikci_id] ?? '—'; return $t; });
            return $k;
        });
    $tedKol = ['id', 'ad'];
    if (Schema::hasColumn('tedarikciler', 'anlasmali')) $tedKol[] = 'anlasmali';
    if (Schema::hasColumn('tedarikciler', 'telefon')) $tedKol[] = 'telefon';
    $tedarikciler = DB::table('tedarikciler')->orderBy('ad')->get($tedKol);
    return response()->json(['ok' => true, 'talep' => $talep, 'kalemler' => $kalemler, 'tedarikciler' => $tedarikciler]);
});
