    $talep = DB::table('satinalma_talepleri')->where('id', $id)->where('sube_id', $p->sube_id)->first();
    if (!$talep) return response()->json(['ok' => false, 'mesaj' => 'Bulunamadı.']);
    if (in_array($talep->durum, ['siparis', 'tamamlandi'])) return response()->json(['ok' => false, 'mesaj' => 'Bu talep zaten siparişe dönüşmüş.']);
    if (!Schema::hasColumn('tedarikciler', 'anlasmali')) return response()->json(['ok' => false, 'mesaj' => 'Anlaşmalı tedarikçi özelliği kurulu değil.']);
    $anlasmaliIds = DB::table('tedarikciler')->where('anlasmali', 1)->pluck('id')->all();
    if (empty($anlasmaliIds)) return response()->json(['ok' => false, 'mesaj' => 'Anlaşmalı tedarikçi tanımlı değil (Tedarikçiler → Anlaşmalı işaretle).']);
    // ⭐ önerisi anlaşmalı tedarikçi + o tedarikçiden fiyat(teklif) olan kalemler → secilen = onerilen yap
    $kalemler = DB::table('talep_kalemleri')->where('talep_id', $id)->whereNotNull('malzeme_id')
        ->whereIn('onerilen_tedarikci_id', $anlasmaliIds)->get()
        ->filter(fn ($k) => DB::table('talep_teklifleri')->where('talep_kalem_id', $k->id)->where('tedarikci_id', $k->onerilen_tedarikci_id)->exists())
        ->values();
    if ($kalemler->isEmpty()) return response()->json(['ok' => false, 'mesaj' => 'Anlaşmalı tedarikçi önerili + fiyatı girili kalem yok. Önce kaleme anlaşmalı tedarikçiyi ⭐ öner ve teklif/fiyat ekle.']);
    foreach ($kalemler as $k) { DB::table('talep_kalemleri')->where('id', $k->id)->update(['secilen_tedarikci_id' => $k->onerilen_tedarikci_id, 'updated_at' => now()]); $k->secilen_tedarikci_id = $k->onerilen_tedarikci_id; }
    [$siparisNolar, $waGonderilen] = _satinalmaPoYap($talep, $kalemler, $p);
    $kalan = DB::table('talep_kalemleri')->where('talep_id', $id)->whereNotIn('id', $kalemler->pluck('id')->all())->count();
    DB::table('satinalma_talepleri')->where('id', $id)->update(['durum' => $kalan > 0 ? ($talep->durum === 'yeni' ? 'teklif' : $talep->durum) : 'siparis', 'updated_at' => now()]);
    return response()->json(['ok' => true, 'siparisler' => $siparisNolar, 'wa' => $waGonderilen, 'kalan' => $kalan]);
});
// Mobil app: satın alma talep listesi + özet + kritik stok + form verileri (Bearer)
Route::get('/api/patron/talep-liste', function (Request $r) {
    _satinalmaTalepEnsure();
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => false], 401);
    $sid = $p->sube_id;
    $talepler = DB::table('satinalma_talepleri')->where('sube_id', $sid)
        ->orderByRaw("FIELD(durum,'yeni','teklif','onayda','onaylandi','siparis','tamamlandi')")
        ->orderByDesc('created_at')->limit(200)
        ->get(['id', 'departman', 'isteyen_ad', 'aciliyet', 'durum', 'not', 'created_at'])
        ->map(function ($t) {
            $t->kalem_sayisi = DB::table('talep_kalemleri')->where('talep_id', $t->id)->count();
            return $t;
        });
    $ozet = [
        'yeni' => $talepler->where('durum', 'yeni')->count(),
        'onayda' => $talepler->whereIn('durum', ['teklif', 'onayda'])->count(),
        'tamamlanan' => $talepler->where('durum', 'tamamlandi')->count(),
    ];
    $malzemeler = DB::table('malzemeler')->leftJoin('birimler', 'malzemeler.temel_birim_id', '=', 'birimler.id')
        ->orderBy('malzemeler.ad')->get(['malzemeler.id', 'malzemeler.ad', 'birimler.kisaltma as birim_kisaltma']);
    $birimler = DB::table('birimler')->orderBy('id')->get(['id', 'ad', 'kisaltma']);
    $tedarikciler = DB::table('tedarikciler')->orderBy('ad')->get(['id', 'ad']);
    return response()->json([
        'ok' => true,
        'talepler' => $talepler->values(),
        'ozet' => $ozet,
        'kritikler' => _kritikStokListesi($sid),
        'malzemeler' => $malzemeler,
        'birimler' => $birimler,
        'tedarikciler' => $tedarikciler,
        'patron' => in_array($p->rol ?? '', ['sahip', 'mudur']),
    ]);
});
// Bir yarı mamülün üretim partileri (SKT + kalan) + toplam stok
Route::get('/api/patron/yarimamul-partileri', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $recId = (int) $r->recete_id;
    $rec = DB::table('receteler')->where('id', $recId)->first();
    $mid = $rec ? ($rec->malzeme_id ?? null) : null;
    if (!$mid || !Schema::hasTable('stok_partileri')) return ['ok' => 1, 'malzeme_id' => $mid, 'partiler' => [], 'stok' => 0];
    $bugun = strtotime(date('Y-m-d'));
    $partiler = DB::table('stok_partileri')->where('sube_id', $p->sube_id)->where('malzeme_id', $mid)
        ->orderByRaw('skt IS NULL, skt ASC')->orderByDesc('id')->limit(100)->get()
        ->map(function ($x) use ($bugun) {
            $gun = $x->skt ? (int) floor((strtotime($x->skt) - $bugun) / 86400) : null;
            return ['id' => (int) $x->id, 'lot_no' => $x->lot_no, 'skt' => $x->skt, 'skt_gun' => $gun,
                'kalan' => round((float) $x->kalan_miktar, 3), 'giris' => round((float) $x->giris_miktar, 3), 'giris_tarihi' => $x->giris_tarihi];
        });
    $stok = (float) DB::table('stok_hareketleri')->where('sube_id', $p->sube_id)->where('malzeme_id', $mid)->sum('miktar');
    return ['ok' => 1, 'malzeme_id' => (int) $mid, 'partiler' => $partiler, 'stok' => round($stok, 3)];
});

// Adisyon kapanınca reçeteden otomatik stok düşümü (tuketim). GÜVENLİ: hata olsa
// bile satışı bozmaz (try/catch), reçetesi/malzemesi olmayan ürünü sessiz atlar,
// sadece stok_takipli malzemeyi düşer, aynı adisyonu iki kez düşmez (idempotent).
// Yari mamul (alt recete) iceren urunlerde hammaddeye kadar PATLATIR (_restoReceteHammadde).
function _restoStokTuket($adisyonId, $subeId, $personelId)
{
    try {
        // Zaten düşülmüş mü? (idempotent koruma)
        if (DB::table('stok_hareketleri')->where('kaynak_tip', 'adisyon')->where('kaynak_id', $adisyonId)->exists()) return;
        // İptal olmayan kalemler: urun_id -> toplam adet
        $kalemler = DB::table('adisyon_kalemleri')->where('adisyon_id', $adisyonId)
            ->where('durum', '!=', 'iptal')->whereNotNull('urun_id')
            ->selectRaw('urun_id, SUM(adet) adet')->groupBy('urun_id')->get();
        if ($kalemler->isEmpty()) return;
        // Once tum urunlerin hammadde ihtiyacini patlatarak topla (yari mamuller dahil), sonra malzeme basina tek hareket yaz.
        $ihtiyac = []; // malzeme_id => temel birim toplam
        foreach ($kalemler as $kal) {
            $recete = DB::table('receteler')->where('tip', 'urun')->where('urun_id', $kal->urun_id)->first();
            if (!$recete) continue;
            _restoReceteHammadde($recete->id, (float) $kal->adet, $ihtiyac);
        }
        foreach ($ihtiyac as $malzemeId => $temelMiktar) {
            if ($temelMiktar <= 0) continue;
            $m = DB::table('malzemeler')->where('id', $malzemeId)->first(['guncel_maliyet']);
            DB::table('stok_hareketleri')->insert([
                'sube_id' => $subeId, 'malzeme_id' => (int) $malzemeId, 'tip' => 'tuketim', 'miktar' => -$temelMiktar,
                'birim_maliyet' => $m ? (float) $m->guncel_maliyet : 0, 'kaynak_tip' => 'adisyon', 'kaynak_id' => $adisyonId,
                'aciklama' => 'Satış tüketimi', 'personel_id' => $personelId,
            ]);
            // FAZ 3: FEFO — en yakın SKT'li partiden düş (parti takibi varsa)
            if (function_exists('_partiDus')) _partiDus($subeId, (int) $malzemeId, $temelMiktar);
        }
    } catch (\Throwable $e) {
        // sessiz geç — satış akışını asla bozma
    }
}

// URETIM RISKI: kritik malzemeler + her urunun kalan stokla kac porsiyon cikacagi (NESTED/yari mamul dahil),
// darbogaz malzemesi. "Bizi bizden koruyan" motor: hangi hammadde bitince hangi yemek cikmaz.
function _restoUretimRiski($subeId, $esik = 15)
{
    $stok = DB::table('stok_hareketleri')->where('sube_id', $subeId)
        ->selectRaw('malzeme_id, SUM(miktar) m')->groupBy('malzeme_id')->pluck('m', 'malzeme_id');
    $birimAd = DB::table('birimler')->pluck('kisaltma', 'id');
    $malAd = DB::table('malzemeler')->pluck('ad', 'id');
    $urunAd = DB::table('urunler')->pluck('ad', 'id'); // ürün adları tek sorQuda (döngü içi N+1 yerine)
    // 1) Kritik malzemeler (stok <= kritik esik)
    $kritik = [];
    foreach (DB::table('malzemeler')->where('stok_takipli', 1)->where('kritik_stok', '>', 0)->get(['id', 'ad', 'kritik_stok', 'temel_birim_id']) as $m) {
        $mevcut = (float) ($stok[$m->id] ?? 0);
        if ($mevcut <= (float) $m->kritik_stok) {
            $kritik[] = ['id' => (int) $m->id, 'ad' => $m->ad, 'mevcut' => round($mevcut, 2), 'kritik' => (float) $m->kritik_stok, 'birim' => $birimAd[$m->temel_birim_id] ?? ''];
        }
    }
    // 2) Her urun: kalan stokla kac porsiyon (nested patlatma) + darbogaz
    $riskli = [];
    foreach (DB::table('receteler')->where('tip', 'urun')->whereNotNull('urun_id')->get(['id', 'urun_id']) as $rec) {
        $ihtiyac = [];
        _restoReceteHammadde($rec->id, 1, $ihtiyac);
        if (!$ihtiyac) continue;
        $yap = null; $darbogazId = null;
        foreach ($ihtiyac as $mid => $need) {
            if ($need <= 0) continue;
            $por = (int) floor(max(0, (float) ($stok[$mid] ?? 0)) / $need);
            if ($yap === null || $por < $yap) { $yap = $por; $darbogazId = $mid; }
        }
        if ($yap === null) continue;
        $riskli[] = ['urun_id' => (int) $rec->urun_id, 'urun' => $urunAd[$rec->urun_id] ?? '—',
            'yapilabilir' => $yap, 'darbogaz' => $malAd[$darbogazId] ?? '—'];
    }
    usort($riskli, fn ($a, $b) => $a['yapilabilir'] <=> $b['yapilabilir']);
    return ['kritik' => $kritik, 'riskli' => array_values(array_filter($riskli, fn ($x) => $x['yapilabilir'] <= $esik))];
}

// Uretim riski endpoint (ekran icin)
Route::get('/api/patron/uretim-riski', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $esik = $r->esik !== null ? max(0, (int) $r->esik) : 15;
    $risk = _restoUretimRiski($p->sube_id, $esik);
    return ['ok' => 1, 'esik' => $esik, 'kritik' => $risk['kritik'], 'riskli' => $risk['riskli']];
});

