// Manuel stok hareketi: giris | fire | duzeltme
Route::post('/api/patron/stok-hareket', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || $p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $m = DB::table('malzemeler')->where('id', (int) $r->malzeme_id)->first();
    if (!$m) return ['ok' => 0, 'hata' => 'Malzeme bulunamadı'];
    $tip = in_array($r->tip, ['giris', 'fire', 'duzeltme']) ? $r->tip : null;
    if (!$tip) return ['ok' => 0, 'hata' => 'Geçersiz hareket türü'];
    $miktar = (float) $r->miktar; // temel birimde
    if ($miktar == 0) return ['ok' => 0, 'hata' => 'Miktar 0 olamaz'];
    $imzali = $tip === 'fire' ? -abs($miktar) : ($tip === 'giris' ? abs($miktar) : $miktar);
    DB::table('stok_hareketleri')->insert([
        'sube_id' => $p->sube_id, 'malzeme_id' => $m->id, 'tip' => $tip === 'giris' ? 'iade' : ($tip === 'fire' ? 'fire' : 'sayim'),
        'miktar' => $imzali, 'birim_maliyet' => (float) $m->guncel_maliyet, 'kaynak_tip' => 'manuel',
        'aciklama' => $r->aciklama ? (string) $r->aciklama : ($tip === 'fire' ? 'Fire' : ($tip === 'giris' ? 'Manuel giriş' : 'Sayım düzeltme')),
        'personel_id' => $p->id,
    ]);
    return ['ok' => 1];
});

// ============ SAYIM (fiziksel envanter) + TEORIK-GERCEK FARK (variance) ============
// teorik = defter stogu (stok_hareketleri toplami). sayilan = fiili. fark = sayilan - teorik (kayip/fazla).
// Kaydedince defter fiili sayima esitlenir (tip='sayim' duzeltme hareketi). Bu, "bizi bizden koruyan" kayip radari.
function _restoSayimEnsure()
{
    if (!Schema::hasTable('sayimlar')) {
        Schema::create('sayimlar', function ($t) {
            $t->id(); $t->unsignedBigInteger('sube_id'); $t->date('tarih'); $t->string('durum')->default('acik');
            $t->unsignedBigInteger('personel_id')->nullable(); $t->timestamps();
        });
    }
    if (!Schema::hasTable('sayim_kalemleri')) {
        Schema::create('sayim_kalemleri', function ($t) {
            $t->id(); $t->unsignedBigInteger('sayim_id'); $t->unsignedBigInteger('malzeme_id');
            $t->decimal('sayilan', 16, 4)->default(0); $t->decimal('teorik', 16, 4)->default(0);
            $t->decimal('fark', 16, 4)->default(0); $t->decimal('fark_maliyet', 14, 2)->default(0); $t->timestamps();
        });
    }
}

// Yeni sayim sablonu: tum takipli malzemeler + teorik (defter stogu) otomatik dolu, sayilan bos
Route::get('/api/patron/sayim-yeni', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoSayimEnsure();
    $mevcut = _restoStokMevcut($p->sube_id);
    $birim = DB::table('birimler')->pluck('kisaltma', 'id');
    $kat = DB::table('malzeme_kategorileri')->pluck('ad', 'id');
    $rows = DB::table('malzemeler')->where('stok_takipli', 1)->orderBy('ad')->get()->map(fn ($m) => [
        'malzeme_id' => (int) $m->id, 'ad' => $m->ad, 'kategori' => $kat[$m->kategori_id] ?? '—',
        'birim' => $birim[$m->temel_birim_id] ?? '', 'teorik' => round((float) ($mevcut[$m->id] ?? 0), 3), 'guncel_maliyet' => (float) $m->guncel_maliyet,
    ]);
    return ['ok' => 1, 'duzenleyebilir' => $p->rol === 'sahip', 'tarih' => today()->format('d.m.Y'), 'malzemeler' => $rows->values()];
});

// Sayim kaydet -> fark hesapla + defteri fiiliye esitle (tip='sayim')
Route::post('/api/patron/sayim-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || $p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Sayımı sadece işletme sahibi kaydedebilir.'], 403);
    _restoSayimEnsure();
    $kalemler = json_decode((string) $r->kalemler, true);
    if (!is_array($kalemler) || !$kalemler) return ['ok' => 0, 'hata' => 'Sayım boş'];
    return DB::transaction(function () use ($p, $kalemler) {
        $sayimId = DB::table('sayimlar')->insertGetId(['sube_id' => $p->sube_id, 'tarih' => today(), 'durum' => 'kapandi', 'personel_id' => $p->id, 'created_at' => now(), 'updated_at' => now()]);
        $toplamFarkMaliyet = 0.0; $eksik = 0; $fazla = 0; $n = 0;
        foreach ($kalemler as $k) {
            $mid = (int) ($k['malzeme_id'] ?? 0);
            // Sadece sayilan girilen kalemleri isle (bos birakilan = sayilmadi, atla)
            if ($mid <= 0 || !array_key_exists('sayilan', $k) || $k['sayilan'] === null || $k['sayilan'] === '') continue;
            $m = DB::table('malzemeler')->where('id', $mid)->first(['guncel_maliyet']);
            if (!$m) continue;
            $sayilan = (float) $k['sayilan'];
            $teorik = (float) DB::table('stok_hareketleri')->where('sube_id', $p->sube_id)->where('malzeme_id', $mid)->sum('miktar');
            $fark = round($sayilan - $teorik, 4);
            $farkMaliyet = round($fark * (float) $m->guncel_maliyet, 2);
            DB::table('sayim_kalemleri')->insert(['sayim_id' => $sayimId, 'malzeme_id' => $mid, 'sayilan' => $sayilan, 'teorik' => $teorik, 'fark' => $fark, 'fark_maliyet' => $farkMaliyet, 'created_at' => now(), 'updated_at' => now()]);
            if (abs($fark) > 0.0001) {
                DB::table('stok_hareketleri')->insert(['sube_id' => $p->sube_id, 'malzeme_id' => $mid, 'tip' => 'sayim', 'miktar' => $fark,
                    'birim_maliyet' => (float) $m->guncel_maliyet, 'kaynak_tip' => 'sayim', 'kaynak_id' => $sayimId, 'aciklama' => 'Sayım düzeltmesi', 'personel_id' => $p->id, 'created_at' => now()]);
            }
            $toplamFarkMaliyet += $farkMaliyet; $n++;
            if ($fark < 0) $eksik++; elseif ($fark > 0) $fazla++;
        }
        if ($n === 0) { DB::table('sayimlar')->where('id', $sayimId)->delete(); return ['ok' => 0, 'hata' => 'Hiç sayım girilmemiş']; }
        return ['ok' => 1, 'sayim_id' => $sayimId, 'sayilan_kalem' => $n, 'eksik' => $eksik, 'fazla' => $fazla, 'toplam_fark_maliyet' => round($toplamFarkMaliyet, 2)];
    });
});

// Sayim gecmisi
Route::get('/api/patron/sayim-gecmis', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoSayimEnsure();
    $liste = DB::table('sayimlar')->where('sube_id', $p->sube_id)->orderByDesc('id')->limit(30)->get()->map(function ($s) {
        $agg = DB::table('sayim_kalemleri')->where('sayim_id', $s->id)
            ->selectRaw('COUNT(*) n, COALESCE(SUM(fark_maliyet),0) fm, COALESCE(SUM(CASE WHEN fark < 0 THEN 1 ELSE 0 END),0) eksik')->first();
        return ['id' => (int) $s->id, 'tarih' => \Carbon\Carbon::parse($s->tarih)->format('d.m.Y'),
            'kalem' => (int) $agg->n, 'eksik' => (int) $agg->eksik, 'fark_maliyet' => round((float) $agg->fm, 2)];
    });
    return ['ok' => 1, 'sayimlar' => $liste];
});

// Sayim detayi + AI fark yorumu
Route::get('/api/patron/sayim-detay', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoSayimEnsure();
    $s = DB::table('sayimlar')->where('id', (int) $r->id)->where('sube_id', $p->sube_id)->first();
    if (!$s) return ['ok' => 0, 'hata' => 'Sayım bulunamadı'];
    $birim = DB::table('birimler')->pluck('kisaltma', 'id');
    $kalemler = DB::table('sayim_kalemleri')->join('malzemeler', 'sayim_kalemleri.malzeme_id', '=', 'malzemeler.id')
        ->where('sayim_id', $s->id)->orderBy('sayim_kalemleri.fark_maliyet') // en cok kayip ustte
        ->get(['malzemeler.ad', 'malzemeler.temel_birim_id', 'sayim_kalemleri.sayilan', 'sayim_kalemleri.teorik', 'sayim_kalemleri.fark', 'sayim_kalemleri.fark_maliyet'])
        ->map(fn ($k) => ['malzeme' => $k->ad, 'birim' => $birim[$k->temel_birim_id] ?? '', 'sayilan' => (float) $k->sayilan,
            'teorik' => (float) $k->teorik, 'fark' => (float) $k->fark, 'fark_maliyet' => (float) $k->fark_maliyet]);
    $toplam = round($kalemler->sum('fark_maliyet'), 2);
    $ai = [];
    $enKayip = $kalemler->where('fark_maliyet', '<', 0)->sortBy('fark_maliyet')->first();
    if ($enKayip) $ai[] = ['seviye' => 'riskli', 'mesaj' => 'En çok kayıp: ' . $enKayip['malzeme'] . ' (' . number_format(abs($enKayip['fark_maliyet']), 0, ',', '.') . 'TL açık). Fazla porsiyon, fire ya da kaçak olabilir — reçete/porsiyon standardını ve fireyi kontrol edin.'];
    if ($toplam < 0) $ai[] = ['seviye' => 'uyari', 'mesaj' => 'Bu sayımda toplam ' . number_format(abs($toplam), 0, ',', '.') . 'TL açık (fiili stok sistemden az). İşte teorik-gerçek farkınız — kayıp radarı.'];
    elseif ($toplam > 0) $ai[] = ['seviye' => 'bilgi', 'mesaj' => 'Stok sistemden ' . number_format($toplam, 0, ',', '.') . 'TL fazla çıktı — alış girişleri veya reçeteler eksik olabilir.'];
    else $ai[] = ['seviye' => 'iyi', 'mesaj' => 'Fark yok — defter fiili sayımla birebir. Tertemiz.'];
    return ['ok' => 1, 'tarih' => \Carbon\Carbon::parse($s->tarih)->format('d.m.Y'), 'toplam_fark_maliyet' => $toplam, 'ai' => $ai, 'kalemler' => $kalemler->values()];
});

// GELEN MUSTERI DETAYI (donemsel) — trafik serisi + yogun saat/gun + kanal + bolge + sadakat + AI
Route::get('/api/patron/musteri-detay', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $period = in_array($r->period, ['gunluk', 'haftalik', 'aylik', 'yillik']) ? $r->period : 'gunluk';
    [$from, $to, $pfrom, $pto] = _restoPeriyot($period);

    $rows = DB::table('adisyonlar')->where('sube_id', $p->sube_id)->where('durum', 'odendi')
        ->whereBetween('kapanis', [$from, $to])
        ->get(['misafir_sayisi', 'acilis', 'kapanis', 'kanal', 'masa_id', 'musteri_id', 'toplam']);

    $bolgeAd = DB::table('bolgeler')->pluck('ad', 'id');
    $masaBolge = DB::table('masalar')->pluck('bolge_id', 'id');

    $toplamMisafir = 0; $folyo = 0; $ciro = 0.0;
    $saat = array_fill(0, 24, 0);
    $gun = array_fill(0, 7, 0); // 0=Pzt .. 6=Paz
    $kanal = []; $bolge = []; $kayitliMis = 0; $anonimMis = 0;

    foreach ($rows as $a) {
        $m = (int) $a->misafir_sayisi;
        $toplamMisafir += $m; $folyo++; $ciro += (float) $a->toplam;
        $ac = \Carbon\Carbon::parse($a->acilis ?: $a->kapanis);
        $saat[(int) $ac->format('G')] += $m;
        $wd = ((int) $ac->dayOfWeek + 6) % 7; // Carbon 0=Paz..6=Cmt -> 0=Pzt..6=Paz
        $gun[$wd] += $m;
        $k = $a->kanal ?: 'salon';
        $kanal[$k] = ($kanal[$k] ?? 0) + $m;
        if ($a->masa_id && isset($masaBolge[$a->masa_id]) && isset($bolgeAd[$masaBolge[$a->masa_id]])) {
            $bad = $bolgeAd[$masaBolge[$a->masa_id]];
        } else {
            $bad = $k === 'paket' ? 'Paket' : ($k === 'qr' ? 'QR / Self' : 'Diğer');
        }
        $bolge[$bad] = ($bolge[$bad] ?? 0) + $m;
        if ($a->musteri_id) $kayitliMis += $m; else $anonimMis += $m;
    }

    // Trafik zaman serisi (donem granulasyonu)
    $seri = [];
    if ($period === 'gunluk') {
        for ($h = 0; $h < 24; $h++) $seri[] = ['etiket' => sprintf('%02d', $h), 'misafir' => $saat[$h]];
    } elseif ($period === 'yillik') {
        $aylar = [];
        foreach ($rows as $a) { $key = \Carbon\Carbon::parse($a->kapanis)->format('Y-m'); $aylar[$key] = ($aylar[$key] ?? 0) + (int) $a->misafir_sayisi; }
        $cur = \Carbon\Carbon::parse($from)->startOfMonth(); $end = \Carbon\Carbon::parse($to)->startOfMonth();
        while ($cur <= $end) { $seri[] = ['etiket' => $cur->format('m/y'), 'misafir' => $aylar[$cur->format('Y-m')] ?? 0]; $cur->addMonth(); }
    } else {
        $gunler = [];
        foreach ($rows as $a) { $key = \Carbon\Carbon::parse($a->kapanis)->format('Y-m-d'); $gunler[$key] = ($gunler[$key] ?? 0) + (int) $a->misafir_sayisi; }
        $cur = \Carbon\Carbon::parse($from)->startOfDay(); $end = \Carbon\Carbon::parse($to)->startOfDay();
        while ($cur <= $end) { $seri[] = ['etiket' => $cur->format('d/m'), 'misafir' => $gunler[$cur->format('Y-m-d')] ?? 0]; $cur->addDay(); }
    }

    $oncekiMisafir = (int) DB::table('adisyonlar')->where('sube_id', $p->sube_id)->where('durum', 'odendi')
        ->whereBetween('kapanis', [$pfrom, $pto])->sum('misafir_sayisi');

    $kanalAd = ['salon' => 'Masada', 'paket' => 'Paket', 'qr' => 'QR / Self'];
    $kanalList = [];
    foreach ($kanal as $k => $v) $kanalList[] = ['kanal' => $kanalAd[$k] ?? ucfirst($k), 'misafir' => $v, 'yuzde' => $toplamMisafir > 0 ? round($v / $toplamMisafir * 100) : 0];
    usort($kanalList, fn ($a, $b) => $b['misafir'] <=> $a['misafir']);

    $bolgeList = [];
    foreach ($bolge as $ad => $v) $bolgeList[] = ['ad' => $ad, 'misafir' => $v, 'yuzde' => $toplamMisafir > 0 ? round($v / $toplamMisafir * 100) : 0];
    usort($bolgeList, fn ($a, $b) => $b['misafir'] <=> $a['misafir']);

    $gunAdKisa = ['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'];
    $gunList = [];
    for ($i = 0; $i < 7; $i++) $gunList[] = ['gun' => $gunAdKisa[$i], 'misafir' => $gun[$i]];

    $saatList = [];
    for ($h = 0; $h < 24; $h++) if ($saat[$h] > 0) $saatList[] = ['saat' => sprintf('%02d:00', $h), 'misafir' => $saat[$h]];

    // AI koçluk
    $ai = [];
    if ($toplamMisafir > 0) {
        $enSaat = array_keys($saat, max($saat))[0];
        $sonSaat = min(23, $enSaat + 2);
        $enGunI = array_keys($gun, max($gun))[0];
        $gunTam = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar'];
        $ai[] = ['seviye' => 'bilgi', 'mesaj' => 'En yoğun saat ' . sprintf('%02d:00–%02d:00', $enSaat, $sonSaat) . ' — personel ve hazırlığı buna göre planlayın.'];
        $ai[] = ['seviye' => 'bilgi', 'mesaj' => 'En yoğun gün: ' . $gunTam[$enGunI] . '. En sakin günlere kampanya/menü düşünebilirsiniz.'];
        if ($kanalList) $ai[] = ['seviye' => 'bilgi', 'mesaj' => 'Trafiğin çoğu ' . $kanalList[0]['kanal'] . ' (%' . $kanalList[0]['yuzde'] . ').'];
        $sadakatOran = round($kayitliMis / $toplamMisafir * 100);
        $ai[] = ['seviye' => $sadakatOran >= 30 ? 'iyi' : 'bilgi', 'mesaj' => 'Misafirin %' . $sadakatOran . '\'i kayıtlı müşteri (tekrar gelen). Sadakati artırmak en ucuz büyümedir.'];
        if ($oncekiMisafir > 0) {
            $d = (int) round(($toplamMisafir - $oncekiMisafir) / $oncekiMisafir * 100);
            $ai[] = ['seviye' => $d >= 0 ? 'iyi' : 'riskli', 'mesaj' => 'Trafik önceki döneme göre %' . abs($d) . ($d >= 0 ? ' arttı 🎉' : ' azaldı — sebebini araştırın.')];
        }
    } else {
        $ai[] = ['seviye' => 'bilgi', 'mesaj' => 'Bu dönemde ödenmiş misafir kaydı yok.'];
    }

    return [
        'ok' => 1, 'period' => $period,
        'ozet' => [
            'misafir' => $toplamMisafir, 'folyo' => $folyo,
            'ort_grup' => $folyo > 0 ? round($toplamMisafir / $folyo, 1) : 0,
            'kisi_basi' => $toplamMisafir > 0 ? round($ciro / $toplamMisafir) : 0,
            'onceki_misafir' => $oncekiMisafir,
        ],
        'seri' => $seri, 'saatler' => $saatList, 'gunler' => $gunList,
        'kanallar' => $kanalList, 'bolgeler' => $bolgeList,
        'sadakat' => ['kayitli' => $kayitliMis, 'anonim' => $anonimMis],
        'ai' => $ai,
    ];
});

// ============ BAGLI CIHAZLAR (heartbeat) + YAZARKASA durumu ============
function _restoCihazEnsure()
{
    if (!Schema::hasTable('cihazlar')) {
        Schema::create('cihazlar', function ($t) {
            $t->id();
            $t->unsignedBigInteger('sube_id');
            $t->string('kimlik', 100);           // cihaz parmak izi (uuid, prefs'te saklanir)
            $t->string('ad')->nullable();
            $t->string('tip')->default('bilgisayar'); // bilgisayar|tablet|telefon|kds|yazarkasa
            $t->string('platform')->nullable();
            $t->string('surum')->nullable();
            $t->string('rol')->nullable();
            $t->string('ip')->nullable();
            $t->timestamp('son_gorulme')->nullable();
            $t->timestamps();
            $t->unique(['sube_id', 'kimlik']);
        });
    }
    // Additive kolonlar — manuel cihaz yonetimi (IP/port/marka vs. elle girilir)
    $kolonlar = [
        'manuel'  => function ($t) { $t->tinyInteger('manuel')->default(0); },      // 1=elle tanimlandi, 0=heartbeat
        'port'    => function ($t) { $t->string('port', 20)->nullable(); },
        'marka'   => function ($t) { $t->string('marka', 60)->nullable(); },
        'seri_no' => function ($t) { $t->string('seri_no', 60)->nullable(); },
        'aktif'   => function ($t) { $t->tinyInteger('aktif')->default(1); },
        'notlar'  => function ($t) { $t->text('notlar')->nullable(); },
    ];
    foreach ($kolonlar as $kol => $ekle) {
        if (!Schema::hasColumn('cihazlar', $kol)) {
            Schema::table('cihazlar', function ($t) use ($ekle) { $ekle($t); });
        }
    }
}

// Cihaz sinyali (heartbeat) — ResteOS acikken periyodik gonderir. Her rol cagirabilir.
Route::post('/api/cihaz/ping', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _restoCihazEnsure();
    $kimlik = substr(trim((string) $r->kimlik), 0, 100);
    if ($kimlik === '') return ['ok' => 0, 'hata' => 'kimlik yok'];
    $tip = in_array($r->tip, ['bilgisayar', 'tablet', 'telefon', 'kds', 'yazarkasa']) ? $r->tip : 'bilgisayar';
    $veri = [
        'ad' => substr((string) ($r->ad ?: 'ResteOS Cihazı'), 0, 80), 'tip' => $tip,
        'platform' => substr((string) $r->platform, 0, 40), 'surum' => substr((string) $r->surum, 0, 30),
        'rol' => $p->rol, 'ip' => $r->ip(), 'son_gorulme' => now(), 'updated_at' => now(),
    ];
    $row = DB::table('cihazlar')->where('sube_id', $p->sube_id)->where('kimlik', $kimlik)->first();
    if ($row) {
        DB::table('cihazlar')->where('id', $row->id)->update($veri);
    } else {
        $veri['sube_id'] = $p->sube_id; $veri['kimlik'] = $kimlik; $veri['created_at'] = now();
        DB::table('cihazlar')->insert($veri);
    }
    return ['ok' => 1];
});

// Bagli cihazlar listesi + yazarkasa durumu (SAHIP/MUDUR)
Route::get('/api/patron/cihazlar', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoCihazEnsure();
    $esik = 120; // sn — bu sure icinde sinyal geldiyse ONLINE (yesil)
    $now = now();
    $gecen = function ($sn) {
        if ($sn === null) return 'hiç';
        if ($sn < 60) return 'az önce';
        if ($sn < 3600) return floor($sn / 60) . ' dk önce';
        if ($sn < 86400) return floor($sn / 3600) . ' sa önce';
        return floor($sn / 86400) . ' gün önce';
    };
    $liste = DB::table('cihazlar')->where('sube_id', $p->sube_id)->orderByDesc('son_gorulme')->get()->map(function ($c) use ($now, $esik, $gecen) {
        $sg = $c->son_gorulme ? \Carbon\Carbon::parse($c->son_gorulme) : null;
        $sn = $sg ? (int) $sg->diffInSeconds($now) : null;
        return [
            'id' => (int) $c->id, 'ad' => $c->ad, 'tip' => $c->tip, 'platform' => $c->platform, 'surum' => $c->surum,
            'ip' => $c->ip, 'rol' => $c->rol, 'online' => $sn !== null && $sn <= $esik, 'son_gorulme' => $gecen($sn),
            'manuel' => (int) ($c->manuel ?? 0) === 1, 'port' => $c->port ?? null, 'marka' => $c->marka ?? null,
            'seri_no' => $c->seri_no ?? null, 'aktif' => (int) ($c->aktif ?? 1) === 1, 'notlar' => $c->notlar ?? null,
        ];
    })->sortByDesc('manuel')->values();

    // Yazarkasa (OKC) — edonusum_ayarlari + son okc fisi
    $yazarkasa = null;
    $ayar = Schema::hasTable('edonusum_ayarlari') ? DB::table('edonusum_ayarlari')->where('sube_id', $p->sube_id)->first() : null;
    if ($ayar) {
        $aktif = (($ayar->fis_modu ?? '') === 'okc') && !empty($ayar->okc_aktif);
        $sonFis = DB::table('e_faturalar')->where('sube_id', $p->sube_id)->where('tip', 'okc_fis')->orderByDesc('id')->first();
        $durum = 'kapali'; $mesaj = 'Yazarkasa modu kapalı (e-Arşiv kullanılıyor).';
        if ($aktif) {
            if ($sonFis && $sonFis->durum === 'hata') { $durum = 'hata'; $mesaj = 'Aktif ama son fişte HATA — bağlantı/cihaz kontrol edin.'; }
            elseif ($sonFis && $sonFis->durum === 'basildi') { $durum = 'online'; $mesaj = 'Aktif · son mali fiş başarıyla basıldı.'; }
            elseif ($sonFis && $sonFis->durum === 'simulasyon') { $durum = 'test'; $mesaj = 'Aktif ama fiş simülasyonda basılıyor (gerçek cihaz sürücüsü bağlı değil).'; }
            else { $durum = 'bekliyor'; $mesaj = 'Aktif · henüz mali fiş basılmadı.'; }
        }
        $yazarkasa = [
            'marka' => $ayar->okc_marka, 'ip' => $ayar->okc_ip, 'port' => $ayar->okc_port, 'aktif' => $aktif,
            'durum' => $durum, 'mesaj' => $mesaj,
            'son_fis' => $sonFis ? \Carbon\Carbon::parse($sonFis->created_at)->format('d.m H:i') : null,
        ];
    }

    return ['ok' => 1, 'esik_sn' => $esik, 'cihazlar' => $liste, 'yazarkasa' => $yazarkasa];
});

// Manuel cihaz ekle/guncelle (SAHIP/MUDUR) — IP/port/marka vs. elle. Simdilik sinirsiz (ileride paket limiti).
Route::post('/api/patron/cihaz-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoCihazEnsure();
    $tipler = ['yazici', 'yazarkasa', 'terminal', 'cekmece', 'bilgisayar', 'tablet', 'telefon', 'kds', 'barkod', 'el_terminali', 'diger'];
    $tip = in_array($r->tip, $tipler) ? $r->tip : 'diger';
    $ad = trim((string) $r->ad);
    if ($ad === '') return ['ok' => 0, 'hata' => 'Cihaz adı gerekli'];
    $veri = [
        'ad' => mb_substr($ad, 0, 80), 'tip' => $tip,
        'ip' => mb_substr(trim((string) $r->ip), 0, 60),
        'port' => mb_substr(trim((string) $r->port), 0, 20),
        'marka' => mb_substr(trim((string) $r->marka), 0, 60),
        'seri_no' => mb_substr(trim((string) $r->seri_no), 0, 60),
        'notlar' => mb_substr(trim((string) $r->notlar), 0, 500),
        'aktif' => in_array((string) $r->aktif, ['0', 'false', ''], true) ? 0 : 1,
        'manuel' => 1, 'updated_at' => now(),
    ];
    $id = (int) $r->id;
    if ($id > 0) {
        $var = DB::table('cihazlar')->where('id', $id)->where('sube_id', $p->sube_id)->first();
        if (!$var) return ['ok' => 0, 'hata' => 'Cihaz bulunamadı'];
        DB::table('cihazlar')->where('id', $id)->update($veri);
    } else {
        $veri['sube_id'] = $p->sube_id;
        $veri['kimlik'] = 'manuel-' . \Illuminate\Support\Str::random(14);
        $veri['rol'] = $p->rol;
        $veri['created_at'] = now();
        $id = DB::table('cihazlar')->insertGetId($veri);
    }
    return ['ok' => 1, 'id' => $id];
});

// Manuel cihaz sil (SAHIP/MUDUR). Heartbeat cihazlar da silinebilir (tekrar sinyalde geri gelir).
Route::post('/api/patron/cihaz-sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoCihazEnsure();
    DB::table('cihazlar')->where('id', (int) $r->id)->where('sube_id', $p->sube_id)->delete();
    return ['ok' => 1];
});

// ============ HAREKETLER / AKTIVITE LOG (tum kaynaklar tek zaman akisi) ============
Route::get('/api/patron/hareketler', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    \App\Http\Middleware\AktiviteLog::ensure();
    $sube = $p->sube_id;
    $to = $r->to ? \Carbon\Carbon::parse($r->to)->endOfDay() : now();
    $gun = (int) ($r->gun ?: 7);
    $from = $r->from ? \Carbon\Carbon::parse($r->from)->startOfDay() : (clone $to)->subDays($gun);
    $kategoriF = ($r->kategori && $r->kategori !== 'hepsi') ? $r->kategori : null;
    $kimF = $r->kim ? (int) $r->kim : null;
    $ara = trim((string) $r->ara);
    $limit = 800;

    $pAd = DB::table('personeller')->pluck('ad', 'id');
    $pRol = DB::table('personeller')->pluck('rol', 'id');
    $hepsi = [];
    $ekle = function ($zaman, $kategori, $baslik, $aciklama, $personelId, $tutar, $yon, $kt, $ki, $ip = null, $yol = null) use (&$hepsi) {
        if (!$zaman) return;
        $hepsi[] = ['zaman' => (string) $zaman, 'kategori' => $kategori, 'baslik' => $baslik, 'aciklama' => $aciklama,
            'personel_id' => $personelId ? (int) $personelId : null, 'tutar' => $tutar !== null ? (float) $tutar : null,
            'yon' => $yon, 'kaynak_tip' => $kt, 'kaynak_id' => $ki ? (int) $ki : null,
            'ip' => $ip ?: null, 'yol' => $yol ?: null];
    };

    // 1) Merkezi aktivite log (config/ayar/menu/recete/yetki/tema/giris...)
    try {
        foreach (DB::table('aktivite_loglari')->where('sube_id', $sube)->whereBetween('created_at', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $a) {
            $ekle($a->created_at, $a->kategori, $a->aksiyon, $a->aciklama, $a->personel_id, null, null, 'aktivite', $a->id, $a->ip ?? null, $a->yol ?? null);
        }
    } catch (\Throwable $e) {}
    // 2) Odemeler
    try {
        foreach (DB::table('odemeler')->join('adisyonlar', 'odemeler.adisyon_id', '=', 'adisyonlar.id')->where('adisyonlar.sube_id', $sube)
            ->whereBetween('odemeler.created_at', [$from, $to])->orderByDesc('odemeler.id')->limit($limit)
            ->get(['odemeler.id', 'odemeler.tip', 'odemeler.tutar', 'odemeler.personel_id', 'odemeler.created_at', 'odemeler.adisyon_id']) as $o) {
            $tipAd = ['nakit' => 'Nakit', 'kredi' => 'Kredi Kartı', 'yemek_karti' => 'Yemek Kartı', 'acik_hesap' => 'Açık Hesap'][$o->tip] ?? $o->tip;
            $ekle($o->created_at, 'odeme', 'Ödeme alındı (' . $tipAd . ')', null, $o->personel_id, $o->tutar, 'giris', 'adisyon', $o->adisyon_id);
        }
    } catch (\Throwable $e) {}
    // 3) Iskonto/Ikram/Void
    try {
        foreach (DB::table('iptal_indirim_loglari')->where('sube_id', $sube)->whereBetween('created_at', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $l) {
            $ad = ['indirim' => 'İskonto', 'ikram' => 'İkram', 'void' => 'Ürün silme (void)'][$l->tip] ?? $l->tip;
            $ekle($l->created_at, 'kayip', $ad, $l->sebep ?? null, $l->personel_id, $l->tutar, 'cikis', 'adisyon', $l->adisyon_id);
        }
    } catch (\Throwable $e) {}
    // 4) Stok hareketleri
    try {
        $malAd = DB::table('malzemeler')->pluck('ad', 'id');
        foreach (DB::table('stok_hareketleri')->where('sube_id', $sube)->whereBetween('created_at', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $s) {
            $ad = ['alis' => 'Stok girişi (alış)', 'tuketim' => 'Satış tüketimi', 'fire' => 'Fire / zayi', 'sayim' => 'Sayım düzeltmesi', 'iade' => 'Manuel giriş', 'transfer' => 'Transfer'][$s->tip] ?? $s->tip;
            $mik = (float) $s->miktar;
            $ekle($s->created_at, 'stok', $ad, ($malAd[$s->malzeme_id] ?? '') . ' · ' . rtrim(rtrim(number_format($mik, 2, '.', ''), '0'), '.'),
                $s->personel_id, $s->birim_maliyet ? abs($mik) * (float) $s->birim_maliyet : null, $mik < 0 ? 'cikis' : 'giris', 'malzeme', $s->malzeme_id);
        }
    } catch (\Throwable $e) {}
    // 5) Kasa hareketleri
    try {
        if (Schema::hasTable('kasa_hareketleri')) {
            foreach (DB::table('kasa_hareketleri')->where('sube_id', $sube)->whereBetween('created_at', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $k) {
                $yon = ($k->yon ?? '') === 'cikis' ? 'cikis' : 'giris';
                $ekle($k->created_at, 'kasa', 'Kasa ' . ($yon === 'giris' ? 'giriş' : 'çıkış'), $k->aciklama ?? null, $k->personel_id ?? null, $k->tutar ?? null, $yon, 'kasa', $k->id);
            }
        }
    } catch (\Throwable $e) {}
    // 6) Cari hareketler
    try {
        if (Schema::hasTable('cari_hareketler')) {
            $cariAd = DB::table('cari_hesaplar')->pluck('ad', 'id');
            foreach (DB::table('cari_hareketler')->where('sube_id', $sube)->whereBetween('created_at', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $c) {
                $th = ($c->tip ?? '') === 'tahsilat';
                $ekle($c->created_at, 'cari', $th ? 'Cari tahsilat' : 'Cari borç', $cariAd[$c->cari_id] ?? ($c->aciklama ?? null), $c->personel_id ?? null, $c->tutar ?? null, $th ? 'giris' : 'cikis', 'cari', $c->cari_id ?? null);
            }
        }
    } catch (\Throwable $e) {}
    // 7) Personel hareketleri (avans/prim/kesinti/odeme)
    try {
        if (Schema::hasTable('personel_hareketleri')) {
            foreach (DB::table('personel_hareketleri')->where('sube_id', $sube)->whereBetween('tarih', [substr($from, 0, 10), substr($to, 0, 10)])->orderByDesc('id')->limit($limit)->get() as $ph) {
                $ad = ['avans' => 'Personel avans', 'prim' => 'Personel prim', 'kesinti' => 'Personel kesinti', 'odeme' => 'Personel ödeme', 'maas' => 'Maaş ödemesi'][$ph->tur ?? ''] ?? ('Personel: ' . ($ph->tur ?? ''));
                $ekle($ph->tarih, 'personel', $ad, $pAd[$ph->personel_id] ?? null, $ph->created_by ?? null, $ph->tutar ?? null, 'cikis', 'personel', $ph->personel_id);
            }
        }
    } catch (\Throwable $e) {}
    // 8) Giderler (maas haric — o personel_hareketleri'nde)
    try {
        foreach (DB::table('giderler')->where('sube_id', $sube)->where('kategori', '!=', 'maas')->whereBetween('tarih', [substr($from, 0, 10), substr($to, 0, 10)])->orderByDesc('id')->limit($limit)->get() as $g) {
            $ekle($g->tarih, 'gider', 'Gider · ' . ($g->kategori ?? ''), $g->aciklama ?? null, $g->created_by ?? null, $g->tutar ?? null, 'cikis', 'gider', $g->id);
        }
    } catch (\Throwable $e) {}
    // 9) Fis/fatura
    try {
        if (Schema::hasTable('e_faturalar')) {
            foreach (DB::table('e_faturalar')->where('sube_id', $sube)->whereBetween('created_at', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $f) {
                $ad = ($f->tip === 'okc_fis' ? 'Yazarkasa fişi' : 'e-Arşiv fatura') . ' (' . $f->durum . ')';
                $ekle($f->created_at, 'fis', $ad, $f->belge_no ?? null, null, $f->toplam ?? null, null, 'fatura', $f->id);
            }
        }
    } catch (\Throwable $e) {}
    // 10) Adisyon iptal
    try {
        foreach (DB::table('adisyonlar')->where('sube_id', $sube)->where('durum', 'iptal')->whereBetween('acilis', [$from, $to])->orderByDesc('id')->limit($limit)->get() as $a) {
            $ekle($a->acilis, 'satis', 'Adisyon iptal edildi', null, $a->acan_personel_id ?? null, $a->toplam ?? null, 'cikis', 'adisyon', $a->id);
        }
    } catch (\Throwable $e) {}
    // 11) Masa loglari (tasi/birlestir/bol/garson devri)
    try {
        if (Schema::hasTable('adisyon_masa_loglari')) {
            foreach (DB::table('adisyon_masa_loglari')->join('adisyonlar', 'adisyon_masa_loglari.adisyon_id', '=', 'adisyonlar.id')
                ->where('adisyonlar.sube_id', $sube)->whereBetween('adisyon_masa_loglari.created_at', [$from, $to])
                ->orderByDesc('adisyon_masa_loglari.id')->limit($limit)
                ->get(['adisyon_masa_loglari.islem', 'adisyon_masa_loglari.created_at', 'adisyon_masa_loglari.personel_id', 'adisyon_masa_loglari.adisyon_id']) as $m) {
                $etk = ['tasima' => 'Masa taşındı', 'birlestirme' => 'Masa birleştirildi', 'bolme' => 'Adisyon bölündü', 'garson_devri' => 'Garson devri'][$m->islem] ?? $m->islem;
                $ekle($m->created_at, 'satis', $etk, null, $m->personel_id, null, null, 'adisyon', $m->adisyon_id);
            }
        }
    } catch (\Throwable $e) {}

    // Filtre
    $suz = array_values(array_filter($hepsi, function ($h) use ($kategoriF, $kimF, $ara) {
        if ($kategoriF && $h['kategori'] !== $kategoriF) return false;
        if ($kimF && (int) $h['personel_id'] !== $kimF) return false;
        if ($ara !== '') {
            $hay = mb_strtolower(($h['baslik'] ?? '') . ' ' . ($h['aciklama'] ?? '') . ' ' . (string) ($h['tutar'] ?? ''));
            if (mb_strpos($hay, mb_strtolower($ara)) === false) return false;
        }
        return true;
    }));
    usort($suz, fn ($a, $b) => strcmp($b['zaman'], $a['zaman']));

    // Ozet
    $girisT = 0.0; $cikisT = 0.0; $katSay = [];
    foreach ($suz as $h) {
        if ($h['tutar'] !== null) { if ($h['yon'] === 'giris') $girisT += $h['tutar']; elseif ($h['yon'] === 'cikis') $cikisT += $h['tutar']; }
        $katSay[$h['kategori']] = ($katSay[$h['kategori']] ?? 0) + 1;
    }
    $toplam = count($suz);

    // Sayfalama + kisi adi + okunur zaman
    $boyut = min(100, max(10, (int) ($r->boyut ?: 40)));
    $sayfa = max(1, (int) ($r->sayfa ?: 1));
    $dilim = array_slice($suz, ($sayfa - 1) * $boyut, $boyut);

    // IP -> cihaz eşlemesi (kayıtlı/heartbeat cihazlar); kaynak (Kasa/Mobil) cihaz tipinden.
    $cihazMap = [];
    try {
        foreach (DB::table('cihazlar')->where('sube_id', $sube)->whereNotNull('ip')->where('ip', '!=', '')->get(['ip', 'ad', 'tip', 'platform']) as $cz) {
            if (!isset($cihazMap[$cz->ip])) $cihazMap[$cz->ip] = $cz;
        }
    } catch (\Throwable $e) {}
    $kaynakAd = fn ($tip) => in_array($tip, ['bilgisayar', 'kds']) ? 'Kasa' : (in_array($tip, ['telefon', 'tablet', 'el_terminali']) ? 'Mobil' : 'Cihaz');
    $hedefAd = ['adisyon' => 'Adisyon', 'masa' => 'Masa', 'malzeme' => 'Malzeme', 'cari' => 'Cari', 'kasa' => 'Kasa', 'personel' => 'Personel', 'gider' => 'Gider', 'fatura' => 'Fatura/Fiş'];

    foreach ($dilim as &$h) {
        $c = \Carbon\Carbon::parse($h['zaman']);
        $h['saat'] = $c->format('H:i'); $h['tarih'] = $c->format('d.m.Y'); $h['gun_key'] = $c->format('Y-m-d');
        $h['zaman_tam'] = $c->format('d.m.Y H:i:s');
        $h['personel'] = $h['personel_id'] ? ($pAd[$h['personel_id']] ?? null) : null;
        $rolK = $h['personel_id'] ? ($pRol[$h['personel_id']] ?? null) : null;
        $h['rol'] = $rolK ? (['sahip' => 'Sahip', 'mudur' => 'Müdür', 'kasa' => 'Kasa', 'garson' => 'Garson'][$rolK] ?? ucfirst($rolK)) : null;
        // Cihaz / kaynak (IP eşleşmesi varsa)
        $cz = ($h['ip'] && isset($cihazMap[$h['ip']])) ? $cihazMap[$h['ip']] : null;
        $h['cihaz'] = $cz ? $cz->ad : null;
        $h['kaynak'] = $cz ? $kaynakAd($cz->tip) : ($h['ip'] ? 'Bilinmeyen cihaz' : null);
        // Hedef (okunur)
        $h['hedef'] = ($h['kaynak_tip'] && $h['kaynak_id']) ? (($hedefAd[$h['kaynak_tip']] ?? ucfirst((string) $h['kaynak_tip'])) . ' #' . $h['kaynak_id']) : null;
    }
    unset($h);

    return ['ok' => 1, 'toplam' => $toplam, 'sayfa' => $sayfa, 'boyut' => $boyut,
        'ozet' => ['toplam' => $toplam, 'giris' => round($girisT), 'cikis' => round($cikisT), 'kategori' => $katSay],
        'hareketler' => array_values($dilim),
        'personeller' => DB::table('personeller')->where('sube_id', $sube)->orderBy('ad')->get(['id', 'ad']),
    ];
});

// ---- TEDARİKÇİLER ----
Route::get('/api/patron/tedarikciler', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $alis = DB::table('alis_faturalari')->where('sube_id', $p->sube_id)
        ->selectRaw('tedarikci_id, SUM(toplam) t, COUNT(*) c, MAX(tarih) son')->groupBy('tedarikci_id')->get()->keyBy('tedarikci_id');
    $tedKolonlar = ['id', 'ad', 'telefon', 'aciklama'];
    if (Schema::hasColumn('tedarikciler', 'anlasmali')) $tedKolonlar[] = 'anlasmali';
    $liste = DB::table('tedarikciler')->orderBy('ad')->get($tedKolonlar)->map(function ($x) use ($alis) {
        $a = $alis[$x->id] ?? null;
        return ['id' => (int) $x->id, 'ad' => $x->ad, 'telefon' => $x->telefon, 'aciklama' => $x->aciklama,
            'anlasmali' => (int) ($x->anlasmali ?? 0),
            'toplam_alis' => $a ? (float) $a->t : 0.0, 'fatura_sayisi' => $a ? (int) $a->c : 0, 'son_alis' => $a ? $a->son : null];
    });
    return ['ok' => 1, 'duzenleyebilir' => $p->rol === 'sahip', 'tedarikciler' => $liste];
});

Route::post('/api/patron/tedarikci-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || $p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $ad = trim((string) $r->ad);
    if ($ad === '') return ['ok' => 0, 'hata' => 'Ad boş olamaz'];
    $veri = ['ad' => $ad, 'telefon' => $r->telefon ? (string) $r->telefon : null, 'aciklama' => $r->aciklama ? (string) $r->aciklama : null, 'updated_at' => now()];
    if (Schema::hasColumn('tedarikciler', 'anlasmali')) $veri['anlasmali'] = $r->input('anlasmali') ? 1 : 0;
    $id = (int) $r->id;
    if ($id > 0) { DB::table('tedarikciler')->where('id', $id)->update($veri); return ['ok' => 1, 'id' => $id]; }
    $veri['created_at'] = now();
    return ['ok' => 1, 'id' => DB::table('tedarikciler')->insertGetId($veri)];
});

Route::post('/api/patron/tedarikci-sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || $p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $id = (int) $r->id;
    if (DB::table('alis_faturalari')->where('tedarikci_id', $id)->exists()) return ['ok' => 0, 'hata' => 'Bu tedarikçinin faturaları var, silinemez.'];
    DB::table('tedarikciler')->where('id', $id)->delete();
    return ['ok' => 1];
});

// ---- ALIŞ FATURALARI (stok girişi + fiyat uyarısı + maliyet güncelleme + gider) ----
Route::get('/api/patron/alis-faturalari', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoGiderEnsure();
    [$ay, $bas, $bit] = _restoAyAralik($r->ay);
    $ted = DB::table('tedarikciler')->pluck('ad', 'id');
    $liste = DB::table('alis_faturalari')->where('sube_id', $p->sube_id)
        ->whereBetween('tarih', [substr($bas, 0, 10), substr($bit, 0, 10)])->orderByDesc('tarih')->orderByDesc('id')->get();
    $toplam = 0.0;
    $rows = $liste->map(function ($f) use ($ted, &$toplam) {
        $toplam += (float) $f->toplam;
        $enUyari = DB::table('alis_fatura_kalemleri')->where('fatura_id', $f->id)
            ->orderByRaw("FIELD(uyari,'kirmizi','sari','yesil') ")->value('uyari');
        return ['id' => (int) $f->id, 'tedarikci' => $ted[$f->tedarikci_id] ?? 'Bilinmiyor', 'fatura_no' => $f->fatura_no,
            'tarih' => $f->tarih, 'toplam' => (float) $f->toplam, 'durum' => $f->durum, 'uyari' => $enUyari ?: 'yesil'];
    });
    return ['ok' => 1, 'ay' => $ay, 'duzenleyebilir' => $p->rol === 'sahip', 'toplam' => round($toplam, 2), 'faturalar' => $rows];
});

Route::get('/api/patron/alis-fatura-detay', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $f = DB::table('alis_faturalari')->where('id', (int) $r->id)->where('sube_id', $p->sube_id)->first();
    if (!$f) return ['ok' => 0, 'hata' => 'Fatura bulunamadı'];
    $ted = DB::table('tedarikciler')->where('id', $f->tedarikci_id)->value('ad');
    $birim = DB::table('birimler')->pluck('kisaltma', 'id');
    $malz = DB::table('malzemeler')->pluck('ad', 'id');
    $kalemler = DB::table('alis_fatura_kalemleri')->where('fatura_id', $f->id)->get()->map(fn ($k) => [
        'malzeme' => $malz[$k->malzeme_id] ?? '—', 'birim' => $birim[$k->alis_birim_id] ?? '', 'miktar' => (float) $k->miktar,
        'birim_fiyat' => (float) $k->birim_fiyat, 'satir_toplam' => (float) $k->satir_toplam,
        'onceki_fiyat' => (float) $k->onceki_fiyat, 'fiyat_farki_yuzde' => (float) $k->fiyat_farki_yuzde, 'uyari' => $k->uyari]);
    return ['ok' => 1, 'tedarikci' => $ted, 'fatura_no' => $f->fatura_no, 'tarih' => $f->tarih, 'toplam' => (float) $f->toplam, 'durum' => $f->durum, 'kalemler' => $kalemler];
});

Route::post('/api/patron/alis-fatura-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if ($p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Fatura girişini sadece işletme sahibi yapabilir.'], 403);
    _restoGiderEnsure();
    $kalemler = json_decode((string) $r->kalemler, true);
    if (!is_array($kalemler) || count($kalemler) === 0) return ['ok' => 0, 'hata' => 'En az bir kalem girmelisiniz'];
    $tarih = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $r->tarih) ? $r->tarih : date('Y-m-d');
    $tedId = (int) $r->tedarikci_id ?: null;

    return DB::transaction(function () use ($r, $p, $kalemler, $tarih, $tedId) {
        // Önce toplamı ve uyarıları hesapla
        $hazir = [];
        $toplam = 0.0;
        foreach ($kalemler as $k) {
            $mid = (int) ($k['malzeme_id'] ?? 0);
            $m = DB::table('malzemeler')->where('id', $mid)->first();
            if (!$m) continue;
            $birimId = (int) ($k['birim_id'] ?? $m->temel_birim_id);
            $miktar = (float) ($k['miktar'] ?? 0);
            $birimFiyat = (float) ($k['birim_fiyat'] ?? 0);
            if ($miktar <= 0 || $birimFiyat < 0) continue;
            $satir = round($miktar * $birimFiyat, 2);
            $toplam += $satir;
            // Önceki alış fiyatı (aynı malzeme, aynı birim) -> fiyat farkı + uyarı
            $onceki = (float) DB::table('alis_fatura_kalemleri')->where('malzeme_id', $mid)->where('alis_birim_id', $birimId)
                ->orderByDesc('id')->value('birim_fiyat');
            $farkYuzde = $onceki > 0 ? round(($birimFiyat - $onceki) / $onceki * 100, 2) : 0.0;
            $uyari = 'yesil';
            if ($onceki > 0) { $a = abs($farkYuzde); $uyari = $a >= 15 ? 'kirmizi' : ($a >= 5 ? 'sari' : 'yesil'); }
            $hazir[] = compact('m', 'birimId', 'miktar', 'birimFiyat', 'satir', 'onceki', 'farkYuzde', 'uyari');
        }
        if (count($hazir) === 0) return ['ok' => 0, 'hata' => 'Geçerli kalem yok'];

        $faturaId = DB::table('alis_faturalari')->insertGetId([
            'sube_id' => $p->sube_id, 'tedarikci_id' => $tedId, 'fatura_no' => $r->fatura_no ? (string) $r->fatura_no : null,
            'tarih' => $tarih, 'toplam' => round($toplam, 2), 'durum' => 'onaylandi',
            'giren_personel_id' => $p->id, 'onaylayan_personel_id' => $p->id, 'created_at' => now(), 'updated_at' => now(),
        ]);

        foreach ($hazir as $h) {
            $m = $h['m'];
            DB::table('alis_fatura_kalemleri')->insert([
                'fatura_id' => $faturaId, 'malzeme_id' => $m->id, 'alis_birim_id' => $h['birimId'], 'miktar' => $h['miktar'],
                'birim_fiyat' => $h['birimFiyat'], 'satir_toplam' => $h['satir'], 'onceki_fiyat' => $h['onceki'],
                'fiyat_farki_yuzde' => $h['farkYuzde'], 'fiyat_farki_tutar' => round(($h['birimFiyat'] - $h['onceki']) * $h['miktar'], 2),
                'uyari' => $h['uyari'], 'created_at' => now(), 'updated_at' => now(),
            ]);
            // Stok girişi: temel birime çevir
            $kars = _restoBirimKarsilik($m->id, $h['birimId'], $m->temel_birim_id);
            $temelMiktar = $h['miktar'] * $kars;
            $temelMaliyet = $kars > 0 ? $h['birimFiyat'] / $kars : $h['birimFiyat']; // temel birim başına maliyet
            DB::table('stok_hareketleri')->insert([
                'sube_id' => $p->sube_id, 'malzeme_id' => $m->id, 'tip' => 'alis', 'miktar' => $temelMiktar,
                'birim_maliyet' => $temelMaliyet, 'kaynak_tip' => 'fatura', 'kaynak_id' => $faturaId,
                'aciklama' => 'Alış faturası', 'personel_id' => $p->id,
            ]);
            // Hareketli ağırlıklı ortalama maliyet güncelle
            $eskiStok = (float) DB::table('stok_hareketleri')->where('sube_id', $p->sube_id)->where('malzeme_id', $m->id)->where('kaynak_id', '!=', $faturaId)->sum('miktar');
            $eskiMaliyet = (float) $m->guncel_maliyet;
            if ($eskiStok > 0 && $eskiMaliyet > 0) {
                $yeni = ($eskiStok * $eskiMaliyet + $temelMiktar * $temelMaliyet) / ($eskiStok + $temelMiktar);
            } else {
                $yeni = $temelMaliyet;
            }
            DB::table('malzemeler')->where('id', $m->id)->update(['guncel_maliyet' => round($yeni, 4), 'updated_at' => now()]);
            // FAZ 1: tedarikçi-malzeme katalog/fiyat otomatik güncelle (radar + gizli-zam beyni)
            if ($tedId && function_exists('_tedarikMalzemeFiyat')) _tedarikMalzemeFiyat($p->sube_id, $tedId, $m->id, $h['birimId'], $h['birimFiyat'], $tarih);
        }

        // Otomatik gider (kategori malzeme)
        $tedAd = $tedId ? DB::table('tedarikciler')->where('id', $tedId)->value('ad') : 'Tedarikçi';
        DB::table('giderler')->insert(['sube_id' => $p->sube_id, 'kategori' => 'malzeme',
            'aciklama' => $tedAd . ($r->fatura_no ? ' · ' . $r->fatura_no : '') . ' (alış faturası)', 'tutar' => round($toplam, 2),
            'tarih' => $tarih, 'created_by' => $p->id]);

        return ['ok' => 1, 'id' => $faturaId, 'toplam' => round($toplam, 2)];
    });
});

Route::post('/api/patron/alis-fatura-sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || $p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $id = (int) $r->id;
    $f = DB::table('alis_faturalari')->where('id', $id)->where('sube_id', $p->sube_id)->first();
    if (!$f) return ['ok' => 0, 'hata' => 'Fatura bulunamadı'];
    DB::transaction(function () use ($id, $f, $p) {
        DB::table('stok_hareketleri')->where('kaynak_tip', 'fatura')->where('kaynak_id', $id)->delete();
        DB::table('alis_fatura_kalemleri')->where('fatura_id', $id)->delete();
        DB::table('alis_faturalari')->where('id', $id)->delete();
        // Bağlı otomatik gideri de kaldır (tutar+tarih eşleşmesiyle en yakın)
        $g = DB::table('giderler')->where('sube_id', $p->sube_id)->where('kategori', 'malzeme')->where('tutar', (float) $f->toplam)->where('tarih', $f->tarih)->orderByDesc('id')->first();
        if ($g) DB::table('giderler')->where('id', $g->id)->delete();
    });
    return ['ok' => 1];
});

// ---- REÇETE EDİTÖRÜ ----
Route::get('/api/patron/urun-recete', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $urunId = (int) $r->urun_id;
    $urun = DB::table('urunler')->where('id', $urunId)->first(['id', 'ad', 'fiyat']);
    if (!$urun) return ['ok' => 0, 'hata' => 'Ürün bulunamadı'];
    $recete = DB::table('receteler')->where('tip', 'urun')->where('urun_id', $urunId)->first();
    $birim = DB::table('birimler')->pluck('kisaltma', 'id');
    $malz = DB::table('malzemeler')->get()->keyBy('id');
    $kalemler = [];
    $maliyet = 0.0;
    if ($recete) {
        foreach (DB::table('recete_kalemleri')->where('recete_id', $recete->id)->whereNotNull('malzeme_id')->get() as $k) {
            $m = $malz[$k->malzeme_id] ?? null;
            $kars = _restoBirimKarsilik($k->malzeme_id, $k->birim_id, $m->temel_birim_id ?? null);
            $satirMal = $m ? (float) $k->miktar * $kars * (float) $m->guncel_maliyet : 0.0;
            $maliyet += $satirMal;
            $kalemler[] = ['malzeme_id' => (int) $k->malzeme_id, 'malzeme' => $m->ad ?? '—', 'miktar' => (float) $k->miktar,
                'birim_id' => (int) $k->birim_id, 'birim' => $birim[$k->birim_id] ?? '', 'satir_maliyet' => round($satirMal, 2)];
        }
        // Yari mamul (alt recete) satirlari
        foreach (DB::table('recete_kalemleri')->where('recete_id', $recete->id)->whereNotNull('alt_recete_id')->get() as $k) {
            $alt = DB::table('receteler')->where('id', $k->alt_recete_id)->first(['ad', 'verim_miktar']);
            if (!$alt) continue;
            $verim = (float) $alt->verim_miktar > 0 ? (float) $alt->verim_miktar : 1.0;
            $satirMal = (float) $k->miktar * (_restoReceteToplamMaliyet($k->alt_recete_id) / $verim);
            $maliyet += $satirMal;
            $kalemler[] = ['alt_recete_id' => (int) $k->alt_recete_id, 'malzeme' => $alt->ad, 'yarimamul' => true, 'miktar' => (float) $k->miktar,
                'birim_id' => (int) $k->birim_id, 'birim' => $birim[$k->birim_id] ?? '', 'satir_maliyet' => round($satirMal, 2)];
        }
    }
    $fc = (float) $urun->fiyat > 0 ? round($maliyet / (float) $urun->fiyat * 100, 1) : 0.0;
    return ['ok' => 1, 'duzenleyebilir' => $p->rol === 'sahip', 'urun_ad' => $urun->ad, 'fiyat' => (float) $urun->fiyat,
        'maliyet' => round($maliyet, 2), 'food_cost' => $fc, 'kalemler' => $kalemler];
});

Route::post('/api/patron/recete-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if ($p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Reçeteyi sadece işletme sahibi düzenleyebilir.'], 403);
    $urunId = (int) $r->urun_id;
    $urun = DB::table('urunler')->where('id', $urunId)->first();
    if (!$urun) return ['ok' => 0, 'hata' => 'Ürün bulunamadı'];
    $kalemler = json_decode((string) $r->kalemler, true);
    if (!is_array($kalemler)) return ['ok' => 0, 'hata' => 'Geçersiz veri'];
    return DB::transaction(function () use ($urun, $urunId, $kalemler) {
        $recete = DB::table('receteler')->where('tip', 'urun')->where('urun_id', $urunId)->first();
        if ($recete) {
            $receteId = $recete->id;
            DB::table('recete_kalemleri')->where('recete_id', $receteId)->delete();
        } else {
            $receteId = DB::table('receteler')->insertGetId(['ad' => $urun->ad . ' Reçetesi', 'tip' => 'urun', 'urun_id' => $urunId, 'verim_miktar' => 1, 'created_at' => now(), 'updated_at' => now()]);
        }
        foreach ($kalemler as $k) {
            $miktar = (float) ($k['miktar'] ?? 0);
            $birimId = (int) ($k['birim_id'] ?? 0);
            $altId = (int) ($k['alt_recete_id'] ?? 0);
            if ($altId > 0) {
                // Yari mamul satiri — dongu engeli (kendini/dolayli kendini icerme)
                if ($miktar <= 0 || $birimId <= 0) continue;
                if ($altId === $receteId || _restoReceteDonguVar($receteId, $altId)) continue;
                DB::table('recete_kalemleri')->insert(['recete_id' => $receteId, 'alt_recete_id' => $altId, 'miktar' => $miktar, 'birim_id' => $birimId, 'created_at' => now(), 'updated_at' => now()]);
                continue;
            }
            $mid = (int) ($k['malzeme_id'] ?? 0);
            if ($mid <= 0 || $miktar <= 0 || $birimId <= 0) continue;
            DB::table('recete_kalemleri')->insert(['recete_id' => $receteId, 'malzeme_id' => $mid, 'miktar' => $miktar, 'birim_id' => $birimId, 'created_at' => now(), 'updated_at' => now()]);
        }
        return ['ok' => 1];
    });
});

// Reçetesi olmayan/olan ürünleri listele (reçete yönetimi ekranı için)
Route::get('/api/patron/recete-urunler', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $mMap = _restoUrunMaliyetMap();
    $receteli = DB::table('receteler')->where('tip', 'urun')->whereNotNull('urun_id')
        ->join('recete_kalemleri', 'receteler.id', '=', 'recete_kalemleri.recete_id')
        ->distinct()->pluck('receteler.urun_id')->toArray();
    $receteliSet = array_flip($receteli);
    $urunler = DB::table('urunler')->where('aktif', 1)->orderBy('ad')->get(['id', 'ad', 'fiyat'])->map(function ($u) use ($mMap, $receteliSet) {
        $mal = $mMap['id'][$u->id] ?? 0;
        $fc = (float) $u->fiyat > 0 && $mal > 0 ? round($mal / (float) $u->fiyat * 100, 1) : 0.0;
        return ['id' => (int) $u->id, 'ad' => $u->ad, 'fiyat' => (float) $u->fiyat, 'maliyet' => round($mal, 2),
            'food_cost' => $fc, 'receteli' => isset($receteliSet[$u->id])];
    });
    return ['ok' => 1, 'urunler' => $urunler];
});

// ============ YARI MAMUL (alt recete) YONETIMI ============
// Yari mamul = tip='yari_mamul' recete: ad + verim (kac cikar) + kalemler (malzeme veya baska yari mamul).
// Patlatma modeli: ayri stok TUTULMAZ; urun recetesine eklenince maliyeti/hammaddesi otomatik yansir.

// Liste (yonetim + urun recetesinde secim listesi icin)
Route::get('/api/patron/yarimamuller', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $birim = DB::table('birimler')->pluck('kisaltma', 'id');
    $kalemSay = DB::table('recete_kalemleri')->selectRaw('recete_id, COUNT(*) c')->groupBy('recete_id')->pluck('c', 'recete_id');
    $liste = DB::table('receteler')->where('tip', 'yari_mamul')->orderBy('ad')->get()->map(function ($rec) use ($birim, $kalemSay) {
        $verim = (float) $rec->verim_miktar > 0 ? (float) $rec->verim_miktar : 1.0;
        $toplam = _restoReceteToplamMaliyet($rec->id);
        return ['id' => (int) $rec->id, 'ad' => $rec->ad, 'verim_miktar' => (float) $rec->verim_miktar,
            'verim_birim_id' => (int) $rec->verim_birim_id, 'verim_birim' => $birim[$rec->verim_birim_id] ?? '',
            'kalem_sayisi' => (int) ($kalemSay[$rec->id] ?? 0), 'toplam_maliyet' => round($toplam, 2), 'birim_maliyet' => round($toplam / $verim, 4)];
    });
    return ['ok' => 1, 'duzenleyebilir' => $p->rol === 'sahip', 'yarimamuller' => $liste->values()];
});

// Bir yari mamulun detayi (editor icin) — malzeme + alt recete kalemleri
Route::get('/api/patron/yarimamul-detay', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $rec = DB::table('receteler')->where('id', (int) $r->id)->where('tip', 'yari_mamul')->first();
    if (!$rec) return ['ok' => 0, 'hata' => 'Yarı mamül bulunamadı'];
    $birim = DB::table('birimler')->pluck('kisaltma', 'id');
    $malz = DB::table('malzemeler')->get()->keyBy('id');
    $kalemler = [];
    $maliyet = 0.0;
    foreach (DB::table('recete_kalemleri')->where('recete_id', $rec->id)->get() as $k) {
        if ($k->malzeme_id) {
            $m = $malz[$k->malzeme_id] ?? null;
            $kars = _restoBirimKarsilik($k->malzeme_id, $k->birim_id, $m->temel_birim_id ?? null);
            $satir = $m ? (float) $k->miktar * $kars * (float) $m->guncel_maliyet : 0.0;
            $maliyet += $satir;
            $kalemler[] = ['malzeme_id' => (int) $k->malzeme_id, 'malzeme' => $m->ad ?? '—', 'miktar' => (float) $k->miktar,
                'birim_id' => (int) $k->birim_id, 'birim' => $birim[$k->birim_id] ?? '', 'satir_maliyet' => round($satir, 2)];
        } elseif ($k->alt_recete_id) {
            $alt = DB::table('receteler')->where('id', $k->alt_recete_id)->first(['ad', 'verim_miktar']);
            if (!$alt) continue;
            $verim = (float) $alt->verim_miktar > 0 ? (float) $alt->verim_miktar : 1.0;
            $satir = (float) $k->miktar * (_restoReceteToplamMaliyet($k->alt_recete_id) / $verim);
            $maliyet += $satir;
            $kalemler[] = ['alt_recete_id' => (int) $k->alt_recete_id, 'malzeme' => $alt->ad, 'yarimamul' => true, 'miktar' => (float) $k->miktar,
                'birim_id' => (int) $k->birim_id, 'birim' => $birim[$k->birim_id] ?? '', 'satir_maliyet' => round($satir, 2)];
        }
    }
    return ['ok' => 1, 'duzenleyebilir' => $p->rol === 'sahip', 'ad' => $rec->ad, 'verim_miktar' => (float) $rec->verim_miktar,
        'verim_birim_id' => (int) $rec->verim_birim_id, 'maliyet' => round($maliyet, 2), 'kalemler' => $kalemler];
});

// Yari mamul olustur/duzenle (SAHIP)
Route::post('/api/patron/yarimamul-kaydet', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if ($p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yarı mamülü sadece işletme sahibi düzenleyebilir.'], 403);
    $ad = trim((string) $r->ad);
    if ($ad === '') return ['ok' => 0, 'hata' => 'Yarı mamül adı boş olamaz'];
    $verim = (float) $r->verim_miktar;
    if ($verim <= 0) return ['ok' => 0, 'hata' => 'Verim (kaç çıkıyor) 0’dan büyük olmalı'];
    $verimBirim = (int) $r->verim_birim_id;
    if ($verimBirim <= 0) return ['ok' => 0, 'hata' => 'Verim birimi seçin (litre/kg/porsiyon…)'];
    $kalemler = json_decode((string) $r->kalemler, true);
    if (!is_array($kalemler)) return ['ok' => 0, 'hata' => 'Geçersiz veri'];
    $id = (int) $r->id;
    return DB::transaction(function () use ($ad, $verim, $verimBirim, $kalemler, $id) {
        if ($id > 0) {
            $rec = DB::table('receteler')->where('id', $id)->where('tip', 'yari_mamul')->first();
            if (!$rec) return ['ok' => 0, 'hata' => 'Yarı mamül bulunamadı'];
            DB::table('receteler')->where('id', $id)->update(['ad' => $ad, 'verim_miktar' => $verim, 'verim_birim_id' => $verimBirim, 'updated_at' => now()]);
            DB::table('recete_kalemleri')->where('recete_id', $id)->delete();
            $receteId = $id;
        } else {
            $receteId = DB::table('receteler')->insertGetId(['ad' => $ad, 'tip' => 'yari_mamul', 'urun_id' => null,
                'verim_miktar' => $verim, 'verim_birim_id' => $verimBirim, 'created_at' => now(), 'updated_at' => now()]);
        }
        foreach ($kalemler as $k) {
            $miktar = (float) ($k['miktar'] ?? 0);
            $birimId = (int) ($k['birim_id'] ?? 0);
            $altId = (int) ($k['alt_recete_id'] ?? 0);
            if ($altId > 0) {
                if ($miktar <= 0 || $birimId <= 0) continue;
                if ($altId === $receteId || _restoReceteDonguVar($receteId, $altId)) continue; // dongu engeli
                DB::table('recete_kalemleri')->insert(['recete_id' => $receteId, 'alt_recete_id' => $altId, 'miktar' => $miktar, 'birim_id' => $birimId, 'created_at' => now(), 'updated_at' => now()]);
                continue;
            }
            $mid = (int) ($k['malzeme_id'] ?? 0);
            if ($mid <= 0 || $miktar <= 0 || $birimId <= 0) continue;
            DB::table('recete_kalemleri')->insert(['recete_id' => $receteId, 'malzeme_id' => $mid, 'miktar' => $miktar, 'birim_id' => $birimId, 'created_at' => now(), 'updated_at' => now()]);
        }
        return ['ok' => 1, 'id' => $receteId];
    });
});

// Yari mamul sil (SAHIP) — baska recetede kullaniliyorsa engelle
Route::post('/api/patron/yarimamul-sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || $p->rol !== 'sahip') return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    $id = (int) $r->id;
    $kullanan = DB::table('recete_kalemleri')->where('alt_recete_id', $id)->count();
    if ($kullanan > 0) return ['ok' => 0, 'hata' => "Bu yarı mamül $kullanan reçetede kullanılıyor; önce oralardan çıkarın."];
    DB::table('recete_kalemleri')->where('recete_id', $id)->delete();
    DB::table('receteler')->where('id', $id)->where('tip', 'yari_mamul')->delete();
    return ['ok' => 1];
});

// ---- FİNANSAL ÖZET (aylık gelir/gider/net + tedarikçi alış) ----
Route::get('/api/patron/finans', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _restoGiderEnsure();
    [$ay, $bas, $bit] = _restoAyAralik($r->ay);
    // Gelir: odemeler (adisyon join ile sube filtre)
    $gelirRows = DB::table('odemeler')->join('adisyonlar', 'odemeler.adisyon_id', '=', 'adisyonlar.id')
        ->where('adisyonlar.sube_id', $p->sube_id)->whereBetween('odemeler.created_at', [$bas, $bit])
        ->selectRaw('odemeler.tip, SUM(odemeler.tutar) t, SUM(odemeler.bahsis) b')->groupBy('odemeler.tip')->get();
    $gelir = 0.0; $bahsis = 0.0; $gelirTip = [];
    foreach ($gelirRows as $g) { $gelir += (float) $g->t; $bahsis += (float) $g->b; $gelirTip[] = ['tip' => $g->tip, 'tutar' => (float) $g->t]; }
    // Gider: giderler kategori kırılımı
    $giderRows = DB::table('giderler')->where('sube_id', $p->sube_id)->whereBetween('tarih', [substr($bas, 0, 10), substr($bit, 0, 10)])
        ->selectRaw('kategori, SUM(tutar) t')->groupBy('kategori')->get();
    $gider = 0.0; $giderKat = [];
    foreach ($giderRows as $g) { $gider += (float) $g->t; $giderKat[] = ['kategori' => $g->kategori, 'tutar' => (float) $g->t]; }
    usort($giderKat, fn ($a, $b) => $b['tutar'] <=> $a['tutar']);
    // Tedarikçi alış (bilgi)
    $alis = (float) DB::table('alis_faturalari')->where('sube_id', $p->sube_id)->whereBetween('tarih', [substr($bas, 0, 10), substr($bit, 0, 10)])->sum('toplam');
    return ['ok' => 1, 'ay' => $ay, 'gelir' => round($gelir, 2), 'bahsis' => round($bahsis, 2), 'gider' => round($gider, 2),
        'net' => round($gelir - $gider, 2), 'gelir_tip' => $gelirTip, 'gider_kategori' => $giderKat, 'alis_toplam' => round($alis, 2)];
});

// ADISYON OPERASYONLARI (yetki kontrollu): kapat | iskonto | ikram | iptal
// Limit asimi/garson kisiti -> onay_pin (mudur/sahip PIN'i) ile onaylanir.
Route::post('/api/patron/adisyon-islem', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $islem = $r->islem;
    $a = DB::table('adisyonlar')->find((int) $r->adisyon_id);
    if (!$a) return ['ok' => 0, 'hata' => 'Adisyon bulunamadı'];
    if ($a->durum !== 'acik') return ['ok' => 0, 'hata' => 'Bu adisyon zaten kapanmış veya iptal edilmiş.'];

    // Onaylayan (mudur/sahip PIN'i) — limit asimi/iptal onayinda kullanilir
    $onaylayan = null;
    if ($r->onay_pin) {
        $onaylayan = DB::table('personeller')->where('sube_id', $p->sube_id)->where('pin', (string) $r->onay_pin)->first();
        if (!$onaylayan) return ['ok' => 0, 'hata' => 'Onay PIN hatalı.'];
    }
    $yetki = fn ($k) => _restoYetkiVar($p, $k);

    if ($islem === 'kapat') {
        if (!$yetki('adisyon_kapat')) return ['ok' => 0, 'hata' => 'Ödeme alma / masa kapatma yetkiniz yok.'];
        // ATOMİK CLAIM: yalnız hâlâ 'acik' ise kapat -> iki kasadan EŞZAMANLI kapanışta çift ödeme/çift kasa kaydı OLMAZ.
        $claimed = DB::table('adisyonlar')->where('id', $a->id)->where('durum', 'acik')->update(['durum' => 'odendi', 'kapanis' => now(), 'updated_at' => now()]);
        if ($claimed === 0) return ['ok' => 0, 'hata' => 'Bu adisyon az önce kapatıldı.'];
        $tip = in_array($r->odeme_tip, ['nakit', 'kredi', 'yemek_karti', 'acik_hesap']) ? $r->odeme_tip : 'nakit';
        $kalan = (float) $a->toplam - (float) DB::table('odemeler')->where('adisyon_id', $a->id)->sum('tutar');
        if ($tip === 'acik_hesap') {
            // "Bana yazin" -> secili cari hesaba borc yazilir (nakit girmez ama ciroya sayilir)
            $cari = DB::table('cari_hesaplar')->where('id', (int) $r->cari_id)->where('sube_id', $p->sube_id)->first();
            if (!$cari) return ['ok' => 0, 'hata' => 'Açık hesap için bir cari seçmelisiniz.'];
            if ($kalan > 0) {
                DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => 'acik_hesap', 'tutar' => $kalan, 'personel_id' => $p->id, 'created_at' => now()]);
                DB::table('cari_hareketler')->insert(['sube_id' => $p->sube_id, 'cari_id' => $cari->id, 'tip' => 'borc', 'tutar' => $kalan,
                    'adisyon_id' => $a->id, 'aciklama' => ($a->masa_id ? 'Masa açık hesap' : 'Adisyon açık hesap'), 'personel_id' => $p->id, 'created_at' => now()]);
            }
            $mesaj = $cari->ad . ' hesabına yazıldı (' . number_format($kalan, 0, ',', '.') . 'TL).';
        } else {
            if ($kalan > 0) {
                DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => $tip, 'tutar' => $kalan, 'personel_id' => $p->id, 'created_at' => now()]);
                // Nakit ise kasaya (acik vardiya varsa) otomatik giris
                if ($tip === 'nakit') _kasaYaz($p->sube_id, 'satis', 'giris', $kalan, 'Nakit satış · adisyon #' . $a->id, 'adisyon', $a->id, $p->id);
            }
            $mesaj = 'Ödeme alındı (' . ['nakit' => 'Nakit', 'kredi' => 'Kredi', 'yemek_karti' => 'Yemek Kartı'][$tip] . '), masa kapatıldı.';
        }
        // (durum/kapanis yukarıda atomik claim ile zaten yazıldı)
        if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
        _restoStokTuket($a->id, $p->sube_id, $p->id); // reçeteden otomatik stok düşümü (güvenli, bozmaz)
        _adisyonKapanisIsle($a->id); // CRM sadakat + mali fiş
        return ['ok' => 1, 'mesaj' => $mesaj];
    }

    // PARCALI / BOLUNMUS ODEME — kapatmadan tutar al; kalan 0'a inince otomatik kapatir.
    if ($islem === 'ode') {
        if (!$yetki('adisyon_kapat')) return ['ok' => 0, 'hata' => 'Ödeme alma yetkiniz yok.'];
        $tip = in_array($r->odeme_tip, ['nakit', 'kredi', 'yemek_karti']) ? $r->odeme_tip : 'nakit';
        // Yemek kartı markası (Multinet/Sodexo/Ticket…) -> odemeler.marka'da rapor için sakla
        if (!Schema::hasColumn('odemeler', 'marka')) {
            Schema::table('odemeler', function ($t) { $t->string('marka', 40)->nullable(); });
        }
        if (!Schema::hasColumn('odemeler', 'kalem_ids')) {
            Schema::table('odemeler', function ($t) { $t->text('kalem_ids')->nullable(); }); // geri alınca hangi kalemler açılacak
        }
        $marka = mb_substr(trim((string) $r->marka), 0, 40) ?: null;

        // KALEM-BAZLI BÖL: seçili kalemleri öde (masada herkes kendi yediğini öder).
        $kids = array_values(array_filter(array_map('intval', explode(',', (string) $r->kalem_idler))));
        if (!empty($kids)) {
            _odemeSplitEnsure();
            $secili = DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->whereIn('id', $kids)
                ->where('durum', '!=', 'iptal')->where('odeme_durum', '!=', 'odendi')->get();
            $tutar = (float) $secili->sum('tutar');
            if ($tutar <= 0) return ['ok' => 0, 'hata' => 'Seçili kalemler zaten ödenmiş veya bulunamadı.'];
            DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => $tip, 'tutar' => $tutar, 'marka' => $marka, 'kalem_ids' => json_encode($secili->pluck('id')->all()), 'personel_id' => $p->id, 'created_at' => now()]);
            DB::table('adisyon_kalemleri')->whereIn('id', $secili->pluck('id')->all())->update(['odeme_durum' => 'odendi', 'updated_at' => now()]);
            if ($tip === 'nakit') _kasaYaz($p->sube_id, 'satis', 'giris', $tutar, 'Nakit (kalem böl) · adisyon #' . $a->id, 'adisyon', $a->id, $p->id);
            $kalan = (float) DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->where('odeme_durum', '!=', 'odendi')->sum('tutar');
            if ($kalan <= 0.009) {
                DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'odendi', 'kapanis' => now()]);
                if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
                _restoStokTuket($a->id, $p->sube_id, $p->id);
                _adisyonKapanisIsle($a->id); // CRM sadakat + mali fiş
                return ['ok' => 1, 'kapandi' => true, 'kalan' => 0, 'toplam' => (float) $a->toplam, 'mesaj' => 'Tüm kalemler ödendi, masa kapatıldı.'];
            }
            return ['ok' => 1, 'kapandi' => false, 'kalan' => $kalan, 'toplam' => (float) $a->toplam,
                'mesaj' => number_format($tutar, 0, ',', '.') . 'TL alındı · kalan ' . number_format($kalan, 0, ',', '.') . 'TL'];
        }

        $kalan = (float) $a->toplam - (float) DB::table('odemeler')->where('adisyon_id', $a->id)->sum('tutar');
        $tutar = round((float) $r->tutar, 2);
        if ($tutar <= 0) return ['ok' => 0, 'hata' => 'Geçerli bir tutar girin.'];
        if ($tutar > $kalan) $tutar = $kalan; // fazlasi alinmaz (nakit para ustu UI'da hesaplanir)
        DB::table('odemeler')->insert(['adisyon_id' => $a->id, 'tip' => $tip, 'tutar' => $tutar, 'marka' => $marka, 'personel_id' => $p->id, 'created_at' => now()]);
        if ($tip === 'nakit') _kasaYaz($p->sube_id, 'satis', 'giris', $tutar, 'Nakit (parçalı) · adisyon #' . $a->id, 'adisyon', $a->id, $p->id);
        $yeniKalan = max(0, round($kalan - $tutar, 2));
        if ($yeniKalan <= 0.009) {
            DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'odendi', 'kapanis' => now()]);
            if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
            _restoStokTuket($a->id, $p->sube_id, $p->id);
            _adisyonKapanisIsle($a->id); // CRM sadakat + mali fiş
            return ['ok' => 1, 'kapandi' => true, 'kalan' => 0, 'toplam' => (float) $a->toplam, 'mesaj' => 'Ödeme tamamlandı, masa kapatıldı.'];
        }
        return ['ok' => 1, 'kapandi' => false, 'kalan' => $yeniKalan, 'toplam' => (float) $a->toplam,
            'mesaj' => number_format($tutar, 0, ',', '.') . 'TL alındı · kalan ' . number_format($yeniKalan, 0, ',', '.') . 'TL'];
    }

    if ($islem === 'iskonto') {
        if (!$yetki('iskonto')) return ['ok' => 0, 'hata' => 'İskonto uygulama yetkiniz yok.'];
        $oran = max(0, min(100, (float) $r->oran));
        if ($oran <= 0) return ['ok' => 0, 'hata' => 'Geçerli bir iskonto oranı girin.'];
        $limit = $p->rol === 'sahip' ? 100 : (float) ($p->iskonto_limit ?? 0);
        if ($oran > $limit) {
            if (!$onaylayan) return ['ok' => 0, 'onay_gerek' => true, 'hata' => '%' . round($oran) . ' iskonto, limitinizi (%' . round($limit) . ') aşıyor. Yetkili PIN onayı gerekli.'];
            $onayLimit = $onaylayan->rol === 'sahip' ? 100 : (float) ($onaylayan->iskonto_limit ?? 0);
            if (!_restoYetkiVar($onaylayan, 'iskonto') || $onayLimit < $oran) return ['ok' => 0, 'hata' => 'Onaylayan kişinin iskonto yetkisi/limiti de yetersiz.'];
        }
        $indirim = round((float) $a->ara_toplam * $oran / 100, 2);
        $yeni = max(0, (float) $a->ara_toplam - $indirim - (float) $a->ikram);
        DB::table('adisyonlar')->where('id', $a->id)->update(['indirim' => $indirim, 'toplam' => $yeni]);
        DB::table('iptal_indirim_loglari')->insert(['sube_id' => $p->sube_id, 'adisyon_id' => $a->id, 'tip' => 'indirim',
            'tutar' => $indirim, 'sebep' => $r->sebep ?: ('%' . round($oran) . ' iskonto'), 'personel_id' => ($onaylayan->id ?? $p->id), 'created_at' => now()]);
        return ['ok' => 1, 'mesaj' => '%' . round($oran) . ' iskonto uygulandı (' . number_format($indirim, 0, ',', '.') . 'TL)' . ($onaylayan ? ' — ' . $onaylayan->ad . ' onayı ile' : '') . '.'];
    }

    if ($islem === 'ikram') {
        if (!$yetki('ikram')) return ['ok' => 0, 'hata' => 'İkram yetkiniz yok.'];
        // Ikram URUN bazlidir: adisyondaki secili kalemler ikram edilir
        $ids = array_filter(array_map('intval', explode(',', (string) $r->kalem_idler)));
        $adlar = '';
        if (!empty($ids)) {
            $secili = DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->whereIn('id', $ids)->where('durum', '!=', 'iptal')->get(['urun_adi', 'tutar']);
            $tutar = (float) $secili->sum('tutar');
            $adlar = $secili->pluck('urun_adi')->implode(', ');
        } else {
            $tutar = max(0, (float) $r->tutar); // eski/serbest tutar (geriye uyum)
        }
        if ($tutar <= 0) return ['ok' => 0, 'hata' => 'İkram için ürün seçin.'];
        if ($tutar > (float) $a->ara_toplam) $tutar = (float) $a->ara_toplam;
        // Ikram LIMITI: (1) TL limiti, (2) GÜNLÜK ADET limiti — ikisinden biri aşılırsa yönetici onayı
        $iLimit = $p->rol === 'sahip' ? 1e12 : (float) ($p->ikram_limit ?? 0);
        $gunlukLimit = _ikramGunlukLimit($p->rol);
        $bugunAdet = (int) DB::table('iptal_indirim_loglari')->where('sube_id', $p->sube_id)->where('tip', 'ikram')
            ->where('personel_id', $p->id)->whereDate('created_at', today())->count();
        $tlAsildi = $tutar > $iLimit;
        $adetAsildi = $bugunAdet >= $gunlukLimit;
        if ($tlAsildi || $adetAsildi) {
            if (!$onaylayan) {
                $neden = $adetAsildi
                    ? ('Günlük ikram hakkınız doldu (' . $bugunAdet . '/' . $gunlukLimit . ').')
                    : (number_format($tutar, 0, ',', '.') . 'TL ikram, limitinizi (' . number_format($iLimit, 0, ',', '.') . 'TL) aşıyor.');
                return ['ok' => 0, 'onay_gerek' => true, 'hata' => $neden . ' Yetkili PIN onayı gerekli.'];
            }
            $onayLimit = $onaylayan->rol === 'sahip' ? 1e12 : (float) ($onaylayan->ikram_limit ?? 0);
            if (!_restoYetkiVar($onaylayan, 'ikram') || ($tlAsildi && $onayLimit < $tutar)) return ['ok' => 0, 'hata' => 'Onaylayan kişinin ikram yetkisi/limiti de yetersiz.'];
        }
        $yeni = max(0, (float) $a->ara_toplam - (float) $a->indirim - $tutar);
        DB::table('adisyonlar')->where('id', $a->id)->update(['ikram' => $tutar, 'toplam' => $yeni]);
        // Hangi kalemler ikram edildi -> işaretle (listede belirgin gösterim)
        _ikramKalemEnsure();
        DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->update(['ikram' => 0]);
        if (!empty($ids)) DB::table('adisyon_kalemleri')->whereIn('id', $ids)->update(['ikram' => 1]);
        $sebepMetin = ($adlar ? ('İkram: ' . $adlar) : 'İkram') . (trim((string) $r->sebep) !== '' ? (' · ' . trim((string) $r->sebep)) : '');
        DB::table('iptal_indirim_loglari')->insert(['sube_id' => $p->sube_id, 'adisyon_id' => $a->id, 'tip' => 'ikram',
            'tutar' => $tutar, 'sebep' => $sebepMetin, 'personel_id' => ($onaylayan->id ?? $p->id), 'created_at' => now()]);
        return ['ok' => 1, 'mesaj' => number_format($tutar, 0, ',', '.') . 'TL ikram' . ($adlar ? ' (' . $adlar . ')' : '') . ' uygulandı' . ($onaylayan ? ' — ' . $onaylayan->ad . ' onayı ile' : '') . '.'];
    }

    if ($islem === 'iptal') {
        if (!$yetki('adisyon_iptal')) return ['ok' => 0, 'hata' => 'Adisyon iptal yetkiniz yok.'];
        if (!in_array($p->rol, ['sahip', 'mudur'])) {
            if (!$onaylayan || !in_array($onaylayan->rol, ['sahip', 'mudur'])) return ['ok' => 0, 'onay_gerek' => true, 'hata' => 'Adisyon iptali için müdür/sahip PIN onayı gerekli.'];
        }
        DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'iptal']);
        if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
        DB::table('iptal_indirim_loglari')->insert(['sube_id' => $p->sube_id, 'adisyon_id' => $a->id, 'tip' => 'void',
            'tutar' => (float) $a->toplam, 'sebep' => $r->sebep ?: 'Adisyon iptal', 'personel_id' => ($onaylayan->id ?? $p->id), 'created_at' => now()]);
        return ['ok' => 1, 'mesaj' => 'Adisyon iptal edildi, masa boşaltıldı.'];
    }

    return ['ok' => 0, 'hata' => 'Bilinmeyen işlem'];
});

// Adisyon kalemleri (kasa POS için) — id + ödeme_durum ile; kalem-bazlı böl ödeme için.
Route::get('/api/patron/adisyon-kalemleri', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _odemeSplitEnsure();
    _ikramKalemEnsure();
    $adId = (int) $r->adisyon_id;
    // İptal'leri de DAHİL et (listede üstü çizili gösterilsin) ama toplam/kalan'a sayma
    $hepsi = DB::table('adisyon_kalemleri')->where('adisyon_id', $adId)
        ->select('id', 'urun_adi', 'adet', 'tutar', 'odeme_durum', 'durum', 'ikram')->orderBy('id')->get()
        ->map(fn ($k) => ['id' => (int) $k->id, 'ad' => $k->urun_adi, 'adet' => (int) $k->adet, 'tutar' => (float) $k->tutar,
            'odeme_durum' => $k->odeme_durum ?? 'acik', 'durum' => $k->durum ?? 'gonderildi', 'ikram' => (int) ($k->ikram ?? 0)]);
    $gecerli = $hepsi->where('durum', '!=', 'iptal');
    $kalan = (float) $gecerli->where('odeme_durum', '!=', 'odendi')->sum('tutar');
    return ['ok' => 1, 'kalemler' => $hepsi->values(), 'toplam' => (float) $gecerli->sum('tutar'), 'kalan' => $kalan];
});

// Adisyonda ALINAN ödemeler (geri alma listesi için)
Route::get('/api/patron/adisyon-odemeler', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $markaVar = Schema::hasColumn('odemeler', 'marka');
    $kol = array_merge(['id', 'tip', 'tutar', 'created_at'], $markaVar ? ['marka'] : []);
    $ods = DB::table('odemeler')->where('adisyon_id', (int) $r->adisyon_id)->orderBy('id')->get($kol)
        ->map(fn ($o) => ['id' => (int) $o->id, 'tip' => $o->tip, 'tutar' => (float) $o->tutar,
            'marka' => $markaVar ? ($o->marka ?? null) : null, 'saat' => \Carbon\Carbon::parse($o->created_at)->format('H:i')]);
    return ['ok' => 1, 'odemeler' => $ods];
});

// ÖDEME GERİ AL (düzeltme) — Müdür/Sahip onayı ister; kasa/ciro/kalem geri açılır, adisyon kapandıysa yeniden açılır.
Route::post('/api/patron/odeme-geri-al', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    // HER ZAMAN Müdür/Sahip PIN onayı iste (giriş yapan yönetici bile olsa) — açık onay + kim onayladı izi.
    $onay = $r->onay_pin ? DB::table('personeller')->where('sube_id', $p->sube_id)->where('pin', (string) $r->onay_pin)->first() : null;
    if (!$onay || !in_array($onay->rol, ['sahip', 'mudur'])) {
        return ['ok' => 0, 'onay_gerek' => true, 'hata' => 'Ödeme geri alma için Müdür/Sahip PIN onayı gerekli.'];
    }
    $onaylayanId = $onay->id;
    $ode = DB::table('odemeler')->where('id', (int) $r->odeme_id)->first();
    if (!$ode) return ['ok' => 0, 'hata' => 'Ödeme bulunamadı.'];
    $a = DB::table('adisyonlar')->find($ode->adisyon_id);
    if (!$a || $a->sube_id != $p->sube_id) return ['ok' => 0, 'hata' => 'Adisyon bulunamadı.'];

    DB::table('odemeler')->where('id', $ode->id)->delete();
    // Nakit ise kasadan telafi çıkışı
    if ($ode->tip === 'nakit') _kasaYaz($p->sube_id, 'satis', 'cikis', (float) $ode->tutar, 'Ödeme geri alındı · adisyon #' . $a->id, 'adisyon', $a->id, $onaylayanId);
    // Kalem-bazlı ödemeyse o kalemleri tekrar aç
    if (Schema::hasColumn('odemeler', 'kalem_ids') && $ode->kalem_ids) {
        $kids = json_decode($ode->kalem_ids, true);
        if (is_array($kids) && $kids) DB::table('adisyon_kalemleri')->whereIn('id', $kids)->update(['odeme_durum' => 'acik', 'updated_at' => now()]);
    }
    // Adisyon kapandıysa yeniden aç
    if ($a->durum === 'odendi') {
        DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'acik', 'kapanis' => null]);
        if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'dolu']);
    }
    // Log (Hareketler'de görünür)
    if (Schema::hasTable('iptal_indirim_loglari')) {
        DB::table('iptal_indirim_loglari')->insert(['sube_id' => $p->sube_id, 'adisyon_id' => $a->id, 'tip' => 'odeme_iptal',
            'tutar' => (float) $ode->tutar, 'sebep' => 'Ödeme geri alındı (' . $ode->tip . ')', 'personel_id' => $onaylayanId, 'created_at' => now()]);
    }
    return ['ok' => 1, 'mesaj' => number_format($ode->tutar, 0, ',', '.') . 'TL ' . $ode->tip . ' ödeme geri alındı.'];
});

// ============ YÖNETİCİ ONAY SİSTEMİ (iskonto/ikram/iptal/ödeme geri al) ============
// Kasiyer riskli işlemi yapmak isteyince mesaideki yöneticiye onay isteği gider;
// yönetici KENDİ cihazından onaylar (PIN kasada girilmez, ezberlenemez). PIN yedek kalır.
if (!function_exists('_onayEnsure')) {
    function _onayEnsure()
    {
        if (Schema::hasTable('onay_istekleri')) return;
        Schema::create('onay_istekleri', function ($t) {
            $t->id();
            $t->unsignedBigInteger('sube_id');
            $t->string('tip', 30);                 // iskonto | ikram | iptal | odeme_geri_al
            $t->unsignedBigInteger('adisyon_id')->nullable();
            $t->unsignedBigInteger('ref_id')->nullable(); // odeme_id vb.
            $t->decimal('tutar', 12, 2)->nullable();
            $t->decimal('oran', 6, 2)->nullable();
            $t->text('kalem_idler')->nullable();
            $t->string('baslik', 220)->nullable();
            $t->unsignedBigInteger('isteyen_id')->nullable();
            $t->string('isteyen_ad')->nullable();
            $t->unsignedBigInteger('hedef_id')->nullable();   // onaylaması istenen yönetici
            $t->string('durum', 15)->default('bekliyor');     // bekliyor | onaylandi | reddedildi
            $t->unsignedBigInteger('onaylayan_id')->nullable();
            $t->string('onaylayan_ad')->nullable();
            $t->text('sonuc')->nullable();
            $t->timestamp('created_at')->nullable();
            $t->timestamp('updated_at')->nullable();
            $t->index(['sube_id', 'durum']);
            $t->index(['hedef_id', 'durum']);
        });
    }
}

// Onaylanan isteği SUNUCUDA yürütür (yöneticinin onayı = yetki). [ok, mesaj] döner.
if (!function_exists('_onayEylemUygula')) {
    function _onayEylemUygula($istek, $onaylayanId, $subeId)
    {
        $a = $istek->adisyon_id ? DB::table('adisyonlar')->find($istek->adisyon_id) : null;

        if ($istek->tip === 'odeme_geri_al') {
            $ode = DB::table('odemeler')->where('id', (int) $istek->ref_id)->first();
            if (!$ode) return [false, 'Ödeme bulunamadı.'];
            $a = DB::table('adisyonlar')->find($ode->adisyon_id);
            DB::table('odemeler')->where('id', $ode->id)->delete();
            if ($ode->tip === 'nakit') _kasaYaz($subeId, 'satis', 'cikis', (float) $ode->tutar, 'Ödeme geri alındı · adisyon #' . ($a->id ?? ''), 'adisyon', $a->id ?? null, $onaylayanId);
            if (Schema::hasColumn('odemeler', 'kalem_ids') && $ode->kalem_ids) {
                $kids = json_decode($ode->kalem_ids, true);
                if (is_array($kids) && $kids) DB::table('adisyon_kalemleri')->whereIn('id', $kids)->update(['odeme_durum' => 'acik', 'updated_at' => now()]);
            }
            if ($a && $a->durum === 'odendi') {
                DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'acik', 'kapanis' => null]);
                if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'dolu']);
            }
            DB::table('iptal_indirim_loglari')->insert(['sube_id' => $subeId, 'adisyon_id' => $a->id ?? null, 'tip' => 'odeme_iptal', 'tutar' => (float) $ode->tutar, 'sebep' => 'Ödeme geri alındı (' . $ode->tip . ')', 'personel_id' => $onaylayanId, 'created_at' => now()]);
            return [true, number_format($ode->tutar, 0, ',', '.') . 'TL ' . $ode->tip . ' ödeme geri alındı.'];
        }

        if (!$a || $a->durum !== 'acik') return [false, 'Adisyon uygun durumda değil.'];

        if ($istek->tip === 'iskonto') {
            $oran = max(0, min(100, (float) $istek->oran));
            $indirim = round((float) $a->ara_toplam * $oran / 100, 2);
            $yeni = max(0, (float) $a->ara_toplam - $indirim - (float) $a->ikram);
            DB::table('adisyonlar')->where('id', $a->id)->update(['indirim' => $indirim, 'toplam' => $yeni]);
            DB::table('iptal_indirim_loglari')->insert(['sube_id' => $subeId, 'adisyon_id' => $a->id, 'tip' => 'indirim', 'tutar' => $indirim, 'sebep' => '%' . round($oran) . ' iskonto (yönetici onayı)', 'personel_id' => $onaylayanId, 'created_at' => now()]);
            return [true, '%' . round($oran) . ' iskonto uygulandı (' . number_format($indirim, 0, ',', '.') . 'TL).'];
        }

        if ($istek->tip === 'ikram') {
            $ids = array_values(array_filter(array_map('intval', explode(',', (string) $istek->kalem_idler))));
            $adlar = '';
            if (!empty($ids)) {
                $secili = DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->whereIn('id', $ids)->where('durum', '!=', 'iptal')->get(['urun_adi', 'tutar']);
                $tutar = (float) $secili->sum('tutar');
                $adlar = $secili->pluck('urun_adi')->implode(', ');
            } else {
                $tutar = max(0, (float) $istek->tutar);
            }
            if ($tutar <= 0) return [false, 'İkram tutarı geçersiz.'];
            if ($tutar > (float) $a->ara_toplam) $tutar = (float) $a->ara_toplam;
            $yeni = max(0, (float) $a->ara_toplam - (float) $a->indirim - $tutar);
            DB::table('adisyonlar')->where('id', $a->id)->update(['ikram' => $tutar, 'toplam' => $yeni]);
            _ikramKalemEnsure();
            DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->update(['ikram' => 0]);
            if (!empty($ids)) DB::table('adisyon_kalemleri')->whereIn('id', $ids)->update(['ikram' => 1]);
            $aciklama = trim((string) ($istek->aciklama ?? ''));
            $sebepMetin = ($adlar ? ('İkram: ' . $adlar) : 'İkram') . ($aciklama !== '' ? (' · ' . $aciklama) : '') . ' (yönetici onayı)';
            DB::table('iptal_indirim_loglari')->insert(['sube_id' => $subeId, 'adisyon_id' => $a->id, 'tip' => 'ikram', 'tutar' => $tutar,
                'sebep' => $sebepMetin, 'personel_id' => $onaylayanId, 'created_at' => now()]);
            return [true, number_format($tutar, 0, ',', '.') . 'TL ikram' . ($adlar ? ' (' . $adlar . ')' : '') . ' uygulandı.'];
        }

        if ($istek->tip === 'iptal') {
            DB::table('adisyonlar')->where('id', $a->id)->update(['durum' => 'iptal']);
            if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'bos']);
            DB::table('iptal_indirim_loglari')->insert(['sube_id' => $subeId, 'adisyon_id' => $a->id, 'tip' => 'void', 'tutar' => (float) $a->toplam, 'sebep' => 'Adisyon iptal (yönetici onayı)', 'personel_id' => $onaylayanId, 'created_at' => now()]);
            return [true, 'Adisyon iptal edildi, masa boşaltıldı.'];
        }

        return [false, 'Bilinmeyen işlem.'];
    }
}

// O an MESAİDEKİ yöneticiler (onay isteği göndermek için). Yoksa tüm yöneticiler (yedek).
Route::get('/api/patron/mesaideki-yoneticiler', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $mesaide = collect();
    if (Schema::hasTable('personel_mesai')) {
        $mesaide = DB::table('personeller as pe')->join('personel_mesai as m', 'm.personel_id', '=', 'pe.id')
            ->where('pe.sube_id', $p->sube_id)->whereIn('pe.rol', ['sahip', 'mudur'])->where('m.durum', 'acik')
            ->where('pe.id', '!=', $p->id) // kendini seçemez (kendi işlemini onaylayamaz)
            ->select('pe.id', 'pe.ad', 'pe.rol')->distinct()->get();
    }
    $yedek = false;
    if ($mesaide->isEmpty()) {
        $mesaide = DB::table('personeller')->where('sube_id', $p->sube_id)->whereIn('rol', ['sahip', 'mudur'])
            ->where('id', '!=', $p->id)->get(['id', 'ad', 'rol']);
        $yedek = true;
    }
    return ['ok' => 1, 'yedek' => $yedek, 'yoneticiler' => $mesaide->map(fn ($y) => ['id' => (int) $y->id, 'ad' => $y->ad, 'rol' => $y->rol])->values()];
});

// Onay isteği oluştur (kasiyer) — yöneticiye düşer.
// Onay tablosuna sonradan eklenen kolonlar (sebep + isteyene bildirildi mi)
if (!function_exists('_onayKolonEnsure')) {
    function _onayKolonEnsure()
    {
        try {
            if (!Schema::hasColumn('onay_istekleri', 'aciklama')) Schema::table('onay_istekleri', fn ($t) => $t->string('aciklama', 240)->nullable());
            if (!Schema::hasColumn('onay_istekleri', 'bildirildi')) Schema::table('onay_istekleri', fn ($t) => $t->tinyInteger('bildirildi')->default(0));
        } catch (\Throwable $e) {}
    }
}
Route::post('/api/patron/onay-iste', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _onayEnsure();
    _onayKolonEnsure();
    $tip = in_array($r->tip, ['iskonto', 'ikram', 'iptal', 'odeme_geri_al']) ? $r->tip : null;
    if (!$tip) return ['ok' => 0, 'hata' => 'Geçersiz işlem tipi.'];
    $id = DB::table('onay_istekleri')->insertGetId([
        'sube_id' => $p->sube_id, 'tip' => $tip,
        'adisyon_id' => $r->adisyon_id ? (int) $r->adisyon_id : null,
        'ref_id' => $r->ref_id ? (int) $r->ref_id : null,
        'tutar' => $r->tutar !== null ? (float) $r->tutar : null,
        'oran' => $r->oran !== null ? (float) $r->oran : null,
        'kalem_idler' => $r->kalem_idler ?: null,
        'baslik' => mb_substr((string) $r->baslik, 0, 220),
        'aciklama' => $r->filled('aciklama') ? mb_substr((string) $r->aciklama, 0, 240) : null,
        'isteyen_id' => $p->id, 'isteyen_ad' => $p->ad,
        'hedef_id' => $r->hedef_id ? (int) $r->hedef_id : null,
        'durum' => 'bekliyor', 'bildirildi' => 0, 'created_at' => now(), 'updated_at' => now(),
    ]);
    return ['ok' => 1, 'istek_id' => $id];
});

// İSTEYEN (garson) kendi biten taleplerini yoklar -> onaylandı/reddedildi bildirimi (bir kez)
Route::get('/api/patron/onay-benim-sonuc', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _onayEnsure();
    _onayKolonEnsure();
    $liste = DB::table('onay_istekleri')->where('isteyen_id', $p->id)
        ->whereIn('durum', ['onaylandi', 'reddedildi'])->where('bildirildi', 0)
        ->orderBy('id')->limit(8)->get(['id', 'tip', 'baslik', 'durum', 'onaylayan_ad', 'sonuc']);
    if ($liste->count()) {
        DB::table('onay_istekleri')->whereIn('id', $liste->pluck('id')->all())->update(['bildirildi' => 1]);
    }
    return ['ok' => 1, 'sonuclar' => $liste->map(fn ($i) => [
        'id' => (int) $i->id, 'tip' => $i->tip, 'baslik' => $i->baslik, 'durum' => $i->durum,
        'onaylayan' => $i->onaylayan_ad, 'sonuc' => $i->sonuc,
    ])->values()];
});

// Onay durumu (kasiyer yoklar).
Route::get('/api/patron/onay-durum', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _onayEnsure();
    $i = DB::table('onay_istekleri')->where('id', (int) $r->id)->where('sube_id', $p->sube_id)->first();
