// Bekleyen onaylar (yönetici yoklar — kendisine düşenler).
Route::get('/api/patron/bekleyen-onaylar', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return ['ok' => 1, 'onaylar' => []];
    _onayEnsure();
    // Son 10 dk içindeki, bana ya da genel hedeflenen bekleyenler
    // KENDİ isteği hariç TÜM yöneticiler görebilir (hedef tutmazsa takılmasın; ilk onaylayan geçerli).
    $liste = DB::table('onay_istekleri')->where('sube_id', $p->sube_id)->where('durum', 'bekliyor')
        ->where('created_at', '>=', now()->subMinutes(10))
        ->where('isteyen_id', '!=', $p->id)
        ->orderByDesc('id')->get();
    return ['ok' => 1, 'onaylar' => $liste->map(fn ($i) => [
        'id' => (int) $i->id, 'tip' => $i->tip, 'baslik' => $i->baslik, 'tutar' => $i->tutar !== null ? (float) $i->tutar : null,
        'isteyen' => $i->isteyen_ad, 'saat' => \Carbon\Carbon::parse($i->created_at)->format('H:i'),
    ])->values()];
});

// Onay cevabı (yönetici onaylar/reddeder) — onaylandıysa eylemi SUNUCUDA yürütür.
Route::post('/api/patron/onay-cevap', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p || !in_array($p->rol, ['sahip', 'mudur'])) return ['ok' => 0, 'hata' => 'Yetkisiz'];
    _onayEnsure();
    $i = DB::table('onay_istekleri')->where('id', (int) $r->istek_id)->where('sube_id', $p->sube_id)->first();
    if (!$i) return ['ok' => 0, 'hata' => 'İstek bulunamadı.'];
    if ($i->durum !== 'bekliyor') return ['ok' => 0, 'hata' => 'Bu istek zaten yanıtlandı.'];
    if ((int) $i->isteyen_id === (int) $p->id) return ['ok' => 0, 'hata' => 'Kendi isteğinizi onaylayamazsınız.'];
    if ($r->cevap === 'red') {
        DB::table('onay_istekleri')->where('id', $i->id)->update(['durum' => 'reddedildi', 'onaylayan_id' => $p->id, 'onaylayan_ad' => $p->ad, 'updated_at' => now()]);
        return ['ok' => 1, 'durum' => 'reddedildi'];
    }
    [$ok, $mesaj] = _onayEylemUygula($i, $p->id, $p->sube_id);
    DB::table('onay_istekleri')->where('id', $i->id)->update([
        'durum' => $ok ? 'onaylandi' : 'reddedildi', 'onaylayan_id' => $p->id, 'onaylayan_ad' => $p->ad,
        'sonuc' => $mesaj, 'updated_at' => now(),
    ]);
    return ['ok' => 1, 'durum' => $ok ? 'onaylandi' : 'reddedildi', 'mesaj' => $mesaj];
});

// MASA AC: bos masaya yeni (bos) adisyon acar. Yetki: adisyon_ac (sahip hep).
Route::post('/api/patron/masa-ac', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if (!_restoYetkiVar($p, 'adisyon_ac')) return ['ok' => 0, 'hata' => 'Masa / adisyon açma yetkiniz yok.'];
    $masa = DB::table('masalar')->where('id', (int) $r->masa_id)->where('sube_id', $p->sube_id)->first();
    if (!$masa) return ['ok' => 0, 'hata' => 'Masa bulunamadı'];
    // Zaten acik adisyon varsa onu don (cift acilma olmasin)
    $mevcut = DB::table('adisyonlar')->where('masa_id', $masa->id)->where('durum', 'acik')->value('id');
    if ($mevcut) return ['ok' => 1, 'adisyon_id' => $mevcut, 'mesaj' => $masa->ad . ' zaten açık.'];
    $misafir = max(1, (int) $r->misafir);
    $id = DB::table('adisyonlar')->insertGetId([
        'sube_id' => $p->sube_id, 'masa_id' => $masa->id, 'kanal' => 'salon',
        'misafir_sayisi' => $misafir, 'durum' => 'acik', 'acan_personel_id' => $p->id,
        'ara_toplam' => 0, 'indirim' => 0, 'ikram' => 0, 'toplam' => 0,
        'acilis' => now(), 'created_at' => now(), 'updated_at' => now(),
    ]);
    DB::table('masalar')->where('id', $masa->id)->update(['durum' => 'dolu']);
    return ['ok' => 1, 'adisyon_id' => $id, 'mesaj' => $masa->ad . ' açıldı (' . $misafir . ' kişi).'];
});

// MENU: siparis girisi icin kategori + urun listesi
Route::get('/api/menu', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $kategoriler = DB::table('menu_kategorileri')->where('sube_id', $p->sube_id)->orderBy('sira')->orderBy('ad')->get(['id', 'ad'])
        ->map(fn ($k) => ['id' => (int) $k->id, 'ad' => $k->ad]);
    // Kategori adi haritasi + emoji ureticisi (QR menu ile AYNI) -> foto yoksa kasada emoji kutusu
    $katAdMap = DB::table('menu_kategorileri')->where('sube_id', $p->sube_id)->pluck('ad', 'id');
    $ma = new \App\Services\MusteriAsistan($p->sube_id);
    $istVar = Schema::hasColumn('urunler', 'istasyon');
    $kolonlar = ['id', 'ad', 'fiyat', 'kategori_id', 'tukendi', 'gorsel', 'updated_at'];
    if ($istVar) $kolonlar[] = 'istasyon';
    $urunler = DB::table('urunler')->where('sube_id', $p->sube_id)->where('aktif', 1)->orderBy('ad')
        ->get($kolonlar)
        ->map(fn ($u) => ['id' => (int) $u->id, 'ad' => $u->ad, 'fiyat' => (float) $u->fiyat,
            'kategori_id' => $u->kategori_id ? (int) $u->kategori_id : 0, 'tukendi' => (bool) $u->tukendi,
            'istasyon' => $istVar ? ($u->istasyon ?: 'mutfak') : 'mutfak', // bar/izgara/firin/soguk/tatli/mutfak
            'emoji' => $ma->katEmoji((string) ($katAdMap[$u->kategori_id] ?? ''), (string) $u->ad),
            'gorsel' => $u->gorsel ? ($u->gorsel . '?v=' . ($u->updated_at ? strtotime($u->updated_at) : 0)) : null]);
    return ['ok' => 1, 'kategoriler' => $kategoriler, 'urunler' => $urunler];
});

