// Urun fotografi yukle (uygulamadan)
Route::post('/api/patron/urun-foto', function (Request $r) {
    $p = _apiPersonel($r);
    if (!_restoMenuYetki($p)) return response()->json(['ok' => 0, 'hata' => 'Yetkiniz yok'], $p ? 403 : 401);
    $id = (int) $r->input('urun_id');
    if (!DB::table('urunler')->where('id', $id)->where('sube_id', $p->sube_id)->exists()) return response()->json(['ok' => 0, 'hata' => 'Ürün bulunamadı'], 404);
    if (!$r->hasFile('foto') || !$r->file('foto')->isValid()) return response()->json(['ok' => 0, 'hata' => 'Geçerli dosya yok'], 422);
    $f = $r->file('foto');
    $ext = strtolower($f->getClientOriginalExtension() ?: 'jpg');
    if (!in_array($ext, ['jpg', 'jpeg', 'png', 'webp'])) return response()->json(['ok' => 0, 'hata' => 'JPG, PNG veya WEBP'], 422);
    if ($f->getSize() > 8 * 1024 * 1024) return response()->json(['ok' => 0, 'hata' => 'En fazla 8 MB'], 422);
    $dir = storage_path('app/urun_foto');
    if (!is_dir($dir)) @mkdir($dir, 0775, true);
    foreach (glob($dir . '/' . $id . '.*') ?: [] as $old) @unlink($old);
    $f->move($dir, $id . '.' . $ext);
    $url = url('/urun-foto/' . $id);
    DB::table('urunler')->where('id', $id)->update(['gorsel' => $url, 'updated_at' => now()]);
    return ['ok' => 1, 'url' => $url . '?v=' . time()];
});

// ADISYONA URUN EKLE (siparis al). kalemler = JSON [{urun_id,adet}]. Yetki: adisyon_ac.
Route::post('/api/patron/adisyon-urun-ekle', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    if (!_restoYetkiVar($p, 'adisyon_ac')) return ['ok' => 0, 'hata' => 'Sipariş ekleme yetkiniz yok.'];
    $a = DB::table('adisyonlar')->find((int) $r->adisyon_id);
    if (!$a) return ['ok' => 0, 'hata' => 'Adisyon bulunamadı'];
    if ($a->durum !== 'acik') return ['ok' => 0, 'hata' => 'Bu adisyon açık değil.'];
    $kalemler = json_decode((string) $r->kalemler, true);
    if (!is_array($kalemler) || empty($kalemler)) return ['ok' => 0, 'hata' => 'Ürün seçilmedi'];
    $eklenen = 0;
    $tukendiAtlanan = [];
    foreach ($kalemler as $k) {
        $uid = (int) ($k['urun_id'] ?? 0);
        $adet = max(1, (int) ($k['adet'] ?? 1));
        $u = DB::table('urunler')->where('id', $uid)->where('sube_id', $p->sube_id)->first();
        if (!$u) continue;
        if ($u->tukendi) { $tukendiAtlanan[] = $u->ad; continue; } // 86: tukenen urun siparise eklenmez
        DB::table('adisyon_kalemleri')->insert([
            'adisyon_id' => $a->id, 'urun_id' => $u->id, 'urun_adi' => $u->ad,
            'adet' => $adet, 'birim_fiyat' => (float) $u->fiyat, 'tutar' => (float) $u->fiyat * $adet,
            'durum' => 'gonderildi', 'personel_id' => $p->id, 'gonderim_zamani' => now(),
            'created_at' => now(), 'updated_at' => now(),
        ]);
        $eklenen++;
    }
    if ($eklenen === 0) {
        $msg = $tukendiAtlanan ? ('Tükendi (86): ' . implode(', ', $tukendiAtlanan) . ' — eklenemedi.') : 'Geçerli ürün eklenemedi';
        return ['ok' => 0, 'hata' => $msg];
    }
    $araToplam = (float) DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->sum('tutar');
    $toplam = max(0, $araToplam - (float) $a->indirim - (float) $a->ikram);
    DB::table('adisyonlar')->where('id', $a->id)->update(['ara_toplam' => $araToplam, 'toplam' => $toplam, 'updated_at' => now()]);
    if ($a->masa_id) DB::table('masalar')->where('id', $a->masa_id)->update(['durum' => 'dolu']);
    $mesaj = $eklenen . ' kalem eklendi.';
    if ($tukendiAtlanan) $mesaj .= ' (Tükendi, atlandı: ' . implode(', ', $tukendiAtlanan) . ')';
    return ['ok' => 1, 'mesaj' => $mesaj, 'ara_toplam' => $araToplam, 'toplam' => $toplam, 'tukendi_atlanan' => $tukendiAtlanan];
});

// KALEM VOID (urun sil): yetki urun_sil; yoksa mudur/sahip onay_pin. Loglar + toplam gunceller.
Route::post('/api/patron/kalem-void', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    $a = DB::table('adisyonlar')->find((int) $r->adisyon_id);
    if (!$a) return ['ok' => 0, 'hata' => 'Adisyon bulunamadı'];
    if ($a->durum !== 'acik') return ['ok' => 0, 'hata' => 'Bu adisyon açık değil.'];
    $kalem = DB::table('adisyon_kalemleri')->where('id', (int) $r->kalem_id)->where('adisyon_id', $a->id)->first();
    if (!$kalem || $kalem->durum === 'iptal') return ['ok' => 0, 'hata' => 'Kalem bulunamadı'];
    $onaylayan = null;
    if (!_restoYetkiVar($p, 'urun_sil')) {
        if ($r->onay_pin) $onaylayan = DB::table('personeller')->where('sube_id', $p->sube_id)->where('pin', (string) $r->onay_pin)->first();
        if (!$onaylayan || !_restoYetkiVar($onaylayan, 'urun_sil')) {
            return ['ok' => 0, 'onay_gerek' => true, 'hata' => 'Ürün silme yetkiniz yok. Yetkili (müdür/sahip) PIN onayı gerekli.'];
        }
    }
    DB::table('adisyon_kalemleri')->where('id', $kalem->id)->update(['durum' => 'iptal', 'updated_at' => now()]);
    DB::table('iptal_indirim_loglari')->insert(['sube_id' => $p->sube_id, 'adisyon_id' => $a->id, 'adisyon_kalem_id' => $kalem->id,
        'tip' => 'void', 'tutar' => (float) $kalem->tutar, 'sebep' => $r->sebep ?: 'Ürün silindi', 'personel_id' => ($onaylayan->id ?? $p->id), 'created_at' => now()]);
    // VOID edilen kalem HAZIRLANMAYA BAŞLANMIŞSA (fiziksel üretim başladı) -> hammaddeyi FIRE olarak düş.
    // 'gonderildi' (mutfağa düştü ama aşçı "Başla" demedi) = henüz üretilmedi -> FİRE YOK (haksız maliyet olmasın).
    // basla_zamani dolu VEYA durum hazırlanıyor/hazır/servis ise üretim başlamış sayılır.
    $uretildi = in_array($kalem->durum, ['hazirlaniyor', 'hazir', 'servis'], true) || !empty($kalem->basla_zamani ?? null);
    try {
        if ($uretildi && $kalem->urun_id) {
            $recete = DB::table('receteler')->where('tip', 'urun')->where('urun_id', $kalem->urun_id)->first(['id']);
            if ($recete) {
                $ihtiyac = [];
                _restoReceteHammadde($recete->id, (float) $kalem->adet, $ihtiyac);
                foreach ($ihtiyac as $malzemeId => $temelMiktar) {
                    if ($temelMiktar <= 0) continue;
                    $m = DB::table('malzemeler')->where('id', $malzemeId)->first(['guncel_maliyet']);
                    DB::table('stok_hareketleri')->insert([
                        'sube_id' => $p->sube_id, 'malzeme_id' => (int) $malzemeId, 'tip' => 'fire', 'miktar' => -$temelMiktar,
                        'birim_maliyet' => $m ? (float) $m->guncel_maliyet : 0, 'kaynak_tip' => 'void', 'kaynak_id' => $kalem->id,
                        'aciklama' => 'Void/fire: ' . $kalem->urun_adi, 'personel_id' => ($onaylayan->id ?? $p->id),
                    ]);
                }
            }
        }
    } catch (\Throwable $e) {
    }
    $araToplam = (float) DB::table('adisyon_kalemleri')->where('adisyon_id', $a->id)->where('durum', '!=', 'iptal')->sum('tutar');
    $toplam = max(0, $araToplam - (float) $a->indirim - (float) $a->ikram);
    DB::table('adisyonlar')->where('id', $a->id)->update(['ara_toplam' => $araToplam, 'toplam' => $toplam, 'updated_at' => now()]);
    return ['ok' => 1, 'mesaj' => $kalem->urun_adi . ' silindi.' . ($onaylayan ? ' — ' . $onaylayan->ad . ' onayı ile' : ''), 'toplam' => $toplam];
});

// Istasyon kod->etiket. Filtre parametresi bu kodlarla gelir.
if (!function_exists('_mutfakIstasyonlar')) {
    function _mutfakIstasyonlar(): array
    {
        return ['izgara' => '🔥 Izgara', 'firin' => '🍕 Fırın', 'mutfak' => '🍳 Sıcak', 'soguk' => '🥗 Soğuk', 'tatli' => '🍰 Tatlı', 'bar' => '🍹 Bar'];
    }
}

// MUTFAK (KDS): bekleyen siparis kalemleri (durum=gonderildi) adisyona gruplu.
// + istasyon (urunden), + kur, + all-day toplu uretim, + istasyon dagilimi. ?istasyon=izgara ile filtre.
// KDS yasam dongusu kolonlari: urun hedef hazirlik suresi + kalem 'basla' zamani
if (!function_exists('_kdsKolonEnsure')) {
    function _kdsKolonEnsure()
    {
        if (cache()->get('kds_kolon_ok')) return; // sıcak KDS poll'ünde her saniye introspection yapma
        try {
            if (!Schema::hasColumn('urunler', 'hazirlik_dk')) Schema::table('urunler', function ($t) { $t->integer('hazirlik_dk')->default(0); });
            if (!Schema::hasColumn('adisyon_kalemleri', 'basla_zamani')) Schema::table('adisyon_kalemleri', function ($t) { $t->timestamp('basla_zamani')->nullable(); });
            cache()->put('kds_kolon_ok', 1, now()->addHours(12));
        } catch (\Throwable $e) {
        }
    }
    // Kalan sureye gore renk: bol->yesil, yaklasti->amber, gecti->kirmizi
    function _kdsRenk($kalan, $hedef)
    {
        if ($kalan > $hedef * 0.4) return 'yesil';
        if ($kalan > 0) return 'amber';
        return 'kirmizi';
    }
}
if (!function_exists('_mutfakVeri')) {
function _mutfakVeri($subeId, $filtre = null) {
    $p = (object) ['sube_id' => $subeId]; // helper: asagidaki $p->sube_id aynen calissin
    _kdsKolonEnsure();
    $simdi = now();
    $vars = 15;   // varsayilan hedef hazirlik (dk) — urune ozel girilmemisse
    $istasyonVar = cache()->remember('kds_urun_istasyon', 3600, fn () => Schema::hasColumn('urunler', 'istasyon'));
    $hzVar = cache()->remember('kds_urun_hazirlikdk', 3600, fn () => Schema::hasColumn('urunler', 'hazirlik_dk'));
    $q = DB::table('adisyon_kalemleri')->join('adisyonlar', 'adisyon_kalemleri.adisyon_id', '=', 'adisyonlar.id')
        ->leftJoin('masalar', 'adisyonlar.masa_id', '=', 'masalar.id')
        ->leftJoin('urunler', 'adisyon_kalemleri.urun_id', '=', 'urunler.id')
        ->where('adisyonlar.sube_id', $p->sube_id)->where('adisyonlar.durum', 'acik')
        ->whereIn('adisyon_kalemleri.durum', ['gonderildi', 'hazirlaniyor']);   // Yeni + Hazirlaniyor
    $sel = ['adisyon_kalemleri.id', 'adisyon_kalemleri.urun_adi', 'adisyon_kalemleri.adet', 'adisyon_kalemleri.not',
        'adisyon_kalemleri.kur', 'adisyon_kalemleri.gonderim_zamani', 'adisyon_kalemleri.durum', 'adisyon_kalemleri.basla_zamani',
        'adisyonlar.id as adisyon_id', 'masalar.ad as masa', 'adisyonlar.kanal'];
    $sel[] = $istasyonVar ? DB::raw("COALESCE(urunler.istasyon,'mutfak') as istasyon") : DB::raw("'mutfak' as istasyon");
    $sel[] = $hzVar ? DB::raw("COALESCE(NULLIF(urunler.hazirlik_dk,0),$vars) as hedef") : DB::raw("$vars as hedef");
    // Ikincil 'id' sirasi -> ayni gonderim_zamani'ndaki kalemler her yenilemede AYNI sirada (yer degistirmez)
    $rows = $q->select($sel)->orderBy('adisyon_kalemleri.gonderim_zamani')->orderBy('adisyon_kalemleri.id')->get();

    $etiket = _mutfakIstasyonlar();
    $gruplu = [];
    $istSay = [];
    $toplu = [];
    foreach ($rows as $k) {
        $ist = $k->istasyon ?: 'mutfak';
        $dkK = $k->gonderim_zamani ? (int) \Carbon\Carbon::parse($k->gonderim_zamani)->diffInMinutes($simdi) : 0;
        $hzG = $k->basla_zamani ? (int) \Carbon\Carbon::parse($k->basla_zamani)->diffInMinutes($simdi) : 0; // BASLADIKTAN beri gecen dk
        $hedef = max(1, (int) $k->hedef);
        $kalan = $hedef - $dkK;
        $adet = (float) $k->adet;
        $tkey = $ist . '|' . $k->urun_adi;
        if (!isset($toplu[$tkey])) $toplu[$tkey] = ['ad' => $k->urun_adi, 'istasyon' => $ist, 'adet' => 0.0, 'dk' => $dkK];
        $toplu[$tkey]['adet'] += $adet;
        $toplu[$tkey]['dk'] = max($toplu[$tkey]['dk'], $dkK);
        $istSay[$ist] = ($istSay[$ist] ?? 0) + $adet;
        if ($filtre && $filtre !== 'hepsi' && $ist !== $filtre) continue;
        $aid = $k->adisyon_id;
        if (!isset($gruplu[$aid])) {
            $gruplu[$aid] = ['adisyon_id' => $aid, 'masa' => $k->masa ?? ucfirst((string) $k->kanal), 'kanal' => (string) $k->kanal,
                'masali' => ($k->masa !== null),   // gercek masa mi, yoksa paket/gel-al/online mi
                'gecen' => $dkK, 'hedef' => $hedef, 'kalan' => $kalan, 'hazirlik_gecen' => 0, 'basladi' => false, 'kalemler' => []];
        }
        $gruplu[$aid]['gecen'] = max($gruplu[$aid]['gecen'], $dkK);
        $gruplu[$aid]['hedef'] = max($gruplu[$aid]['hedef'], $hedef);
        $gruplu[$aid]['kalan'] = min($gruplu[$aid]['kalan'], $kalan);   // en yavas kalem = en kritik
        $gruplu[$aid]['hazirlik_gecen'] = max($gruplu[$aid]['hazirlik_gecen'], $hzG);
        if ($k->durum === 'hazirlaniyor') $gruplu[$aid]['basladi'] = true;
        $gruplu[$aid]['kalemler'][] = ['id' => $k->id, 'ad' => $k->urun_adi, 'adet' => $adet, 'not' => $k->not, 'kur' => $k->kur, 'istasyon' => $ist, 'durum' => $k->durum,
            'gz' => $k->gonderim_zamani ? \Carbon\Carbon::parse($k->gonderim_zamani)->format('Y-m-d H:i') : null];
    }
    foreach ($gruplu as $aid => $g) {
        $gruplu[$aid]['dk'] = $g['gecen'];                        // geriye donuk uyum
        $gruplu[$aid]['renk'] = _kdsRenk($g['kalan'], $g['hedef']);
        $gruplu[$aid]['asama'] = $g['basladi'] ? 'hazirlaniyor' : 'yeni';
        // Basladiktan SONRA hazirlik hedefini de astiysa -> KRITIK (frontend: tam kirmizi yanip soner)
        $gruplu[$aid]['hazirlik_asti'] = $g['basladi'] && (($g['hazirlik_gecen'] ?? 0) >= $g['hedef']);
    }
    // ===== TUR (coursing): her adisyonun kacinci gonderim turu oldugunu belirle (HAZIR olanlar DAHIL) =====
    // Boylece 1. tur servis olup gitse bile sonraki fis "2. Tur" der; ayni kartta turlar ayracla gorunur.
    $aidler = array_keys($gruplu);
    if ($aidler) {
        $turRows = DB::table('adisyon_kalemleri')->whereIn('adisyon_id', $aidler)->whereNotNull('gonderim_zamani')
            ->select('adisyon_id', DB::raw("DATE_FORMAT(gonderim_zamani,'%Y-%m-%d %H:%i') as gz"))->distinct()->get();
        $byAid = [];
        foreach ($turRows as $tr) $byAid[$tr->adisyon_id][$tr->gz] = true;
        $turMap = [];
        foreach ($byAid as $aid => $gzSet) {
            $gzler = array_keys($gzSet);
            sort($gzler); // kronolojik -> 1. tur en eski
            foreach ($gzler as $i => $gz) $turMap[$aid][$gz] = $i + 1;
        }
        foreach ($gruplu as $aid => &$g) {
            $g['tur_sayisi'] = isset($turMap[$aid]) ? count($turMap[$aid]) : 1;
            $minTur = null;
            foreach ($g['kalemler'] as &$k) {
                $k['tur'] = ($k['gz'] !== null && isset($turMap[$aid][$k['gz']])) ? $turMap[$aid][$k['gz']] : 1;
                $minTur = $minTur === null ? $k['tur'] : min($minTur, $k['tur']);
            }
            unset($k);
            $g['min_tur'] = $minTur ?? 1; // karttaki en dusuk tur (>1 ise bu fis bir "ek tur" = follow-up)
        }
        unset($g);
    }
    $istasyonlar = [];
    foreach ($etiket as $kod => $ad) {
        if (($istSay[$kod] ?? 0) > 0) $istasyonlar[] = ['kod' => $kod, 'ad' => $ad, 'bekleyen' => (int) round($istSay[$kod])];
    }
    $topluArr = array_values($toplu);
    // Istasyon filtresi TOPLU listeye de uygulansin (secili cip -> sadece o istasyon urunleri)
    if ($filtre && $filtre !== 'hepsi') {
        $topluArr = array_values(array_filter($topluArr, fn ($t) => $t['istasyon'] === $filtre));
    }
    usort($topluArr, fn ($a, $b) => $b['dk'] <=> $a['dk']);
    foreach ($topluArr as &$t) { $t['dk'] = (int) $t['dk']; $t['istasyon_ad'] = $etiket[$t['istasyon']] ?? $t['istasyon']; }
    unset($t);
    $siparisler = array_values($gruplu);
    // EN ESKI (en cok bekleyen) EN SOLDA; yeni gelenler saga eklenir. Esit sureliler icin
    // adisyon_id tiebreaker -> PHP 7.4 kararsiz usort'ta sira her yenilemede OYNAMASIN (sabit).
    usort($siparisler, fn ($a, $b) => ($b['dk'] <=> $a['dk']) ?: ($a['adisyon_id'] <=> $b['adisyon_id']));
    return ['ok' => 1, 'siparisler' => $siparisler, 'istasyonlar' => $istasyonlar,
        'toplu' => $topluArr, 'toplam_bekleyen' => (int) round(array_sum($istSay))];
}
}
Route::get('/api/mutfak', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    return _mutfakVeri($p->sube_id, $r->query('istasyon'));
});
