// Rezervasyon musterisini telefondan coz (CRM): bul, yoksa olustur; alerji/not musteriye yaz. musteri_id doner.
if (!function_exists('_rezMusteriCozumle')) {
    function _rezMusteriCozumle($subeId, $ad, $tel, $not = '')
    {
        $tel = trim((string) $tel);
        if ($tel === '') return null;
        if (!Schema::hasColumn('musteriler', 'telefon_norm')) {
            Schema::table('musteriler', fn ($t) => $t->string('telefon_norm', 12)->nullable()->index());
        }
        $norm = _telNorm($tel);
        $m = $norm ? DB::table('musteriler')->where('sube_id', $subeId)->where('telefon_norm', $norm)->first() : null;
        if (!$m) $m = DB::table('musteriler')->where('sube_id', $subeId)->where('telefon', $tel)->first();
        if ($m) {
            $upd = [];
            if ((trim((string) $m->ad) === '') && $ad !== '') $upd['ad'] = $ad;
            if (trim((string) $not) !== '') $upd['notlar'] = mb_substr($not, 0, 240); // alerji/tercih
            if ($upd) { $upd['updated_at'] = now(); DB::table('musteriler')->where('id', $m->id)->update($upd); }
            return (int) $m->id;
        }
        return (int) DB::table('musteriler')->insertGetId([
            'sube_id' => $subeId, 'ad' => $ad ?: 'Misafir', 'telefon' => $tel, 'telefon_norm' => $norm,
            'notlar' => trim((string) $not) !== '' ? mb_substr($not, 0, 240) : null,
            'created_at' => now(), 'updated_at' => now(),
        ]);
    }
}

// Ozel istek etiketlerini temizle (dizi veya CSV -> guvenli CSV)
if (!function_exists('_rezEtiketTemizle')) {
    function _rezEtiketTemizle($raw)
    {
        if (is_string($raw)) $raw = explode(',', $raw);
        if (!is_array($raw)) return '';
        $temiz = [];
        foreach ($raw as $e) {
            $e = trim(mb_substr((string) $e, 0, 30));
            if ($e !== '') $temiz[] = $e;
        }
        return implode(',', array_slice(array_values(array_unique($temiz)), 0, 12));
    }
}

// On siparis kalemlerini kaydet (JSON/dizi: [{urun_id, adet, not}]) -> eklenen adet
if (!function_exists('_rezKalemKaydet')) {
    function _rezKalemKaydet($subeId, $rezId, $raw)
    {
        if (is_string($raw)) $raw = json_decode($raw, true);
        if (!is_array($raw)) return 0;
        $n = 0;
        foreach ($raw as $k) {
            if (!is_array($k)) continue;
            $uid = (int) ($k['urun_id'] ?? 0);
            $adet = max(1, min(99, (int) ($k['adet'] ?? 1)));
            if ($uid <= 0) continue;
            $u = DB::table('urunler')->where('id', $uid)->where('sube_id', $subeId)->first(['id', 'ad', 'fiyat']);
            if (!$u) continue;
            DB::table('rezervasyon_kalemleri')->insert([
                'rezervasyon_id' => $rezId, 'urun_id' => $u->id, 'urun_adi' => $u->ad,
                'adet' => $adet, 'fiyat' => (float) $u->fiyat, 'not' => trim((string) ($k['not'] ?? '')) ?: null,
            ]);
            $n++;
        }
        return $n;
    }
}

// PATRON API: gune gore rezervasyon listesi (varsayilan bugun)
Route::get('/api/patron/rezervasyonlar', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _rezervasyonEnsure($p->sube_id);
    $tarih = $r->query('tarih') ?: now()->format('Y-m-d');
    $baseRows = DB::table('rezervasyonlar')->leftJoin('masalar', 'rezervasyonlar.masa_id', '=', 'masalar.id')
        ->where('rezervasyonlar.sube_id', $p->sube_id)->where('rezervasyonlar.tarih', $tarih)
        ->orderBy('rezervasyonlar.saat')
        ->select('rezervasyonlar.*', 'masalar.ad as masa_ad')
        ->get();
    // AI Santral cagri ses kayitlarini rezervasyonlara bagla (yonetici dinleyebilsin). TOPLU sorgu.
    $sesMap = []; $oturumMap = [];
    $rezIds = $baseRows->pluck('id')->all();
    if ($rezIds && Schema::hasTable('santral_oturumlari')) {
        $otIds = []; // oturum_id -> rez_id
        foreach (DB::table('santral_oturumlari')->whereIn('rezervasyon_id', $rezIds)->get(['id', 'rezervasyon_id']) as $o) {
            $oturumMap[$o->rezervasyon_id] = (int) $o->id; $otIds[$o->id] = $o->rezervasyon_id;
        }
        if ($otIds && Schema::hasTable('santral_ses_kayit')) {
            foreach (DB::table('santral_ses_kayit')->whereIn('oturum_id', array_keys($otIds))->orderBy('id')->get(['id', 'oturum_id', 'tur', 'boyut', 'created_at']) as $s) {
                $rid = $otIds[$s->oturum_id] ?? null;
                if ($rid) $sesMap[$rid][] = ['url' => '/santral-ses-dinle/' . $s->id, 'tur' => $s->tur, 'boyut' => (int) $s->boyut, 'tarih' => (string) $s->created_at];
            }
        }
    }
    $rows = $baseRows->map(fn ($x) => [
        'id' => (int) $x->id, 'ad' => $x->ad, 'telefon' => $x->telefon, 'kisi' => (int) $x->kisi,
        'tarih' => $x->tarih, 'saat' => substr($x->saat, 0, 5), 'durum' => $x->durum, 'kaynak' => $x->kaynak,
        'not' => $x->not, 'masa_id' => $x->masa_id ? (int) $x->masa_id : null, 'masa_ad' => $x->masa_ad,
        'cagri_oturum_id' => $oturumMap[$x->id] ?? null,
        'sesler' => $sesMap[$x->id] ?? [],
    ]);
    // Gunluk ozet
    $aktif = $rows->whereIn('durum', ['bekliyor', 'onaylandi']);
    $ozet = [
        'toplam' => $rows->count(),
        'bekleyen' => $rows->where('durum', 'bekliyor')->count(),
        'onayli' => $rows->where('durum', 'onaylandi')->count(),
        'geldi' => $rows->where('durum', 'geldi')->count(),
        'kisi' => $aktif->sum('kisi'),
    ];
    // Sonraki 7 gunun rezervasyon sayilari (mini takvim)
    $gunler = [];
    for ($i = 0; $i < 7; $i++) {
        $g = now()->addDays($i)->format('Y-m-d');
        $gunler[] = ['tarih' => $g, 'adet' => DB::table('rezervasyonlar')->where('sube_id', $p->sube_id)->where('tarih', $g)->whereIn('durum', ['bekliyor', 'onaylandi', 'geldi'])->count()];
    }
    return ['ok' => 1, 'tarih' => $tarih, 'rezervasyonlar' => $rows->values(), 'ozet' => $ozet, 'gunler' => $gunler];
});

// PATRON API: rezervasyon GOSTERGE PANELI (analitik) — gun kartlari + durum/saat/kaynak dagilimi + aylik ozet + performans
Route::get('/api/patron/rezervasyon-panel', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _rezervasyonEnsure($p->sube_id);
    $tarih = $r->query('tarih') ?: now()->format('Y-m-d');
    $ay = $r->query('ay') ?: substr($tarih, 0, 7); // YYYY-MM

    $gunRows = DB::table('rezervasyonlar')->where('sube_id', $p->sube_id)->where('tarih', $tarih)->get();
    $aktifGun = $gunRows->whereIn('durum', ['bekliyor', 'onaylandi', 'geldi']);
    $gun = [
        'toplam' => $gunRows->count(),
        'bekleyen' => $gunRows->where('durum', 'bekliyor')->count(),
        'onaylanan' => $gunRows->where('durum', 'onaylandi')->count(),
        'gelen' => $gunRows->where('durum', 'geldi')->count(),
        'iptal' => $gunRows->where('durum', 'iptal')->count(),
        'gelmedi' => $gunRows->where('durum', 'gelmedi')->count(),
        'toplam_misafir' => (int) $aktifGun->sum('kisi'),
    ];
    $tp = max(1, $gunRows->count());

    // Durum dagilimi
    $durumAd = ['bekliyor' => 'Bekliyor', 'onaylandi' => 'Onaylı', 'geldi' => 'Geldi', 'gelmedi' => 'Gelmedi', 'iptal' => 'İptal'];
    $durumDagilim = [];
    foreach ($durumAd as $k => $ad) {
        $a = $gunRows->where('durum', $k)->count();
        $durumDagilim[] = ['durum' => $k, 'ad' => $ad, 'adet' => $a, 'yuzde' => round($a / $tp * 100, 1)];
    }

    // Saat dagilimi (10:00 - 23:00)
    $saatDagilim = [];
    for ($h = 10; $h <= 23; $h++) {
        $hh = str_pad((string) $h, 2, '0', STR_PAD_LEFT);
        $saatDagilim[] = ['saat' => $hh, 'adet' => $gunRows->filter(fn ($x) => substr((string) $x->saat, 0, 2) === $hh)->count()];
    }

    // Kaynak dagilimi
    $kaynakAd = ['web' => 'Web', 'telefon' => 'Telefon', 'qr' => 'QR', 'walk_in' => 'Kapıdan', 'walkin' => 'Kapıdan', 'admin' => 'Panel'];
    $kaynakDagilim = [];
    foreach ($gunRows->groupBy('kaynak') as $kaynak => $grp) {
        $kaynakDagilim[] = ['kaynak' => (string) $kaynak, 'ad' => $kaynakAd[strtolower((string) $kaynak)] ?? ucfirst((string) $kaynak),
            'adet' => $grp->count(), 'yuzde' => (int) round($grp->count() / $tp * 100)];
    }
    usort($kaynakDagilim, fn ($a, $b) => $b['adet'] <=> $a['adet']);

    // Aylik ozet (gun bazinda adet) + performans (ay geneli)
    $ayBasi = \Carbon\Carbon::parse($ay . '-01')->startOfMonth();
    $ayRows = DB::table('rezervasyonlar')->where('sube_id', $p->sube_id)
        ->whereBetween('tarih', [$ayBasi->format('Y-m-d'), (clone $ayBasi)->endOfMonth()->format('Y-m-d')])->get();
    $aylikGunler = [];
    for ($g = 1; $g <= (int) $ayBasi->daysInMonth; $g++) {
        $gt = (clone $ayBasi)->day($g)->format('Y-m-d');
        $aylikGunler[] = ['gun' => $g, 'tarih' => $gt, 'adet' => $ayRows->where('tarih', $gt)->count()];
    }
    $ayToplam = $ayRows->count();
    $gelenAy = $ayRows->where('durum', 'geldi')->count();
    $gelmediAy = $ayRows->where('durum', 'gelmedi')->count();
    $iptalAy = $ayRows->where('durum', 'iptal')->count();
    $cozulen = max(1, $gelenAy + $gelmediAy + $iptalAy);
    $aylar = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];
    $performans = [
        'tamamlanma' => (int) round($gelenAy / $cozulen * 100),
        'iptal' => $ayToplam > 0 ? (int) round($iptalAy / $ayToplam * 100) : 0,
    ];

    return [
        'ok' => 1, 'tarih' => $tarih, 'ay' => $ay,
        'ay_adi' => $aylar[(int) $ayBasi->format('n')] . ' ' . $ayBasi->format('Y'),
        'gun' => $gun,
        'durum_dagilim' => $durumDagilim,
        'saat_dagilim' => $saatDagilim,
        'kaynak_dagilim' => array_values($kaynakDagilim),
        'aylik' => ['gunler' => $aylikGunler, 'ilk_gun_hafta' => (int) (clone $ayBasi)->day(1)->dayOfWeekIso, 'toplam' => $ayToplam],
        'performans' => $performans,
    ];
});

// PATRON API: rezervasyon ekle
Route::post('/api/patron/rezervasyon-ekle', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _rezervasyonEnsure($p->sube_id);
    $ad = trim((string) $r->input('ad'));
    if ($ad === '') return ['ok' => 0, 'hata' => 'İsim gerekli'];
    $tarih = $r->input('tarih') ?: now()->format('Y-m-d');
    $saat = substr(trim((string) $r->input('saat', '19:00')), 0, 5);
    $tel = trim((string) $r->input('telefon'));
    $masaId = (int) $r->input('masa_id');
    if ($masaId && !DB::table('masalar')->where('id', $masaId)->where('sube_id', $p->sube_id)->exists()) $masaId = 0;
    // GUARD: geçmiş tarih/saat reddi
    if ($tarih < now()->format('Y-m-d')) return ['ok' => 0, 'hata' => 'Geçmiş tarihe rezervasyon alınamaz.'];
    if ($tarih === now()->format('Y-m-d') && $saat < now()->format('H:i')) return ['ok' => 0, 'hata' => 'Geçmiş saate rezervasyon alınamaz.'];
    // GUARD: aynı masa + tarih + ±90 dk pencerede aktif rezervasyon varsa çift-rezervasyonu reddet
    if ($masaId) {
        $dk = fn ($s) => ((int) substr((string) $s, 0, 2)) * 60 + (int) substr((string) $s, 3, 2);
        $yeniDk = $dk($saat);
        foreach (DB::table('rezervasyonlar')->where('sube_id', $p->sube_id)->where('masa_id', $masaId)
            ->where('tarih', $tarih)->whereIn('durum', ['bekliyor', 'onaylandi', 'geldi'])->pluck('saat') as $cs) {
            if (abs($dk(substr((string) $cs, 0, 5)) - $yeniDk) < 90) {
                return ['ok' => 0, 'hata' => 'Bu masa ' . substr((string) $cs, 0, 5) . ' civarında zaten rezerve. Başka masa/saat seçin.'];
            }
        }
    }

    // Musteri CRM: telefondan bul/olustur (alerji-not musteriye yazilir) + ozel istek etiketleri
    $musteriId = _rezMusteriCozumle($p->sube_id, $ad, $tel, (string) $r->input('musteri_not'));
    if ($musteriId && $r->filled('dogum_tarihi') && function_exists('_waDogumKaydet')) { try { _waDogumKaydet($musteriId, $r->input('dogum_tarihi')); } catch (\Throwable $e) {} }
    $etiketler = _rezEtiketTemizle($r->input('etiketler'));

    $id = DB::table('rezervasyonlar')->insertGetId([
        'sube_id' => $p->sube_id, 'musteri_id' => $musteriId, 'masa_id' => $masaId ?: null, 'ad' => $ad,
        'telefon' => $tel ?: null, 'kisi' => max(1, (int) $r->input('kisi', 2)),
        'tarih' => $tarih, 'saat' => $saat, 'durum' => 'onaylandi', 'kaynak' => 'telefon',
        'not' => trim((string) $r->input('not')) ?: null, 'etiketler' => $etiketler ?: null,
        'personel_id' => $p->id, 'created_at' => now(),
    ]);

    // On siparis (ne yiyecek) kalemleri
    $kalem = _rezKalemKaydet($p->sube_id, $id, $r->input('on_siparis'));

    // WhatsApp rezervasyon onayı (telefon varsa; guard'lı — rezervasyon akışını bozmaz)
    try { if (function_exists('_waRezervasyonOnay')) _waRezervasyonOnay($id); } catch (\Throwable $e) {}

    return ['ok' => 1, 'id' => $id, 'musteri_id' => $musteriId, 'kalem' => $kalem,
        'mesaj' => "$ad · $tarih $saat rezervasyonu eklendi." . ($kalem ? " ($kalem ön sipariş)" : '')];
});

// PATRON API: telefondan musteri bul (CRM kart: gecmis + alerji/not)
Route::get('/api/patron/musteri-bul', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $tel = trim((string) $r->input('telefon'));
    if ($tel === '' || !Schema::hasTable('musteriler')) return ['ok' => 1, 'bulundu' => false];
    if (!Schema::hasColumn('musteriler', 'telefon_norm')) return ['ok' => 1, 'bulundu' => false];
    $norm = _telNorm($tel);
    $m = $norm ? DB::table('musteriler')->where('sube_id', $p->sube_id)->where('telefon_norm', $norm)->first() : null;
    if (!$m) $m = DB::table('musteriler')->where('sube_id', $p->sube_id)->where('telefon', $tel)->first();
    if (!$m) return ['ok' => 1, 'bulundu' => false];
    $sonZiyaret = DB::table('adisyonlar')->where('musteri_id', $m->id)->where('durum', 'odendi')->max('kapanis');
    return ['ok' => 1, 'bulundu' => true, 'musteri' => _musteriKart($m),
        'son_ziyaret' => $sonZiyaret ? \Carbon\Carbon::parse($sonZiyaret)->format('d.m.Y') : null];
});

// PATRON API: rezervasyon detay (musteri karti + on siparis kalemleri + etiketler)
Route::get('/api/patron/rezervasyon-detay', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _rezervasyonEnsure($p->sube_id);
    $rez = DB::table('rezervasyonlar')->leftJoin('masalar', 'rezervasyonlar.masa_id', '=', 'masalar.id')
        ->where('rezervasyonlar.id', (int) $r->input('id'))->where('rezervasyonlar.sube_id', $p->sube_id)
        ->select('rezervasyonlar.*', 'masalar.ad as masa_ad')->first();
    if (!$rez) return ['ok' => 0, 'hata' => 'Rezervasyon bulunamadı'];
    $kalemler = DB::table('rezervasyon_kalemleri')->where('rezervasyon_id', $rez->id)->get()
        ->map(fn ($k) => ['urun_id' => (int) $k->urun_id, 'urun_adi' => $k->urun_adi, 'adet' => (int) $k->adet,
            'fiyat' => (float) $k->fiyat, 'not' => $k->not]);
    $musteri = $rez->musteri_id ? _musteriKart(DB::table('musteriler')->find($rez->musteri_id)) : null;
    return ['ok' => 1, 'rezervasyon' => $rez, 'kalemler' => $kalemler->values(),
