// Sipariş-bazlı CANLI kurye konumu + mesafe/ETA (uygulama içi harita — dış URL/ tarayıcı YOK)
if (!function_exists('_teslimKonumEnsure')) {
    function _teslimKonumEnsure()
    {
        if (cache()->get('teslim_konum_kolon_ok')) return;
        foreach (['teslim_lat', 'teslim_lng'] as $c) {
            if (!Schema::hasColumn('adisyonlar', $c)) {
                Schema::table('adisyonlar', fn ($t) => $t->decimal($c, 10, 7)->nullable());
            }
        }
        // Gerçek kurye GPS zamanı — demo simülasyonu bunu olan kuryede DEVRE DIŞI bırakır
        if (!Schema::hasColumn('kuryeler', 'gercek_gps_at')) {
            Schema::table('kuryeler', fn ($t) => $t->timestamp('gercek_gps_at')->nullable());
        }
        cache()->put('teslim_konum_kolon_ok', 1, now()->addHours(12));
    }
}
if (!function_exists('_adresGeokodla')) {
    // Adres (metin) -> {lat,lng}; Nominatim (OSM, bedava). Tam sokak adresi tutmazsa
    // kademeli basitlestirme (mahalle/ilce) dener. 30 gun pozitif, 30 dk negatif cache.
    function _adresGeokodla($adres)
    {
        $adres = trim((string) $adres);
        if (mb_strlen($adres) < 4) return null;
        $ck = 'geo2_' . md5($adres); // v2: eski basarisiz cache'i gecersiz kil
        $c = cache()->get($ck);
        if ($c !== null) return $c ?: null;

        // Aday sorgular: once tam adres, tutmazsa basitlestir (mahalle / ilce + İstanbul)
        $adaylar = [$adres];
        if (!preg_match('/t[üu]rkiye/iu', $adres)) $adaylar[] = $adres . ', Türkiye';
        if (preg_match('/([\p{L}]+)\s*mah/iu', $adres, $m)) $adaylar[] = $m[1] . ', İstanbul, Türkiye';
        if (strpos($adres, ',') !== false) {
            $parcalar = array_map('trim', explode(',', $adres));
            $son = end($parcalar);
            if ($son !== '') $adaylar[] = $son . ', İstanbul, Türkiye';
        }
        $adaylar = array_values(array_unique($adaylar));

        foreach ($adaylar as $q) {
            try {
                $resp = \Illuminate\Support\Facades\Http::withHeaders(['User-Agent' => 'ResteOS/1.0 kurye-takip'])
                    ->timeout(7)->get('https://nominatim.openstreetmap.org/search', [
                        'q' => $q, 'format' => 'json', 'limit' => 1, 'countrycodes' => 'tr', 'accept-language' => 'tr',
                    ]);
                $j = $resp->successful() ? $resp->json() : null;
                if (is_array($j) && !empty($j) && isset($j[0]['lat'], $j[0]['lon'])) {
                    $g = ['lat' => (float) $j[0]['lat'], 'lng' => (float) $j[0]['lon']];
                    cache()->put($ck, $g, now()->addDays(30));
                    return $g;
                }
            } catch (\Throwable $e) {}
        }
        cache()->put($ck, false, now()->addMinutes(30));
        return null;
    }
}
Route::get('/api/paket/{id}/konum', function (Request $r, $id) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $a = DB::table('adisyonlar')->where('id', $id)->where('sube_id', $p->sube_id)->where('kanal', 'paket')->first();
    if (!$a) return response()->json(['ok' => 0, 'hata' => 'Sipariş bulunamadı'], 404);
    _teslimKonumEnsure();

    // Restoran (şube) konumu — mesai geofence merkezi
    $sube = DB::table('subeler')->where('id', $p->sube_id)->first();
    $subeLat = ($sube && isset($sube->mesai_lat) && $sube->mesai_lat) ? (float) $sube->mesai_lat : null;
    $subeLng = ($sube && isset($sube->mesai_lng) && $sube->mesai_lng) ? (float) $sube->mesai_lng : null;

    // Kurye canlı konum
    $kurye = null; $k = null;
    if ($a->kurye_id) {
        $k = DB::table('kuryeler')->find($a->kurye_id);
        if ($k) {
            $dk = (isset($k->konum_zamani) && $k->konum_zamani) ? (int) round(\Carbon\Carbon::parse($k->konum_zamani)->diffInMinutes(now())) : null;
            $kurye = [
                'ad' => $k->ad, 'telefon' => $k->telefon,
                'lat' => isset($k->son_lat) ? (float) $k->son_lat : null,
                'lng' => isset($k->son_lng) ? (float) $k->son_lng : null,
                'konum_dk' => $dk,
            ];
        }
    }

    // Hedef (müşteri adresi) — bir kez geokodla + sakla
    $adres = $a->teslimat_adres ?: null;
    $hedefLat = isset($a->teslim_lat) ? (float) $a->teslim_lat : null;
    $hedefLng = isset($a->teslim_lng) ? (float) $a->teslim_lng : null;
    if (($hedefLat === null || $hedefLng === null) && $adres) {
        $g = _adresGeokodla($adres);
        if ($g) {
            $hedefLat = $g['lat']; $hedefLng = $g['lng'];
            DB::table('adisyonlar')->where('id', $a->id)->update(['teslim_lat' => $hedefLat, 'teslim_lng' => $hedefLng]);
        }
    }

    // DEMO CANLI İLERLEME: gerçek GPS GELMEYEN kurye (demo) her sorguda hedefe ~%18 yaklaşsın.
    // Gerçek kurye (son 2 dk içinde gercek_gps_at) ASLA simüle edilmez — kendi GPS'i esastır.
    if ($k && $kurye && $kurye['lat'] !== null && $hedefLat !== null && $hedefLng !== null) {
        $gercekVar = isset($k->gercek_gps_at) && $k->gercek_gps_at
            && \Carbon\Carbon::parse($k->gercek_gps_at)->gt(now()->subSeconds(120));
        if (!$gercekVar) {
            $uzaklikM = _mesaiMesafe($kurye['lat'], $kurye['lng'], $hedefLat, $hedefLng);
            if ($uzaklikM > 45) {
                $f = 0.18; // kalan mesafenin bir kısmı (yaklaştıkça yavaşlar — doğal varış hissi)
                $yeniLat = $kurye['lat'] + ($hedefLat - $kurye['lat']) * $f;
                $yeniLng = $kurye['lng'] + ($hedefLng - $kurye['lng']) * $f;
                DB::table('kuryeler')->where('id', $k->id)->update(['son_lat' => $yeniLat, 'son_lng' => $yeniLng, 'konum_zamani' => now()]);
                $kurye['lat'] = $yeniLat; $kurye['lng'] = $yeniLng; $kurye['konum_dk'] = 0;
            }
        }
    }

    // Mesafe + ETA (kurye -> hedef; hedef yoksa kurye -> şube)
    $mesafeKm = null; $eta = null;
    if ($kurye && $kurye['lat'] !== null) {
        $hLat = $hedefLat !== null ? $hedefLat : $subeLat;
        $hLng = $hedefLng !== null ? $hedefLng : $subeLng;
        if ($hLat !== null && $hLng !== null) {
            $mesafeKm = round(_mesaiMesafe($kurye['lat'], $kurye['lng'], $hLat, $hLng) / 1000, 2);
            $eta = max(1, (int) round($mesafeKm / 22 * 60)); // ~22 km/s şehir içi scooter
        }
    }

    return ['ok' => 1,
        'durum' => $a->teslimat_durumu,
        'kurye' => $kurye,
        'hedef' => $hedefLat !== null ? ['lat' => $hedefLat, 'lng' => $hedefLng, 'adres' => $adres] : ($adres ? ['adres' => $adres] : null),
        'sube' => $subeLat !== null ? ['lat' => $subeLat, 'lng' => $subeLng, 'ad' => $sube->ad ?? 'Restoran'] : null,
        'mesafe_km' => $mesafeKm,
        'tahmini_dk' => $eta,
    ];
});

// Paket sipariş durum akışı (token'li): kabul -> hazir, yola -> yolda, teslim -> kapat, iptal -> iptal
Route::post('/api/paket/durum', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    $id = (int) $r->input('id');
    $aksiyon = (string) $r->input('aksiyon');
    $a = DB::table('adisyonlar')->where('id', $id)->where('sube_id', $p->sube_id)->where('kanal', 'paket')->first();
    if (!$a) return response()->json(['ok' => 0, 'mesaj' => 'Sipariş bulunamadı'], 404);
    _paketTahsilatEnsure();
    $upd = ['updated_at' => now()];
    switch ($aksiyon) {
        case 'kabul':
            $upd['teslimat_durumu'] = 'hazir';
            break;
        case 'yola':
            $upd['teslimat_durumu'] = 'yolda';
            $kid = (int) $r->input('kurye_id');
            if ($kid && DB::table('kuryeler')->where('id', $kid)->where('sube_id', $a->sube_id)->exists()) {
                $upd['kurye_id'] = $kid;
                DB::table('kuryeler')->where('id', $kid)->update(['durum' => 'teslimatta']);
            }
            break;
        case 'teslim':
            // Kasa DOĞRUDAN teslim+tahsil (gel-al / kuryesiz / kasa elden teslim aldı)
            $upd['teslimat_durumu'] = 'teslim';
            if (Schema::hasColumn('adisyonlar', 'teslim_zamani')) $upd['teslim_zamani'] = now();
            DB::table('adisyonlar')->where('id', $id)->update($upd);
            _paketSettle(DB::table('adisyonlar')->find($id), $p->id);
            return ['ok' => 1, 'mesaj' => 'Teslim edildi ve kasaya işlendi'];
        case 'tahsil':
            // İKİ AŞAMA 2: kurye teslim etti (tahsilat=kuryede), kasa parayı/fişi aldı -> kasaya işle
            _paketSettle($a, $p->id);
            return ['ok' => 1, 'mesaj' => 'Tahsil edildi, kasaya işlendi'];
        case 'yeniden':
            // Teslim edilemeyeni tekrar gönderime al
            $upd['teslimat_durumu'] = 'hazir';
            $upd['tahsilat_durumu'] = null;
            $upd['teslim_notu'] = null;
            break;
        case 'iptal':
            $upd['teslimat_durumu'] = 'iptal';
            $upd['durum'] = 'iptal';
            $upd['kapanis'] = now();
            break;
        default:
            return response()->json(['ok' => 0, 'mesaj' => 'Geçersiz aksiyon'], 422);
    }
    DB::table('adisyonlar')->where('id', $id)->update($upd);
    return ['ok' => 1];
});

