// ============================ MESAI (QR + geofence ile giris/cikis) ============================
if (!function_exists('_mesaiKur')) {
    function _mesaiKur()
    {
        if (!Schema::hasTable('personel_mesai')) {
            try {
                Schema::create('personel_mesai', function ($t) {
                    $t->increments('id');
                    $t->unsignedBigInteger('sube_id')->index();
                    $t->unsignedBigInteger('personel_id')->index();
                    $t->timestamp('giris_at')->nullable();
                    $t->timestamp('cikis_at')->nullable();
                    $t->double('giris_lat')->nullable(); $t->double('giris_lng')->nullable();
                    $t->double('cikis_lat')->nullable(); $t->double('cikis_lng')->nullable();
                    $t->string('cikis_tip', 20)->nullable();   // qr|geofence|aktivite|kapanis|elle
                    $t->string('durum', 10)->default('acik');   // acik|kapali
                    $t->unsignedInteger('adim_bas')->default(0);
                    $t->unsignedInteger('adim')->default(0);
                    $t->timestamp('son_ic_at')->nullable();     // geofence: son iceride oldugu an
                    $t->timestamp('created_at')->nullable();
                });
            } catch (\Throwable $e) {}
        }
        foreach ([['mesai_secret', 's'], ['mesai_lat', 'd'], ['mesai_lng', 'd'], ['mesai_yaricap', 'i']] as $c) {
            if (!Schema::hasColumn('subeler', $c[0])) {
                try {
                    Schema::table('subeler', function ($t) use ($c) {
                        if ($c[1] === 's') $t->string($c[0], 64)->nullable();
                        elseif ($c[1] === 'i') $t->unsignedInteger($c[0])->nullable();
                        else $t->double($c[0])->nullable();
                    });
                } catch (\Throwable $e) {}
            }
        }
    }

    function _mesaiSecret($subeId)
    {
        _mesaiKur();
        $s = DB::table('subeler')->where('id', $subeId)->value('mesai_secret');
        if (!$s) { $s = \Illuminate\Support\Str::random(40); DB::table('subeler')->where('id', $subeId)->update(['mesai_secret' => $s]); }
        return $s;
    }

    // 20 sn'lik zaman penceresi (window) icin kod. Kasa ekrani AYNISINI JS'de (Web Crypto) uretir.
    function _mesaiKod($secret, $window) { return substr(hash_hmac('sha256', (string) $window, $secret), 0, 10); }

    function _mesaiMesafe($la1, $ln1, $la2, $ln2)
    {
        $R = 6371000; $dLa = deg2rad($la2 - $la1); $dLn = deg2rad($ln2 - $ln1);
        $a = sin($dLa / 2) ** 2 + cos(deg2rad($la1)) * cos(deg2rad($la2)) * sin($dLn / 2) ** 2;
        return $R * 2 * atan2(sqrt($a), sqrt(1 - $a));
    }

    function _mesaiDk($bas, $bit = null) // imzasiz sure (dk) — Carbon 3 isaret tuzagina karsi timestamp matematigi
    {
        $b = \Illuminate\Support\Carbon::parse($bas)->timestamp;
        $e = $bit ? \Illuminate\Support\Carbon::parse($bit)->timestamp : now()->timestamp;
        return (int) round(max(0, $e - $b) / 60);
    }

    // 12 saati gecen ACIK mesaileri kapat: cikis = son aktivite (son kalem) -> yoksa son_ic -> yoksa giris.
    function _mesaiOtoKapat($subeId)
    {
        _mesaiKur();
        $acik = DB::table('personel_mesai')->where('sube_id', $subeId)->where('durum', 'acik')->get();
        foreach ($acik as $m) {
            if (_mesaiDk($m->giris_at) < 12 * 60) continue;
            $sonAkt = DB::table('adisyon_kalemleri as k')->join('adisyonlar as a', 'k.adisyon_id', '=', 'a.id')
                ->where('a.sube_id', $subeId)
                ->where(function ($q) use ($m) { $q->where('k.personel_id', $m->personel_id)->orWhere('a.acan_personel_id', $m->personel_id); })
                ->where('k.gonderim_zamani', '>=', $m->giris_at)->max('k.gonderim_zamani');
            $cikis = $sonAkt ?: ($m->son_ic_at ?: $m->giris_at);
            DB::table('personel_mesai')->where('id', $m->id)->update(['cikis_at' => $cikis, 'durum' => 'kapali', 'cikis_tip' => 'kapanis']);
        }
    }
}

// Kasa POS: donen QR icin TOTP secret + sunucu saati (client-side uretir -> sunucu yuku YOK). Yetki: sahip/mudur.
Route::get('/api/mesai/qr-secret', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    return ['ok' => 1, 'secret' => _mesaiSecret($p->sube_id), 'step' => 20, 'now' => time()];
});

// Kasa fiziksel olarak isletmede -> geofence referans konumunu ayarla.
Route::post('/api/mesai/konum-ayarla', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _mesaiKur();
    DB::table('subeler')->where('id', $p->sube_id)->update([
        'mesai_lat' => (float) $r->input('lat'), 'mesai_lng' => (float) $r->input('lng'),
        'mesai_yaricap' => (int) ($r->input('yaricap') ?: 150),
    ]);
    return ['ok' => 1];
});

// Mevcut isletme (geofence) konumunu getir. Yetki: sahip/mudur.
Route::get('/api/mesai/konum', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _mesaiKur();
    $s = DB::table('subeler')->where('id', $p->sube_id)->first();
    return ['ok' => 1, 'var' => ($s && $s->mesai_lat) ? 1 : 0,
        'lat' => $s->mesai_lat ?? null, 'lng' => $s->mesai_lng ?? null,
        'yaricap' => (int) ($s->mesai_yaricap ?? 150)];
});

// Personel QR okuttu -> GIRIS ya da CIKIS (TOTP + geofence dogrula).
Route::post('/api/mesai/okut', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 401);
    _mesaiKur(); _mesaiOtoKapat($p->sube_id);
    $kod = (string) $r->input('kod'); $w = (int) $r->input('w');
    $lat = $r->input('lat'); $lng = $r->input('lng');
    $secret = _mesaiSecret($p->sube_id);
    $cur = intdiv(time(), 20);
    if (abs($w - $cur) > 1) return ['ok' => 0, 'hata' => 'QR süresi doldu, tekrar okut'];
    if (!hash_equals(_mesaiKod($secret, $w), $kod)) return ['ok' => 0, 'hata' => 'QR geçersiz'];
    $sube = DB::table('subeler')->where('id', $p->sube_id)->first();
    if ($sube && $sube->mesai_lat && $sube->mesai_lng && $lat !== null && $lng !== null) {
        $mes = _mesaiMesafe((float) $sube->mesai_lat, (float) $sube->mesai_lng, (float) $lat, (float) $lng);
        if ($mes > (int) ($sube->mesai_yaricap ?: 150) + 50) return ['ok' => 0, 'hata' => 'İşletmede değilsiniz (konum uzak)'];
    }
    $acik = DB::table('personel_mesai')->where('sube_id', $p->sube_id)->where('personel_id', $p->id)->where('durum', 'acik')->first();
    $adim = (int) $r->input('adim', 0);
    if ($acik) {
        DB::table('personel_mesai')->where('id', $acik->id)->update([
            'cikis_at' => now(), 'cikis_lat' => $lat, 'cikis_lng' => $lng, 'cikis_tip' => 'qr', 'durum' => 'kapali',
            'adim' => max(0, $adim - (int) $acik->adim_bas),
        ]);
        return ['ok' => 1, 'durum' => 'cikis', 'saat' => now()->format('H:i')];
    }
    DB::table('personel_mesai')->insert([
        'sube_id' => $p->sube_id, 'personel_id' => $p->id, 'giris_at' => now(),
        'giris_lat' => $lat, 'giris_lng' => $lng, 'durum' => 'acik', 'adim_bas' => $adim, 'adim' => 0,
        'son_ic_at' => now(), 'created_at' => now(),
    ]);
    return ['ok' => 1, 'durum' => 'giris', 'saat' => now()->format('H:i')];
});

// Personel mesai durumu (app kilidi icin).
Route::get('/api/mesai/durum', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _mesaiKur(); _mesaiOtoKapat($p->sube_id);
    $acik = DB::table('personel_mesai')->where('personel_id', $p->id)->where('durum', 'acik')->first();
    return ['ok' => 1, 'acik' => $acik ? 1 : 0, 'giris_at' => $acik->giris_at ?? null,
            'rol' => $p->rol, 'kilit' => in_array($p->rol, ['sahip', 'mudur']) ? 0 : 1];
});

// Geofence ping (app 5 dk'da bir; disarida ise 15 dk sonra oto-cikis).
Route::post('/api/mesai/ping', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _mesaiKur();
    $acik = DB::table('personel_mesai')->where('personel_id', $p->id)->where('durum', 'acik')->first();
    if (!$acik) return ['ok' => 1, 'acik' => 0];
    $adim = (int) $r->input('adim', $acik->adim_bas);
    $lat = $r->input('lat'); $lng = $r->input('lng');
    $sube = DB::table('subeler')->where('id', $p->sube_id)->first();
    $ic = true;
    if ($sube && $sube->mesai_lat && $sube->mesai_lng && $lat !== null && $lng !== null) {
        $mes = _mesaiMesafe((float) $sube->mesai_lat, (float) $sube->mesai_lng, (float) $lat, (float) $lng);
        $ic = $mes <= (int) ($sube->mesai_yaricap ?: 150) + 60;
    }
    if ($ic) {
        DB::table('personel_mesai')->where('id', $acik->id)->update(['son_ic_at' => now(), 'adim' => max(0, $adim - (int) $acik->adim_bas)]);
        return ['ok' => 1, 'acik' => 1, 'ic' => 1];
    }
    $sonIc = $acik->son_ic_at ?: $acik->giris_at;
    if (_mesaiDk($sonIc) >= 15) {
        DB::table('personel_mesai')->where('id', $acik->id)->update([
            'cikis_at' => $sonIc, 'cikis_tip' => 'geofence', 'durum' => 'kapali', 'adim' => max(0, $adim - (int) $acik->adim_bas),
        ]);
        return ['ok' => 1, 'acik' => 0, 'oto_cikis' => 1];
    }
    return ['ok' => 1, 'acik' => 1, 'ic' => 0];
});

// Puantaj: patron TUM personel, personel kendi (gun bazli).
Route::get('/api/mesai/liste', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _mesaiKur(); _mesaiOtoKapat($p->sube_id);
    $patron = in_array($p->rol, ['sahip', 'mudur']);
    $gun = $r->query('gun', now()->toDateString());
    $q = DB::table('personel_mesai as m')->leftJoin('personeller as pr', 'm.personel_id', '=', 'pr.id')
        ->where('m.sube_id', $p->sube_id)->whereDate('m.giris_at', $gun);
    if (!$patron) $q->where('m.personel_id', $p->id);
    $rows = $q->orderBy('m.giris_at', 'desc')->get(['m.*', 'pr.ad as personel_ad']);
    $out = [];
    foreach ($rows as $m) {
        $out[] = [
            'id' => $m->id, 'ad' => $m->personel_ad,
            'giris' => \Illuminate\Support\Carbon::parse($m->giris_at)->format('H:i'),
            'cikis' => $m->cikis_at ? \Illuminate\Support\Carbon::parse($m->cikis_at)->format('H:i') : null,
            'durum' => $m->durum, 'cikis_tip' => $m->cikis_tip,
            'dakika' => _mesaiDk($m->giris_at, $m->cikis_at), 'adim' => (int) $m->adim,
        ];
    }
    return ['ok' => 1, 'patron' => $patron ? 1 : 0, 'gun' => $gun, 'kayitlar' => $out];
});

// ============================ BARKOD (urun + malzeme) ============================
if (!function_exists('_barkodKur')) {
    function _barkodKur()
    {
        if (Schema::hasTable('barkodlar')) return;
        try {
            Schema::create('barkodlar', function ($t) {
                $t->increments('id');
                $t->unsignedBigInteger('sube_id')->index();
                $t->string('barkod', 64);
                $t->string('tur', 12);         // urun | malzeme
                $t->unsignedBigInteger('hedef_id');
                $t->timestamp('created_at')->nullable();
                $t->unique(['sube_id', 'barkod']);
                $t->index(['tur', 'hedef_id']);
            });
        } catch (\Throwable $e) {}
    }
}

// Barkodu ÇÖZ: hangi ürün/malzeme? (POS + sayım + mal kabul ortak kullanır)
Route::get('/api/barkod/coz', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _barkodKur();
    $kod = trim((string) $r->query('kod', ''));
    if ($kod === '') return ['ok' => 0, 'hata' => 'Boş kod'];
    $b = DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('barkod', $kod)->first();
    if (!$b) return ['ok' => 0, 'bulundu' => 0, 'hata' => 'Bu barkod tanımlı değil', 'barkod' => $kod];
    if ($b->tur === 'urun') {
        $u = DB::table('urunler')->where('id', $b->hedef_id)->first(['id', 'ad', 'fiyat', 'kategori_id', 'tukendi', 'aktif']);
        if (!$u) return ['ok' => 0, 'hata' => 'Ürün silinmiş'];
        return ['ok' => 1, 'bulundu' => 1, 'tur' => 'urun', 'id' => (int) $u->id, 'ad' => $u->ad, 'fiyat' => (float) $u->fiyat, 'tukendi' => (int) $u->tukendi];
    }
    $m = DB::table('malzemeler')->where('id', $b->hedef_id)->first(['id', 'ad', 'temel_birim_id', 'guncel_maliyet']);
    if (!$m) return ['ok' => 0, 'hata' => 'Malzeme silinmiş'];
    $birim = DB::table('birimler')->where('id', $m->temel_birim_id)->value('kisaltma');
    return ['ok' => 1, 'bulundu' => 1, 'tur' => 'malzeme', 'id' => (int) $m->id, 'ad' => $m->ad, 'birim' => $birim, 'maliyet' => (float) $m->guncel_maliyet];
});

// Bir öğenin barkodlarını listele (urun/malzeme düzenleme ekranı).
Route::get('/api/barkod/liste', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    _barkodKur();
    $tur = (string) $r->query('tur', 'urun');
    $hid = (int) $r->query('hedef_id', 0);
    $rows = DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('tur', $tur)->where('hedef_id', $hid)
        ->orderBy('id')->get(['id', 'barkod']);
    return ['ok' => 1, 'barkodlar' => $rows];
});

// Barkod ekle (bir öğeye). Aynı barkod başka öğedeyse hata.
Route::post('/api/barkod/ekle', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    _barkodKur();
    $kod = trim((string) $r->input('barkod', ''));
    $tur = (string) $r->input('tur', 'urun');
    $hid = (int) $r->input('hedef_id', 0);
    if ($kod === '' || !$hid || !in_array($tur, ['urun', 'malzeme'])) return ['ok' => 0, 'hata' => 'Eksik bilgi'];
    $var = DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('barkod', $kod)->first();
    if ($var) {
        if ($var->tur === $tur && (int) $var->hedef_id === $hid) return ['ok' => 1, 'zaten' => 1];
        return ['ok' => 0, 'hata' => 'Bu barkod başka bir öğede tanımlı'];
    }
    DB::table('barkodlar')->insert(['sube_id' => $p->sube_id, 'barkod' => $kod, 'tur' => $tur, 'hedef_id' => $hid, 'created_at' => now()]);
    return ['ok' => 1];
});

Route::post('/api/barkod/sil', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0], 403);
    _barkodKur();
    DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('id', (int) $r->input('id'))->delete();
    return ['ok' => 1];
});

// İÇ BARKOD ÜRET — barkodsuz ürün/malzeme için benzersiz dahili numara (CODE128 basılır).
Route::post('/api/barkod/ic-uret', function (Request $r) {
    $p = _apiPersonel($r);
    if (!$p) return response()->json(['ok' => 0], 401);
    if (!in_array($p->rol, ['sahip', 'mudur'])) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz'], 403);
    _barkodKur();
    $tur = (string) $r->input('tur', 'urun');
    $hid = (int) $r->input('hedef_id', 0);
    if (!$hid || !in_array($tur, ['urun', 'malzeme'])) return ['ok' => 0, 'hata' => 'Eksik bilgi'];
    // '99' + tur(1|2) + hedef(5) + rastgele(3) -> 11 hane (gerçek EAN-13 ile çakışmaz)
    $pre = '99' . ($tur === 'urun' ? '1' : '2') . str_pad((string) $hid, 5, '0', STR_PAD_LEFT);
    for ($i = 0; $i < 20; $i++) {
        $kod = $pre . random_int(100, 999);
        if (!DB::table('barkodlar')->where('sube_id', $p->sube_id)->where('barkod', $kod)->exists()) {
            DB::table('barkodlar')->insert(['sube_id' => $p->sube_id, 'barkod' => $kod, 'tur' => $tur, 'hedef_id' => $hid, 'created_at' => now()]);
            return ['ok' => 1, 'barkod' => $kod];
        }
    }
    return ['ok' => 0, 'hata' => 'Üretilemedi, tekrar dene'];
});

// ============================ AI SANTRAL (telefonla konusan yapay zeka) ============================
// Kopru (Node restaurant-santral-ai) bu uclari cagirir: STT metni gonderir, cevap+aksiyon alir.
// Ses YOK; sadece metin. Postman ile de test edilebilir (Faz 1). Bkz: docs/ai-santral-mimari.md
if (!function_exists('_santralEnsure')) {
    function _santralEnsure()
    {
        if (!Schema::hasTable('santral_oturumlari')) {
            Schema::create('santral_oturumlari', function ($t) {
                $t->id();
                $t->unsignedBigInteger('sube_id');
                $t->string('telefon', 30)->nullable();
                $t->unsignedBigInteger('musteri_id')->nullable();
                $t->longText('gecmis')->nullable();               // JSON [{role,content},...]
                $t->string('durum', 15)->default('acik');         // acik | kapandi
                $t->string('sonuc', 20)->nullable();              // rezervasyon | siparis | aktar | bilgi | kacan
                $t->unsignedBigInteger('rezervasyon_id')->nullable();
                $t->unsignedBigInteger('adisyon_id')->nullable();
                $t->longText('siparis_veri')->nullable();         // Faz 4: adisyona donusecek ham veri (JSON)
                $t->timestamp('created_at')->useCurrent();
                $t->timestamp('updated_at')->nullable();
                $t->index(['sube_id', 'durum']);
            });
        }
    }
}

// Cagri acildi -> oturum baslat + karsilama metni dondur
// Santral beyin uçları: köprü X-Santral-Secret gönderir. env SANTRAL_SECRET tanımlıysa ZORUNLU doğrula
// (maliyet + sahte sipariş/rezervasyon koruması). Boşsa (tanımsız) geriye uyum için serbest.
if (!function_exists('_santralAuthGuard')) {
    function _santralAuthGuard($r)
    {
        $beklenen = (string) env('SANTRAL_SECRET', '');
        if ($beklenen === '') return null;
        $gelen = (string) ($r->header('X-Santral-Secret') ?: $r->input('santral_secret') ?: '');
        if (!hash_equals($beklenen, $gelen)) return response()->json(['ok' => 0, 'hata' => 'Yetkisiz santral isteği'], 401);
        return null;
    }
}

Route::match(['get', 'post'], '/api/santral/baslat', function (Request $r) {
    if ($rr = _santralAuthGuard($r)) return $rr;
    _santralEnsure();
    $subeId = (int) ($r->input('sube_id') ?: DB::table('subeler')->min('id') ?: 1);
    // MENU BOS SUBE TUZAGI: istenen subede aktif urun yoksa, urunu olan subeye otomatik gec.
    // (Tek-restoran kurulumu; yanlis DEFAULT_SUBE_ID yuzunden "menu elimde yok" olmasin.)
    $santralUrunSay = function ($sid) {
        if (!Schema::hasTable('urunler')) return 0;
        $q = DB::table('urunler')->where('sube_id', $sid)->where('aktif', 1);
        if (Schema::hasColumn('urunler', 'tukendi')) $q->where('tukendi', 0);
        return (int) $q->count();
    };
    if ($santralUrunSay($subeId) === 0) {
        $dolu = DB::table('urunler')->where('aktif', 1)
            ->select('sube_id', DB::raw('COUNT(*) as n'))->groupBy('sube_id')->orderByDesc('n')->first();
        if ($dolu && $dolu->sube_id) $subeId = (int) $dolu->sube_id;
    }
    $telefon = trim((string) $r->input('telefon'));
    $geriOturum = (int) $r->input('geri_arama_oturum'); // >0 ise: yarida kalan oturumu baglamla devam ettir
    if (function_exists('_santralGeriAramaEnsure')) _santralGeriAramaEnsure();
    $as = new \App\Services\SantralAsistan($subeId, $telefon);
    $menuAdet = $as->menuAdet();

    if ($geriOturum > 0) {
        // GERI ARAMA MODU: onceki gorusmeyi yukle + dogal "yarida kaldi" karsilamasi + kaldigi yerden devam.
        $onceki = DB::table('santral_oturumlari')->where('id', $geriOturum)->first();
        $oncekiG = $onceki ? (json_decode($onceki->gecmis ?: '[]', true) ?: []) : [];
        $isim = $as->taninanMusteri();
        $ad = ($isim && $isim !== '(isim yok)') ? ' ' . $isim : '';
        $mevcutRez = $as->mevcutRezMetni();
        $karsilama = 'Merhaba' . $ad . ', az önce görüşmemiz yarıda kalmıştı, sizi geri aramak istedim.'
            . ($mevcutRez !== '' ? ' Bu arada zaten ' . $mevcutRez . ' rezervasyonunuz görünüyor.' : '')
            . (count($oncekiG) ? ' Kaldığımız yerden devam edelim mi?' : ' Size nasıl yardımcı olabilirim?');
        $seed = $oncekiG;
        $seed[] = ['role' => 'assistant', 'content' => $karsilama];
        if (count($seed) > 40) $seed = array_slice($seed, -40);
        $oid = DB::table('santral_oturumlari')->insertGetId([
            'sube_id' => $subeId, 'telefon' => $telefon ?: null,
            'gecmis' => json_encode($seed, JSON_UNESCAPED_UNICODE),
            'durum' => 'acik', 'geri_arama' => 1, 'created_at' => now(),
        ]);
    } else {
        // NORMAL gelen cagri. Musteri KENDI geri aradiysa bekleyen otomatik geri-aramayi iptal et.
        $tl = preg_replace('/\D/', '', $telefon);
        if (strlen($tl) >= 10) {
            try { DB::table('santral_geri_arama')->where('telefon', $tl)->whereIn('durum', ['bekliyor', 'araniyor'])->update(['durum' => 'vazgecildi', 'son_deneme_at' => now()]); } catch (\Throwable $e) {}
        }
        $karsilama = $as->karsilama();
        $oid = DB::table('santral_oturumlari')->insertGetId([
            'sube_id' => $subeId, 'telefon' => $telefon ?: null,
            'gecmis' => json_encode([['role' => 'assistant', 'content' => $karsilama]], JSON_UNESCAPED_UNICODE),
            'durum' => 'acik', 'created_at' => now(),
        ]);
    }
    return response()->json(['ok' => 1, 'oturum_id' => $oid, 'karsilama' => $karsilama, 'sube_id' => $subeId, 'menu_adet' => $menuAdet, 'geri_arama' => $geriOturum > 0 ? 1 : 0, 'musteri' => $as->taninanMusteri(), 'son_siparis' => $as->sonSiparisMetni()], 200, [], JSON_UNESCAPED_UNICODE);
});

// TESHIS OZETI: son cagrilar + son musteriler + son telefon adisyonlari + ses kayitlari (tek bakista)
Route::match(['get', 'post'], '/api/santral/teshis-ozet', function (Request $r) {
    if (function_exists('_santralEnsure')) _santralEnsure();
    if (function_exists('_santralSesEnsure')) _santralSesEnsure();
    $out = [];
    try {
        $out['son_cagrilar'] = DB::table('santral_oturumlari')->orderByDesc('id')->limit(6)
            ->get(['id', 'sube_id', 'telefon', 'sonuc', 'durum', 'adisyon_id', 'rezervasyon_id', 'created_at']);
    } catch (\Throwable $e) { $out['son_cagrilar'] = 'hata: ' . $e->getMessage(); }
    try {
        $out['son_musteriler'] = DB::table('musteriler')->orderByDesc('id')->limit(6)
            ->get(['id', 'sube_id', 'ad', 'telefon', 'adres', 'siparis_sayisi', 'created_at']);
    } catch (\Throwable $e) { $out['son_musteriler'] = 'hata: ' . $e->getMessage(); }
    try {
        $out['son_telefon_adisyon'] = DB::table('adisyonlar')->where('kanal', 'paket')->where('platform', 'telefon')
            ->orderByDesc('id')->limit(6)->get(['id', 'sube_id', 'musteri_id', 'toplam', 'odeme_yontemi', 'teslimat_adres', 'durum', 'acilis']);
    } catch (\Throwable $e) { $out['son_telefon_adisyon'] = 'hata: ' . $e->getMessage(); }
    try {
        $out['son_ses_kayit'] = Schema::hasTable('santral_ses_kayit')
            ? DB::table('santral_ses_kayit')->orderByDesc('id')->limit(6)->get(['id', 'oturum_id', 'tur', 'boyut', 'created_at'])
            : 'tablo yok';
    } catch (\Throwable $e) { $out['son_ses_kayit'] = 'hata: ' . $e->getMessage(); }
    return response()->json(['ok' => 1, 'ozet' => $out], 200, [], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
});

// TEST: bir telefona ait musteri kaydini sil (temiz baslangic). ?telefon=5xx&onay=1
Route::match(['get', 'post'], '/api/santral/musteri-sil', function (Request $r) {
    $tel = preg_replace('/\D/', '', (string) $r->input('telefon'));
    if (strlen($tel) < 7) return response()->json(['ok' => 0, 'hata' => 'telefon gir (?telefon=5xx...&onay=1)'], 200, [], JSON_UNESCAPED_UNICODE);
    if (!$r->input('onay')) return response()->json(['ok' => 0, 'hata' => 'onay=1 ekleyin (silme onayi)'], 200, [], JSON_UNESCAPED_UNICODE);
    $son10 = substr($tel, -10);
    $silinen = [];
    foreach (DB::table('musteriler')->whereNotNull('telefon')->orderByDesc('id')->limit(5000)->get(['id', 'ad', 'telefon']) as $m) {
        if (substr(preg_replace('/\D/', '', (string) $m->telefon), -10) === $son10) {
            try { DB::table('adisyonlar')->where('musteri_id', $m->id)->update(['musteri_id' => null]); } catch (\Throwable $e) {}
            DB::table('musteriler')->where('id', $m->id)->delete();
            $silinen[] = ['id' => $m->id, 'ad' => $m->ad, 'telefon' => $m->telefon];
        }
    }
    return response()->json(['ok' => 1, 'silinen' => $silinen, 'sayi' => count($silinen)], 200, [], JSON_UNESCAPED_UNICODE);
});

