// Musteri konustu -> cevap uret (+ tamamlanan aksiyonu isle)
Route::match(['get', 'post'], '/api/santral/konus', function (Request $r) {
    if ($rr = _santralAuthGuard($r)) return $rr;
    _santralEnsure();
    $oid = (int) $r->input('oturum_id');
    $metin = (string) $r->input('metin');
    $o = DB::table('santral_oturumlari')->where('id', $oid)->first();
    if (!$o) return response()->json(['ok' => 0, 'hata' => 'oturum_yok'], 404, [], JSON_UNESCAPED_UNICODE);

    $gecmis = json_decode($o->gecmis ?: '[]', true) ?: [];
    // haricRezId: bu cagride olusturulan rezervasyon mevcut-rez sayilmasin (musteriye "zaten var" demesin)
    $as = new \App\Services\SantralAsistan($o->sube_id, $o->telefon, (int) ($o->rezervasyon_id ?? 0));
    $res = $as->konus($metin, $gecmis);

    // gecmise ekle
    $gecmis[] = ['role' => 'user', 'content' => trim($metin)];
    $gecmis[] = ['role' => 'assistant', 'content' => $res['cevap']];
    if (count($gecmis) > 40) $gecmis = array_slice($gecmis, -40);

    $guncelle = ['gecmis' => json_encode($gecmis, JSON_UNESCAPED_UNICODE), 'updated_at' => now()];

    // Tamamlanan aksiyonu isle
    if ($res['aksiyon'] === 'rezervasyon' && !empty($res['veri']['rezervasyon'])) {
        $rz = $res['veri']['rezervasyon'];
        if (function_exists('_rezervasyonEnsure')) _rezervasyonEnsure($o->sube_id);
        try {
            // CRM: ÖNCE müşteriyi çöz ki musteri_id rezervasyona BAĞLANSIN (eskiden insert'te eksikti -> CRM kopuk).
            $kimlikTel = trim((string) ($o->telefon ?: ($rz['telefon'] ?? '')));
            $adRz = trim((string) ($rz['ad'] ?? ''));
            $mid = null;
            if ($kimlikTel !== '' && function_exists('_santralMusteriEnsure')) {
                try {
                    $mid = _santralMusteriEnsure((int) $o->sube_id, $kimlikTel);
                    if ($mid && $adRz !== '') DB::table('musteriler')->where('id', $mid)->update(['ad' => $adRz, 'updated_at' => now()]);
                } catch (\Throwable $e) {
                }
            }
            $tarihV = preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($rz['tarih'] ?? '')) ? $rz['tarih'] : now()->format('Y-m-d');
            $saatV = preg_match('/^\d{1,2}:\d{2}$/', (string) ($rz['saat'] ?? '')) ? substr((string) $rz['saat'], 0, 5) : '19:00';
            // CIFT REZERVASYON GUARD: ayni telefon + tarih + saat aktif rezervasyon varsa YENISINI OLUSTURMA (model kacirsa bile).
            $rid = null;
            $son10g = substr(preg_replace('/\D/', '', $kimlikTel), -10);
            if (strlen($son10g) >= 7) {
                foreach (DB::table('rezervasyonlar')->where('sube_id', $o->sube_id)->where('tarih', $tarihV)
                    ->whereIn('durum', ['bekliyor', 'onaylandi'])->get(['id', 'telefon', 'saat']) as $er) {
                    if (substr(preg_replace('/\D/', '', (string) $er->telefon), -10) === $son10g && substr((string) $er->saat, 0, 5) === $saatV) {
                        $rid = (int) $er->id; break; // mevcut rezervasyona bagla, duplikat olusturma
                    }
                }
            }
            $yeniKayit = false;
            if (!$rid) {
                $rid = DB::table('rezervasyonlar')->insertGetId([
                    'sube_id' => $o->sube_id,
                    'musteri_id' => $mid,
                    'ad' => trim((string) ($rz['ad'] ?? 'Telefon müşterisi')),
                    'telefon' => trim((string) ($rz['telefon'] ?? $o->telefon ?? '')) ?: null,
                    'kisi' => max(1, (int) ($rz['kisi'] ?? 2)),
                    'tarih' => $tarihV,
                    'saat' => $saatV,
                    'durum' => 'bekliyor',
                    'kaynak' => 'telefon',
                    'not' => trim((string) ($rz['not'] ?? '')) !== '' ? ('AI Santral — ' . trim((string) $rz['not'])) : 'AI Santral',
                    'created_at' => now(),
                ]);
                $yeniKayit = true;
            } else {
                // NOT BIRIKME: mevcut rezervasyona YENI not geldiyse ekle (musteri sonraki aramada not ekletebilir).
                $yeniNot = trim((string) ($rz['not'] ?? ''));
                if ($yeniNot !== '') {
                    try {
                        $mevcutNot = (string) DB::table('rezervasyonlar')->where('id', $rid)->value('not');
                        if (mb_stripos($mevcutNot, $yeniNot) === false) { // ayni notu tekrarlama
                            $birlesik = trim($mevcutNot) !== '' ? ($mevcutNot . ' | ' . $yeniNot) : ('AI Santral — ' . $yeniNot);
                            DB::table('rezervasyonlar')->where('id', $rid)->update(['not' => mb_substr($birlesik, 0, 250)]);
                        }
                    } catch (\Throwable $e) {}
                }
            }
            // Ad bos/generic kaldiysa ve bu aramada gercek ad geldiyse guncelle
            if (!$yeniKayit && $adRz !== '') {
                try {
                    $mevcutAd = (string) DB::table('rezervasyonlar')->where('id', $rid)->value('ad');
                    if ($mevcutAd === '' || mb_stripos($mevcutAd, 'telefon') !== false) {
                        DB::table('rezervasyonlar')->where('id', $rid)->update(['ad' => $adRz]);
                    }
                } catch (\Throwable $e) {}
            }
            $guncelle['rezervasyon_id'] = $rid;
            $guncelle['sonuc'] = 'rezervasyon';
        } catch (\Throwable $e) { /* tablo/kolon farki: sessiz gec, cevap yine doner */ }
    } elseif ($res['aksiyon'] === 'siparis' && !empty($res['veri']['siparis'])) {
        // Faz 4: AI'nin aldigi paket siparisini GERCEK adisyona dusur (mevcut paket akisi: _paketSiparisAl).
        $sp = $res['veri']['siparis'];
        $guncelle['siparis_veri'] = json_encode($sp, JSON_UNESCAPED_UNICODE);
        $guncelle['sonuc'] = 'siparis';
        if (function_exists('_paketSiparisAl')) {
            try {
                $sube = DB::table('subeler')->where('id', $o->sube_id)->first();
                $kalemler = [];
                foreach (($sp['kalemler'] ?? []) as $k) {
                    $ad = trim((string) ($k['urun'] ?? $k['ad'] ?? ''));
                    if ($ad === '') continue;
                    $kalemler[] = ['ad' => $ad, 'adet' => max(1, (int) ($k['adet'] ?? 1))];
                }
                // Odeme yontemi: AI'dan gelen (kapida_nakit|kapida_kart|online) -> adisyon.odeme_yontemi
                // Mevcut konvansiyonla hizali: 'nakit' | 'kart_kapida' (kuryeye POS getir sinyali) | 'online'
                $odemeHam = (string) ($sp['odeme'] ?? '');
                $odemeYon = $odemeHam === 'kapida_kart' ? 'kart_kapida' : ($odemeHam === 'online' ? 'online' : 'nakit');
                if (Schema::hasColumn('santral_oturumlari', 'sonuc')) $guncelle['sonuc'] = 'siparis';
                // Musteri KIMLIGI = CallerID (tanima icin); yoksa AI'nin aldigi telefon
                $kimlikTel = trim((string) ($o->telefon ?: ($sp['telefon'] ?? '')));
                $adSp = trim((string) ($sp['ad'] ?? ''));
                $adrSp = trim((string) ($sp['adres'] ?? ''));
                if ($sube && $kalemler) {
                    $r2 = _paketSiparisAl($sube, [
                        'platform' => 'telefon',
                        'odeme_yontemi' => $odemeYon,
                        'musteri' => [
                            'ad' => $adSp ?: ('Telefon ' . $kimlikTel),
                            'telefon' => $kimlikTel,
                            'adres' => $adrSp,
                        ],
                        'kalemler' => $kalemler,
                    ]);
                    if (!empty($r2['adisyon_id'])) {
                        $guncelle['adisyon_id'] = $r2['adisyon_id'];
                        // CRM: ad/adres ogrenildiyse musteri kaydini GUNCELLE (sonraki aramada tanisin)
                        try {
                            $mid = DB::table('adisyonlar')->where('id', $r2['adisyon_id'])->value('musteri_id');
                            if ($mid) {
                                $up = [];
                                if ($adSp !== '') $up['ad'] = $adSp;
                                if ($adrSp !== '') $up['adres'] = $adrSp;
                                if ($up) { $up['updated_at'] = now(); DB::table('musteriler')->where('id', $mid)->update($up); }
                            }
                        } catch (\Throwable $e) {}
                    }
                }
            } catch (\Throwable $e) { /* adisyon olusturulamadi: ham veri yine saklandi, cevap yine doner */ }
        }
    } elseif ($res['aksiyon'] === 'aktar') {
        $guncelle['sonuc'] = 'aktar';
    }
    if ($res['bitir']) $guncelle['durum'] = 'kapandi';

    DB::table('santral_oturumlari')->where('id', $oid)->update($guncelle);

    return response()->json([
        'ok' => 1,
        'cevap' => $res['cevap'],
        'aksiyon' => $res['aksiyon'],
        'bitir' => $res['bitir'],
        'teshis' => $as->teshis,
    ], 200, [], JSON_UNESCAPED_UNICODE);
});

// Cagri kapandi -> oturumu kapat
// CallerID ile musteri kaydini bul; yoksa minimal olustur (tanima icin). Doner: musteri_id|null
if (!function_exists('_santralMusteriEnsure')) {
    function _santralMusteriEnsure($subeId, $telefon)
    {
        try {
            if (!Schema::hasTable('musteriler')) return null;
            $clean = preg_replace('/\D/', '', (string) $telefon);
            if (strlen($clean) < 7) return null;
            $son10 = substr($clean, -10);
            foreach (DB::table('musteriler')->where('sube_id', $subeId)->whereNotNull('telefon')->orderByDesc('id')->limit(5000)->get(['id', 'telefon']) as $m) {
                if (substr(preg_replace('/\D/', '', (string) $m->telefon), -10) === $son10) return $m->id;
            }
            return DB::table('musteriler')->insertGetId([
                'sube_id' => $subeId, 'ad' => 'Telefon ' . $clean, 'telefon' => $clean,
                'puan' => 0, 'siparis_sayisi' => 0, 'toplam_harcama' => 0, 'created_at' => now(), 'updated_at' => now(),
            ]);
        } catch (\Throwable $e) { return null; }
    }
}

Route::match(['get', 'post'], '/api/santral/bitir', function (Request $r) {
    if ($rr = _santralAuthGuard($r)) return $rr;
    _santralEnsure();
    _santralGeriAramaEnsure();
    $oid = (int) $r->input('oturum_id');
    $sonuc = trim((string) $r->input('sonuc'));
    $upd = ['durum' => 'kapandi', 'updated_at' => now()];
    $o = DB::table('santral_oturumlari')->where('id', $oid)->first();
    if ($o && !$o->sonuc) $upd['sonuc'] = $sonuc ?: 'bilgi';
    DB::table('santral_oturumlari')->where('id', $oid)->update($upd);
    // TANIMA: cagri biterken CallerID ile musteri kaydini garantile (siparis tamamlanmasa da sonraki aramada taninir)
    if ($o && $o->telefon) _santralMusteriEnsure((int) $o->sube_id, $o->telefon);
    // TERK TESPITI: gorusme yarida kaldiysa (tamamlanmamis + gercek konusma + callback degil) -> geri arama kuyruguna.
    if ($o) _santralTerkTespit($o, $sonuc ?: ($o->sonuc ?? 'bilgi'));
    // REZERVASYON TAKIBI: cagri rezervasyon KONUSTUYSA + musterinin TEK aktif rezervasyonu varsa, bu oturumu
    // o rezervasyona BAGLA (tum aramalar+ses kayitlari rezervasyonda gorunsun). Siparis cagrilarini (adisyonu olan) baglamaz.
    if ($o) _santralRezervasyonBagla($o);
    return response()->json(['ok' => 1], 200, [], JSON_UNESCAPED_UNICODE);
});

if (!function_exists('_santralRezervasyonBagla')) {
    function _santralRezervasyonBagla($o)
    {
        try {
            if (!empty($o->rezervasyon_id) || !empty($o->adisyon_id)) return; // zaten bagli / siparis cagrisi
            $tel = preg_replace('/\D/', '', (string) ($o->telefon ?? ''));
            if (strlen($tel) < 10) return;
            // Bu cagri rezervasyon konustu mu?
            $g = json_decode($o->gecmis ?: '[]', true) ?: [];
            $rezKonusu = false;
            foreach ($g as $m) { if (mb_stripos((string) ($m['content'] ?? ''), 'rezervasyon') !== false) { $rezKonusu = true; break; } }
            if (!$rezKonusu) return;
            // Musterinin aktif yaklasan rezervasyonu (TEK ise bagla; birden fazlaysa belirsiz, dokunma)
            $son10 = substr($tel, -10);
            $bugun = now()->setTimezone('Europe/Istanbul')->format('Y-m-d');
            $bulunan = null; $adet = 0;
            foreach (DB::table('rezervasyonlar')->where('sube_id', $o->sube_id)->whereIn('durum', ['bekliyor', 'onaylandi'])
                ->where('tarih', '>=', $bugun)->orderByDesc('id')->limit(50)->get(['id', 'telefon']) as $rr) {
                if (substr(preg_replace('/\D/', '', (string) $rr->telefon), -10) === $son10) { $bulunan = $bulunan ?? (int) $rr->id; $adet++; }
            }
            if ($bulunan && $adet === 1) {
                DB::table('santral_oturumlari')->where('id', $o->id)->update(['rezervasyon_id' => $bulunan]);
            }
        } catch (\Throwable $e) {}
    }
}

// ============================ TERK EDILEN CAGRI KURTARMA (geri arama) ============================
if (!function_exists('_santralGeriAramaEnsure')) {
    function _santralGeriAramaEnsure()
    {
        if (!Schema::hasTable('santral_geri_arama')) {
            Schema::create('santral_geri_arama', function ($t) {
                $t->id();
                $t->unsignedBigInteger('oturum_id')->index();  // yarida kalan oturum (baglam icin)
                $t->unsignedBigInteger('sube_id')->nullable();
                $t->string('telefon', 32)->index();
                $t->string('durum', 16)->default('bekliyor');  // bekliyor|araniyor|basarili|cevapsiz|vazgecildi
                $t->unsignedTinyInteger('deneme')->default(0);
                $t->timestamp('son_deneme_at')->nullable();
                $t->timestamp('created_at')->useCurrent();
            });
        }
        // oturumun KENDISI bir geri-arama mi? (callback dongusunu onlemek icin)
        if (Schema::hasTable('santral_oturumlari') && !Schema::hasColumn('santral_oturumlari', 'geri_arama')) {
            try { Schema::table('santral_oturumlari', fn ($t) => $t->boolean('geri_arama')->default(0)); } catch (\Throwable $e) {}
        }
    }
}
// Bir oturum yarida mi kaldi? Kosullar saglaniyorsa geri arama kuyruguna ekle.
if (!function_exists('_santralTerkTespit')) {
    function _santralTerkTespit($o, $sonuc)
    {
        try {
            _santralGeriAramaEnsure();
            // 1) callback'in kendisi yarida kalirsa TEKRAR kuyruga alma (dongu).
            if (!empty($o->geri_arama)) return;
            // 2) tamamlanan/aktarilan cagri terk degildir.
            if (in_array($sonuc, ['siparis', 'rezervasyon', 'aktar'], true)) return;
            // 3) gecerli telefon + EN AZ 1 musteri turu olmali (sadece karsilamayi duyup kapatan/yanlis arama degil).
            $tel = preg_replace('/\D/', '', (string) ($o->telefon ?? ''));
            if (strlen($tel) < 10) return;
            $g = json_decode($o->gecmis ?: '[]', true) ?: [];
            $musteriTuru = 0;
            foreach ($g as $m) if (($m['role'] ?? '') === 'user') $musteriTuru++;
            if ($musteriTuru < 1) return;
            // 4) bu telefon icin zaten aktif (bekliyor/araniyor) geri arama varsa tekrarlama.
            $varMi = DB::table('santral_geri_arama')->where('telefon', $tel)->whereIn('durum', ['bekliyor', 'araniyor'])->exists();
            if ($varMi) return;
            DB::table('santral_geri_arama')->insert([
                'oturum_id' => $o->id, 'sube_id' => $o->sube_id, 'telefon' => $tel,
                'durum' => 'bekliyor', 'deneme' => 0, 'created_at' => now(),
            ]);
        } catch (\Throwable $e) {}
    }
}
// KOPRU YOKLAR: geri aranacaklar (grace suresi gecmis + deneme < 2). Kopru bunlari disari arar.
Route::match(['get', 'post'], '/api/santral/geri-arama-bekleyen', function (Request $r) {
    if ($rr = _santralAuthGuard($r)) return $rr;
    _santralGeriAramaEnsure();
    $graceSn = 45; // musteri kendi geri arasin diye kisa bekleme
    $rows = DB::table('santral_geri_arama')->where('durum', 'bekliyor')->where('deneme', '<', 2)
        ->where('created_at', '<=', now()->subSeconds($graceSn))
        ->orderBy('id')->limit(5)->get(['id', 'oturum_id', 'sube_id', 'telefon']);
    return response()->json(['ok' => 1, 'liste' => $rows], 200, ['Cache-Control' => 'no-store'], JSON_UNESCAPED_UNICODE);
});
// KOPRU BILDIRIR: arama sonucu (araniyor|basarili|cevapsiz). cevapsizsa deneme++ (2'de vazgecilir).
Route::post('/api/santral/geri-arama-durum', function (Request $r) {
    if ($rr = _santralAuthGuard($r)) return $rr;
    _santralGeriAramaEnsure();
    $id = (int) $r->input('id');
    $durum = (string) $r->input('durum');
    $row = DB::table('santral_geri_arama')->where('id', $id)->first();
    if (!$row) return response()->json(['ok' => 0], 200, [], JSON_UNESCAPED_UNICODE);
    if ($durum === 'araniyor') {
        DB::table('santral_geri_arama')->where('id', $id)->update(['durum' => 'araniyor', 'son_deneme_at' => now()]);
    } elseif ($durum === 'basarili') {
        DB::table('santral_geri_arama')->where('id', $id)->update(['durum' => 'basarili', 'son_deneme_at' => now()]);
    } else { // cevapsiz/hata
        $deneme = (int) $row->deneme + 1;
        DB::table('santral_geri_arama')->where('id', $id)->update([
            'durum' => $deneme >= 2 ? 'vazgecildi' : 'bekliyor', 'deneme' => $deneme, 'son_deneme_at' => now(),
        ]);
    }
    return response()->json(['ok' => 1], 200, [], JSON_UNESCAPED_UNICODE);
});

// ============================ TEST VERISI TEMIZLE (en bastan test icin) ============================
// Arama + ses + geri-arama + musteri + rezervasyon + siparis siler. Egitim/kalip/telaffuz KALIR.
// GERI ALINAMAZ -> onay=HEPSINI-SIL zorunlu.
Route::match(['get', 'post'], '/api/santral/test-temizle', function (Request $r) {
    if ($rr = _santralAuthGuard($r)) return $rr;
    if ((string) $r->input('onay') !== 'HEPSINI-SIL') {
        return response()->json(['ok' => 0, 'hata' => 'Onay gerekli: ?onay=HEPSINI-SIL (GERI ALINAMAZ!)'], 200, [], JSON_UNESCAPED_UNICODE);
    }
    $tablolar = [
        'santral_oturumlari', 'santral_ses_kayit', 'santral_geri_arama', 'cagri_loglari',
        'rezervasyonlar', 'rezervasyon_kalemleri',
        'adisyonlar', 'adisyon_kalemleri',
        'musteriler',
    ];
    $silinen = [];
    try { DB::statement('SET FOREIGN_KEY_CHECKS=0'); } catch (\Throwable $e) {}
    foreach ($tablolar as $t) {
        if (!Schema::hasTable($t)) { $silinen[$t] = 'tablo yok'; continue; }
        try {
            $n = (int) DB::table($t)->count();
            DB::table($t)->truncate();
            $silinen[$t] = $n;
        } catch (\Throwable $e) {
            try { $n = (int) DB::table($t)->count(); DB::table($t)->delete(); $silinen[$t] = $n; }
            catch (\Throwable $e2) { $silinen[$t] = 'hata: ' . $e2->getMessage(); }
        }
    }
    try { DB::statement('SET FOREIGN_KEY_CHECKS=1'); } catch (\Throwable $e) {}
    // Fiziksel ses kayit dosyalari
    $sesSilindi = 0;
    try {
        $dir = storage_path('app/santral_ses');
        if (is_dir($dir)) foreach (glob($dir . '/*') as $f) { if (@unlink($f)) $sesSilindi++; }
    } catch (\Throwable $e) {}
    return response()->json(['ok' => 1, 'silinen' => $silinen, 'ses_dosya_silindi' => $sesSilindi, 'not' => 'Egitim/kalip/telaffuz KORUNDU.'], 200, [], JSON_UNESCAPED_UNICODE);
});

